    ["“倦坐在路边，取下这本书来……”"] = "«В дремоте у огня сними с полки эту книгу...»",
    ["“它”……看起来，这是前屋主心中最重要的东西。"] = "«Оно»... Судя по всему, для прежнего хозяина дома это было самым важным в жизни.",
    ["“工匠”……这是“通识者”途径的序列6，能够制作机械奇物和非凡物品。"] = "«Ремесленник»... Это Последовательность 6 Пути «Чтеца Знаний», позволяющая создавать механические диковины и потусторонние предметы.",
    ["“布置”？等等 ，该不会今天所有东西又都是你们组织的吧？"] = "\"Договоренность\"? Подождите, а может быть, все сегодня снова было организовано вами, ребята?",
    ["“当你老了，头发花白，睡意沉沉。”"] = "«Когда ты будешь старой, седой и полной сна...»",
    ["“徘徊于虚妄之中的灵，被人驱使的上界生物，独属于戴莉·西蒙妮的信使”……呵呵，你不觉得很酷吗？"] = "«Дух, блуждающий во лжи, существо из высшего царства, движимое другими, посланник, принадлежащий исключительно Дейли Симоне»…… Хе-хе, тебе не кажется, что это круто?",
    ["“惩戒天使”，祂是主的雷霆，主的怒火，主的手掌，主赐祂权柄，为主审判所有的堕落者和不洁者。"] = "«Ангел наказания», Он — гром Господень, гнев Господень, ладонь Господня, и Господь дарует Ему власть судить всех падших и нечистых от Его имени.",
    ["“惩戒天使”，祂是主的雷霆，主的怒火，主的手掌，是所有堕落者和不洁者的审判官及处刑人。"] = "«Ангел наказания», Он — гром Господень, гнев Господень, ладонь Господня, судья и палач всех падших и нечистых.",
    ["“愚者”先生仁慈而怜悯，是这个世界的救主，却让我们以“他”而非“祂”来称呼。"] = "Мистер Шут добр и милосерден, спаситель этого мира, но позволяет нам называть его «он», а не «Он».",
    ["“愚者”先生以屏障碎片为基石，于灵界中开辟了一片安全空间，在此建立塔罗学派。"] = "Господин «Шут» использовал фрагменты Барьера как краеугольный камень, чтобы открыть безопасное пространство в Мире Духов, основав здесь Клуб Таро.",
    ["“愚者”先生是一位仁慈的神明。没有他的帮助，我也无法逃脱被邪神污染的命运……"] = "Господин Шут — милосердное божество. Без Его помощи мне не удалось бы избежать участи осквернения злым богом...",
    ["“愚者”先生是得到所有教会认可的正神，塔罗学派的成功修建也是得益于他的帮助。"] = "Господин Шут — истинный Бог, признанный всеми церквями, и успешное строительство Клуба Таро также произошло благодаря его помощи.",
    ["“愚者”先生的力量果然深不可测……您一定很感激他。"] = "Сила Господина Шута поистине непостижима... Должно быть, вы безмерно ему благодарны.",
    ["“愚者”派其眷者格尔曼·斯帕罗，行于神弃之地，传播主的光辉，带来光明与温暖。"] = "«Шут» отправляет своего Блаженного, Германа Воробья, гулять по Забытой Земле Богов, распространяя сияние Господа и принося свет и тепло.",
    ["“我们做的事情看似简单，却实实在在影响着一个又一个孩子的人生，所以，我们得尽快开始，不能浪费时间。”"] = "«То, что мы делаем, кажется простым, но это действительно влияет на жизнь одного ребенка за другим, поэтому мы должны начать как можно скорее и не можем терять время».",
    ["“救赎天使”是我主的号角，是神谕的传达者。"] = "«Ангел Искупления» — это рог моего Господа, глашатай Его божественной воли.",
    ["“救赎天使”，祂向世人传递主的声音，主赐给祂死而复生的奇迹，替主救赎被众神遗弃的失落城邦。"] = "«Ангел искупления», Он передает миру глас Господень, Господь дарует Ему чудо воскресения, и Он выкупает затерянный город-государство, оставленный богами от имени Господа.",
    ["“时之天使”，祂是古老年代里的天使，最终臣服于我主，为他敲击天国之钟。"] = "«Ангел Времени» — Ангел из древних эпох, что в конце концов покорился нашему Господу и ударяет в колокол Царства Небесного во славу Его.",
    ["“时之天使”，祂用血肉侍奉主，是主虔诚的信徒，曾用血肉侍奉主，主赐给祂时间的权柄，让祂得以侍奉主到永恒。"] = "«Ангел Времени», Он служит Господу Своей плотью и кровью, является истово верующим Господом, когда-то служил Господу Своей плотью и кровью, и Господь дарует Ему власть времени, позволяя Ему служить Господу вечно.",
    ["“星星”有什么特别的含义吗？"] = "Имеет ли «Звезда» какое-то особое значение?",
    ["“月亮”先生，您认识我？"] = "Мистер Луна, вы меня знаете?",
    ["“正义”小姐不好意思打扰一下，关于仪式魔法……我翻阅了许多资料，但总觉得纸上谈兵，难以真正把握其精髓。"] = "Мисс «Справедливость», извините за беспокойство по поводу Ритуальной Магии…… Я прочитала много материалов, но мне всегда кажется, что это просто пустые разговоры, и трудно по-настоящему уловить ее суть.",
    ["“正义”小姐写信给我，说我或许需要一处地方落脚……<P_Heart>（四处张望）</>但这是哪儿呢？"] = "Мисс «Справедливость» написала мне, сказав, что мне, возможно, понадобится место для проживания……<P_Heart>(Оглядываясь вокруг)</>Но где это?",
    ["“死亡天使”是跟随我主最久的存在，是冥界的执政官。"] = "«Ангел Смерти» — это существо, дольше всех следовавшее за моим Господом, Консул Подземного мира.",
    ["“死亡天使”，祂曾陷入失忆的诅咒，在主的帮助下逐渐找回自我，成为主的护翼，自亘古到永久。"] = "«Ангел Смерти»... Когда-то Он пал жертвой проклятия беспамятства, но с помощью Господа мало-помалу обрел Себя и стал десницей Господа — от века и до века.",
    ["“水银天使”是命运的化身，是我主最宠爱的天使。"] = "«Ангел Меркурия» — это аватар судьбы и ангел, которого мой Господь любит больше всего.",
    ["“水银天使”，祂被吞尾的恶蛇追逐，遇主而重生，因信仰而得救，依此成全命运的奇迹。"] = "«Ангел Меркурия», Его преследует Уроборос, возрождается при встрече с Господом, спасается верой и таким образом совершает чудо судьбы.",
    ["“爱妻奥莉薇，我寄回家的那笔货款，你存进贝克兰德银行了对吗？”"] = "«Моя дорогая жена Оливия, оплату за товары, которые я отправил домой, ты положила в банк Бэкланд, верно?»",
    ["“生命天使”是智慧的结晶，是每个人体内永不磨灭的灵性。"] = "«Ангел Жизни» — кристаллизация мудрости, неугасимая Духовность внутри каждого человека.",
    ["“生命天使”，祂是主智慧的光辉，是每个人体内永不磨灭的灵性，是主给予大地的恩赐。"] = "«Ангел жизни», Он – сияние мудрости Господней, вечная духовность в теле каждого и дар Господень земле.",
    ["“看见我”最大的作用，其实是——操控！"] = "Главное предназначение способности «Узри меня» — на самом деле управление!",
    ["“看见我”源于观众途径序列6催眠师的能力。"] = "«Увидь меня» происходит из способности Гипнотизёра, Последовательность 6 Пути Зрителя.",
    ["“神降”仪式的材料都准备好后，我将陪同你一起开启仪式，见证奇迹般神降之时。"] = "Когда все материалы для ритуала «Божественного Нисхождения» будут готовы, я вместе с тобой начну ритуал, чтобы узреть чудесный миг нисхождения божества.",
    ["“观众”的序列名，会让人误以为这是一个只擅长观察与辅助的途径。但实际上，这也是一种伪装，让人更轻敌的伪装。"] = "Название Последовательности «Зритель» заставляет думать, что это Путь, годный лишь для наблюдения и поддержки. Но на самом деле это тоже маскировка — маскировка, заставляющая недооценивать её обладателя.",
    ["“这里发生什么都不奇怪”——他在暗示什么？"] = "«Здесь нет ничего странного» — что он имеет в виду?",
    ["“霍纳奇斯山脉曾有高位魔女陨落，那里可能有魔女力量的残留。”"] = "«В горах Хорнакис когда-то пала высокопоставленная Демоница, там могли остаться следы силы Демоницы».",
    ["“高阶魔女的能力与寒冷相关——在那里也许可以找到不融的冰。”"] = "«Способности высшей Демоницы связаны с холодом — там, возможно, найдётся неплавящийся лёд».",
    ["“魔术师”女士，对您来说，“愚者”先生是个什么样的存在？"] = "Госпожа «Фокусник», кем для вас является господин «Шут»?",
    ["“魔术师”女士，您小时候……是什么样的？"] = "Госпожа «Фокусник», какой вы были... в детстве?",
    ["“魔术师”女士，您的能力是怎么来的？"] = "Мисс «Маг», как вы обрели свои способности?",
    ["“魔术师”女士，我读过您的《暴风山庄》，非常精彩！"] = "Госпожа «Фокусник», я читал вашу «Штормовую виллу», это было великолепно!",
    ["“魔术师”小姐在花海，去那里找她吧。"] = "Госпожа «Фокусник» в море цветов, ищите её там.",
    ["“魔术师”小姐托我把这本书带给您。 "] = "Мисс Маг попросила меня передать вам эту книгу.",
    ["“魔术师”小姐的委托完成了，我也离开这里吧。"] = "Поручение госпожи «Фокусник» выполнено, пора и мне уходить отсюда.",
    ["“魔术师”小姐？您还好吗？"] = "Госпожа «Фокусник»? Вы в порядке?",
    ["……"] = false,
    ["……<P_Heart>（小声嘟囔）</>……究竟是从哪里搞到的材料，我也好想要一双这样的翅膀。"] = "...<P_Heart>(тихо ворчит)</>... Откуда только такие материалы берутся? Я бы тоже не отказалась от таких крылышек.",
    ["……<P_Heart>（沉默了许久）</>因为我要为我的朋友复仇，所以选择了离开这里，去成长，去变强。"] = "……<P_Heart>(Долгое молчание)</>Потому что я хочу отомстить за своего друга, поэтому я решил уйти отсюда, вырасти, стать сильнее.",
    ["…………我好像明白了。"] = "…………Думаю, я понимаю.",
    ["……一杯。"] = "……Один стакан.",
    ["……不会。"] = "...Не буду.",
    ["……不知道，这里很安静，不用思考。"] = "...Не знаю, здесь очень тихо, можно ни о чём не думать.",
    ["……不！！我的完美反派——我的鲜血盛宴！！"] = "……Нет!! Мой идеальный злодей — мой кровавый пир!!",
    ["……也没什么特别的。我住在贝克兰德桥区的一间小公寓，我和母亲相依为命。"] = "……Ничего особенного. Я жил в маленькой квартирке в районе Бэкланд-Бридж, и мы с матерью зависели друг от друга.",
    ["……也许吧。但据我所知，高序列的材料会更加昂贵。"] = "...Возможно. Но, насколько мне известно, материалы для высоких Последовательностей стоят ещё дороже.",
    ["……亡灵？！"] = "...Нежить?!",
    ["……什么都不需要。"] = "……Ничего не нужно.",
    ["……什么都愿意……您的魅力……"] = "...Всё, что угодно... Ваше очарование...",
    ["……他从地上起来了，“诅咒”也算是解除了吧。"] = "……Он поднялся с земли, «Проклятие» можно считать снятым, верно?",
    ["……他几年前去世了。"] = "...Он скончался несколько лет назад.",
    ["……你们不懂，你们从来不想懂。"] = "…Вы ничего не понимаете и никогда не хотели понять.",
    ["……你们在干什么？"] = "……Что ты делаешь?",
    ["……你占卜的结果是对的吗？"] = "...Ваше предсказание верно?",
    ["……你昨天不是问过吗？"] = "……Разве ты не спрашивал вчера?",
    ["……你说什么？"] = "……Что вы сказали?",
    ["……你还真会起名字。"] = "……Ты действительно умеешь называть вещи.",
    ["……危险……我来保护您……"] = "...Опасность... Я защищу вас...",
    ["……可惜神不会创造同样的灵魂两次。"] = "……Жаль, что Бог не создаст одну и ту же душу дважды.",
    ["……可能您坐过我的马车，女士。"] = "……Возможно, вы ездили в моей карете, мадам.",
    ["……呃。"] = "……Эм-м-м.",
    ["……哈哈。"] = "……Ха-ха.",
    ["……唯有亲眼所见的恶徒鲜血，才能换得泰利和奥莉薇的安息。"] = "……Только кровь злодеев, увиденная моими собственными глазами, может принести Терри и Оливии покой.",
    ["……嘿嘿。"] = "...хе-хе.",
    ["……因为在等待戈多？"] = "……Из-за ожидания Годо?",
    ["……在这一点上，我后悔与蒸汽教会走得太近。"] = "…В этот момент я сожалею, что подошел слишком близко к Церкви Пара.",
    ["……学会系鞋带了吗？这次没人帮你了……别被绊倒了……"] = "……Ты научился завязывать шнурки? На этот раз здесь нет никого, кто мог бы вам помочь… не сбивайтесь с толку…",
    ["……安全起见，不能叫醒他，必须先送他回去。"] = "...Ради безопасности будить его нельзя, нужно сперва доставить его обратно.",
    ["……对。每一个来买瓜的，都是。"] = "...верно. Каждый, кто приходит купить дыни, так и делает.",
    ["……就在这里？"] = "……Прямо здесь?",
    ["……居然如此华丽精美，完全是我的那些珍藏衣饰比不过的……不，只是差一点点……好吧，差挺多的。"] = "...Она настолько великолепна и изысканна, что совершенно не сравнима с моей коллекцией одежды... Нет, это немного... ладно, это совсем другое.",
    ["……已经等了很久吗？"] = "...Давно уже ждете?",
    ["……布雷登，你说的那场战争——"] = "…Брэйден, та война, о которой ты упомянул…",
    ["……怎么会如此华丽精美？之前我以为私人高端定制的翅膀就足够完美了，如今看来在这双翅膀面前简直不堪一击。"] = "……Как это могло быть так великолепно и изысканно? Раньше я думал, что частные элитные крылья достаточно совершенны, но теперь они кажутся уязвимыми перед этой парой крыльев.",
    ["……总之，一切都弄清楚了。那就离开这里吧。"] = "……В любом случае, теперь все ясно. Давай покинем это место.",
    ["……您看出来了？这是我自己做着玩的小东西。"] = "……Вы заметили? Это небольшая вещь, которую я сделал для развлечения.",
    ["……您确定她会喜欢这个“回报”吗？"] = "...Вы уверены, что ей придется по душе такая «награда»?",
    ["……我家里已经没人了。"] = "……В моей семье никого не осталось.",
    ["……我想做一名蒸汽机械师。"] = "……Я хочу быть паровым механиком.",
    ["……我想做得更好。"] = "...Я хочу сделать всё ещё лучше.",
    ["……我打算回老街。"] = "...Я собираюсь вернуться на Старую улицу.",
    ["……我教你一个买水果的技巧吧。"] = "……Позвольте мне научить вас, как покупать фрукты.",
    ["……我的琴声能让人分手？"] = "……Моя игра на фортепиано может заставить людей расстаться?",
    ["……我这样？"] = "……Так?",
    ["……抱歉。"] = "……Извини.",
    ["……拿着它，你会回家的……孩子。"] = "...Возьми его, ты вернешься домой... дитя.",
    ["……搞错了？什么意思……罗珊有危险？！"] = "……Ошибка? Что ты имеешь в виду... Розанна в опасности?!",
    ["……是。"] = "...Да.",
    ["……是的。但这或许是非凡者必须承受的代价，一个时刻对抗着危险和疯狂的可怜虫。"] = "...Да. Но, возможно, это цена, которую должен платить Потусторонний: жалкий бедняга, постоянно борющийся с опасностью и безумием.",
    ["……是的，我很能够理解你，克莱恩先生。"] = "...Да, я очень хорошо вас понимаю, господин Клейн.",
    ["……是那位小姐啊。"] = "...Так это та самая госпожа.",
    ["……是酒？你跟你的酒过日子去吧！"] = "……Это алкоголь? Иди, живи своей жизнью со своим алкоголем!",
    ["……有意思。那就让我看看，你究竟能走多远。"] = "...Интересно. Тогда позволь мне посмотреть, как далеко ты сможешь зайти.",
    ["……水平还挺特别的。"] = "……Уровень совершенно уникален.",
    ["……永远臣服……永远追随……"] = "...Вечно покоряться... вечно следовать...",
    ["……牙齿尖尖？打架的茶？"] = "……Острые зубы? Боевой чай?",
    ["……猫？是猫在说……？"] = "……Кошка? Кот разговаривает...?",
    ["……玛格丽特小姐对您完全没有那种想法，她在想诊费和蛋糕。"] = "……РС. Маргарет совершенно не имеет о тебе таких мыслей; она думает о плате за консультацию и торте.",
    ["……真是奇怪，我从来不留人过夜，她叫什么？"] = "……Как странно, я никогда не позволяю людям оставаться на ночь, как ее зовут?",
    ["……确实能理解他们的反应。"] = "……Я, конечно, могу понять их реакцию.",
    ["……等等。剧情居然已经进行到这里了……可真让我意外……"] = "……Ждать. Сюжет действительно дошел до этого момента... Это меня действительно удивляет...",
    ["……罗珊这是急着去哪？"] = "……Куда Розанна так спешит?",
    ["……老头子走的时候，我说我还有孩子。"] = "...Когда старик ушел, я сказала, что у меня еще есть дети.",
    ["……蘑菇不需要光合作用。"] = "……Грибам не нужен фотосинтез.",
    ["……说来有些离奇，我的能力是从一个老太太那里得到的。是安丽萨太太，她是我的病人，那时我还是一个诊所的医生。"] = "……Это немного странно, но я получил свои силы от старушки. Это была миссис Анлиса; она была моей пациенткой, когда я еще работал врачом в клинике.",
    ["……请给我点时间，让我再考虑一下吧。"] = "……Пожалуйста, дайте мне немного времени, позвольте мне подумать об этом еще раз.",
    ["……跟我走。别惊讶，这不是条寻常路。"] = "……Подписывайтесь на меня. Не удивляйтесь, это не обычный путь.",
    ["……这是一场秘密的约会。"] = "……Это секретное свидание.",
    ["……这让我想到罗塞尔日记里，大帝说过的那句话：“占卜家”总是说一半藏一半，从来不把事情讲明白吗？"] = "…Это напоминает мне слова Императора из дневника Розелль: разве «Провидцы» не всегда говорят половину правды, скрывая другую половину, и никогда не объясняют всё до конца?",
    ["……那好吧。"] = "……Ну ладно.",
    ["《变态开膛手杰克》……这出戏里的受害者最让人心疼了，您觉得怎么样？"] = "《Джек-Потрошитель》... Жертва в этой пьесе самая душераздирающая. Что вы думаете?",
    ["《机械屋解谜手册》？打开看看……"] = "«Руководство по головоломкам с механическим домом»? Давай я открою и посмотрю...",
    ["一个人的态度，怎么会无缘无故变这么多？态度的变化，会是他行凶的理由吗？"] = "Как отношение человека может измениться столь резко без всякой видимой причины? Могло ли это изменение стать мотивом для преступления?",
    ["一个好的占卜师，解读的不仅是牌面。"] = "Хороший предсказатель интерпретирует не только карты.",
    ["一个施加了简单封印的宝箱。我们的目标，就是解除它。这正是一个非常适合初学者练习的“解除封印”仪式。"] = "Сундук, защищенный простым запечатыванием. Наша цель — снять его. Это идеальный ритуал распечатывания для тренировки новичков.",
    ["一个曾经舍命救下男爵的人，出于什么理由才会行凶？"] = "По какой причине тот, кто однажды рисковал своей жизнью ради спасения барона, совершил такое преступление?",
    ["一代又一代的人们坚持了下来，期待造物主能重新将目光投向这个被祂遗弃的地方。"] = "Поколение за поколением люди упорствовали, надеясь, что Создатель еще раз бросит Свой взор на это место, которое Он покинул.",
    ["一切还好吗？"] = "Все ли в порядке?",
    ["一只小猫！"] = "Котёнок!",
    ["一同等待戈多。"] = "Вместе в ожидании Годо.",
    ["一周后她坟头长了一棵藤，开着不合季节的花。后来藤蔓结出了这些南瓜。"] = "Через неделю на ее могиле выросла виноградная лоза, цветущая несезонными цветами. Позже на лозах появились эти тыквы.",
    ["一声枪响在寂静的雪原上回荡。乌鸦没有倒下，但也没有飞远，仿佛没听到一般在原地张望。"] = "Выстрел эхом разнесся по тихим заснеженным равнинам. Ворона не упала, но и не улетела далеко, как будто не услышала ее, оглядываясь на месте.",
    ["一定是它们位置变了，吸走了我的幸运！你说可不可怕！"] = "Они наверняка сместились со своих мест и высосали всю мою удачу! Скажи, разве это не жутко?!",
    ["一定！"] = "Определенно!",
    ["一封信件。打开看一下吧。"] = "Письмо. Давайте откроем его и посмотрим.",
    ["一年晋升序列8，再一年序列7，三年到序列6，是非常有天赋的非凡者。"] = "За год повысился до Последовательности 8, ещё через год до Последовательности 7, за три года достиг Последовательности 6 — весьма одарённый Потусторонний.",
    ["一开始我以为阿尔伯特得了老年病……后来发现是被封印物影响了。"] = "Сначала я подумал, что у Альберта старческая болезнь... но потом понял, что на него повлиял Запечатанный Артефакт.",
    ["一旦遇到队友失控，不管归属于哪只队伍，我们都会出手帮忙。"] = "Если кто-то из товарищей потеряет контроль, мы придем на помощь вне зависимости от того, из какого он отряда.",
    ["一本笔记？上面写着……《睡莲镇漫游指南》？"] = "Блокнот? Там написано... \"Путеводитель по городу водяных лилий\"?",
    ["一样等戈多么？是的。"] = "Все равно ждете Годо? Да.",
    ["一次又一次……他展现的知识，他回应的祈求，他对塔罗会和白银城的庇护……"] = "Снова и снова… знания, которые он являл, мольбы, на которые он отвечал, его покровительство Клубу Таро и Серебряному городу…",
    ["一直到头发花白，才明白自己当初了解的知识，还只是神秘学入门的程度。"] = "Только когда мои волосы поседели, я осознал, что знания, которые я понял тогда, находились только на вводном уровне оккультизма.",
    ["一群调皮的小孩正兴奋地四散奔逃，躲进各个角落里。"] = "Гурьба озорных ребятишек с визгом разбегается во все стороны, прячась по углам.",
    ["一腔热血的副队长"] = "Страстный вице-капитан",
    ["一说起药剂我就停不下来，那些老东西每次都嫌我吵……"] = "Я не могу остановиться, когда начинаю говорить о зельях; эти старые дураки всегда жалуются, что я шумный...",
    ["一起加油吧，{{PlayerName}}。努力提升自己，总有一天，我们都会回到故乡。"] = "Давайте усердно работать вместе, {{PlayerName}}. Стремитесь совершенствоваться, и однажды мы оба вернемся в свой родной город.",
    ["三个异常。"] = "Три аномалии.",
    ["三十八年，我花了三十八年证明这条猜想。还是不对……我没有第二个三十八年了。"] = "Тридцать восемь лет я потратил тридцать восемь лет на доказательство этой гипотезы. Всё-таки не так... У меня нет второго тридцать восемь лет.",
    ["三十年？我感觉才一小会儿。"] = "Тридцать лет? Такое ощущение, что прошло совсем немного времени.",
    ["三十年？那时候的戈多还是我们等的戈多吗？"] = "Тридцать лет? Является ли Годо того времени тем Годо, которого мы ждем?",
    ["三千七百。我一辈子记录了三千七百种植物。"] = "Три тысячи семьсот. За всю жизнь я описал три тысячи семьсот видов растений.",
    ["三年了，它停了三年……修好它，或许不难。"] = "Три года... оно простояло три года. Починить его, возможно, не так уж трудно.",
    ["三年前，整个世界都被卷入了战争的时候，这里也没有例外。"] = "Три года назад, когда весь мир был втянут в войну, это место не стало исключением.",
    ["三段式尊名不仅是一个名字，它更接近一种神性的注视、一种召唤的咒文。"] = "Трехчастное почетное имя – это не просто имя, оно ближе к божественному взору, заклинанию призыва.",
    ["上次东区有个代罚者失控，就是我跟斯维因一起解决的。"] = "В прошлый раз Благословенный Ветром потерял контроль над Восточным округом, и мы со Свейном решили эту проблему.",
    ["下一幕"] = "Следующая сцена",
    ["下次有事直接说，妈妈保证不骂你。"] = "В следующий раз скажи мне прямо. Мама обещает не ругать тебя.",
    ["不……不要！"] = "Нет... нет!",
    ["不……现在不是时候。观众不登台。先看接下来会发生什么。"] = "Нет... сейчас не время. Зритель не выходит на сцену. Посмотрим, что будет дальше.",
    ["不……这怎么可能？！"] = "Нет... как это возможно?!",
    ["不。我知道我做了什么。"] = "Нет, я знаю, что я сделал.",
    ["不为什么，再见。"] = "Без причины, до свидания.",
    ["不了不了，我不怎么会玩……"] = "Нет-нет, я правда не умею играть...",
    ["不会被卖出的，永远陪伴着“工匠”的。"] = "То, что никогда не будет продано и навеки останется с «Ремесленником».",
    ["不会觉得吓人吗？"] = "Тебе не кажется, что это страшно?",
    ["不可能……这东西怎么回来了？！"] = "Невозможно... как эта штука вернулась сюда?!",
    ["不可能！她明明经常来！还一直看着我！"] = "Невозможный! Она явно приходит часто! И она продолжает смотреть на меня!",
    ["不可能，我和那些陌生人合作了，他们不可能背叛我，不可能抢走我的战利品！"] = "Не может быть, я сотрудничал с этими незнакомцами, они не могли предать меня и не могли отнять мою добычу!",
    ["不在乎喵，我只关心什么时候开饭喵。"] = "Мне все равно, мяу. Меня волнует только то, когда нас покормят, мяу.",
    ["不太对？哪里不对？"] = "Не совсем так? В чем дело?",
    ["不好说。她有时候一周来两回，有时候半个月不见人。"] = "Трудно сказать. Иногда она приходит два раза в неделю, иногда ее нет на полмесяца.",
    ["不好，是被那个女孩困在了这个城堡吗，得设法离开！"] = "О нет, эта девушка заперла меня в этом замке? Я должен найти способ уйти!",
    ["不好，那本日记是她不愿面对这一切的心，它要靠近碎片，把记忆藏起来。"] = "О нет, этот дневник — ее сердце, которое не хочет смотреть в лицо всему этому. Он хочет приблизиться к фрагменту и скрыть воспоминание.",
    ["不如去教堂祈祷一下吧。"] = "Почему бы не пойти в церковь и не помолиться?",
    ["不如让我们……亲身体验一下吧？"] = "Почему бы нам не... опробовать это на собственном опыте?",
    ["不完全是，一般来说，“不眠者”序列的同事成为“午夜诗人”后，会为了消化魔药去写诗。"] = "Не совсем. Как правило, коллеги Последовательности \"Бессонный\", становясь \"Полуночным Поэтом\", начинают писать стихи, чтобы переварить Зелье.",
    ["不对。刚才在墓碑前，她一直在说凯瑟琳的死，说自己的愧疚。"] = "Это неправильно. Только что перед надгробием она все говорила о смерти Екатерины и собственной вине.",
    ["不对。还是不对。"] = "Неправильный. Все еще неправильно.",
    ["不对不对。海莉夫人不是这样说的。"] = "Нет, нет. Это не то, что сказала мадам Хейли.",
    ["不对，发生了什么？！"] = "Нет, что случилось?!",
    ["不属于这个时代的愚者"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者——"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者啊……"] = "Шут, не принадлежащий этой эпохе",
    ["不属于这个时代的愚者，灰雾之上的神秘主宰，执掌好运的黄黑之王。"] = "Шут, не принадлежащий этой эпохе, таинственный правитель над серым туманом, Король Желтого и Черного, приносящий удачу.",
    ["不必客气，探索神秘的道路上，分享知识是应有的美德。"] = "Пожалуйста. Обмен знаниями — это добродетель, которую следует поддерживать на пути исследования таинственного.",
    ["不必露出忧伤的表情，比起其他，这并不算坏。"] = "Не нужно показывать грустное выражение лица; по сравнению с остальными вещами это неплохо.",
    ["不愧是“愚者”先生，祂在真正地关心着底层人民的生活。赞美愚者！有机会，我一定要去基金会实地拜访一下。"] = "Как и ожидалось от Мистераа, Он действительно заботится о жизни людей внизу. Слава Шуту! Если у меня будет возможность, я должен посетить фонд лично.",
    ["不提这些旧事了，{{先生|女士}}，别让这些影响您欣赏山脚下的景色。"] = "Давай не будем говорить об этих старых вещах, {{Mr.|Ms.}}. Не позволяйте этому повлиять на ваше удовольствие от пейзажей у подножия горы.",
    ["不是。但你可以叫我伯爵阁下。"] = "Нет. Но ты можешь звать меня граф.",
    ["不是你的错，他们本来就有矛盾。"] = "Вы не виноваты, у них изначально конфликты.",
    ["不是因为它被偷走，而是发现自己突然产生了强烈的回家欲望。"] = "Дело не в том, что его украли, а в том, что я вдруг почувствовал сильное желание вернуться домой.",
    ["不是我。"] = "Это был не я.",
    ["不是我想唱，是魔药的要求。想消化“海洋歌者”的魔药，必须在海上歌唱，用歌声引发风暴。"] = "Дело не в том, что я хотел петь; это было требованием зелья. Чтобы переварить зелье «Морской король», нужно петь в море, используя голос, чтобы вызвать шторм.",
    ["不是改变占卜。是改变“解读”塔罗的方式。"] = "Дело не в изменении гадания. Дело в изменении способа «толкования» Таро.",
    ["不是昨天，不是明天，不是三十年后。"] = "Не вчера, не завтра, не тридцать лет спустя.",
    ["不是每天。只是……每一便士都有它的用处。省下来的钱，可以买一本参考书，或者让哥哥少加一次班。"] = "Не каждый день. Просто... каждая копейка имеет свое применение. На сэкономленные деньги можно купить справочник или позволить моему брату работать на одну сверхурочную смену меньше.",
    ["不止，我开门穿墙，专挑那些克扣工钱的贵族捉弄，偷他们的钱，分给街坊邻居。"] = "Не только это: я открываю двери, прохожу сквозь стены, выбираю знатных скупердяев, которые урезают жалованье, подшучиваю над ними, ворую их деньги и раздаю соседям.",
    ["不用太有压力，你还只是非凡世界的新生。在你成长起来之前，我们不会让你面对到那些恐怖的存在。"] = "Не переживай так сильно, ты ещё новичок в Потустороннем мире. Пока ты не окрепнешь, мы не позволим тебе столкнуться с теми ужасными существами.",
    ["不用担心，我们为你准备了一个身份——恩马特港的外贸商人。今晚黑伍德庄园将举办一场投资晚宴，你可以用这封邀请函进入庄园舞会。"] = "Не волнуйтесь, мы подготовили для вас личность — внешнеторгового торговца из Порта Энмат. Сегодня вечером в поместье Хейвуд состоится инвестиционный ужин, и вы сможете использовать это приглашение, чтобы попасть на бал в поместье.",
    ["不用谢，你得需要一笔“启动资金”嘛。"] = "Пожалуйста, в конце концов вам нужен «стартовый капитал».",
    ["不看"] = "Не смотреть",
    ["不知道的别乱打听，小心执行就是了。"] = "Не расспрашивай о том, чего не знаешь, просто выполняй приказ осторожно.",
    ["不知道这个“它”，如今还在不在这里……\n<P_Yellow>（获得了线索并放入背包：日记残片）</>"] = "Интересно, здесь ли это «оно» сегодня...\n<P_Yellow> (Подсказка получена и добавлена ​​в инвентарь: Фрагмент дневника)</>",
    ["不知道，她从来不跟我们提这些。每年这时候她都去，说是去看一位故人。"] = "Нет, она никогда не упоминает нам об этих вещах. Каждый год она уезжает в это время, говоря, что собирается навестить старого друга.",
    ["不能急。弗莱说过，观众最重要的是观察。再等等。"] = "Я не могу торопиться. Фрай сказал, что самое важное для зрителя — это наблюдать. Подождем еще немного.",
    ["不能，我们哪也不去。 "] = "Нет, мы никуда не пойдем.",
    ["不要啊，我亲爱的艾米——每天两杯！"] = "Не надо, моя дорогая Эми, два стакана в день!",
    ["不许更改！把你的手拿开！所有的<P_Yellow>角色</>都已经就位 ，谁也别想来打断这场完美的处刑！"] = "Никакие изменения не допускаются! Убери руки! Все символы <P_Yellow> </> находятся на своих местах; никому не позволено прерывать это идеальное исполнение!",
    ["不论如何，谢谢你。我想我很快就要和他们团聚了……"] = "Несмотря ни на что, спасибо. Я думаю, что скоро воссоединюсь с ними...",
    ["不过……<P_Heart>（表情柔和）</>其实我很感激他们。"] = "Однако... <P_Heart>(Выражение смягчается)</> на самом деле, я им очень благодарен.",
    ["不过……为了保护他们，我现在尽量不和他们见面。非凡世界太危险了，我不想让危险波及到他们。"] = "Однако... чтобы защитить их, я стараюсь их сейчас не видеть. Необыкновенный мир слишком опасен, и я не хочу, чтобы опасность достигла их.",
    ["不过他去了一趟贝克兰德，回来就变了个人……到处扔这块怀表，但怀表总会回到他手里……"] = "Но однажды он поехал в Бэкланд и вернулся другим человеком... он повсюду разбрасывает эти карманные часы, но они всегда возвращаются к нему в руку...",
    ["不过他至少付钱了。比某些客人强。"] = "По крайней мере, он заплатил. Лучше, чем некоторые клиенты.",
    ["不过以前在值夜者娱乐室，我经常弹曲子给队员们听。"] = "Однако, вернувшись в комнату отдыха «Ночных ястребов», я часто играл для участников команды мелодии.",
    ["不过序列9的能力有限，更多是理论上的认识。"] = "Впрочем, возможности Последовательности 9 ограничены, это в основном теоретические познания.",
    ["不过我怀疑他根本不会和我打。阿尔弗雷德先生是那种很讲规矩的人——他为什么要和一条狗打架呢？"] = "Однако я сомневаюсь, что он вообще будет драться со мной. Мистер Альфред относится к тому типу людей, которые очень требовательны к правилам: зачем ему драться с собакой?",
    ["不过我那时太小，并不记得这些了，是长大后看卷宗才了解的。"] = "Но я тогда был слишком молод, я этого не помню. Я узнал об этом только после прочтения файлов, когда вырос.",
    ["不过有一件还算幸运的好事。"] = "Но есть одно счастье.",
    ["不过没关系，我们可以把墓建在这里，就当是大家陪他一起。"] = "Но ничего страшного. Мы можем устроить могилу прямо здесь — так мы все будем рядом с ним.",
    ["不过现在也挺好，看书，研究神秘学，教教你们这些年轻人。"] = "Но сейчас довольно хорошо читать книги, изучать оккультизм и учить вас, молодежь.",
    ["不过非要说的话，我喜欢观察植物生长。看着一颗种子从土里钻出来，慢慢长高，长出叶子，开花结果——这个过程太美妙了。"] = "Но если мне пришлось сказать, мне нравится наблюдать за ростом растений. Наблюдать, как семя прорастает из почвы, медленно растет, пускает листья, цветет и приносит плоды — этот процесс просто чудесен.",
    ["不过，你的建议有一定的价值。我会和他们提议的。"] = "Однако ваше предложение имеет определенную ценность. Я им это предложу.",
    ["不过，你知道有关学校的初代校长雕像的事吗？听说对着它许愿往往都能应验……"] = "Однако знаете ли вы о статуе первого директора школы? Я слышала, что загаданное желание часто сбывается...",
    ["不过，发生在这片雪山上，倒也不奇怪。"] = "Однако неудивительно, что это произошло именно на этой заснеженной горе.",
    ["不过，她这次去得有点久了，不会出什么事吧？"] = "Однако на этот раз ее не было немного долго. Могло ли что-то случиться?",
    ["不过，我并非现在的“拜朗人”，我所属的国家是拜朗帝国。"] = "Однако я не «Балам» настоящего; страной, к которой я принадлежал, была Империя Балам.",
    ["不过，我看得出来，他和我很不一样。我刚来这里的时候，把这里当做游戏，玩得很爽，很开心。"] = "Однако я могу сказать, что он сильно отличается от меня. Когда я впервые приехал сюда, я относился к этому месту как к игре и играл очень весело и радостно.",
    ["不过，我要提醒你一下，“神降”仪式还需要准备其他材料，记得收集齐再来开启仪式。"] = "Однако я должен напомнить вам, что ритуал «божественного спуска» требует и других материалов; не забудьте собрать их все перед началом ритуала.",
    ["不过，正因如此，我们才更要努力变强，守护平静的日常生活不被打扰。"] = "Однако именно поэтому мы должны стремиться стать сильнее, чтобы защитить нашу мирную повседневную жизнь от нарушения.",
    ["不过，至少他不用为后半生无法画画而伤心了，哈哈……唉……"] = "Но, по крайней мере, ему не нужно грустить из-за того, что он не сможет рисовать до конца своей жизни, хаха... вздох...",
    ["不过，血液也是液体，记得不要在里面浪费太多时间。"] = "Но кровь тоже жидкость, не трать на неё слишком много времени.",
    ["不这么做的话，我怎么追捕一个海上的亡命徒？向格尔曼·斯帕罗祈祷吗？"] = "Если я этого не сделаю, как я смогу выследить беглеца в море? Помолиться Герману Воробью?",
    ["不重要，我们等的戈多说好今天来。"] = "Неважно. Годо, которого мы ждем, обещал прийти сегодня.",
    ["不错，还有呢。"] = "Неплохо, что еще?",
    ["不需要，谢谢。"] = "Нет, спасибо.",
    ["不，他很喜欢讲冷笑话。尤其是关于以前的房东弗兰奇先生的。"] = "Нет, он любит рассказывать отцовские анекдоты. Особенно о нашем бывшем хозяине, мистере Фрэнке.",
    ["不，我不是戈多，我来错了。"] = "Нет, я не Годо, я пришел не туда.",
    ["不，我并不为此感到伤心。那些记忆很久远，而且，那时的我人性淡漠，对这一切并没有真切的感知。"] = "Нет, мне не грустно по этому поводу. Эти воспоминания очень далеки, и в то время моя человечность была безразлична, поэтому у меня не было настоящего восприятия всего этого.",
    ["不，我是想弄清楚残影是什么，防止这里有非凡力量外泄。看来，您也是非凡者？"] = "Нет, я просто хочу выяснить природу этих остаточных теней, чтобы не допустить утечки потусторонней силы. Похоже, вы тоже Потусторонний?",
    ["不，指南针只是放大了我内心的胆怯，困住旅行者的，是他们自己的心。"] = "Нет, компас лишь усилил робость в моём сердце. Путника сковывает его собственное сердце.",
    ["不，这栋宅子还在，那位老爷的后人也还在。"] = "Нет, этот особняк всё еще стоит, и потомки того господина тоже живы.",
    ["与马车夫交流可以知道，开膛手应该是在<P_Yellow>警局外</>被终结，在剧本上记录一下吧。"] = "Из разговора с кучером выясняется, что с Потрошителем было покончено <P_Yellow>у полицейского участка</>. Запишите это в сценарий.",
    ["丢失塔罗牌的占卜师"] = "Прорицатель, потерявший карты Таро",
    ["两位有选定的花束吗？"] = "У вас двоих есть выбранный букет?",
    ["两千五百八十三年间，被神遗弃的黑暗之民，生活在宿命的诅咒之中。"] = "Две тысячи пятьсот восемьдесят три года темный народ, оставленный Богом, жил под проклятием судьбы.",
    ["两千多年里，正神从未垂怜过我们。黑暗里只有祂回应了我，带来了……希望。"] = "На протяжении более двух тысяч лет истинные боги ни разу не проявили к нам милосердия. Только Он ответил мне во тьме, принеся... надежду.",
    ["两千苏勒一磅。"] = "Две тысячи суле за фунт.",
    ["两次遇见那位猎人，他似乎都想说些什么。"] = "Оба раза я встречал этого охотника, он как будто хотел что-то сказать.",
    ["严格来说，我第一次和他认真交谈，是在梦里。"] = "Строго говоря, мой первый серьезный разговор с ним был во сне.",
    ["为了书里那段推理情节，你知道我掉了多少根头发，失了多少次眠吗？"] = "По этому рассуждению в книге знаете ли вы, сколько волос я потерял и сколько раз страдал от бессонницы?",
    ["为了更好地理解人类，也为了更好地陪伴奥黛丽。"] = "Чтобы лучше понимать людей и лучше сопровождать Одри.",
    ["为了重要的人，谁都可以变勇敢……"] = "Ради важных людей каждый может стать храбрым...",
    ["为什么不能？"] = "Почему нет?",
    ["为什么这么说？"] = "Почему ты так говоришь?",
    ["为什么，为什么？为什么他明知道死亡，还是走了进来？"] = "Почему, почему? Почему он вошел, хотя знал, что это означает смерть?",
    ["为什么？"] = "Почему?",
    ["为什么？为什么我就不用代价。"] = "Почему? Почему мне не приходится платить цену?",
    ["为什么？你明明是从小陪伴他的管家，为什么要谋害霍克斯男爵？"] = "Зачем? Вы же служили ему с самого его детства... Почему вы решили убить барона Хоукса?",
    ["为什么？管家想做什么？男爵又在做什么？"] = "Почему? Что хочет сделать дворецкий? И что делает барон?",
    ["为什么？贝克兰德可是大都市，机会更多吧？"] = "Почему? Бэкланд – мегаполис, наверняка там больше возможностей?",
    ["举个例子，假如你是“占卜家”，就可以考虑去占卜俱乐部，或是到街边支个占卜摊子，替人占卜，收获反馈。"] = "Например, если вы «Провидец», можно рассмотреть поход в Клуб Провидцев или установку гадальной палатки на улице, чтобы гадать людям и получать отклик.",
    ["之后再把脚踏车股票质押给银行，用贷款归还前面的贷款。"] = "После этого заложите запасы велосипедов в банке и используйте кредит для погашения предыдущего кредита.",
    ["乐意效劳。"] = "Рад был помочь.",
    ["乔安娜抽到宝剑十。我告诉她，这是终结和失败，练得再好也上不了大城市的舞台。"] = "Джоанна вытянула Десятку Мечей. Я сказал ей, что это означает финиш и провал, и что как бы хорошо она ни тренировалась, ей никогда не выйти на сцену большого города.",
    ["也不能说完全不会，我其实有努力过的，但每次念完，别人的表情都有些奇怪。"] = "Нельзя сказать, что я совсем не умею... Я правда старался, но каждый раз, когда я заканчивал декламировать, у людей были такие странные лица.",
    ["也会让她最终在没有痛苦的美梦中离开。"] = "И позволит ей в конце концов уйти без боли, в сладком сне.",
    ["也发现了密室的真相。"] = "Вы также узнали правду о запертой комнате.",
    ["也告诉你的战友们，巡逻时离那里远点，那儿的寒冷不正常。遇见古怪的情况也最好不要惊扰，这都是保命的办法……"] = "Передай и своим товарищам: во время патруля пусть держатся подальше оттуда, тот холод ненормален. А встретив что-то странное, лучше не тревожить это. Всё это способы сохранить жизнь...",
    ["也就是说，你对我完全没有敌意？也不想利用我？这还真是新奇。"] = "Другими словами, у вас нет ко мне абсолютно никакой неприязни? И ты не хочешь меня использовать? Это действительно ново.",
    ["也意味着要离开黑荆棘。"] = "Это также означает необходимость покинуть Чёрный Чертополох.",
    ["也救了我。"] = "Меня тоже спас.",
    ["也是在我学会说话之后，没有把我当成怪物的人。"] = "А еще она не считала меня чудовищем после того, как я научилась говорить.",
    ["也祝您好运！"] = "Удачи и тебе!",
    ["也许下面有什么线索，先清理出来看看吧。"] = "Возможно, под ним есть подсказки. Давайте уберем это и посмотрим.",
    ["也许他有事耽搁了。"] = "Возможно, его что-то задержало.",
    ["也许你对星相的解读错了？"] = "Возможно, ваша интерпретация астрологии неверна?",
    ["也许可以用那辆炮车，把我送过去。"] = "Возможно, я смогу использовать эту пушечную лафету, чтобы отправить меня туда.",
    ["也许吧，昨天，今天，明天，我没有留意。"] = "Может быть. Вчера, сегодня, завтра я не обращал внимания.",
    ["也许报销要适度，毕竟经费有限……您喜欢在教会工作吗？"] = "Возможно, возмещение должно быть умеренным, ведь средства ограничены... Вам нравится работать в Церкви?",
    ["也许茶会主人的线索和猫有关？"] = "Возможно, ключ к разгадке ведущего чаепития связан с котом?",
    ["也许这样的感情，只有同为老乡的你，才能够理解吧。"] = "Пожалуй, только ты, как земляк, можешь понять такие чувства.",
    ["也谢谢你……没有丢下我。"] = "И спасибо... что не бросил меня.",
    ["习惯就好了。"] = "Вы привыкнете к этому.",
    ["乡下钟表匠，修一辈子表，也做不出像样的东西。"] = "Деревенский часовщик за всю жизнь только и может, что чинить стрелки, а ничего путного так и не смастерит.",
    ["书桌表面看起来有些污渍和划痕，但都是可以去除的。我检查了抽屉的滑轨和桌腿的接合处，其实结构还很结实。"] = "Поверхность стола выглядела так, будто на ней были пятна и царапины, но все их можно было удалить. Я проверил направляющие ящиков и соединения ножек стола; на самом деле конструкция все еще была очень прочной.",
    ["书？书上的东西，怎么会错呢？"] = "Книга? Как вещи в книге могут быть неправильными?",
    ["书？我能看看吗？"] = "Книги? Могу ли я взглянуть?",
    ["买下材料"] = "Купить материалы",
    ["买炸鸡？"] = "Купить жареную курицу?",
    ["买过的人都说——值。但有几个人买了之后再也没回来。"] = "Все, кто их покупал, говорили — оно того стоило. Но некоторые люди так и не вернулись после их покупки.",
    ["了解俱乐部"] = "Поймите клуб",
    ["争论？呵呵，只是就一些研究和我的学生彼此交流罢了，谈不上争论。"] = "Аргумент? Хех, это просто обмен исследованиями с моими учениками, это не считается аргументом.",
    ["事情不对劲，相信我。"] = "Что-то не так, поверь мне.",
    ["于是我把海鱼的基因和卷心菜结合了一下。结果是——它能长在海里了，但吃起来有鱼腥味。"] = "Поэтому я объединил гены морской рыбы с капустой. В результате он может расти в море, но на вкус он рыбный.",
    ["于是相聚在这里。"] = "И вот мы собрались здесь.",
    ["亨利先生，你好好看看，这就是艾米莉亚，你的未婚妻。"] = "Мистер Генри, посмотрите внимательно. Это Амелия, ваша невеста.",
    ["亲爱的——我来了——"] = "Дорогая, я здесь.",
    ["亲爱的弟弟，恭喜我吧！这是一位占星大师！"] = "Мой дорогой брат, поздравь меня! Это мастер астрологии!",
    ["亲爱的！"] = "Милый!",
    ["亲爱的，为什么我记得罗塞尔大帝写过一样的诗？"] = "Дорогая моя, почему я помню, что император Розель писал то же самое стихотворение?",
    ["亲爱的，我为你写了一首诗。"] = "Моя дорогая, я написала для тебя стихотворение.",
    ["人品"] = "Характер",
    ["人类发明了这么多复杂的理论，却常常忽略最简单的直觉。"] = "Люди изобрели так много сложных теорий, но часто игнорируют простейшую интуицию.",
    ["人类总觉得治疗是单向的——医生治疗病人，强者帮助弱者。但奥黛丽教会我：真正的关系，是互相看见。"] = "Люди всегда думают, что исцеление одностороннее: врачи лечат пациентов, сильные помогают слабым. Но Одри научила меня: настоящие отношения – это видеть друг друга.",
    ["人类的“深暗时代”，到来了。"] = "Наступила «Тёмная эра» человечества.",
    ["人类的误区就在于，总觉得狗应该是笨的、简单的、只能摇尾巴的。"] = "Непонимание людей состоит в том, что они всегда считают, что собака должна быть глупой, простой и способной только вилять хвостом.",
    ["人类要是像木偶那样安静就好了，还是待在家里好啊。"] = "Если бы только люди были такими же тихими, как марионетки; лучше остаться дома.",
    ["什……什么？这是……这……"] = "Ч-что?.. Это же... это...",
    ["什么回来了？"] = "Что сюда вернулось?",
    ["什么意思？"] = "Что это значит?",
    ["什么意思？你……在求我跳崖自杀？"] = "Что ты имеешь в виду? Ты... просишь меня прыгнуть со скалы и покончить жизнь самоубийством?",
    ["什么样的理由呢？"] = "Что это была за причина?",
    ["什么理由？"] = "Какая причина?",
    ["什么秘密？有什么是我可以了解的吗？"] = "Какие секреты? Есть ли что-нибудь, о чем я могу знать?",
    ["什么都可以算，除了三种。"] = "Я могу угадать всё, кроме трёх вещей.",
    ["什么都吵，开门吵，收摊吵，你碍我晾香肠、我挡你搬蔬菜……一天天可热闹了。"] = "Все — ссора: открыть дверь — ссора, закрыть ларек — ссора, ты мешаешь мне вешать колбасы, я мешаю тебе передвигать овощи... так оживленно каждый божий день.",
    ["什么都没发生。"] = "Ничего не произошло.",
    ["什么钱？"] = "Какие ещё деньги?",
    ["什么，我的火腿也熏得你难受？不懂欣赏的蠢货，那是腌制的香味！"] = "Что, моя ветчина тебе тоже неприятна? Ты идиот без вкуса, это аромат исцеления!",
    ["什么？"] = "Что?",
    ["什么？我自己捡回来的？！"] = "Что? Я сам это нашел?!",
    ["什么？苏茜女士在隐身？"] = "Что? Мисс Сьюзи невидима?",
    ["什么？这只是你的恶作剧？害死了十一个人？"] = "Что? Это была всего лишь твоя шутка? Вы стали причиной смерти одиннадцати человек?",
    ["仁慈的母亲给了我们改变世界的能力，如果我们不用，才是最大的浪费。"] = "Милосердная Матерь даровала нам силу изменить этот мир, и не использовать её было бы величайшей растратой.",
    ["仆人端着茶，是最后一个前往卧室的人。根据证言，他有说谎的可能，嫌疑很大。"] = "Слуга, принесший чай, вошел в спальню последним. Согласно показаниям, у него есть вероятность лжи, и его подозрения высоки.",
    ["仆人谎称自己听见了霍克斯男爵的声音……不对，不应该有这么多矛盾，就像是……什么地方出现了错误一样。"] = "Слуга солгал, что слышал голос барона Хоукса… нет, противоречий не должно быть так много. Как будто... где-то что-то пошло не так.",
    ["今夜邀请诸位，除共叙情谊，还有一件重要的事宣布。"] = "Приглашая вас всех сегодня вечером, помимо обмена дружбой, я также хочу объявить о важном деле.",
    ["今天就到这里吧，我也该走了。<P_Heart>（小声嘀咕）</>……从哪里搞到的这种材料，我也好想要一套。"] = "Давайте остановимся здесь на сегодня; Мне пора идти. <P_Heart> (Бормочет про себя) </>...Откуда он взял такой материал? Я тоже хочу набор.",
    ["今天带了好吃的……来，你说一句。"] = "Я сегодня принесла что-нибудь вкусненькое... давай, скажи что-нибудь.",
    ["今天有个年轻男人来找你占卜，抱着猫来的。"] = "Сегодня к вам за гаданием пришёл молодой мужчина, держащий на руках кота.",
    ["今天的整理和打扫工作也都做完了。"] = "Сегодняшняя работа по уборке и уборке тоже завершена.",
    ["今天罗珊和一个来委托的女孩成为了朋友，还约好休息日去逛街。"] = "Розель подружилась с девушкой, которая сегодня пришла выполнить задание, и они даже договорились сходить за покупками в выходной день.",
    ["从今以后，他们不必害怕、不必疼痛，更不必受苦。"] = "Отныне им не придется бояться, не испытывать боли и уж тем более не страдать.",
    ["从凯瑟琳死的那天起，我不再只读牌面。我学会了看牌背后的人。"] = "С того дня, как умерла Кэтрин, я перестал просто читать карты. Я научился смотреть на человека, стоящего за картами.",
    ["从头到尾。都<P_Yellow>只有你</>在这里，欣赏这场闹剧。"] = "От начала и до конца, <P_Yellow>, здесь был только ты, </>, наслаждаясь этим фарсом.",
    ["从居民们的聊天内容来看，剧情发生的时间应该是<P_Yellow>白昼般的夜晚</>，在剧本上记录一下吧。"] = "Судя по болтовне жителей, время действия сюжета должно быть <P_Yellow>, ночь такая же яркая, как день</>; запишите это в сценарий.",
    ["从我还是个普通水手时算起，甚至更早……很多年了。"] = "Если считать с того времени, когда я был обычным моряком, или даже раньше... прошло много лет.",
    ["从而撬动现实，实现特定的目的——无论是祈求、召唤、封印、占卜，或是其他。"] = "тем самым влияя на реальность ради достижения конкретных целей — будь то молитва, призыв, запечатывание, гадание или что-то еще.",
    ["从职员们的谈话来看，终结了开膛手的角色应该是<P_Yellow>警察队长</>，在剧本上记录一下吧。"] = "Судя по разговору персонала, персонажем, который покончил с Потрошителем, должен быть <P_Yellow>, капитан полиции </>; запишите это в сценарий.",
    ["从进出口公司到财政部，这个过程一定有很多故事吧？"] = "От импортно-экспортной компании до Министерства финансов этот процесс должен иметь множество историй, верно?",
    ["从那以后，每到周一下午三点，我就会自己走过去。有时候她还没开口，我就已经趴好了。"] = "С тех пор каждый понедельник в три часа дня я сам прихожу туда. Бывает, она еще слова не успела сказать, а я уже послушно лежу.",
    ["从那天起，我才真的走进了“学徒”身份背后的秘密。我得到了能力，也得到了……活下去的机会。"] = "С того самого дня я по-настоящему прикоснулась к тайнам, скрытым за ролью «Ученика». Я обрела силу, а вместе с ней и... шанс выжить.",
    ["仔细一看，屋子里到处都是精美的机械制品，但似乎已经很久没有人生活了。"] = "Присмотревшись, комната полна изысканных механических изделий, но кажется, что здесь уже давно никто не живет.",
    ["仔细检查了周围之后，发现了不少线索啊……"] = "Тщательно осмотрев окрестности, я нашел немало улик...",
    ["仔细观察"] = "Внимательно наблюдайте",
    ["仔细阅读内容"] = "Внимательно читайте содержимое",
    ["他……看起来比实际年龄大一些。不是因为老，是因为……操心的事情太多。"] = "Он... выглядит старше своего возраста. Не потому, что он стар, а потому, что... он беспокоится о слишком многих вещах.",
    ["他一定令您骄傲。"] = "Он должен заставить вас гордиться.",
    ["他一定是位很好的老师。"] = "Он, должно быть, очень хороший учитель.",
    ["他一直在聊工作，有点呆板，但遭受这么多次打击还在努力生活，应该是个有上进心的人。"] = "Он продолжал говорить о работе, немного скучно, но, должно быть, он амбициозный человек, раз все еще пытается жить после стольких неудач.",
    ["他不怕死。他只是觉得，活着还能做更多事。你们两个都是对的。"] = "Он не боится смерти. Он просто чувствует, что может сделать больше, пока жив. Вы оба правы.",
    ["他们只会把主人关在房间里做那些打架的茶，连去花园里玩都不让！"] = "Хозяина запирают только в комнате, чтобы заварить эти боевые чаи, а нам даже в саду играть не дают!",
    ["他们回来了！"] = "Они вернулись!",
    ["他们在争辩湖里有没有心愿女神。"] = "Они спорят о том, есть ли в озере Богиня желаний.",
    ["他们在等年轻的戈多，不是三十年后的我。"] = "Они ждут молодого Годо, а не меня через тридцать лет.",
    ["他们应该有一块所有人都能来祭拜的墓地。"] = "У них должно быть кладбище, куда каждый сможет прийти, чтобы выразить свое почтение.",
    ["他们捂着嘴巴，屏住呼吸，正等待着<P_Yellow>谁</>来寻找？"] = "Они зажимают рты, затаив дыхание, и ждут, <P_Yellow>кто</> придёт их искать?",
    ["他们是被……魅惑了？看来是魔女力量的影响。先打败他们！"] = "Их... очаровали? Похоже, это влияние силы Демоницы. Сначала победим их!",
    ["他们短期内变不回来，我也可以继续研究那些“浪费天赋”的药剂了。"] = "Некоторое время они не смогут вернуться обратно, и я могу продолжить исследование этих зелий, «тратящих талант».",
    ["他们花了很多篇幅讨论“自我认知”“童年创伤”“潜意识冲突”。"] = "Они уделяют много времени обсуждению «самопознания», «детских травм» и «подсознательных конфликтов».",
    ["他们觉得这个称呼对我来说是一种荣誉：神选定的革命者。记者、神职人员、所有人都喜欢使用这个称呼。"] = "Они думают, что это звание для меня честь: революционер, избранный Богом. Журналисты, священнослужители, все любят использовать это название.",
    ["他们说我亵渎了生命的界限。但生命本来就没有界限啊！母亲创造万物的时候，难道不是希望它们互相融合、互相成就吗？"] = "Говорили, что я осквернил границы жизни. Но жизнь не имеет границ! Когда Мать создавала все вещи, разве она не надеялась, что они сольются и достигнут друг друга?",
    ["他们都没死，我只是偷走了他们“活着”的意识，骗他们中了诅咒。"] = "Они не умерли; Я просто украл у них сознание «живости» и обманом заставил их поверить, что они прокляты.",
    ["他们都遇难了……这是真的吗？"] = "Они все погибли... Это правда?",
    ["他会是出色的值夜者……不，他已经是了。"] = "Он будет отличным Ночным Ястребом... нет, он уже им является.",
    ["他会要求从更深的角度去挖掘、佐证观点，等我们吵得不可开交，他又笑着说自己讨论得多么满足。"] = "Он потребовал бы, чтобы мы копнули глубже и нашли доказательства нашей точки зрения. Когда мы интенсивно спорили, он улыбался и говорил, насколько он удовлетворен дискуссией.",
    ["他关爱着每位生灵，哪怕你没有信仰“愚者”，依然可以享受塔罗学派的一切。"] = "Он заботится о каждом живом существе; даже если ты не веришь в «Шута», ты всё равно можешь пользоваться всем, что предлагает Клуб Таро.",
    ["他出生的时候，我就在这里。他第一次骑马，第一次打猎……我全都记得。"] = "Я был здесь, когда он родился. Его первая поездка на лошади, его первая охота... Я все это помню.",
    ["他刚才向艾琳娜点头……艾琳娜是他安排的？"] = "Он только что кивнул Елене... Елену он устроил?",
    ["他刚才连续两次说了同样的祝酒词，第二次几乎一模一样。"] = "Он просто произнес один и тот же тост два раза подряд, и второй раз был почти точно таким же.",
    ["他刚来到黑荆棘时，就和每个新人一样，什么都不懂，还是我教他神秘学课程。"] = "Когда он впервые приехал в Чёрный Чертополох, он, как и каждый новичок, ничего не понимал. Это я преподавал ему оккультные курсы.",
    ["他又喝醉了？"] = "Он снова пьян?",
    ["他吃过文化亏，所以就像支持克莱恩读大学一样，支持我的梦想。"] = "Он страдал от недостатка образования, поэтому, как он поддержал Клейна в поступлении в университет, он поддержал и мою мечту.",
    ["他对你挺好的。"] = "Он был очень добр к тебе.",
    ["他就是这样。把什么事都藏在那些不好笑的笑话里。"] = "Он именно такой. Скрывая все в этих несмешных шутках.",
    ["他就藏在这墓地的某个棺材里。"] = "Он прячется в одном из гробов на этом кладбище.",
    ["他总说标点要像婚约般严谨。"] = "Он всегда говорил, что пунктуация должна быть столь же строгой, как брачный контракт.",
    ["他是一个为弟弟妹妹着想的好哥哥。"] = "Он замечательный старший брат, который всегда заботится о младших.",
    ["他是一位旅人，和我们一样年轻。"] = "Он путешественник, такой же молодой, как и мы.",
    ["他是个好队长……本该也是个好画家。"] = "Он был хорошим капитаном... и должен был стать хорошим художником.",
    ["他是的，谢谢。"] = "Он был, спасибо.",
    ["他是罗珊的父亲，一位令人尊敬的值夜者。"] = "Он был отцом Розанны, благородным и уважаемым Ночным Ястребом.",
    ["他是那种……会让你深刻体会到社会真实性的人。"] = "Он тот человек... который заставляет тебя глубоко осознать реальность общества.",
    ["他是那种会把所有责任揽到自己身上的人，跟着他学习，对你们这群年轻人有好处。"] = "Это тот тип человека, который берет всю ответственность на себя. Учиться у него полезно для вас, молодые люди.",
    ["他现在已经是愚者教会的主教了。新白银城迁到了拜朗帝国附近，戴里克带着族人重建了家园。"] = "Сейчас он епископ Церкви Шута. Новый Город Серебра переехал недалеко от Империи Байрам, и Деррик восстановил свой дом вместе со своими членами клана.",
    ["他现在很受族人爱戴，他选了“太阳”，作为自己的代号。"] = "Теперь он очень любим своим народом; он выбрал «Солнце» в качестве своего кодового имени.",
    ["他生前答应过我，却一直没兑现。那天的曲子很长，舞步很慢……我总觉得，他终于听见了我没说出口的那些话。"] = "Он обещал мне при жизни, но так и не сдержал слова. В тот день мелодия лилась долго, па были медленными... Мне показалось, он наконец услышал всё то, о чём я не успела сказать вслух.",
    ["他的反应是真实的。是真的在拼命保护男爵。"] = "Его реакция реальна. Он действительно защищает барона ценой своей жизни.",
    ["他的智商还不如卷毛狒狒，却总能想出各种理由涨房租。"] = "Его интеллект даже не так хорош, как у кудрявого павиана, но он всегда может придумать разные причины, чтобы поднять арендную плату.",
    ["他的眼神偶尔扫向某个方向——不是看人，像在确认什么。"] = "Его взгляд изредка устремляется в определенную сторону — ни на кого не глядя, словно что-то подтверждая.",
    ["他看上去很焦急……"] = "Он выглядит очень обеспокоенным...",
    ["他答应过的，不会骗我们。"] = "Он обещал, что не будет нам врать.",
    ["他给出了答案，让他们进入了“知识领域”，但进去的人，再也没有回来。"] = "Он дал ответ, приведя их в «Область Знания», но те, кто вошел, так и не вернулись.",
    ["他罪有应得，我只想知道全部的真相。"] = "Он получил по заслугам. Я лишь хочу узнать всю правду.",
    ["他说外面的世界很大。"] = "Он говорил, что внешний мир огромен.",
    ["他说廷根有个大学城，坐飞艇能飞到云上。 "] = "Он сказал, что в Тингене есть университетский округ, и над облаками можно летать на дирижабле.",
    ["他说弗兰奇先生的智商比卷毛狒狒还低——如果状态良好的话。"] = "Он сказал, что интеллект мистера Фрэнка ниже, чем у кудрявого павиана, если он в хорошем состоянии.",
    ["他说贝克兰德的火车很长，一路能到雪山。"] = "Он сказал, что поезд в Баклунде очень длинный и может дойти до заснеженных гор.",
    ["他走了，你还要卖掉这栋宅子吗？"] = "Он ушел. Вы все еще собираетесь продавать этот дом?",
    ["他那时候总说，戴莉，你很有天赋。"] = "Тогда он всегда говорил: «Дэйли, у тебя большой талант».",
    ["他闭着眼睛？！动作迟缓……是梦游？"] = "У него глаза закрыты?! Его движения вялые... он ходит во сне?",
    ["代价也挺大，前面好几个序列完全不能打，到序列六都是学者型。"] = "Цена тоже немалая: первые несколько Последовательностей совсем не боевые, вплоть до Последовательности 6 все учёного типа.",
    ["代价只有一样：你的生命。用你剩下的那点时间，换你穷尽一生也追不上的全部真理。"] = "Есть только одна цена: ваша жизнь. Используйте то немногое время, которое у вас осталось, чтобы обменять всю правду, которую вы никогда не смогли бы разыскать за всю жизнь.",
    ["代价是什么？我的灵魂吗？"] = "Какова цена? Моя душа?",
    ["代价是你的生命，而你的灵魂，将永远与数学共舞。"] = "Цена — ваша жизнь, и ваша душа будет вечно танцевать с математикой.",
    ["以前你和克莱恩一起生活在廷根吗？"] = "Вы с Клейном раньше жили в Тингене?",
    ["以前她一走，瓦莱莉就哭。她索性编了故事哄小瓦莱莉开心。"] = "Раньше, когда она уходила, Валери плакала. Поэтому она просто придумала историю, чтобы подбодрить маленькую Валери.",
    ["以前？"] = "До?",
    ["以及将城堡打理得井井有条之人，乃至在交错铁路上积累财富成就大亨之人——任意一条，皆可留名于此。"] = "А те, кто поддерживает замок в идеальном порядке, или даже те, кто накопил богатство на пересекающихся железных дорогах и стал магнатами, — любой из них может оставить здесь свое имя.",
    ["以后如果在海上听到这种歌声，建议你立刻捂住耳朵，或者……跳进海里。"] = "Если вы в будущем услышите такое пение в море, советую немедленно заткнуть уши или... прыгнуть в море.",
    ["以后就不再空荡荡了。"] = "Он больше не будет пустым.",
    ["以我的审美，还会欺骗你吗？不愧是“愚者”先生亲自祝福过的翅膀……质感确实不一样。"] = "С моим эстетическим чувством я бы солгал тебе? Как и ожидалось от крыльев, лично благословленных Мистеромом... текстура действительно другая.",
    ["仪式魔法确实是一门实践性极强的学问，它不仅需要理解符号、咒文和仪轨，更需要用灵性去感受、去引导。"] = "Ритуальная магия действительно является очень практичной дисциплиной. Это требует не только понимания символов, заклинаний и ритуальных процедур, но и использования духовности для ощущения и руководства.",
    ["仪式魔法，核心在于通过特定的仪轨、符号、祷文和祭品，引导灵性力量，构建一个临时的、符合某种规则的场，"] = "Суть Ритуальной Магии заключается в использовании определенных ритуальных процедур, символов, молитв и подношений для направления духовной силы и создания временного поля, соответствующего определенным правилам.",
    ["仲裁人擅长的是规则、秩序和压制，观众擅长的是观察和引导。如果他真的想抓我，我大概会先用“心理学隐身”让自己看起来像一块石头。"] = "Арбитр хорош в правилах, порядке и подавлении; Зритель хорош в наблюдении и руководстве. Если бы он действительно хотел меня поймать, я бы, наверное, сначала использовал «Психологическую невидимость», чтобы выглядеть камнем.",
    ["任什么苦难也不能使我移动。"] = "Никакие страдания не могут заставить меня двигаться.",
    ["任何理智的人，面对那种超越想象的力量，都会先选择谨慎。"] = "Любой разумный человек, столкнувшись с этой силой, превосходящей воображение, сначала предпочтет быть осторожным.",
    ["任何重复或遗漏，都可能导致仪式失败，甚至引发反噬。"] = "Любое повторение или упущение могло привести к провалу ритуала или даже вызвать негативную реакцию.",
    ["会分不清真假吗？"] = "Неужели вы не сможете отличить истину от лжи?",
    ["会长贝尔纳黛邀请塔罗会的“太阳”先生戴里克·伯格，牺牲的白银城首席的科林·伊利亚特加入塔罗学派，以历史投影的形式担当学派导师，教导学员。"] = "Президент Бернадетт пригласила г-на Сана, Деррика Берга из Клуба Таро и принесенного в жертву вождя Серебряного Города Колина Илиада присоединиться к Клубу Таро, выступая в качестве наставников в форме исторических прогнозов для обучения студентов.",
    ["传奇人物？我似乎也听说了一些……"] = "Легендарная личность? Кажется, я тоже что-то слышал...",
    ["传说有个长相俊美的吸血鬼在这里出没，好多姑娘跑来想偶遇他。"] = "Легенда гласит, что это место часто посещает красивый вампир, и многие девушки приходят сюда в надежде встретиться с ним.",
    ["传说都是假的！只有笨蛋才会相信。"] = "Все легенды — фейк! Только дурак поверит им.",
    ["伦纳德先生，“星星”这个代号是您自己选的吗？"] = "Мистер Леонард, вы сами выбрали кодовое имя «Стар»?",
    ["伦纳德先生，“纯粹”的黑暗是不是与黑夜的权柄有关？"] = "Господин Леонард, «чистая» Тьма связана с полномочием Ночи?",
    ["伦纳德先生，值夜者都要学会写诗吗？"] = "Мистер Леонард, всем ли «Ночным ястребам» нужно научиться писать стихи?",
    ["伦纳德先生，您当初为什么会加入黑夜教会？"] = "Мистер Леонард, почему вы изначально присоединились к Церкви Вечной Ночи?",
    ["伦纳德先生，您特地赶回来？"] = "Мистер Леонард, вы вернулись специально для этого?",
    ["伦纳德先生，黑荆棘对您意味着什么？"] = "Мистер Леонард, что для вас значит Чёрный Чертополох?",
    ["伦纳德先生？"] = "Мистер Леонард?",
    ["伦纳德先生？伦纳德先生？"] = "Мистер Леонард? Мистер Леонард?",
    ["似乎是……记录了一些谜题和解法，看起来是总结出的某种规律？"] = "Кажется, он... записывает какие-то загадки и решения. Похоже ли это на какую-то обобщенную закономерность?",
    ["似乎有东西藏在积雪下面，挖出来看看。"] = "Кажется, под снегом что-то спрятано. Давай откопаем и посмотрим.",
    ["但{{他|她}}说得对。我奶奶走了十年，可我总觉得她在——在好天气里晒被子，风刮过来，像她在摸我的头。"] = "Но {{he|she}} прав. Бабушки нет уже десять лет, но я всегда ощущаю ее присутствие: в хорошую погоду сохнут одеяла, а когда дует ветер, она словно гладит меня по голове.",
    ["但不知怎么了，对着肉摊，我的心特别慌，空落落的。"] = "Но почему-то перед мясной лавкой у меня на душе становится неспокойно и пусто.",
    ["但不管我走到多远的地方，我永远记得黑荆棘，只要我回到这里，我就又回到了家。"] = "Но как бы далеко я ни пошел, я всегда буду помнить Блэкторна. Пока я возвращаюсь сюда, я снова возвращаюсь домой.",
    ["但他们不知道我们在保护他们。"] = "Но они и понятия не имеют, что мы их защищаем.",
    ["但你不是一个好的占卜师。"] = "Но ты плохой предсказатель.",
    ["但你不是仆人，阿尔伯特。你是我的家人。"] = "Но ты не слуга, Альберт. Ты моя семья.",
    ["但你也多少了解到这其中的奥秘了，跟你交流这方面，应该不算违反约定。"] = "Но вы в некоторой степени поняли связанные с этим секреты. Сообщение с вами об этом не должно быть нарушением соглашения.",
    ["但你人还是来了，还是走到了我面前。"] = "Но ты все равно пришел и все равно подошел ко мне.",
    ["但你会。你是自己走到这里，自己选择蹲下的，对吗？"] = "Но ты пойдешь. Ты ведь сам сюда пришел, сам решил присесть на корточки, верно?",
    ["但你却能通过胸针找到我……"] = "Но ты смог найти меня через брошь...",
    ["但你所拥有的好奇心和热情，在任何时候都能给你帮助。"] = "Но любопытство и энтузиазм, которыми вы обладаете, могут помочь вам в любой момент.",
    ["但你没有看到你自己的。"] = "Но ты не видел своего.",
    ["但你看墙上——已经挂着六枚了。他每刻一枚，墙上就多一枚。总有一天，墙上会挂满星币。"] = "Но взгляните на стену — там уже шестеро висят. Каждый раз, когда он вырезает одну, на стене появляется еще одна. Однажды стена будет покрыта пентаклями.",
    ["但却有人为一句承诺，守了它这么多年……"] = "Но ради одного лишь обещания кто-то оберегал его столько лет...",
    ["但后来克莱恩找到工作，我们打算搬去水仙花街。但租期还剩半年，又要赔一笔违约金……"] = "Но потом Клейн нашел работу, и мы решили перебраться на улицу Нарциссов. Вот только до конца аренды оставалось еще полгода, и пришлось бы выплачивать неустойку...",
    ["但后来我才明白，杀死其他猎手，抢夺他们的，要高效得多。"] = "Но позже я понял, что убивать других охотников и отбирать у них добычу намного эффективнее.",
    ["但唯一让我担心的是……她太懂事了……承担了很多不是她这个年纪应该承担的……"] = "Но единственное, что меня беспокоит, это... она слишком благоразумна... берет на себя много вещей, которые ей не следовало бы делать в ее возрасте...",
    ["但奇怪的是，学得越多，我越觉得自己不需要学那么多。有时候，只需要趴在她脚边，把脑袋搁上去就好了。"] = "Но странно вот что: чем больше я узнаю, тем сильнее мне кажется, что знать так много вовсе и не нужно. Иногда достаточно просто лечь у ее ног и положить ей голову на колени.",
    ["但她的戒指下方，隐约可见极细的针尖，灯光下一闪而逝。"] = "Но под ее кольцом едва виднелся крошечный кончик иглы, сверкающий в свете.",
    ["但对我这种人来说，已经是梦了。"] = "Но для кого-то вроде меня это уже мечта.",
    ["但您会说话，会读心理学，还会进入梦境……"] = "Но ведь вы умеете говорить, разбираетесь в психологии и проникаете в сны...",
    ["但我不后悔。活着的时候，该用的能力都用过了，该报的仇也报了。比起那些苟延残喘却一事无成的非凡者，我这辈子够本了。"] = "Но я ни о чем не жалею. Пока я был жив, я использовал все способности, которые должен был использовать, и отомстил всем, что мне нужно было. По сравнению с теми Потусторонними, которые просто борются за выживание и ничего не достигают, я прожил жизнь, достойную того, чтобы ее прожить.",
    ["但我也是她的家人。我想，有很多事情，家人之间是不需要多问的。"] = "Но я тоже член её семьи. Думаю, между близкими есть много вещей, о которых не нужно лишний раз расспрашивать.",
    ["但我们不能。"] = "Но мы не можем.",
    ["但我们恰好也可以顺着日记上去，抢在它之前拿到碎片！"] = "Но ведь мы можем подняться по страницам дневника и забрать осколок раньше него!",
    ["但我们真的只是一家安保公司。"] = "Но на самом деле мы всего лишь охранная компания.",
    ["但我只是想让船自己养活自己啊。这不是很棒的生存策略吗？"] = "Но я просто хочу, чтобы корабль был самодостаточным. Разве это не блестящая стратегия выживания?",
    ["但我并不后悔，我度过了懦弱但幸福的一生。"] = "Но я не жалею об этом; Я прожил трусливую, но счастливую жизнь.",
    ["但我想要雇佣的不是同伴，是一群保镖！"] = "Но я не ищу компаньонов, я ищу группу телохранителей!",
    ["但我每用一次，就忘掉一点。开始只是小事——忘了早餐，忘了昨天见过谁。"] = "Но каждый раз, когда я их использовал, я немного забывал. Поначалу это были просто мелочи — забыть завтрак, забыть, кого я видел вчера.",
    ["但我没办法。我试过把南瓜砸了——没用，砸烂了第二天还是会长出来。只能接着卖。卖一颗，就能见她一次。"] = "Но у меня нет выбора. Я пробовал разбить тыквы — бесполезно, на следующий день они вырастают снова. Остается только продавать. Продам одну — увижу ее еще разок.",
    ["但我知道，她只是把所有的情感都藏在了那些齿轮里。"] = "Но я знал, что она просто скрывает все свои эмоции в этих механизмах.",
    ["但我算过，就算每晚少睡三个小时，也只能再记录几百种。"] = "Но я подсчитал, что даже если я буду спать на три часа меньше каждую ночь, я смогу записать лишь на несколько сотен больше.",
    ["但是……这间屋子里真的还剩下神奇物品吗？这些证据似乎是相反的……"] = "Но... действительно ли в этой комнате остались какие-то мистические предметы? Эти факты, кажется, говорят об обратном...",
    ["但是入口被这些柱子封锁起来了，我们要破坏它们！"] = "Но вход заблокирован этими колоннами, мы должны разрушить их!",
    ["但是我总觉得，人类的心理学书有时候写得不太对。"] = "Но мне всегда кажется, что книги по психологии человека иногда не совсем верны.",
    ["但更高序列意味着更强力量，可以保护更多人……"] = "Но более высокая Последовательность означает более сильную власть, которая может защитить больше людей...",
    ["但最后还是把他们击沉了。那些海盗……<P_Heart>（停顿）</>要么被海流卷走，要么成了鲨鱼的猎物。"] = "Но в конце концов мы их потопили. Эти пираты... <P_Heart>(Пауза)</> были либо унесены течением, либо стали добычей акул.",
    ["但有段时间他很少讲，南大陆的局势不好，他们公司裁了很多人，他为了保住工作，不得不接受更繁重的任务，经常加班，去环境恶劣的地方出差。"] = "Но какое-то время он редко говорил об этом. Ситуация на Южном континенте была плохой, их компания уволила много людей, и, чтобы сохранить свою работу, ему приходилось выполнять более тяжелые задачи, часто работать сверхурочно и ездить в командировки в места с суровыми климатическими условиями.",
    ["但狗也可以聪明，也可以思考，也可以选择自己的生活方式。"] = "Но собаки также могут быть умными, думать и выбирать собственный образ жизни.",
    ["但真实造物主毕竟是邪神，您不担心被污染吗？"] = "Но Истинный Создатель, в конце концов, злой бог, не беспокоишься ли ты, что развратишься?",
    ["但要是最近的话，应该是我留下的各种历史痕迹、“亵渎之牌”，和贝尔纳黛，让我们最后得以见面。"] = "Но если это произошло недавно, то это должны быть различные исторические следы, которые я оставил после себя, «Карта богохульства» и Бернадетт, которая позволила нам наконец встретиться.",
    ["但记住——永远不要占卜自己，也不要占卜高位存在。前者会让你陷入自我欺骗，后者会让你被“注视”。"] = "Но помните: никогда не предсказывайте для себя и никогда не предсказывайте для существ высокого уровня. Первое приведет вас к самообману, а второе заставит вас «наблюдать».",
    ["但还有什么曲子能在婚礼上演奏的呢？"] = "Но какие еще песни можно играть на свадьбе?",
    ["但这些信息需要解读，而解读的准确性取决于占卜者的经验。"] = "Однако эту информацию необходимо интерпретировать, и точность интерпретации зависит от опыта прорицателя.",
    ["但这对整个王国来说，已经是在进步的路上了。"] = "Но для всего королевства это уже на пути прогресса.",
    ["但这是因为她已经没什么亲人了。我照顾了她很久，她想把她死后珍贵的非凡特性交给我继承，还有那串手链……"] = "Но это потому, что у нее не осталось родственников. Я заботился о ней долгое время, и после смерти она хотела передать мне свои драгоценные черты Потустороннего вместе с этим браслетом...",
    ["佐伊·帕普里卡。 你想看到这条猜想的终点吗？数字、等式、冰山之后的真理。"] = "Зоя Паприка. Хотите увидеть конец этой гипотезы? Правда о цифрах, уравнениях и айсберге.",
    ["佐伊！"] = "Зоя!",
    ["佐伊，学院来信了。你的课题占用教研室太久了，需要腾出来给新项目。"] = "Зоя, письмо из академии. Ваш проект слишком долго занимал исследовательскую комнату, ее необходимо освободить для нового проекта.",
    ["佛尔思小姐让我找您借一件神奇物品。"] = "Госпожа Форс просила меня одолжить у вас одну необычную вещь.",
    ["作为“梦魇”，我可以进入他人的梦境。那时候他刚经历一场非凡事件，我需要确认他是否隐瞒了一些信息。"] = "Как «Кошмар» я могу проникать в сны других людей. В то время с ним только что произошел Чрезвычайный инцидент, и мне нужно было подтвердить, скрыл ли он какую-либо информацию.",
    ["作为一名守护廷根的值夜者，我不能每天按时回家，给她讲睡前故事，只能向女神祈祷，愿她有个美梦。"] = "Как Ночной Ястреб, охраняющий Тинген, я не могу каждый день приходить домой вовремя, чтобы рассказывать ей сказки на ночь, поэтому могу только молиться Богине, желая ей сладких снов.",
    ["作为女神的信徒，我不能违背自己的平等思想。"] = "Как верующий в Богиню, я не могу идти против своих собственных принципов равенства.",
    ["作为廷根市唯一的高档百货，我们一直不知道背后的出资者是谁。"] = "Будучи единственным элитным универмагом Тингена, мы так до сих пор и не знаем, кто за ним стоит.",
    ["作为曾经的佣兵小队，你们真的不考虑和我去进行一场冒险吗？"] = "Будучи бывшим наемником, ты действительно не собираешься отправиться со мной в приключение?",
    ["你——你在婚礼前夕爱上别人了？"] = "Ты… ты влюбился в кого-нибудь еще накануне нашей свадьбы?",
    ["你——！我不跟你说话了！"] = "Ты-! Я больше с тобой не разговариваю!",
    ["你……你怎么神智这么清醒？"] = "Ты... почему твой разум такой ясный?",
    ["你……好，我相信你。"] = "Ты... ладно, я тебе доверяю.",
    ["你……您能把那东西赶出去？太好了！走走，快跟我来！"] = "Ты... Вы можете прогнать эту тварь? Замечательно! Пойдемте, скорее за мной!",
    ["你、你懂占星？你真是个大好人！"] = "Ты, ты знаешь астрологию? Вы действительно замечательный человек!",
    ["你一个人要注意……"] = "Береги себя здесь один...",
    ["你不愿意，就算了。一个月了，每次到最后一步，我都做不到……"] = "Если не хочешь, то забудь. Прошел месяц, и каждый раз, когда я дохожу до последнего шага, я просто не могу себя заставить это сделать...",
    ["你不懂，我回去就结婚了，当然要整整齐齐。"] = "Ты не понимаешь: я вернусь и сразу женюсь, так что я должен выглядеть безупречно.",
    ["你不知道吗？传说金秋湖受到了大地的恩赐，所以常年处于丰收季。不过——"] = "Разве ты не знаешь? Легенда гласит, что озеро Золотая Осень получила благословение земли, поэтому круглый год здесь сезон сбора урожая. Однако-",
    ["你不知道？"] = "Вы не знали?",
    ["你为什么问我为什么问你坐在墙头？"] = "Почему ты спрашиваешь меня, почему я спрашиваю тебя, почему ты сидишь на стене?",
    ["你之前提到的和同事的打赌游戏，你们是怎么开始的？"] = "С чего началась игра на спор с коллегами, о которой ты говорил раньше?",
    ["你也一样，丢下一切离开这里吧……"] = "Ты тоже брось всё и уходи отсюда...",
    ["你也听过这首诗！"] = "Вы тоже слышали это стихотворение!",
    ["你也是个什么都没有的家伙。——喂，布雷登，你有纽扣吗？"] = "У тебя тоже ничего за душой нет. — Эй, Брейден, у тебя есть пуговицы?",
    ["你也是来追寻真理的？"] = "Вы тоже здесь, чтобы искать правду?",
    ["你也有这样的感觉，对吧？"] = "У тебя тоже есть такое чувство, да?",
    ["你也要嫁给吸血鬼？！"] = "Ты тоже хочешь выйти замуж за вампира?!",
    ["你今天怎么问题这么多？"] = "Почему у тебя сегодня так много вопросов?",
    ["你从二十二岁就在最后一步了。现在你六十岁了。"] = "Ты был на последнем шаге с тех пор, как тебе исполнилось двадцать два. Теперь тебе шестьдесят.",
    ["你以为你只是个见证者？不。你也是被召唤来的。那本书选择了你，因为你也在追——追一个你自己都说不清的东西。"] = "Вы думаете, что вы просто свидетель? Нет. Тебя тоже вызвали. Эта книга выбрала вас, потому что вы тоже гонитесь за чем-то, чего даже не можете четко определить.",
    ["你们先前的冒险经验一定很丰富吧，不考虑重新体验刺激的生活吗？"] = "Должно быть, у вас уже было много богатых приключений; Вы думали о том, чтобы вновь испытать захватывающую жизнь?",
    ["你们又这样！{{PlayerName}} 你也和他们一起胡闹！连老维尔先生都串通好了！"] = "Опять вы за свое! {{PlayerName}}, ты тоже с ними заодно дурачишься! Даже со старым мистером Виллом сговорились!",
    ["你们在说什么？"] = "О чем вы говорите?",
    ["你们怎么知道我是占卜师？"] = "Откуда ты узнал, что я прорицатель?",
    ["你们是谁？在这里干什么？"] = "Кто ты? Что ты здесь делаешь?",
    ["你们是遇上什么事情了吗？"] = "С тобой что-то случилось?",
    ["你们有没有发现，自从那个叫西尔维娅的外乡人来了之后，怪事就不断发生！"] = "Вы заметили, что с тех пор, как пришла та чужачка по имени Сильвия, постоянно происходят странные вещи!",
    ["你们知道她去哪了吗？"] = "Вы знаете, куда она ушла?",
    ["你们认识海莉夫人很久了吗？"] = "Вы давно знакомы с госпожой Хейли?",
    ["你们说的那个占卜师，她叫什么？在哪里摆摊？"] = "Как зовут прорицателя, о котором вы говорите? Где она ставит свой ларек?",
    ["你俩别吵了，难得回廷根一次。让您见笑了。"] = "Хватит спорить, вы двое. Редко кто возвращается в Тинген. Заставить тебя смеяться.",
    ["你先上去，我也能借助日记上去！"] = "Ты поднимись первым, я также могу использовать дневник, чтобы подняться наверх!",
    ["你先去坐一下吧，我这还有病人。"] = "Пойди присядь пока, у меня тут еще пациент.",
    ["你只能去炸鸡店找玛丽奶奶了……她是非凡者，手里有一件神奇物品，能帮你找到回来的路……"] = "Тебе остаётся только пойти в закусочную с жареной курицей к бабушке Мэри... Она Потусторонний, и у неё есть чудесный предмет, который поможет найти дорогу обратно...",
    ["你叫什么名字呢？要不叫你……小布丁？"] = "Как же тебя зовут? Может, назвать тебя... Пудинг?",
    ["你可以先去老维尔餐厅，想办法将他们带来。"] = "Сначала вы можете пойти в ресторан Old Will's и найти способ привести их сюда.",
    ["你可以去找瑞安娜，她是一位很有名的占卜师，就在白水晶房。"] = "Ты можешь найти Риану; она очень известная прорицательница прямо в Белой Кристальной Комнате.",
    ["你可以在我的棚子里看看。出了什么事吗？"] = "Можешь заглянуть в мой сарай. Что случилось?",
    ["你可以理解为更擅长“看”的人。"] = "Вы можете понять это как человека, который лучше «видит».",
    ["你可以理解为，在梦境中活动的能力。"] = "Вы можете понимать это как способность действовать во сне.",
    ["你可以通过我的意识探索空间、回收碎片。"] = "С помощью моего сознания ты сможешь исследовать пространство и собирать осколки.",
    ["你可别问我。我就是个在车站卖熏鱼的，那些事一概不知道。"] = "Не спрашивай меня. Я всего лишь продавец копченой рыбы на вокзале; Я ничего не знаю об этих делах.",
    ["你可是有“愚者”先生的眷顾，在一位强大神明的庇护和注视下完成仪式，不会出问题的。"] = "За тобой ведь благосклонность господина Шута, и ты совершаешь ритуал под покровом и взором могущественного божества, всё пройдёт хорошо.",
    ["你回去吧，我不想看见另一个学徒重蹈覆辙。"] = "Возвращайся, не хочу, чтобы ещё один Ученик повторил ту же ошибку.",
    ["你回来了？找到那个骗子了吗？"] = "Ты вернулся? Вы нашли это мошенничество?",
    ["你在等这位“老爷”？"] = "Вы ждете этого «Мастера»?",
    ["你在这里干什么？"] = "Что ты здесь делаешь?",
    ["你太急了。“看见我”的副作用是丢失记忆。阿尔伯特每用一次，记忆就少一分。但他对战友的执念太深，即使忘记一切，依然记得要那块地。"] = "Ты был слишком нетерпелив. Побочным эффектом «See Me» является потеря памяти. Каждый раз, когда Альберт использует его, его память ухудшается. Но его одержимость товарищами слишком глубока; даже если он все забудет, он все равно помнит, что хотел эту землю.",
    ["你好，你是一朵……蘑菇？"] = "Привет, ты... гриб?",
    ["你好，年轻人，看到你在这里半天，想一起参加讨论吗？"] = "Здравствуйте, молодой человек. Увидев вас здесь некоторое время, не хотели бы вы присоединиться к обсуждению?",
    ["你好，我是活动的向导，带他们来参加。"] = "Здравствуйте, я гид на мероприятии, привожу их сюда для участия.",
    ["你好，特邀观众。"] = "Здравствуйте, специальный гость.",
    ["你好，瓦莱莉！"] = "Здравствуй, Валери!",
    ["你好，罗珊女士，我叫安多，今天就麻烦你了。"] = "Здравствуйте, г-жа Розанна, меня зовут Андо, извините, что беспокою вас сегодня.",
    ["你好，这只怀表……"] = "Привет, эти карманные часы...",
    ["你妻子现在呢？"] = "Как сейчас твоя жена?",
    ["你始终关注着凶手，却没看见我。"] = "Ты все время был сосредоточен на убийце, но не видел меня.",
    ["你学会的东西，将来会变成你手里的剑。"] = "То, чему вы научитесь, в конечном итоге станет мечом в вашей руке.",
    ["你对建筑很有研究，是从事这个行业？还是这个专业的学生？"] = "У вас глубокое понимание архитектуры; вы в этой отрасли? Или студент этой специальности?",
    ["你就没怀疑过是书出问题吗？"] = "И ты ни разу не заподозрил, что дело в самой книге?",
    ["你已经完成了誓言，可以往前走了，我会借光明的力量指引你。"] = "Вы уже выполнили свой обет и можете двигаться дальше. Я буду вести тебя силой света.",
    ["你带来的书，书里的残影，都是“最后一页”的呼唤……"] = "Книга, которую вы принесли, и остатки тени в ней — все это призывы с «Последней страницы»…",
    ["你帮帮我。用你的占卜，找找艾琳的位置。"] = "Помоги мне. Используйте свое гадание, чтобы определить местонахождение Эйлин.",
    ["你很勇敢啊！"] = "Ты очень смелый!",
    ["你很懂塔罗。正位逆位，每一套体系的释义，你都能背出来。"] = "Вы очень хорошо знаете Таро. В прямом и перевернутом положении вы можете произносить интерпретации каждой системы.",
    ["你得亲自和他说，一起去吧。"] = "Ты должен сказать ему сам. Давайте пойдем вместе.",
    ["你怀疑过阿尔伯特，怀疑过艾琳娜。但没有停留在第一印象。继续观察，修正判断，直到看见真相。"] = "Вы подозревали Альберта, вы подозревали Елену. Но вы не остановились на первом впечатлении. Вы продолжали наблюдать, корректировали свои суждения, пока не увидели истину.",
    ["你怎么……把你最珍惜的东西……给我了……"] = "Зачем ты... дал мне... самое дорогое, что у тебя есть...",
    ["你怎么知道这些的？"] = "Откуда ты все это знаешь?",
    ["你怎么这么说哥哥呢？我太伤心了。"] = "Как ты можешь так говорить о старшем брате? Мое сердце разбито.",
    ["你想了解什么呢？"] = "Что бы вы хотели знать?",
    ["你想借的就是这枚“归乡”指南针。但它的负面效果会导致我和它绑定，无法主动将它丢弃。"] = "Ты хотел одолжить именно этот компас «Возвращение домой». Но его негативный эффект привязывает меня к нему, и я не могу выбросить его по своей воле.",
    ["你想扔掉的是那个被评委否定的自己。"] = "То, что вы хотите выбросить, — это та версия себя, которую отвергли судьи.",
    ["你想知道世界的真相吗？它为什么这样运转，它最终会走向哪里。所有追问的尽头。"] = "Хотите узнать правду о мире? Почему он действует таким образом, к чему это в конечном итоге приведет. Конец всем допросам.",
    ["你想让诅咒停在自己这里，堵上灾难的大门？"] = "Хотите, чтобы проклятие прекратилось и заблокировало врата катастрофы?",
    ["你想问我晋升序列5的仪式？"] = "Ты хочешь спросить меня о ритуале продвижения на Последовательность 5?",
    ["你感到一阵头晕目眩……"] = "Вы чувствуете волну головокружения...",
    ["你愿意吗？"] = "Ты согласен?",
    ["你才是笨蛋！妈妈没有骗过我，我的愿望会实现的。"] = "Ты манекен! Мама никогда мне не лгала, мое желание сбудется.",
    ["你扔不掉它，也许存在什么原因。我会把怀表送回原位，今晚守着它，看它到底为什么回来。"] = "Вы не можете его выбросить; возможно, есть причина. Я верну карманные часы на прежнее место и посмотрю их сегодня вечером, чтобы понять, почему они продолжают возвращаться.",
    ["你找到了凶手。"] = "Вы нашли убийцу.",
    ["你把他们引来了！"] = "Ты привел их сюда!",
    ["你把星相解读都背下来了？还几眼就能解出我的命运？"] = "Вы запомнили все астрологические интерпретации? И ты можешь решить мою судьбу всего за несколько взглядов?",
    ["你把自己的未婚妻叫做女巫？"] = "Ты называешь свою невесту ведьмой?",
    ["你拍了十三张照片，帮一只乌鸦收集了十三种记忆。你有没有好奇过……是谁让那只乌鸦活到第十四天的？"] = "Ты сделал тринадцать снимков и помог ворону собрать тринадцать воспоминаний. Не возникало ли у тебя мысли... кто позволил этому ворону дожить до четырнадцатого дня?",
    ["你拿走了指南针，对吗？"] = "Ты забрал компас, верно?",
    ["你敢想象没有卫生系统的因蒂斯当初是什么样吗？！简直不忍直视！到处都是恶心的排泄物！"] = "Вы вообще представляете, каким был Интис до появления канализации?! На это же страшно было смотреть! Повсюду были отвратительные нечистоты!",
    ["你是……"] = "Ты...",
    ["你是……我女儿失踪了，你有没有见过她？"] = "Вы... Моя дочь пропала, вы ее видели?",
    ["你是……艾、艾米？！"] = "Ты... Эм, Эми?!",
    ["你是一个很合格的观众。"] = "Вы очень квалифицированный зритель.",
    ["你是不是根本没收钱？"] = "Вы деньги вообще не собрали?",
    ["你是个有天赋的占卜师，记住我今天说的话。我该走了。"] = "Вы одаренный предсказатель. Помните, что я сказал сегодня. Мне пора идти.",
    ["你是在塔罗会成员的注视下诞生的，我当然认识你。"] = "Ты родился под взглядами членов Клуба Таро, поэтому я тебя, конечно, знаю.",
    ["你是恶魔吗？"] = "Ты демон?",
    ["你是想说……传说都是假的吗？布丁不会回来了……对吗？"] = "Вы хотите сказать, что все легенды — фальшивка? Пудинг не вернется... верно?",
    ["你是我们之中最年轻的，要代替我们回去啊。"] = "Ты самый младший среди нас, ты должен вернуться за нами.",
    ["你是执掌好运的黄黑之王"] = "Ты король желтого и черного, приносящий удачу.",
    ["你是本地人吗？我循着地址来，但主人不在。"] = "Вы местный? Я пошел по адресу, но владельца здесь нет.",
    ["你是灰雾之上的神秘主宰"] = "Ты таинственный правитель над серым туманом",
    ["你是观众途径的非凡者，没有比你更合适的人选，注意宾客的微表情，注意环境里的异常，注意所有“看起来不太对”的东西。"] = "Вы находитесь за пределами пути наблюдателя; нет никого более подходящего, чем ты. Обращайте внимание на микровыражения гостей, замечайте любые аномалии в окружающей обстановке и следите за всем, что «кажется не совсем правильным».",
    ["你是说我的小猫？它们……能少打翻我几瓶药剂就好。"] = "Вы говорите о моих котятах? Если бы... они могли опрокинуть меньше моих зелий.",
    ["你是说我的猫不爱我，一切只是我的自作多情？！"] = "Хочешь сказать, мой кот меня не любит, а я просто тешил себя иллюзиями?!",
    ["你是说，我已经死了？我就死在了这里？"] = "Ты хочешь сказать, что я уже мертв? Я умер прямо здесь?",
    ["你最喜欢的占星术没告诉你？这位可是一眼就看出来了！"] = "Ваша любимая астрология вам не подсказала? Этот человек увидел это с первого взгляда!",
    ["你来得晚，那是几年前的事情了。"] = "Ты опоздал; это произошло несколько лет назад.",
    ["你每天都这样精打细算？"] = "Вы каждый день так подсчитываете?",
    ["你没听过那句话吗？被关起来的鸟没有价值。"] = "Разве вы не слышали эту поговорку? Птица в клетке не имеет никакой ценности.",
    ["你没有忘记。只是暂时想不起来。"] = "Ты не забыл. Вы просто какое-то время не могли вспомнить.",
    ["你没有问过他最近变化的原因吗？"] = "Ты не спрашивал его, почему он так изменился в последнее время?",
    ["你的物品并非凡物，自然仪式也要有相应的位格。而且，我隐约感觉，它也许能帮助“愚者”先生早日从沉眠中醒来。"] = "Ваш предмет не является обычным предметом, поэтому естественно, что ритуал должен иметь соответствующий уровень. Более того, я смутно чувствую, что это могло бы помочь Мистеруу скорее проснуться от сна.",
    ["你的确不是镇上的人……嗯，是我的表。"] = "Ты действительно не из этого города... Хм, это мои часы.",
    ["你的考虑是对的。“无光”的黑暗和“纯粹”的黑暗，这是两个概念。"] = "Ты рассудил верно. Тьма «без света» и Тьма «чистая» — это два разных понятия.",
    ["你的身上，寄托了对抗末日的希望。"] = "Вы несете надежду противостоять апокалипсису.",
    ["你看。"] = "Смотреть.",
    ["你看上去有点眼熟，我们见过？"] = "Ты выглядишь немного знакомо. Мы встретились?",
    ["你看到了什么？"] = "Что ты видел?",
    ["你看到了埃莉诺的叶子，佐伊的冰山，埃德温的答案。你看到了他们为什么走进来。"] = "Вы видели листья Элеоноры, айсберги Зои, ответы Эдвина. Вы видели, почему они вошли.",
    ["你看见了祂们，祂们也看见了你。"] = "Вы видите Их, и Они тоже видят вас.",
    ["你看起来对基金会很感兴趣，它曾是“愚者”先生创立的，位于贝克兰德北区，佩斯菲尔街22号，有机会你也可以去那里看一看。"] = "Похоже, вас очень интересует этот фонд. Когда-то его основал Господин Шут. Он находится в Северном районе Бэкланда, на улице Песец, 22. Будет возможность — обязательно загляните туда.",
    ["你真厉害。这很复杂吧？"] = "Ты потрясающий. Это должно быть сложно, верно?",
    ["你知道吗？“未来号”本身也是我的研究对象！"] = "А знаешь? Сам корабль «Будущее» — тоже предмет моих исследований!",
    ["你知道奥黛丽小姐在里面做什么吗？不会好奇吗？"] = "Вы знаете, что мисс Одри делает внутри? Разве тебе не любопытно?",
    ["你知道我离证明它只差最后一步了吗？"] = "Знаете ли вы, что я всего в одном шаге от того, чтобы доказать это?",
    ["你知道最有趣的是什么吗？是我们家以前的房东弗兰奇先生。"] = "Знаете, что было самое интересное? Это был наш бывший домовладелец, мистер Фрэнк.",
    ["你知道蹲着不能进行光合作用吧？"] = "Вы знаете, что не можете фотосинтезировать, сидя на корточках, верно?",
    ["你知道？"] = "Вы это знаете?",
    ["你确定……要用生命换取窥见真理的机会吗？"] = "Ты уверен... ты хочешь обменять свою жизнь на шанс увидеть правду?",
    ["你能不能帮我试探一下？"] = "Можете ли вы помочь мне проверить почву?",
    ["你能听见逝者的声音，却越来越难听见活人的。他们害怕你，觉得你身上带着死亡的气息。"] = "Ты слышишь голоса усопших, но тебе все труднее слышать живых. Они боятся тебя, чуя, что от тебя веет дыханием смерти.",
    ["你能想象一位年长的病人突然向你展示了穿墙术的那种震撼吗？"] = "Можете ли вы представить себе шок, когда пожилой пациент вдруг покажет вам способность проходить сквозь стены?",
    ["你被它欺负了？"] = "Вас это издевалось?",
    ["你观察得很仔细。"] = "Вы весьма наблюдательны.",
    ["你觉得知识是什么？"] = "Как вы думаете, что такое знание?",
    ["你认得我？"] = "Ты узнаешь меня?",
    ["你让我喝的其实不是茶，是非凡药剂吧？"] = "Чай, который ты заставил меня выпить, на самом деле не чай, а зелье Потустороннего, верно?",
    ["你说……我这瓜，保真吗？"] = "Ты сказал... сохраню ли я свою честность?",
    ["你说什么？亨利·怀恩！你再说一遍！"] = "Что вы сказали? Генри Вайн! Скажи это еще раз!",
    ["你说你会来看我们，可你骗人，呜呜——"] = "Ты сказал, что придешь к нам, но ты солгал, *рыдает*—",
    ["你说得对……我是老了……新的求知者就在眼前……带进去……把他带进去……"] = "Ты прав... Я стар... прямо передо мной новый искатель знаний... забери его... забери его внутрь...",
    ["你说得对，{{PlayerName}}！现在并不是沮丧的时候！"] = "Ты прав, {{PlayerName}}! Сейчас не время впадать в депрессию!",
    ["你说得对，我知道一个还不错的地方，跟我来！"] = "Ты прав, я знаю отличное местечко, идём со мной!",
    ["你说的那位……士兵？他怎么样？"] = "Тот... солдат, которого ты упомянул? Как он?",
    ["你说的闹鬼祖宅是怎么回事？"] = "Что там насчет родового дома с привидениями, о котором ты упомянул?",
    ["你说过你讨厌脏东西……它最近在换羽，掉得到处是羽粉，我在巷子里帮它梳理……"] = "Ты сказал, что ненавидишь грязные вещи... он в последнее время линяет, повсюду разбрасывает перьевую пыль, поэтому я помогал ему ухаживать за ним в переулке...",
    ["你谁啊！别捣乱！"] = "Кто ты! Не создавай проблем!",
    ["你走吧，其实今天不会有暴风雪，我骗你的。"] = "Тебе следует идти. Собственно, метели сегодня не будет; Я солгал тебе.",
    ["你趁着给霍克斯男爵送药毒杀了他，伪装出他还活着的假象，甚至伪造案发现场，嫁祸仆人。"] = "Вы отравили барона Хоукса, когда доставляли ему лекарство, имитировали иллюзию, что он все еще жив, и даже подделали место преступления, чтобы подставить слугу.",
    ["你身上也有这些南瓜的气息——你确定那些，也保真吗？"] = "От тебя тоже пахнет этими тыквами — ты уверен, что они тоже настоящие?",
    ["你身上有那种气质。海莉夫人也有——往那一站，就让人想把自己的事说给她听。"] = "У тебя такой темперамент. У мадам Хейли это тоже есть: просто стоя там, люди хотят рассказать ей о своих проблемах.",
    ["你还好吗？"] = "Ты в порядке?",
    ["你还是等不及了。"] = "Ты все еще не мог дождаться.",
    ["你还算善良。前面十几个人，杀掉任何一个，你就解脱了。"] = "Ты по-прежнему добросердечен. Из дюжины или около того людей до вас вы были бы свободны, если бы убили любого из них.",
    ["你这么一问，我才发现我竟然已经为教会奉献三十多年了。"] = "Теперь, когда вы спрашиваете, я понимаю, что на самом деле я посвятил Церкви более тридцати лет.",
    ["你这人……唉！"] = "Ты действительно... вздох!",
    ["你这南瓜多少钱一磅？"] = "Сколько стоит твоя тыква за фунт?",
    ["你选择了生命？"] = "Ты выбрал жизнь?",
    ["你都长这么大了……我差点全都忘记了。"] = "Ты стал таким большим... Я почти всё забыл.",
    ["你醒了……"] = "Ты проснулся...",
    ["你长得，确实和老爷有些像。"] = "Ты немного похож на Мастера.",
    ["你问我？！是不是你藏起来了？"] = "Ты спрашиваешь меня?! Ты это спрятал?",
    ["你问问题的角度很刁钻，你这个人很不会聊天。"] = "Ты задаёшь очень каверзные вопросы. Собеседник из тебя так себе.",
    ["你骗我到这里，让我做替死鬼，解除你的诅咒？"] = "Ты обманул меня, чтобы сделать меня козлом отпущения и снять твое проклятие?",
    ["佩妮……你以前才这么高。现在都……"] = "Пенни... Раньше ты была вот такой маленькой. А теперь...",
    ["使用“读心者”的非凡能力"] = "Используйте способность Потусторонний «Читатель мыслей».",
    ["依然是一个庸俗的人，无人理解我心中的暴雨……"] = "Еще пошлый человек, никто не понимает бури в моем сердце...",
    ["侦探将正确的时间告诉了我，剧情发生的时间应该是<P_Yellow>黄昏</>，在剧本上记录一下吧。"] = "Детектив назвал мне точное время: действие в сюжете должно происходить в <P_Yellow>сумерках</>. Запишите это в сценарии.",
    ["俱乐部内提供各种占卜工具和占卜房，会员还可以免费享用咖啡和茶水，成本价购买餐食、酒水和一些占卜教材等。"] = "Клуб предоставляет различные инструменты и комнаты для гадания. Кроме того, члены клуба могут бесплатно пить чай и кофе, а также покупать закуски, выпивку и учебные материалы по гаданию по себестоимости.",
    ["值夜者和代罚者之间会有竞争吗？"] = "Есть ли конкуренция между «Ночными ястребами» и «Назначенными карателями»?",
    ["值夜者来考察？这也……太夸张了吧？是不是先问问罗珊的想法比较好？"] = "Ночные ястребы идут к ветеринару? Это... слишком преувеличено, не так ли? Не лучше ли сначала спросить, что думает Розанна?",
    ["值夜者的工作，大部分时间紧张忙碌，但也要学着给自己找些放松的方式。"] = "Работа Ночного Ястреба большую часть времени напряженная и занятая, но нужно также научиться находить способы расслабиться.",
    ["假如我可以帮你把怀表扔出镇子呢？"] = "Что, если бы я мог помочь тебе выкинуть карманные часы из города?",
    ["做个实验，逗他们玩玩，前十一个都没什么意思。"] = "Просто эксперимент, поигрался с ними. Первые одиннадцать были довольно скучными.",
    ["做义工能够平衡我们的劳动付出，我和她再也不因此吵架了。"] = "Волонтерство может сбалансировать наши трудозатраты, и мы с ней больше не спорим из-за этого.",
    ["做得很好。灵性之墙已成，仪式空间初步稳固。现在，仪式的核心开始了。看那些被点亮的区域。"] = "Отличная работа. Формируется Стена духовности и изначально стабилизируется ритуальное пространство. Теперь начинается суть ритуала. Посмотрите на эти освещенные области.",
    ["做研究太累了，上周那个实验的数据又错了，早上的组会又被老师骂了一通。"] = "Заниматься наукой так утомительно: на прошлой неделе данные эксперимента снова оказались неверными, а утром на собрании кафедры профессор устроил мне разнос.",
    ["做这些事的意义是什么？"] = "Какой смысл делать эти вещи?",
    ["偶尔会想起以前的事，那些已经离开的同伴。"] = "Иногда я думаю о прошлом, о тех товарищах, которые уже ушли.",
    ["偶尔探望他们，是我唯一能做的事了。"] = "Навещать их время от времени — единственное, что я могу сделать.",
    ["傍晚的月光斜斜洒满集市，完美地掩盖了暗处的罪恶。 "] = "Вечерний лунный свет освещал рынок, идеально маскируя скрывающееся в тени зло.",
    ["像你这么抠门，真是可怜了那姑娘。"] = "Ты такой скупердяй, девушку прямо жалко.",
    ["像做梦一样？"] = "Нравится мечтать?",
    ["像循环一样重复，太怪了！我调查过，这似乎和睡莲仙女有关。"] = "Это повторяется как цикл, это слишком странно! Я исследовал, и, похоже, это связано с Феей Водяной Лилии.",
    ["像隐士一般避开阳光。"] = "Избегайте солнечного света, как отшельник.",
    ["僻静无人的河畔，只有流水声与猩红的月光作伴，这真是个绝佳的葬身之地，对吧？"] = "Уединенный и пустынный берег реки, где только шум бегущей воды и алый лунный свет создают компанию, действительно идеальное место для похорон, не так ли?",
    ["先别忙着沮丧，我们还有办法！这不就是你找我的意义吗！"] = "Не впадайте в депрессию, у нас еще есть выход! Не для этого ли ты пришел ко мне!",
    ["先别急，你身上有和他们关系密切的物品吗？也许我可以通过占卜找到他们。"] = "Не спешите; есть ли у вас какие-либо предметы, тесно связанные с ними? Возможно, я смогу найти их посредством гадания.",
    ["先别说话。我拉你出来。"] = "Не говори пока. Я вытащу тебя.",
    ["先将我在船舶公司的股份，短期质押给银行，拿到贷款后买入脚踏车股票。"] = "Сначала заложите мои акции пароходной компании в банке на короткий срок, а после получения кредита купите запасы велосипедов.",
    ["先收起来吧，再看看其他地方探索一下。\n<P_Yellow>（已放入背包：《机械屋解谜手册》）</>"] = "Отложите пока это и исследуйте другие места. \n<P_Yellow>(Добавлен в рюкзак: «Руководство по головоломке «Механический дом»)»</>",
    ["先是一阵虚幻的破碎声，接着我感受到有东西在溶解，和我的精神慢慢融合……"] = "Сначала раздался иллюзорный звон разбитого стекла, а затем я ощутил, как нечто растворяется и медленно сливается с моим духом...",
    ["先生，太感谢了，您看这些要多少钱？"] = "Сэр, большое вам спасибо. Сколько я вам за это должен?",
    ["先生，您这是在……"] = "Сэр, вы...",
    ["先生，我们已经拒绝你很多次了。"] = "Сэр, мы уже много раз вам отказывали.",
    ["先生，我替战友们谢谢您！"] = "Сэр, спасибо вам от имени моих товарищей!",
    ["先生，这是你丢的表吗？"] = "Сэр, это те часы, которые вы потеряли?",
    ["先过掉这个任务进行下一环"] = "Пройдите этот квест, чтобы перейти к следующей ссылке.",
    ["克莱恩先生，我听说您来自廷根市？"] = "Мистер Клейн, я слышал, вы из Тингена?",
    ["克莱恩先生，我最近总觉得钱不够用……您有什么省钱的建议吗？"] = "Господин Клейн, в последнее время мне всегда кажется, что у меня недостаточно денег... Есть ли у вас какой-нибудь совет, как сэкономить деньги?",
    ["克莱恩先生，我注意到您常常提到“阿兹克先生”，他是您的导师吗？"] = "Мистер Клейн, я заметил, что вы часто упоминаете мистера Азика. Он ваш наставник?",
    ["克莱恩先生，我知道非凡者需要通过“扮演”来消化魔药，但具体该怎么做，我很想听听您的理解。"] = "Мистер Клейн, я знаю, что Потусторонним нужно переваривать зелья посредством «Действия», но мне бы очень хотелось услышать ваше понимание того, как конкретно это делать.",
    ["克莱恩先生，说实话，曾经的我以为占卜只是骗人的把戏。"] = "Господин Клейн, если честно, раньше я думал, что гадание — это всего лишь обманный трюк.",
    ["克莱恩总是熬夜看书，他的房间经常亮着灯，直到后半夜。"] = "Клейн всегда допоздна читал; Свет в его комнате часто горел до середины ночи.",
    ["克莱恩第一次见到我的时候，也是这么想的——“打扮得像个真正的通灵者，这是在扮演自己？”"] = "Когда Клейн впервые встретил меня, он подумал точно так же: «Одевается как истинный Медиум — неужели пытается отыгрывать самого себя?»",
    ["公爵？那是什么？"] = "Герцог? Что это такое?",
    ["关于“愚者”先生"] = "О Мистерее",
    ["关于信仰"] = "О вере",
    ["关于未来"] = "О будущем",
    ["关于现在"] = "О настоящем",
    ["关于租下庄园"] = "Об аренде усадьбы",
    ["关于贝利夫"] = "О судебном приставе",
    ["关于过去"] = "О прошлом",
    ["其他人呢，谁还有机会杀害霍克斯男爵？"] = "А что насчет остальных? У кого еще была возможность убить барона Хоукса?",
    ["其实——"] = "На самом деле—",
    ["其实不是的。"] = "На самом деле это было не так.",
    ["其实我在找一个富商的女儿，她参加完你的茶会后，就再没回过家了。"] = "Вообще-то я ищу дочь богатого купца. Она так и не вернулась домой после вашего чаепития.",
    ["其实我觉得这不是心理咨询，只是作为朋友，对她的关心。"] = "На самом деле, я не думаю, что это психологическая консультация, просто забота о ней как о друге.",
    ["其实我这趟旅程的目的，就是为了解开这个谜题。"] = "Собственно, цель моего путешествия — разгадать эту тайну.",
    ["其实洋葱也不是不能挂，别总对着我的眼睛……"] = "Вообще-то лук повесить можно, только не суй его прямо мне в глаза...",
    ["其实这也是“愚者”先生的启示，祂总是考虑得如此周到。"] = "Собственно, это тоже было откровением от господина Шута; Он всегда такой задумчивый.",
    ["其实那些“女神的礼物”，都是赛拉悄悄布置好的。"] = "На самом деле все эти «дары богини» были тайно организованы Сарой.",
    ["具体时间节点不算——你知道，塔罗占卜课没那么精确。"] = "Точные сроки не в счет... Сам знаешь, уроки гадания на картах Таро не отличаются такой точностью.",
    ["再一次？"] = "Снова?",
    ["再不安生，我发誓我会狠狠踢你的屁股！"] = "Если ты не будешь себя хорошо вести, клянусь, я надеру тебе задницу!",
    ["再仔细找找，谁知道这三年这个巴掌大的地方又埋了多少新人。"] = "Посмотрите внимательно еще раз. Кто знает, сколько новых людей было похоронено в этом крохотном месте за последние три года.",
    ["再加上我画的幻想中的成年奥莉薇……哦，做母亲的总会把女儿幻想得比自己美。"] = "Плюс портрет взрослой Оливии, который я нарисовала в своем воображении... ох, матери всегда воображают своих дочерей красивее их самих.",
    ["再后来开始忘记你，忘记这个家。只记得那块地。只记得要得到它。"] = "Потом я начал забывать тебя, забывать этот дом. Я помнил только эту землю. Только вспомнил, что хотел его получить.",
    ["再向上追寻完整，我就会成为他的容器，我不愿意；而抽出灵魂，自行缝合，又会使我重新成为那个冷漠的“我”。"] = "Если я продолжу стремиться к полноте на высших уровнях, то стану его сосудом, чего я не желаю; а если извлеку душу и сошью ее сам, то снова стану тем холодным и безразличным «собой».",
    ["再拆开书页，发现图案和已知的占星解读一致，就大概猜到了。"] = "Когда я открыл страницы книги и обнаружил, что закономерности соответствуют известным астрологическим интерпретациям, я примерно догадался об этом.",
    ["再比如以前家里都是我做饭，但那几天，他突然做了一大锅嫩豌豆炖羔羊肉。"] = "Другой пример: раньше я готовил все дома, но за эти несколько дней он внезапно приготовил большую кастрюлю нежного горохового рагу с бараниной.",
    ["再看看其他的"] = "Проверьте другие",
    ["再见"] = "До свидания",
    ["再见。"] = "До свидания.",
    ["再见。哦对了，一次买多个我可以帮你争取折扣！"] = "До свидания. Ах да, если вы купите несколько товаров одновременно, я могу помочь вам получить скидку!",
    ["再见了，希望下次你也能如此幸运。"] = "Прощайте, надеюсь, в следующий раз вам повезет не меньше.",
    ["再见啦，凯瑟琳。"] = "До свидания, Кэтрин.",
    ["再见，希望你喜欢这个俱乐部。"] = "До свидания, надеюсь, вам понравится этот клуб.",
    ["再见，年轻人。"] = "До свидания, молодой человек.",
    ["再见，第十三个！更有趣的还在等着我们。"] = "Прощай, тринадцатый! Нас ждет кое-что еще более интересное.",
    ["再观察一下"] = "Понаблюдайте еще немного",
    ["冥皇，也就是“死神”萨林格尔。他预料到了自己的陨落，于是将我——他的血裔——的灵魂分割成两半。"] = "Император подземного мира, то есть «Смерть» Сэлинджер. Он предвидел свое падение, поэтому разделил мою душу – своего кровного потомка – на две половины.",
    ["冲激，冲激，冲激，大海啊，在岩石脚下崩裂！"] = "Мчись, мчись, мчись, море, разбейся у подножия скал!",
    ["冷静点，莫里老哥，你没法踢死人的屁股。"] = "Успокойся, брат Мори, мертвецу задницу не надерешь.",
    ["冷，真冷！我这辈子第一次到这么冷的地方，我的牙都在打颤！"] = "Холодно, так холодно! Впервые в жизни я был в таком холодном месте. У меня зубы стучат!",
    ["准备好后，我将陪同你一起开启仪式，见证奇迹般神降之时。"] = "После того, как вы будете готовы, я буду сопровождать вас, чтобы начать ритуал и стать свидетелем чудесного момента божественного нисхождения.",
    ["准备好祭品，去教堂前的广场上，向愚者祈求。神灵降恩，奇迹诞生，你的愿望将被实现。"] = "Приготовьте подношения, идите на площадь перед церковью и помолитесь Юродивому. Когда Бог сойдет с благодатью и родится чудо, ваше желание исполнится.",
    ["准备很齐全，那就开始调配魔药吧。"] = "Вы хорошо подготовились, поэтому приступим к приготовлению зелья.",
    ["准备行动"] = "Приготовьтесь действовать",
    ["准确来说，杀人凶手是你，但造成这一切矛盾的真凶另有其人!"] = "Если быть точным, убийца — вы, но истинный виновник всех этих противоречий — кто-то другой!",
    ["几年后，凯瑟琳病死在湖边的小屋里。乔安娜在表演中失误摔伤，再也站不起来。"] = "Спустя несколько лет Кэтрин умерла от болезни в хижине у озера. Джоанна оступилась во время выступления, покалечилась и больше никогда не смогла встать на ноги.",
    ["凯瑟琳抽到星币五。我告诉她，贫穷没有尽头，我们的梦想永远不会实现。"] = "Екатерина вытащила Пятерку Пентаклей. Я сказал ей, что бедности нет конца и что наши мечты никогда не сбудутся.",
    ["凶手在卧室做了什么？"] = "Что убийца делал в спальне?",
    ["出乎我的意料。"] = "Это было выше моих ожиданий.",
    ["出什么事了？"] = "Что случилось?",
    ["出价"] = "Делать ставку",
    ["分了分了，一人一半，够大半年享受了。"] = "Разделите, разделите пополам, хватит, чтобы наслаждаться больше полугода.",
    ["分就分！"] = "Ладно, давай расстанемся!",
    ["分歧？不，那根本不是分歧。是他们不理解！"] = "Разногласия? Нет, дело вовсе не в них. Они просто ничего не понимают!",
    ["切换地点"] = "Сменить местоположение",
    ["切换时间"] = "Время переключения",
    ["切换舞台"] = "Переключить стадию",
    ["切换角色"] = "Переключить персонажа",
    ["列奥德罗"] = "Леодеро",
    ["列奥纳多"] = "Леонардо",
    ["列文虎克"] = "Левенгук",
    ["列祖列宗"] = "Предки",
    ["刚刚调查时我也找到了一些东西，也许可以放在一起。看看这个旧钱夹。"] = "Я также нашел кое-что во время расследования. Возможно, нам удастся собрать их вместе. Посмотрите на этот старый кошелек.",
    ["刚才你拉琴的时候，乌鸦突然全飞走了。我们站在那片安静的花田里，看着风景，忽然觉得心情好了很多。话也说开了。"] = "Только что, когда ты играл на скрипке, вороны вдруг улетели. Мы стояли в этом тихом цветочном поле, глядя на пейзаж, и внезапно почувствовали себя намного лучше. Мы даже открылись друг другу.",
    ["刚才冲上去的时候，忽然就不怕了。以前我总是怕他们报复，怕妹妹受伤……"] = "Когда я только что подбежал, я вдруг больше не боялся. Раньше я всегда боялась, что они отомстят, боялась, что моя сестра пострадает...",
    ["刚才在门口明明听到了齿轮转动的声音，这时候却消失了……"] = "Я только что отчетливо услышал звук вращающихся у двери шестеренок, но в этот момент он исчез...",
    ["刚才我遇到过一位猎人，或许他还没走远，一起去问问他吧。"] = "Я только что встретил охотника. Возможно, он еще не далеко ушел. Пойдем и спросим его.",
    ["刚才的事情，我都想起来了。 "] = "Я помню все, что произошло только что.",
    ["刚才那位太太。她的丈夫去年冬天死在这片湖里。"] = "Эта дама только что. Ее муж умер в этом озере прошлой зимой.",
    ["刚才那家伙呢？还有那个臭丫头！"] = "Где сейчас был этот парень? И эта вонючая девчонка!",
    ["刚泡的咖啡。"] = "Свежесваренный кофе.",
    ["别、别碰我！我有未婚妻！"] = "Не, не трогай меня! У меня есть невеста!",
    ["别人都懂，而你整天就知道看占星书，都好久没——"] = "Все остальные понимают, но ты умеешь только целыми днями просматривать книги по астрологии, а ты уже давно...",
    ["别以为你们赢了，下一幕，我会亲自为你们写……"] = "Не думайте, что вы выиграли. В следующем акте я сама для вас это напишу...",
    ["别太过分——我们几个加起来都凑不出你身上那么多扣子！"] = "Не заходите слишком далеко — у нас троих, вместе взятых, не так много кнопок, как у вас!",
    ["别往里看，异者，即便是你也承受不住这样的注视。"] = "Не смотри внутрь, чужак. Даже тебе не выдержать этого взора.",
    ["别怕，他好像没有恶意，他是在……等人？"] = "Не бойся, у него вроде нет дурных намерений. Он... кого-то ждет?",
    ["别急着走啊！今天有缘，40镑给您！您摸摸这手感，这材质！"] = "Да не спешите уходить! Раз уж нам суждено было встретиться сегодня — отдам всего за 40 фунтов! Пощупайте сами: какова выделка, каков материал!",
    ["别急，慢慢回忆。"] = "Не торопитесь, старайтесь запоминать медленно.",
    ["别担心，女士，也许我能帮你找到她。"] = "Не волнуйтесь, мадам, возможно, я смогу помочь вам найти ее.",
    ["别担心，我刚交了稿，无事一身轻。"] = "Не волнуйся, я только что сдал рукопись, и теперь на душе легко.",
    ["别担心，这次给你的只是普通的茶，来点甜点吗？"] = "Не волнуйтесь, на этот раз я дам вам только обычный чай. Хотите десерта?",
    ["别担心，那只是昨天杀鸭子的血。我吓唬她们的。"] = "Не бойся, это всего лишь кровь вчерашней утки. Я просто пугала их.",
    ["别灰心啊，你的曲子赶跑了乌鸦，也帮情侣解决了矛盾。普通的婚礼乐师能做到这些吗？"] = "Не расстраивайтесь. Ваша музыка отогнала ворон и помогла паре разрешить конфликт. Сможет ли это сделать обычный свадебный музыкант?",
    ["别碰那个。黄褶白盖，伞托膨大——剧毒！"] = "Не трогай это. Желтые жабры, белая шляпка, выпуклое основание — очень ядовиты!",
    ["别管他，这家伙一辈子没出过迪西，让他长长见识。"] = "Не обращайте на него внимания. Этот парень ни разу в жизни не покидал Дези. Пусть он наберется опыта.",
    ["别误会，不是她嫌我打扫得不好，我的妻子是一位风暴信徒。"] = "Не поймите неправильно, дело не в том, что она думает, что я плохо убираюсь, моя жена верит в Шторм.",
    ["别道歉，多亏了你才能通过上一关呢！走吧，我们回老维尔餐厅！"] = "Не извиняйтесь, предыдущий этап нам удалось пройти только благодаря вам! Пошли, мы возвращаемся в ресторан Старого Уилла!",
    ["到头来，没胆量的那个，从来都不是他。"] = "В конце концов, тот, кто был бесхребетным, никогда не был им.",
    ["到小丑上台的时间了？通过耍球挑战，就能得到下一关的线索！"] = "Пришло ли время Клоуну выйти на сцену? Пройдите испытание по жонглированию мячом и получите подсказку для перехода на следующий уровень!",
    ["到底还是买下来了……总觉得咽不下这口气。"] = "В конце концов я купила его... Я просто не могу проглотить этот гнев.",
    ["到这一步就是“做出符合魔药名称的行为”，而下一步，“便是明悟暗藏的规律”。"] = "Достижение этого шага означает «выполнение действий, соответствующих названию зелья», а следующий шаг — «постижение скрытых законов».",
    ["制作非凡药剂并不简单，你做的药剂就只是为了……能听懂猫说话？"] = "Приготовить необычные зелья непросто. Зелье, которое ты приготовил, только для того, чтобы... уметь понимать кошек?",
    ["刺眼的清晨"] = "Ослепительное утро",
    ["前几年，一位朋友也和我一起回到过那里。我想，拉姆德的变化应该不会太大？"] = "Несколько лет назад вместе со мной туда вернулся и друг. Я думаю, Ламуду не стоило слишком сильно меняться?",
    ["前来占卜的侦探"] = "Детектив приезжает на гадание",
    ["前面十一个人，都完成任务，解脱了。而我……太难了。"] = "Все одиннадцать человек до меня выполнили квест и были освобождены. Но для меня... это слишком сложно.",
    ["前面好像有人在呼救？过去看看"] = "Кажется, впереди кто-то зовёт на помощь? Надо посмотреть",
    ["剧本不见了"] = "Скрипт пропал",
    ["剩下那些魔药就送你了，祝你玩得开心。"] = "Оставшиеся зелья дарю тебе. Желаю повеселиться!",
    ["副作用就是……<P_Heart>（认真思考）</> 有些人看到的东西太有趣了，所以不想醒过来。但这说明它效果好，不是吗？"] = "Побочный эффект в том, что... <P_Heart>(серьезно задумалась)</> увиденное некоторыми настолько увлекательно, что они просто не хотят просыпаться. Но это лишь доказывает ее действенность, правда?",
    ["副作用是使用者进入循环空间后，每一次循环，手上会随机出现一个机关谜题，需要在限定时间内解开，否则会被吞噬、转化为一个全新的机关谜题。"] = "Побочным эффектом является то, что после того, как пользователь входит в пространство цикла, с каждым циклом у него на руке появляется случайная механическая головоломка. Ее необходимо решить за ограниченное время, иначе пользователь будет сожран и превращен в совершенно новую механическую головоломку.",
    ["加入"] = "Присоединиться",
    ["医生，您看起来有心事，诊所遇到麻烦了吗？"] = "Доктор, у вас такой вид, будто у вас что-то на уме. В поликлинике проблемы?",
    ["十几年前她就在这条街上占卜了。"] = "Она гадает на этой улице уже больше десяти лет.",
    ["十分美丽……你知道得很清楚啊？"] = "Очень красиво... ты это прекрасно знаешь, не так ли?",
    ["千百年来的祈求终于有了回应，灰雾之上的伟大存在将目光投向了这片遗落之地。"] = "Молитвы тысячелетий наконец получили ответ, и великое существо над серым туманом бросило свой взор на эту затерянную землю.",
    ["午夜茶会？"] = "Полуночное чаепитие?",
    ["单纯因为你是个马虎的笨蛋，弗洛。"] = "Просто потому, что ты неосторожная дура, Фло.",
    ["卖的是独立的墓地，不会出现过一段时间就找不到墓碑的问题，而且我们会有人定期打扫。"] = "Вы покупаете отдельную могилу. Проблем с тем, что через какое-то время не удастся найти надгробие, не возникнет, и у нас есть люди, которые его регулярно чистят.",
    ["占位"] = "Инфо",
    ["占卜"] = "Гадание",
    ["占卜的核心是“启示”，是通过灵性与灵界建立联系，获取模糊的信息。"] = "Сутью гадания является «откровение», которое предполагает установление связи с Духовным миром через духовность для получения расплывчатой ​​информации.",
    ["占卜看到的只是最可能的那条路。怎么解读，怎么走，其实掌握在自己手里。"] = "То, что видится при гадании, — лишь наиболее вероятный путь. Как его интерпретировать и как по нему идти, на самом деле в ваших руках.",
    ["即使后来开始回想故乡，但我至少有妻子、女儿、还有两个儿子。在这里也有许多牵挂和归属感。"] = "Хотя о родном городе я начал думать позже, по крайней мере, у меня были жена, дочь и двое сыновей. У меня также было много привязанностей и чувство принадлежности к этому месту.",
    ["原本我现在就能带你去……但我通宵赶稿……实在太困……"] = "Я мог бы отвести тебя прямо сейчас... но я всю ночь сдавал рукопись... и жутко хочу спать...",
    ["原来如此……您弹得怎么样？"] = "Я вижу... как хорошо ты играешь?",
    ["原来如此……非凡特性和相关的神奇物品……看来，这应该是一张销售记录。"] = "Вот и все... Характеристики Потусторонний и связанные с ними мистические предметы... Похоже, это рекорд продаж.",
    ["原来是这样……"] = "Вот оно как...",
    ["原来落在那里了！多谢你。"] = "Так вот куда оно упало! Большое спасибо.",
    ["原来被你捡到了！多谢。"] = "Итак, вы нашли его! Спасибо.",
    ["原理很简单，就是把动能通过齿轮传递，控制节奏让一跳一走的动作有规律。"] = "Принцип прост; он просто передает кинетическую энергию через шестерни, чтобы контролировать ритм, чтобы движения прыжков и ходьбы были регулярными.",
    ["去吧，我的真爱在……呼噜、呼……"] = "Давай, моя настоящая любовь в... храпе, храпе...",
    ["去吧，打开看看你就明白了。"] = "Давай, открой и ты поймешь.",
    ["去和布雷登汇集一下线索……"] = "Иди и собери улики вместе с Брейденом...",
    ["去找吧。如果你也和我一样，是个无可救药的求知者。"] = "Иди и найди это. Если вы такой же безнадежный искатель знаний, как и я.",
    ["去相亲。阿德莱德先生去世后，我们一直作为家人在她身边，也会考察一下相亲对象。"] = "Пойти на свидание вслепую. После смерти мистера Аделаиды мы всегда были рядом с ней как семья, а также проверяем ее кандидатов на свидание вслепую.",
    ["去第三小段"] = "Перейти к третьему сегменту",
    ["去第二小段"] = "Перейти ко второму сегменту",
    ["去金秋湖。那里，埋藏着一个真理。"] = "Отправляйтесь к озеру Золотой Осени. Там истина похоронена.",
    ["又一群迷途的羔羊闯进了我的花园。"] = "В мой сад забрела еще одна группа потерявшихся ягнят.",
    ["又是这样……又是这样……说了多少次……"] = "Опять... опять... сколько раз я говорил...",
    ["又有人来了，或许应该找他问问。"] = "Кто-то снова здесь, возможно, мне следует спросить его.",
    ["又有倒霉蛋来喝茶了。"] = "Очередной невезучий пришел попить чаю.",
    ["又有血族粉丝来了……"] = "Пришёл ещё один фанат Сангвиника...",
    ["又来了……声音……它又在叫我翻那一页……每次都是这句话……"] = "Это происходит снова... голос... он зовет меня снова перевернуть эту страницу... каждый раз одно и то же предложение...",
    ["又来了，破筐烂菜的……谁干的！"] = "И вот снова разбитые корзины и гнилые овощи... кто это сделал!",
    ["又来了？还在做着无谓的挣扎吗？就算领悟几条扮演守则，你也没法摆脱我。"] = "Опять здесь? Все еще ведете бесполезную борьбу? Даже если ты поймешь несколько принципов действия, ты не сможешь избавиться от меня.",
    ["又来？我受够了，我们分手吧！"] = "Опять? С меня хватит, мы расстаемся!",
    ["发现又如何？你被“看见”太多次了……"] = "И что, если бы ты узнал? Тебя «видели» слишком много раз...",
    ["叙述占星解读"] = "Расскажите астрологическую интерпретацию",
    ["古堡……那是我曾经居住的地方。我的妻子曾向我抱怨过，城堡太阴冷，她更喜欢阳光与温暖。"] = "Древний замок... там я когда-то жил. Моя жена жаловалась мне, что в замке слишком холодно и мрачно; она предпочитала солнечный свет и тепло.",
    ["另一件编号“2-327”，名为“看见我”的封印物，灵性痕迹更清晰。我们经过反复占卜，确认它在廷根郊外的黑伍德庄园。"] = "Другой, под номером «2-327», Запечатанный Артефакт под названием «Увидь Меня», имеет более ясный духовный след. После повторного гадания мы подтвердили, что это находится в поместье Хейвуд в пригороде Тинген.",
    ["只是听人偶尔提起，说您的歌声……很有特色。"] = "Я просто слышал, как кто-то время от времени упоминал об этом, говоря, что твой певческий голос... очень уникален.",
    ["只是坐坐吗？"] = "Просто сидеть и сидеть?",
    ["只是好奇，作为大作家的童年会是什么样的。"] = "Просто любопытно, каким было бы детство великого писателя.",
    ["只是更有经验。占星往往要结合现实判断，才能更准确地解读。"] = "У меня просто больше опыта. Для более точной интерпретации астрологию часто необходимо объединить с реальностью.",
    ["只是那时候的我，总觉得站在他身边，自己还差得远。他的干净，他的温柔，他那些永远不会弯折的东西——让我觉得我这样的人，远远不够格。"] = "Просто тогда я всегда чувствовал, что стоя рядом с ним, мне еще далеко не достаточно. Его чистота, его мягкость, все то, что в нем никогда не сгибалось, — они заставили меня почувствовать, что такой человек, как я, далек от квалификации.",
    ["只是黑荆棘的大家太过体贴，生怕触碰到我的伤心事，慢慢就没人提起想听曲子了。"] = "Просто все в Блэкторне были слишком внимательны, опасаясь затронуть мои печальные воспоминания, поэтому в конце концов никто не упомянул о желании больше слушать мелодии.",
    ["只有第十二个，出乎我的预料，所以实验结束了。"] = "Только двенадцатый превзошёл мои ожидания, так что эксперимент окончен.",
    ["只要吹响它，就能召唤他的信使。我可以通过信使给他写信，他也会回信解答我的问题。"] = "Пока я его дую, я могу вызвать его посланника. Я могу писать ему письма через мессенджер, и он ответит на мои вопросы.",
    ["只要在湖边虔诚地留下愿望，就能得到女神的赠礼。"] = "Если вы искренне оставите желание на берегу озера, вы сможете получить подарок от Богини.",
    ["只要我还在黑荆棘，我就会守护这里，保护这些故事，和故事里的人。"] = "Пока я нахожусь в «Черном шипе», я буду охранять это место, беречь эти истории и людей в них.",
    ["只需要付出一到两周的利息，大约两三百镑，就能获得脚踏车公司百分之十的股份。"] = "Вам нужно всего лишь заплатить проценты за одну или две недели, примерно двести или триста фунтов, чтобы приобрести десять процентов акций велосипедной компании.",
    ["可不是吗，他现在啊越来越有队长样了。"] = "Не так ли? Теперь его поведение все больше напоминает капитана.",
    ["可以吗？"] = "Это нормально?",
    ["可以告诉我是怎么一回事吗，女士？"] = "Можете ли вы рассказать мне, что произошло, мадам?",
    ["可以这么说，我希望我足够强大，可以守护想守护的一切。但除此之外……我还有另一个理由。"] = "Можно сказать и так: я хочу стать достаточно сильным, чтобы защитить всё, что мне дорого. Но кроме этого... у меня есть ещё одна причина.",
    ["可你知道吗？最有趣的地方，从来不是看到真相。而是看着人们拼命寻找答案，怀疑别人，怀疑自己。再一步步走向错误的道路。"] = "Но знаете ли вы? Самое интересное – никогда не видеть правды. Это наблюдение за тем, как люди отчаянно ищут ответы, подозревая других, подозревая себя, а затем шаг за шагом идя по неверному пути.",
    ["可她看起来才二十几岁。"] = "Но выглядит она так, будто ей всего лишь двадцать с небольшим.",
    ["可您……"] = "Но ты...",
    ["可您拥有月光般的皮肤、宝石似的红瞳…… "] = "Но у тебя кожа, как лунный свет, красные глаза, как драгоценные камни...",
    ["可惜……但也幸运。"] = "Жаль... но и повезло.",
    ["可惜。"] = "Как жаль.",
    ["可惜的是，为了寻找记忆离开廷根后，我们就很少联系了。但我也会常常怀念起曾经作为教师的时候。"] = "Жаль только, что после отъезда из Тингена на поиски воспоминаний мы почти не общались. Но я часто с теплотой вспоминаю те времена, когда был преподавателем.",
    ["可惜那家伙本人，到死都不知道。"] = "Жаль, что парень сам этого не знал, пока не умер.",
    ["可惜，等我明白的时候，已经是一个可悲的亡灵了。"] = "Жаль, но когда я всё понял, я уже стал жалкой нежитью.",
    ["可我只是想让牛肉变得更便宜，让更多人能吃饱饭。这不是母亲希望看到的吗？"] = "Но я лишь хотел сделать говядину дешевле, чтобы больше людей могли наесться досыта. Разве не этого желает Матерь?",
    ["可我已经找了好几个地方了……真的等不下去了！"] = "Но я уже проверил несколько мест... Я действительно не могу больше ждать!",
    ["可是——"] = "Но...",
    ["可是……已经过去三十年了……"] = "Но... прошло тридцать лет...",
    ["可是你过不去。"] = "Но ты не можешь туда попасть.",
    ["可是如果他们不准备参加面试，多少也要提前打个招呼。这种做法给我们添了很多麻烦。"] = "Но если они не планируют присутствовать на собеседовании, им следует хотя бы заранее предупредить нас. Такое поведение причиняет нам много неприятностей.",
    ["可是您的店就开在贝克兰德……"] = "Но ваша лавка находится в Бэкланде...",
    ["可是我听伦纳德先生说，您明明已经积攒很久了……"] = "Но я слышал, как мистер Леонард сказал, что вы явно накапливали это в течение длительного времени...",
    ["可是我并没有……"] = "Но я не...",
    ["可是我用鼻子闻一闻，就能知道一个人昨晚有没有睡好，用耳朵听一听，就能分辨笑声是真的还是假的。"] = "Но я могу учуять, хорошо ли кто-то спал прошлой ночью, своим носом, и я могу определить, настоящий ли смех или фальшивый, прислушиваясь к нему ушами.",
    ["可是我被压在石头下太久了，十分虚弱，请你帮帮我，和我一起行动吧！"] = "Но меня слишком долго придавливало камнями, я очень слаб. Пожалуйста, помоги мне, пойдём вместе!",
    ["可是报纸上都登了，已经有不少人遇害了！ "] = "А ведь в газетах пишут, что уже пострадало много людей!",
    ["可是没人看见我。原来我也已经死了……"] = "Но меня никто не видел. Оказывается, я тоже был уже мертв...",
    ["可是老师，只有教会典籍中才更多记载了有关四皇之战的内容。从文献中找到具有共性的真相也许更有可能……"] = "Но учитель, только церковные писания содержат больше записей о Войне Четырех Императоров. Поиск общих истин в литературе может оказаться более вероятным...",
    ["可是，你已经……"] = "Но ты уже...",
    ["可是，我想当的是婚礼乐师，不是驱鸟师……"] = "Но я хочу быть свадебным музыкантом, а не отпугивателем птиц...",
    ["可是，老师是守知派最后的导师，他一定知道“最后一页”的代价。"] = "Но учитель был последним наставником Школы Истины; он, должно быть, знал цену «Последней страницы».",
    ["可是，那些应该是几年前的事情了。"] = "Но все это, должно быть, произошло много лет назад.",
    ["可每到夜里，屋里就有奇怪的响动，脚步声、叹气声，还有人在楼上走来走去。"] = "Но каждую ночь в доме раздавались странные звуки, шаги, вздохи и люди, гуляющие по лестнице.",
    ["可玛丽奶奶，您现在是要去哪呢？"] = "Бабушка Мэри, а куда вы сейчас направляетесь?",
    ["可能……因为我没有缺过钱，所以总是忘记钱对于一个新生非凡者有多么重要。"] = "Может быть... потому что у меня никогда не было недостатка в деньгах, я всегда забываю, насколько важны деньги для нового Потустороннего.",
    ["可能因为……有一些品种的副作用比较大。比如那种会让人暂时失去行动能力的孢子，我最初只是想用来对付海盗而已！"] = "Может быть, потому, что... некоторые сорта имеют серьезные побочные эффекты. Как те споры, из-за которых люди временно теряют способность двигаться; Изначально я просто хотел использовать их для борьбы с пиратами!",
    ["可能是因为这个物品吧，我想用它做一件新衣服。我见过你拥有很多精致的衣服，是在哪个高级时装店定制的吗？"] = "Возможно, это из-за этого предмета. Я хочу использовать его для пошива новой одежды. Я видел, что у тебя много изысканной одежды; были ли они изготовлены на заказ в элитном модном бутике?",
    ["可能这也是促使我加入教会的原因吧，感觉这里是个很温暖的地方。"] = "Возможно, именно поэтому я присоединился к Церкви; это было похоже на очень теплое место.",
    ["可这话传着传着就走样了——先是说果子多，后来说这地能让人不死，现在倒好，成死而复生了。"] = "Но по мере распространения этой истории она искажалась — сначала речь шла об изобилии фруктов, затем говорилось, что эта земля может сделать людей бессмертными, а теперь это стало воскресением.",
    ["可除了积雪，这里什么都没有。"] = "Но кроме сугробов снега, здесь больше ничего нет.",
    ["吃饭的话，面包店打烊前会打折处理当天的剩余面包，一袋黑麦面包2便士就能买到，配上1便士的豌豆汤，一顿饭只要3便士。"] = "Что касается еды, пекарня предлагает скидки на оставшийся хлеб за день до закрытия. Мешок ржаного хлеба можно купить за 2 пенсов, а с 1 пенсом горохового супа обед обойдется всего в 3 пенсов.",
    ["各位来宾，请容许我说几句话。"] = "Уважаемые гости, позвольте мне сказать несколько слов.",
    ["各位！昨天我在金烨树的断裂处，发现了红色汁液。见鬼，近来古怪的事情越来越多了。"] = "Каждый! Вчера я обнаружил красный сок на ветвях золотолистного дерева. Черт побери, в последнее время странные вещи происходят все чаще и чаще.",
    ["同意"] = "Соглашаться",
    ["同时，这样的身份让她避开了很多注视，在魔药消化上也非常有天赋。我们一起完成了很多“愚者”先生发布的任务。"] = "В то же время эта личность позволяла ей избегать многих взглядов, а также она очень талантлива в переваривании зелий. Мы вместе выполнили множество квестов, выданных Мистером Дурачком.",
    ["同样的地方，这四把剑或许和非凡力量的掌控有关？"] = "Может, эти четыре меча в том же месте связаны с управлением Потусторонней силой?",
    ["名字什么时候会更新？"] = "Когда будет обновлено название?",
    ["后来……我看着他处理每一个案子，安抚每一个失去亲人的人。他记得队里每个人的生日。"] = "Позже... Я видела, как он справлялся с каждым случаем, утешая каждого, кто потерял близкого человека. Он вспомнил дни рождения каждого в команде.",
    ["后来为什么不弹了？"] = "Почему ты перестал играть позже?",
    ["后来听说贝克兰德要改革，用考试选拔工作人员。我就想……为什么不试试呢？克莱恩也这样劝我。"] = "Позже я услышал, что в Бэкланде грядут реформы и госслужащих будут набирать по экзаменам. И я подумал... почему бы не попробовать? Клейн тоже советовал мне это сделать.",
    ["后来忘了战友的名字。记得要立碑，忘了他们是谁。"] = "Позже я забыл имена своих товарищей. Я вспомнил, что хотел поставить памятник, но забыл, кто они.",
    ["后来怎么样？成功了吗？"] = "Что произошло позже? Вам удалось?",
    ["后来我发现——我每卖出一颗，当天晚上她就会出现。"] = "Позже я заметил: стоило мне продать хоть одну штуку, как в ту же ночь являлась она.",
    ["后来我的妻子过世，我因此消沉了很长一段时间。"] = "Позже моя жена скончалась, и после этого я долгое время пребывал в глубоком унынии.",
    ["后来是什么改变了您的看法？"] = "А что заставило вас передумать позже?",
    ["后来，我从医学院毕业时，也是他帮我找了关系，送我到尤瑟夫诊所去工作。"] = "Позже, когда я окончил медицинскую школу, он также через свои связи устроил меня на работу в клинику Юзефа.",
    ["后来，我们就把他埋在山头，希望他能多看看自己喜欢的这片雪景。只是过去这么久，果然还是找不到了。"] = "Позже мы похоронили его на вершине холма, надеясь, что он сможет увидеть больше любимых снежных пейзажей. Просто прошло столько времени, а его, как и ожидалось, найти не удалось.",
    ["后来，我的老师问我和卢卡斯——生命与真理，哪个更重要。"] = "Позже мой учитель спросил нас с Лукасом: что важнее: жизнь или правда?",
    ["后果？当然会有后果。好的后果——大家都能吃饱。这就够了！"] = "Последствия? Само собой, будут. И весьма отрадные: все смогут наесться досыта. А большего и не надо!",
    ["后面的诗句是……"] = "Следующее стихотворение...",
    ["听……一位朋友提起过。"] = "Я слышал... друг упомянул об этом.",
    ["听上去您很了解这家俱乐部？"] = "Похоже, ты очень хорошо знаешь этот Клуб?",
    ["听他们说您是一位尊贵的骑士！"] = "Я слышал от них, что вы благородный рыцарь!",
    ["听说您打牌输过不少钱？"] = "Я слышал, ты проиграл немало денег, играя в карты?",
    ["听说您还属于风暴之主教会……这有多久了？"] = "Я слышал(а), вы служите в Церкви Повелителя Бурь... И как давно?",
    ["听起来不简单，能举一些例子吗？"] = "Звучит непросто, можете ли вы привести примеры?",
    ["听起来关系似乎没那么糟？"] = "Похоже, отношения не так уж и плохи?",
    ["听起来很危险……"] = "Звучит очень опасно...",
    ["听起来很危险。"] = "Звучит опасно.",
    ["听起来很有意思？"] = "Звучит интересно?",
    ["听起来很美好。"] = "Звучит чудесно.",
    ["听起来确实很特别，那你支持她的爱好吗？"] = "Звучит действительно очень необычно, поддерживаете ли вы ее хобби?",
    ["听起来那时候很热闹……"] = "Звучит так, будто в те времена там было очень оживлённо...",
    ["听起来，比下午找到工作简单，我们走吧？"] = "Звучит проще, чем найти работу во второй половине дня. Ну что, пошли?",
    ["吸血鬼只是插曲，丰饶的污染还要继续查。 "] = "Вампир — всего лишь интермедия; порчу Матери-Земли еще предстоит расследовать.",
    ["吼吼吼！吼吼——吼！"] = "Рев-рев-рев! Рев-рев!",
    ["吼？"] = "Р-р-р?",
    ["呃……"] = "Эм-м-м...",
    ["呃……下次、下次一定！"] = "Э-э... в следующий раз, обязательно в следующий раз!",
    ["呃……其实我……"] = "Э-э... вообще-то я...",
    ["呃……当然读完了。您是怎么想到写这个故事的？"] = "Э... конечно, я закончил. Как вы пришли к этой истории?",
    ["呃……那要当成什么……"] = "Э-э... тогда как мне к ним относиться...",
    ["呃，感觉脑子昏昏沉沉的，我也有些被影响了……"] = "Ох, в голове туман, меня тоже немного задело...",
    ["告知相关情况"] = "Сообщите о соответствующей ситуации",
    ["告诉外面的人……好好活着。在阳光下，替我们多看几眼这个世界。"] = "Скажи людям снаружи... живите хорошо. Под солнечным светом взгляните еще несколько раз на этот мир для нас.",
    ["告诉我吧，鹦鹉叫什么？"] = "Скажите, как зовут попугая?",
    ["呕，味道好恶心，这到底——"] = "Ух, вкус такой отвратительный, что за черт…",
    ["呜……汪！"] = "У-у... Гав!",
    ["呜呜……"] = "Уууууу...",
    ["呜呜，奶奶！"] = "Сорри, бабушка!",
    ["味道怎么样？"] = "Как это было на вкус?",
    ["呵呵……有我熟悉的人。"] = "Хе-хе... там есть люди, с которыми я знаком.",
    ["呵呵，有段时间，我认为自己只是普通的北大陆学者，直到找回了记忆。"] = "Ха-ха, какое-то время я считал себя обычным учёным с Северного континента, пока не восстановил память.",
    ["呵呵，朋友吗……那跟我来吧，我带你们去找她。"] = "Хе-хе, друг, говоришь... Тогда за мной, я отведу вас к ней.",
    ["呼……"] = "Ого...",
    ["呼……幸好……没事……"] = "Уф... к счастью... все в порядке...",
    ["呼……接下来需要好好理一下思路，我隐隐觉得真相就在眼前了……"] = "Фух... Теперь нужно хорошенько все обдумать. Смутно чую, что разгадка уже совсем близко...",
    ["呼噜……不、不是睡，是诅咒。"] = "Гулу... нет, не сон, это проклятие.",
    ["呼，还好没露馅，安多他……"] = "Уф, к счастью, я его не отдал. Андо, он...",
    ["命运不就是一个人单打独斗嘛，别担心了海莉阿姨！"] = "Разве судьба не просто человек, сражающийся в одиночку? Не волнуйтесь, тетя Хали!",
    ["和他理论"] = "Спорить с ним",
    ["和她交谈的男士似乎非常激动，等等……她只说了一句话，旁边的女士怎么哭了？"] = "Джентльмен, разговаривающий с ней, кажется очень взволнованным. Подожди... она сказала только одно предложение; почему женщина рядом с ними плачет?",
    ["和罗珊的相处"] = "Общение с Розанной",
    ["咦，还有和老师水平相当的对手吗？"] = "А, есть противники наравне с учителем?",
    ["咦，这里的乌鸦……"] = "Ха, вороны здесь...",
    ["咦？星星和我画的一样了？！"] = "Хм? Звезды такие же, как я нарисовала?!",
    ["咦？这里还有一个包裹。"] = "Хм? Здесь есть еще один пакет.",
    ["咪——"] = "Мяу-",
    ["咪的女神，你这个没毛的家伙还挺会讨猫欢心的嘛。"] = "Богиня Мяу, ты, безволосое существо, действительно знаешь, как доставить удовольствие кошке.",
    ["咳……好好好，不讨厌，行了吧。"] = "Кхм... ладно, ладно, ладно, я не ненавижу тебя, ясно?",
    ["咳……是不是我刚刚话说重了。"] = "Кхм... кажется, я только что выразился слишком резко.",
    ["咳咳……其实我有在女神面前起誓，不会将扮演法透露给其他无知者。"] = "Кхм... на самом деле, я поклялся перед Богиней, что не раскрою Метод Актерского мастерства другим невежественным людям.",
    ["咳咳……出现了和之前一样的事……"] = "Кашель, кашель... Произошло то же самое, что и прежде...",
    ["咳咳……感觉空气里有不少灰尘……"] = "Кхм... Такое ощущение, что в воздухе много пыли...",
    ["咳咳……我以为你再见到我，会骂我几句呢。"] = "Кхе-кхе... Я думал, ты несколько раз меня отругаешь, когда увидишь меня снова.",
    ["咳咳，很荣幸地宣布，你们的最后一关——鬼屋！"] = "Кхм, для меня большая честь объявить о вашем последнем этапе — Доме с привидениями!",
    ["咳！"] = "Кхм!",
    ["咳！安多还晕着，要不我们先回黑荆棘再说？"] = "Кхм! Андор все еще без сознания, почему бы нам сначала не вернуться в Чёрный Чертополох?",
    ["咳！没什么！快坐下吧！"] = "Кашель! Ничего! Садись скорее!",
    ["咳，我没记错的话，我应该有个和你共饮的机会？"] = "Кхм, если я правильно помню, мне ведь полагался случай выпить с вами?",
    ["咳，是你的毛太漂亮了。"] = "Кхм, просто у тебя слишком красивая шерсть.",
    ["咳，还是要恭喜你。能被这样强大的灵界生物选中的人并不多，赞美“愚者”先生，珍惜你所获得的灵骑吧。"] = "Кхе, мне все равно придется тебя поздравить. Немногие люди могут быть избраны таким могущественным существом из Духовного Мира. Хвалите Мистераа и дорожите полученным вами духовным ездовым животным.",
    ["哇塞，你是真正的占星大师！"] = "Ого, вы настоящий мастер астрологии!",
    ["哈……我做到了！"] = "Ха... Я сделал это!",
    ["哈哈哈……"] = "Ха-ха-ха...",
    ["哈哈，不客气。"] = "Ха-ха, не за что.",
    ["哈哈，你说得对。看来我也有自己的天赋！园丁先生，这个工作我接下了！"] = "Хаха, ты прав. Кажется, у меня есть свой талант! Мистер Гарденер, я возьмусь за эту работу!",
    ["哈哈，吓到了吗？有没有出冷汗？这是我跟“世界”先生学的语气！"] = "Хаха, ты испугался? Вы покрылись холодным потом? Этому тону я научился у мистера Мира!",
    ["哈哈，它答应了。"] = "Хаха, согласен.",
    ["哈哈，抱歉，我已经很久不给别人占卜了。"] = "Хаха, извини, я давно не гадал для других.",
    ["哈哈，有机会我也想见见这位先生！"] = "Ха-ха, выдайся возможность, я бы тоже хотел познакомиться с этим господином!",
    ["哈哈，虽然从无到有很麻烦，但是听到这样的赞美果然还是很爽啊。"] = "Ха-ха, хоть и хлопотно создавать что-то из ничего, но слышать такую ​​похвалу все равно очень приятно.",
    ["哈哈，那不如喝杯咖啡吧？"] = "Хаха, тогда почему бы не выпить чашечку кофе?",
    ["哈罗德百货"] = "Универмаг Харродс",
    ["哈罗德百货……"] = "универмаг Гарольда...",
    ["哈罗德百货没有开门，为什么还有安保？"] = "Универмаг «Гарольд» закрыт, почему там еще охрана?",
    ["哈，我是泰利的朋友嘛。我还看过他珍藏的画像，的确是位美丽的女士。"] = "Ха, я друг Терри. Я даже видел портрет, которым он так дорожил; она действительно красивая женщина.",
    ["哎呀喵，你真是个好家伙！不像那些牙齿尖尖的混球。"] = "О боже, мяу, ты действительно хороший парень! В отличие от этих зубастых придурков.",
    ["哎呀，不多说了。我要赶紧把新鲜的水刃草摊开晾干。"] = "О боже, хватит разговоров. Мне нужно поторопиться и разложить свежую траву Водяных клинков, чтобы она высохла.",
    ["哎呀，看来这一幕少了一位角色呢。"] = "О боже, кажется, в этой сцене не хватает персонажа.",
    ["哎嘿哎嘿哎嘿！"] = "Хе-хе, хе-хе, хе-хе!",
    ["哟，来了个识货的。一看你就是懂行的——要买瓜不？"] = "О, прибыл тот, кто знает свое дело. Я могу сказать, что вы эксперт — хотите купить тыкву?",
    ["哦对，你也来自那里，可以看懂罗塞尔用中文写的日记。"] = "Ах да, вы тоже родом оттуда, так что вы можете понять дневник, который Розель написала на китайском языке.",
    ["哦对，差点忘了！"] = "Ах да, чуть не забыл!",
    ["哦！你出现得有些突然，着实吓了我一跳。"] = "Ой! Ты появился совершенно внезапно, ты меня очень напугал.",
    ["哦？泰利·里斯本去世了啊……我叫戴娜，就住在这附近。"] = "Ой? Терри Лисбон скончался... Меня зовут Дана, я живу неподалеку.",
    ["哦？真的读完了吗……不是只看了三分之一就丢在床头的那种？"] = "Ой? Ты действительно дочитал ее... не ту, когда прочитал только треть и оставил ее в изголовье кровати?",
    ["哪有什么女神。那是瓦莱莉的母亲赛拉假扮的。"] = "Богини не существует. Это была замаскированная мать Валери, Сара.",
    ["哪来的小家伙？不像是村子里的小狗呢。"] = "Откуда взялся этот малыш? Он не похож на собаку из деревни.",
    ["哪里有血？"] = "Где кровь?",
    ["哪里能欣赏你的作品？"] = "Где можно оценить вашу работу?",
    ["哼，给我等着！"] = "Хм, подожди!",
    ["哼，胆小鬼不配成为吸血鬼大人的新娘！"] = "Хм, трусы не заслуживают быть невестой Лорда Вампира!",
    ["唉……"] = "Вздох...",
    ["唉……那我再想想办法。不过，奥莉薇是位美丽无比的女士，应该很容易打听。"] = "Эх... тогда я подумаю о другом способе. Однако Оливия невероятно красивая женщина, о ней легко спросить.",
    ["唉！又来了！我一点办法也没有！"] = "Вздох! Это снова мы! Я понятия не имею, что делать!",
    ["唉，不管是鲁恩还是因蒂斯，都远远比不上故乡啊。"] = "Эх, будь то Лоэн или Интис, они намного уступают моему родному городу.",
    ["唉，不说了，我得赶紧走。"] = "Эх, неважно, мне нужно идти быстро.",
    ["唉，书呆子，我改了书的内容！"] = "Эх, книжный червь, я изменил содержание книги!",
    ["唉，召唤灵界生物，果然还是要看缘分。"] = "Эх, призыв существ из Мира Духов действительно зависит от судьбы.",
    ["唉，托马斯走后，埃莉诺的头发一夜就花白了。"] = "Эх, после ухода Томаса волосы Элеоноры за ночь поседели.",
    ["唉，拿到几瓶非凡药剂，也算是有收获，先离开这里吧。"] = "Эх, получение нескольких бутылок зелий Потусторонний считается выигрышем. Давай сначала покинем это место.",
    ["唉，明天就是小瓦莱莉的生日，也不知道这次赛拉能不能回来。"] = "Эх, завтра день рождения маленькой Валери, и я не знаю, сможет ли Серра вернуться на этот раз.",
    ["唉，自信是好事，但……您自己慢慢想想吧！"] = "Эх, уверенность – это хорошо, но… ты должен подумать об этом сам потихоньку!",
    ["唉，那我去找你的真爱来？"] = "Эх, тогда мне стоит пойти найти твою настоящую любовь?",
    ["唔，冷场了啊……果然还是要多练习沟通的技巧。"] = "Хм, повисла неловкая пауза... Как и ожидалось, мне всё-таки нужно больше практиковаться в навыках общения.",
    ["啊……有了！老尼克送给我的护身符，之前一直戴在他身上。"] = "Ах... да! Амулет, который дал мне Старый Ник; он носил его постоянно.",
    ["啊……这是！"] = "Ах... это!",
    ["啊！啊！就是这个！什么《银月公爵的爱欲》，银色饰品，散落的玫瑰，颈部微小的穿刺伤痕……"] = "Ах! Ах! Вот и все! Такие вещи, как «Жажда герцога Серебряной Луны», серебряные украшения, разбросанные розы, крошечные колотые ранки на шее…",
    ["啊！您回来了！见到戈多了吗？"] = "Ах! Ты вернулся! Вы видели Годо?",
    ["啊！罗珊已经出发了，我得在她之前赶到餐厅做好准备才行！"] = "Ах! Розанна уже ушла, мне нужно прийти в ресторан раньше нее, чтобы подготовиться!",
    ["啊！过来了！"] = "Ах! Он приближается!",
    ["啊，你好，找我有什么事吗？"] = "Ах, здравствуйте, я могу вам чем-нибудь помочь?",
    ["啊，别往我的脖子里扔雪！我再看一会儿。回了家，可能下半辈子都不会再看到了！"] = "Ах, не бросайте мне снег в шею! Я посмотрю еще немного. Вернувшись домой, я, вероятно, не увижу этого до конца своей жизни!",
    ["啊，我怎么……也变成亡灵了，原来我已经是失败者了吗？"] = "Ах, как же я... тоже стал нежитью? Выходит, я уже проиграл?",
    ["啊，我想那应该是一个没有恶意的游魂。他已经完成了自己的愿望……"] = "Ах, я думаю, это, должно быть, была блуждающая душа без злобы. Он исполнил свое желание...",
    ["啊，是里奇的钱包！看这张照片，是他念念不忘的未婚妻。"] = "А, это же бумажник Ричи! Взгляните на эту фотографию — его невеста, по которой он так тосковал.",
    ["啊？"] = "Хм?",
    ["啊？可我的星相书，都是花大力气淘来的手写本……"] = "Хм? Но все мои книги по астрологии — это рукописные копии, ради приобретения которых я приложил немало усилий…",
    ["啊？看着挺好吃的啊。"] = "Хм? Хотя выглядит это довольно вкусно.",
    ["啊？！原来是……找工作？难怪在餐厅时你要问他的薪水！"] = "А?! Так это были... поиски работы? Неудивительно, что в ресторане ты расспрашивал о его жалованье!",
    ["啧。"] = "Тц.",
    ["啧，占星占星，一天就知道占星。"] = "Тьфу, астрология да астрология, только о ней целыми днями и твердишь.",
    ["啧，因蒂斯的贵族我也不怎么欣赏。呃，不欣赏其中一部分行事风格。有的也还可以。"] = "Тьфу, аристократов Интиса я тоже не особо жалую. Ну, то есть некоторые их замашки... Хотя отдельные личности вполне сносны.",
    ["喝下它后，那些丢光的知识我全想起来了，清晰得像是刚看完书。"] = "Выпив его, я вспомнил все утраченные знания так ясно, словно только что прочитал книгу.",
    ["喝下那杯茶的人，会得到与茶会主人共饮的机会。"] = "Тот, кто выпьет эту чашку, получит возможность выпить с хозяином чаепития.",
    ["嗯……"] = "Хм...",
    ["嗯……埃姆林先生，我还有点担心，你说召唤这么强大的灵界生物时……会出问题吗？"] = "Хм... Мистер Эмлин, я все еще немного волнуюсь. Вы сказали, что при вызове такого могущественного существа из Мира Духов... возникнут ли проблемы?",
    ["嗯……很难形容。我第一次见到他，是在我最绝望的时候。"] = "Хм... это сложно описать. Впервые я встретил его, когда был в самом отчаянии.",
    ["嗯……比如先从这些笔记本开始？"] = "Хм... например, начать с этих тетрадей?",
    ["嗯……至少……没有人会再死在这里了……"] = "Да... по крайней мере... здесь больше никто не умрёт...",
    ["嗯。但他从来不抱怨。所以我们也努力不让他费心，让他多一点时间休息。"] = "Да. Но он никогда не жаловался. Поэтому мы тоже старались не давать ему волноваться и давали ему больше времени на отдых.",
    ["嗯哼，不可否认，贝克兰德是大都市，繁华、案件多样、教会资源也充足。但我不需要那些。廷根有河，有雾，有安静的街道。还有……"] = "Мммм, нельзя отрицать, что Бэкланд — это мегаполис: шумный, полный разнообразных дел и богатый церковными ресурсами. Но мне они не нужны. В Тингене есть река, туман и тихие улицы. А еще...",
    ["嗯！是妈妈！"] = "Да! Это мама!",
    ["嗯，会一些，日常记录或者工作都会用到。"] = "Ну, я знаю немного; Я использую его для ежедневных записей или работы.",
    ["嗯，作为值夜者，我们永远相信队友，黑荆棘的同伴永远是最好的。"] = "Что ж, мы, «Ночные ястребы», всегда доверяем нашим товарищам по команде. Спутники Блэкторна всегда лучшие.",
    ["嗯，它是我年轻时意外获得的。那时候我厉害得很，什么门都挡不住我。"] = "Да, он достался мне случайно в молодости. Тогда я был очень силён, и никакая Дверь меня не останавливала.",
    ["嗯，当时有无数塔罗牌摆在眼前，冥冥之中我选中的是“星星”。现在看来，命运的安排还真是奇妙啊。"] = "Да, в тот момент передо мной лежало бесчисленное множество карт Таро, и в темноте я выбрал «Звезду». Теперь кажется, что устроена судьба поистине чудесно.",
    ["嗯，很快就能好。"] = "Да, это не займет много времени.",
    ["嗯，我有一个哥哥和一个妹妹。哥哥在政府部门工作，妹妹还在上学。他们都是很好的人。"] = "Да, у меня есть старший брат и младшая сестра. Мой брат работает в государственном ведомстве, а сестра еще учится в школе. Они оба очень хорошие люди.",
    ["嗯，是啊，可怜了那姑娘。里奇这家伙，再也不会四处借东西了。"] = "Да, ты прав, мне ее жаль. Рич, этот парень, никогда больше не будет занимать вещи у людей.",
    ["嗯，没事。您再一次保护了我。"] = "Да, я в порядке. Ты снова защитил меня.",
    ["嗯，班森在外上班，我和克莱恩就专心投入学业。不过他那段时间……有点奇怪。"] = "Да, Бенсон работал на улице, а мы с Клейн сосредоточились на учебе. Но в то время он был... немного странным.",
    ["嗯，魔药配方和材料都准备好了？"] = "Хм, а формула зелья и материалы готовы?",
    ["嗯？"] = "Хм?",
    ["嗯？什么都没有。不对劲，开启灵视试试。"] = "Хм? Ничего. Что-то не так, попробуем духовное зрение.",
    ["嗯？怎么有强大的灵界生物力量波动？你手上拿的是什么？"] = "Эм? Почему происходят сильные колебания силы духовных существ? Что это у тебя в руке?",
    ["嗯？我怎么隐约感觉到了远超公爵级别的力量？"] = "Хм? Почему я смутно чувствую силу, намного превышающую уровень герцога?",
    ["嗯？有事找我？我在你身上感受到了某种不同寻常的伟大气息。"] = "Хм? Что-то нужно? Я чувствую в тебе необычную и прекрасную ауру.",
    ["嗯？树下的人是……"] = "М? Тот, кто под деревом, это...",
    ["嗯？真巧，她和我名字一样。"] = "Хм? Какое совпадение, у нее то же имя, что и у меня.",
    ["噢，那他应该去贝克兰德法庭工作，而不是继承一个出版社。"] = "О, тогда ему следует работать в Баклундском суде, а не наследовать издательство.",
    ["四处散开的孩童"] = "Дети разбегаются повсюду",
    ["回到你的演奏上，《婚礼进行曲》会不会太复杂了？"] = "Возвращаясь к твоей игре: не слишком ли сложен «Свадебный марш»?",
    ["回去吧。俱乐部那些人该等着你带回我凄惨的命运呢，你可以把我在雪山的遭遇告诉他们，让他们开心开心。"] = "Возвращаться. Эти люди в клубе, должно быть, ждут, что ты вернешь мою несчастную судьбу. Ты можешь рассказать им о моей встрече на Снежной горе, чтобы они были счастливы.",
    ["回忆艾琳娜的表情"] = "Вспомните выражение Елены",
    ["回收碎片会让她清醒，但要破坏非凡力量并让你逃离……"] = "Восстановление фрагментов сделает ее трезвой, но уничтожить необыкновенную силу и позволить вам сбежать...",
    ["回来了？感觉如何？"] = "Вернулся? Ну как себя чувствуешь?",
    ["回答我一个问题，我就告诉你答案。"] = "Ответь мне на один вопрос, и я скажу тебе ответ.",
    ["因为……咳，虽然加入了塔罗会，但我实际上还是黑夜教会值夜者，“星星”不仅是女神的象征，也代表了无数的值夜者同伴。"] = "Потому что... хм, хотя я и вступил в Клуб Таро, на самом деле я Ночной Ястреб Церкви Ночи. «Звезда» — это не только символ Богини, но и бесчисленное количество спутников Ночного Ястреба.",
    ["因为你封印及时，没有造成太多伤亡。教会批准了你对“霜之匣”的短暂借用。"] = "Потому что вы вовремя запечатали его, жертв было немного. Церковь одобрила ваше временное использование «Ларца Мороза».",
    ["因为我不想它们失去传承。这些技艺是骑士们安身立命的根本，我不知道这些技艺失传了，我们所恪守的骑士之道是否也会消失。被时代所抛弃的人。"] = "Потому что я не хочу, чтобы прервалось наследие. Эти навыки — основа, на которой держалась жизнь рыцарей. Если они будут утеряны, боюсь, исчезнет и рыцарский кодекс, которому мы следуем. Мы лишь люди, брошенные своей эпохой.",
    ["因为我们在等待戈多。"] = "Потому что мы ждем Годо.",
    ["因为我已经申请把功勋换成了别的东西，黑荆棘需要一些新设备，以及各种额外的符咒和材料。"] = "Это потому, что я уже подал заявку на обмен своих заслуг на другие вещи. Блэкторну нужно новое снаряжение, а также различные дополнительные амулеты и материалы.",
    ["因为我没有急于行动？"] = "Потому что я не спешил действовать?",
    ["因为现在已经不是我们的时代了，是你们的，更是科技的，想想，射击对你们警察来说是不是比格斗更重要。"] = "Потому что наше время уже прошло. Теперь настал ваш век — и век технологий. Подумай сам, разве для вас, полицейских, стрельба не важнее рукопашного боя?",
    ["因为，我也是——观众。"] = "Потому что я тоже — Зритель.",
    ["在“不死者”的阶段，确实会有和我相似的情况。不过我的状态，并不是恩赐，而是一种诅咒。"] = "На стадии «Бессмертного» действительно бывают случаи, схожие с моим. Но моё состояние — не дар, а проклятие.",
    ["在万人迷之前，你是个医生啊，霍普先生。"] = "Прежде чем быть всеобщим любимцем, вы прежде всего врач, мистер Хоуп.",
    ["在三年前就结束了啊。"] = "Это закончилось три года назад.",
    ["在信仰黑夜女神的民众里，赛琳娜也是一个常见的名字。"] = "Селена также является распространенным именем среди людей, которые верят в богиню ночи.",
    ["在其光辉照耀的范围内，魔药材料能稳定状态，非凡生物会加速生长。"] = "В радиусе действия его излучения материалы для зелий могут стабилизировать свое состояние, а существа Потустороннего ускоряют свой рост.",
    ["在历史中，我看到银色盔甲的恶灵守护在您身边。"] = "В истории я видел злого духа в серебряных доспехах, охраняющего тебя.",
    ["在哪里！这些猩红遗物，我得交给那个神出鬼没的“管家”，才能获得恩赐！"] = "Где же они! Эти Алые реликвии я должен передать неуловимому «Дворецкому», чтобы получить дар!",
    ["在廷根，我去市场买白水晶，老劳伦斯会多塞我一颗。在贝克兰德，穿黑袍进嘉德列百货，店员眼神就像见了鬼。"] = "В Тингене, когда я ходил на рынок покупать белый хрусталь, старый Лоуренс всегда подкладывал мне лишний. А в Бэкланде зайди в универмаг «Гардли» в чёрном балахоне — приказчики смотрят на тебя так, будто увидели призрака.",
    ["在建立之初，祂就提议了很多非常实用的建议：比如简化了审核流程，助学基金的发放绑定到本人账户。"] = "В самом начале Он внес множество весьма практичных предложений: к примеру, упростить процедуру проверки и привязать выплаты стипендиального фонда напрямую к личному счету учащегося.",
    ["在愚者的指引下，神使达尼兹带领众人离开了那片被诅咒的大地，越过泛着金芒的大海，在“慷慨之城”拜亚姆定居，重建家园。"] = "Под руководством Шута божественный посланник Даниц повел всех покинуть эту проклятую землю, пересечь золотомерцающее море и поселиться в «Городе Щедрости» Баяме, чтобы восстановить свои дома.",
    ["在我因为服下魔药状态还不稳定的时候，我听到了诸多赞美和歌颂，这些声音如同船锚，帮我稳定住了自己。"] = "Когда после приема зелья мое состояние все еще было нестабильным, я слышал много хвалебных отзывов и песен. Эти голоса были как якоря, помогая мне стабилизироваться.",
    ["在执政官的记忆里，我看到无辜的人倒下，成为尸体被驱使。为了帝国，他们的生命如羽毛般被轻飘飘夺去。"] = "В воспоминаниях администратора я видел, как невинные люди падали и превращались в трупы, которых нужно было гнать. Ради империи их жизни отняли так же легко, как перья.",
    ["在找那些狂热的知识信徒。四十年来，我一直在阻止你们，阻止你们被知识吞没。"] = "Поиск тех фанатичных верующих в знания. Сорок лет я останавливал тебя, не давал тебе быть поглощённым знанием.",
    ["在教堂广场，用“神降”仪式向“愚者”先生祈求。当神灵降恩，奇迹诞生，你的愿望将会被实现。"] = "На церковной площади используйте ритуал «божественного происхождения», чтобы помолиться Мистеруу. Когда Бог сойдет с благодатью и родится чудо, ваше желание исполнится.",
    ["在桌上。"] = "На столе.",
    ["在梦里，对方想要隐瞒的信息都将无所遁形。"] = "Во сне информацию, которую хочет скрыть другая сторона, спрятать будет некуда.",
    ["在神弃之地，没有资格谈后悔。"] = "В Заброшенной Земле Богов нет никаких оснований говорить о сожалении.",
    ["在这四皇之战的战场上，我们与古老的存在签订契约，用猎杀来换取恩赐。"] = "На поле битвы Войны четырех императоров мы заключаем договор с древними сущностями, обменивая охоту на дары.",
    ["在进行“神降”仪式时，你可以收集周围同样是愚者信徒的人们的力量，通过仪式，将这些信仰的力量传达给“愚者”先生，帮祂稳固锚。"] = "Во время ритуала «Схождения бога» вы можете собрать силу окружающих, также являющихся последователями Шута, и через ритуал передать эту силу веры господину «Шуту», помогая Ему укрепить якоря.",
    ["在非凡世界，诵念陌生的尊名很有可能召唤出未知的危险。除了正神的尊名，以及塔罗会同伴的尊名，你不可诵念其他尊名。"] = "В Необыкновенном Мире повторение неизвестного почетного имени с большой вероятностью может вызвать неизвестные опасности. За исключением почетных имен истинных богов и спутников Клуба Таро, вы не должны повторять другие почетные имена.",
    ["在黑夜女神的教义中，女性和男性拥有一样的社会地位。她们被鼓励走出家门，女性也可以当警察。"] = "В учении Богини Вечной Ночи женщины и мужчины имеют одинаковый социальный статус. Их призывают выйти из своих домов, а женщины также могут быть полицейскими.",
    ["地上到处是残留的血迹……你一直在拿人喂这些南瓜？"] = "На земле повсюду следы крови... ты этими тыквами кормил людей?",
    ["坐骑，或是称之为灵骑更合适。友善的灵界生物，可以作为坐骑。你看起来很想试试？作为这方面的前辈，我不介意指点你一下。"] = "Маунт, или, возможно, правильнее было бы назвать его духом. Дружественные существа из Мира Духов могут использоваться в качестве средств передвижения. Ты выглядишь так, будто действительно хочешь попробовать? Как старший в этом отношении, я не против дать вам несколько советов.",
    ["坚守正义的警察队长"] = "Капитан полиции отстаивает справедливость",
    ["坦诚的说，我的年代，鲁恩的科技还在追着因蒂斯的影子跑——当然，这是因为我的治理。"] = "Честно говоря, в мою эпоху технология Лоэна все еще преследовала тень Интиса — конечно, это произошло из-за моего управления.",
    ["埃姆林先生已经是序列3的强者了？"] = "Мистер Эмлин уже силач 3-й Последовательности?",
    ["埃姆林先生，你的表情……看起来很羡慕。"] = "Мистер Эмлин, выражение вашего лица... выглядит очень завистливым.",
    ["埃姆林先生，我该去哪里举行“神降”仪式呢？"] = "Мистер Эмлин, где мне следует провести ритуал «божественного нисхождения»?",
    ["埃洛伊丝，离开他好吗？他根本不懂你，他只是想要一个听话的机器。"] = "Элоиза, оставь его, ладно? Он вас совсем не понимает; ему просто нужна послушная машина.",
    ["埃莉诺·怀斯，你想看见所有的叶子吗？"] = "Элеонора Уайз, хочешь увидеть все листья?",
    ["埃莉诺，你已经在这座山上待了三个月了。经费都要用完了，你还要采到什么时候？"] = "Элеонора, ты торчишь на этой горе уже три месяца. Средства почти закончились, сколько ты ещё будешь собирать образцы?",
    ["城堡从一片荒地，到如今铁路繁荣、工坊热闹、市场开张——您亲手缔造了这一切，而我相信，这还只是个开始。"] = "От пустоши до процветания замка: железные дороги, шумные мастерские, открытые рынки — все это вы создали своими руками. И я верю, что это лишь начало.",
    ["基拉什么时候回来……"] = "Когда вернется Хила...",
    ["基金会的理念真的非常好，它一定帮助了不少贫穷的孩子求学，赞美“愚者”先生。"] = "Философия фонда поистине превосходна. Должно быть, это помогло многим бедным детям продолжить образование. Слава господину Шуту.",
    ["塔罗牌不也是牌吗？牌是什么不重要，重要的是怎么打这张牌。"] = "Разве карта Таро не просто карта? Неважно, что это за карта; важно то, как вы в это играете.",
    ["处理各种非凡事件，管理那些危险的封印物。"] = "Разрешение различных чрезвычайных происшествий и управление опасными запечатанными артефактами.",
    ["多少钱一次"] = "Сколько за сеанс?",
    ["多少？你这南瓜皮是金子做的，还是南瓜籽是金子做的？"] = "Сколько?! У тебя что, кожура этой тыквы из золота, или семечки золотые?!",
    ["多荒谬，我明明用“归乡”锚定了家的位置，却再也不能回家。"] = "Как нелепо: я ведь «Возвращением домой» закрепил местоположение дома, а вернуться уже не могу.",
    ["夜晚"] = "Ночь",
    ["夜晚在我周围降临。"] = "Ночь опускается вокруг меня.",
    ["夜晚属于女神，幽深的黑暗是这座教堂的主角。黑夜女神教会一贯的风格就是昏暗，宁静，烛火稀少。"] = "Ночь принадлежит Богине, а глубокая тьма – главная героиня этого собора. Церковь Богини Вечной Ночи имеет последовательный стиль: тусклый, тихий и с небольшим количеством свечей.",
    ["大多是值夜班的时候画的，他们喜欢打牌，我喜欢画画。"] = "Большинство из них были нарисованы во время ночной смены. Они любят играть в карты, а я люблю рисовать.",
    ["大家不能就这样躺在这里……我想把这里修成一座墓地，安葬大家，也安葬我自己。"] = "Не могут все здесь так лежать... Я хочу превратить это место в кладбище, чтобы похоронить всех, и себя в том числе.",
    ["大家快不行了，我去求救，然后我遇到了您，您带我找回了营地……啊，营地！我想起来了……"] = "Все умирали, поэтому я пошел за помощью. Потом я встретил тебя, и ты привел меня обратно в лагерь... Ах, лагерь! Я помню сейчас...",
    ["大家是否有注意到，广场上的艺术家和巡警有很多女性，这在其他区域是不常见的。"] = "Все заметили, что среди артистов и патрульных на площади много женщин? В других регионах это не распространено.",
    ["大海比陆地更危险，但也更……自由。"] = "Море опаснее суши, но и более... свободное.",
    ["天使之羽是主材料，还需要风灵之息作为副材料，这些都要准备好。"] = "Перо ангела — основной материал, также нужно Дыхание ветряного духа как дополнительный материал. Всё это необходимо подготовить.",
    ["天使？"] = "Ангел?",
    ["天呐，那老师要怎么区分她们？"] = "Господи, а как учитель их различает?",
    ["天哪……这什么声音？像上次剧院那场演出，糟透了！"] = "Боже мой... что это за звук? Как тот спектакль в театре в прошлый раз, это было ужасно!",
    ["天天和尸体打交道的人，还怕这个？"] = "Тот, кто каждый день имеет дело с трупами, все еще боится этого?",
    ["天气很恶劣，暴风雪半小时内一定会降临！"] = "Погода ужасная; через полчаса обязательно налетит метель!",
    ["天虽然黑，但黑夜之后就是黎明。这个人趴着，但他还活着。只要站起来，十把剑就留在地上，带不走了。"] = "Хотя небо темное, за ночью следует рассвет. Этот человек лежит, но он еще жив. Пока он встанет, десять мечей останутся на земле, и их нельзя будет забрать.",
    ["太好了！跟我来吧！"] = "Большой! Подписывайтесь на меня!",
    ["太好了，侍者，麻烦上一下我们的菜！"] = "Отлично, официант, подайте, пожалуйста, нашу еду!",
    ["太好了，我们一起去玩吧！"] = "Отлично, пойдем играть вместе!",
    ["太好了，那就只剩下一个条件——正常不会融化的冰块。什么样的冰块不会融化呢……"] = "Отлично, тогда остаётся только одно условие — лёд, который в обычных условиях не тает. Какой же лёд не тает...",
    ["太棒了安多！我就知道你一定可以！"] = "Это потрясающе, Андор! Я знал, что ты сможешь это сделать!",
    ["太阳，布丁最喜欢晒太阳……"] = "Солнце, Пурин больше всего любила загорать...",
    ["夫人，别急，佐伊小姐暂时没有危险，而事实需要我们亲眼确认。"] = "Мэм, не волнуйтесь. Мисс Зои пока ничего не угрожает, и нам нужно убедиться в этом собственными глазами.",
    ["夫人，您先别急，我帮您占卜看看。"] = "Мэм, не волнуйтесь. Позвольте мне провести для вас гадание.",
    ["夫人，您看起来很着急？"] = "Госпожа, вы кажетесь очень взволнованной?",
    ["失去的记忆？"] = "Потерянные воспоминания?",
    ["奇怪，你最近运气不错，事业上还会有人帮忙。"] = "Странно, но в последнее время вам очень везет, и кто-то даже поможет вам в карьере.",
    ["奇怪？你是指什么？"] = "Странным? О чем ты?",
    ["奥莉薇已经去世了？"] = "Оливия уже скончалась?",
    ["奥黛丽小姐，为什么苏茜女士会说话呢？它……是神奇生物吗？"] = "Мисс Одри, а почему мисс Сьюзи умеет разговаривать? Она... необыкновенное существо?",
    ["奥黛丽小姐，您在现实世界的身份是一位心理医生？"] = "Мисс Одри, в реальном мире вы психолог?",
    ["奥黛丽小姐，您有尊名吗？如果我想向您祈求帮助，应该诵念什么呢？"] = "Мисс Одри, у вас есть титул? Если я хочу помолиться вам о помощи, что мне следует повторять?",
    ["奥黛丽小姐，我听说你还是鲁恩慈善助学基金的理事。"] = "Мисс Одри, я слышал, что вы также являетесь директором Благотворительного студенческого фонда Луен.",
    ["奥黛丽小姐，谢谢你之前赠予我的钱。"] = "Мисс Одри, спасибо за деньги, которые вы мне дали раньше.",
    ["奥黛丽小姐，除了家族财产，你还自己投资吗？"] = "Мисс Одри, помимо семейной собственности, вы инвестируете и себя?",
    ["奥黛丽是观众途径的非凡者，她太擅长观察别人了，却常常忘记观察自己。她能为别人的痛苦落泪，却把自己的疲惫藏得很好。"] = "Одри — выходец за пределы пути зрителя; она слишком хорошо наблюдает за другими, но часто забывает наблюдать за собой. Она может лить слезы из-за чужой боли, но хорошо скрывает собственную усталость.",
    ["女士，你冷静点。"] = "_\n\nМадам, успокойтесь.",
    ["女神啊，请您务必试试！"] = "О Богиня, пожалуйста, ты должна попробовать!",
    ["奶奶总是唱：“我会变成一只小猫，爬进你的摇篮。”"] = "Бабушка всегда пела: «Я превращусь в котёнка и заползу в твою колыбельку».",
    ["奶奶，我好想吃你做的苹果派。"] = "Бабушка, я так соскучилась по твоему яблочному пирогу.",
    ["奶奶，是你回来了吗？"] = "Бабушка, это ты?",
    ["她不是去见一个人……她是……"] = "Она не ходила к кому-то... она...",
    ["她不是故意这么做的，她只是不太清醒。"] = "Она сделала это не нарочно; она просто не очень рассудительна.",
    ["她临死前拉着我的手说——她这辈子最后悔的，不是相信了占卜。"] = "Перед смертью она взяла меня за руку и сказала: больше всего в жизни она сожалела о том, что не верила в гадание.",
    ["她什么时候回来？"] = "Когда она вернется?",
    ["她什么都没说，但我看见了，相亲的地点是老维尔餐厅。"] = "Она ничего не сказала, но я видел, место свидания вслепую - ресторан Old Will's.",
    ["她从小懂得孝顺老父亲，爱护弟弟，心疼妈妈，有的时候，又特别正直，显得有点傻，唉。"] = "С юных лет она умела быть сыновней по отношению к старому отцу, заботиться о младшем брате и любить мать. Иногда она бывает особенно прямой и выглядит немного глупо, вздыхает.",
    ["她们看到葡萄架下有一滩血，吓得跑了。"] = "Они увидели лужу крови под виноградной решеткой и в страхе убежали.",
    ["她们都给自己起了昵称，大赛琳娜，小赛琳娜，蓝色赛琳娜……"] = "Все они дали себе прозвища: Большая Селена, Маленькая Селена, Синяя Селена...",
    ["她会愣一下，然后笑出来，说：“苏茜，你什么时候学会心理咨询了？”"] = "На мгновение она будет ошеломлена, затем засмеется и скажет: «Сьюзи, когда ты научилась психологическому консультированию?»",
    ["她会说什么吗？"] = "Она что-нибудь говорит?",
    ["她似乎能用言语操控他人的情绪。不像是普通的社交能力，是非凡能力。难道是刺客途径教唆者？"] = "Кажется, она способна управлять чужими эмоциями одними лишь словами. Не похоже на обычный дар убеждения — это Потусторонняя способность. Неужели Подстрекатель Пути Убийцы?",
    ["她动手了！"] = "Она сделала ход!",
    ["她半年前患上了急性血液病，因为没有足够的费用治疗，不久后就去世了。"] = "Полгода назад она перенесла острое заболевание крови и вскоре умерла из-за нехватки денег на лечение.",
    ["她告诉我，这些东西不是用来对付普通罪犯的。"] = "Она сказала мне, что эти вещи предназначены не для обычных преступников.",
    ["她和朋友聊天也张口闭口提到“亲爱的”……可我问她什么她都不说！"] = "Она продолжает говорить «дорогой» каждый раз, когда разговаривает со своими друзьями... но она ничего мне не говорит, когда я спрашиваю!",
    ["她在夜色里诞生，打了两个响指就落成这座小镇。"] = "Она родилась ночью, и двумя щелчками ее пальцев был построен этот маленький городок.",
    ["她好像在说：“苏茜，我需要一个人待一会儿。你能帮我看着门吗？”"] = "Она как бы говорила: «Сьюзи, мне нужно немного побыть одной. Можешь помочь мне присмотреть за дверью?",
    ["她怎么说？"] = "Что она сказала?",
    ["她才十四岁，刚才又避开我溜出家门，我好担心，她是不是跟什么坏人来往了？"] = "Ей всего четырнадцать. Ранее она снова ускользнула из дома, и я так волнуюсь. Она общается с плохими людьми?",
    ["她救了你。"] = "Она спасла тебя.",
    ["她无疑是全场最引人注目的人。五官精致得近乎不真实，灰绿色的眼眸带着漫不经心的疏离——像在享受这场舞会，又像在冷眼旁观所有人。"] = "Она, несомненно, приковывала к себе больше всего взглядов во всём зале. Черты её лица были изысканны до неправдоподобия, а в серо-зелёных глазах читалась небрежная отрешённость — словно она наслаждалась балом, но в то же время с холодным равнодушием наблюдала за всеми.",
    ["她是个好人。虽然她总是一副冷冰冰的样子，但她从不像大地母神教会的那帮人一样，真的阻止我做研究。"] = "Она хороший человек. Хотя у нее всегда холодный взгляд, она никогда не мешает мне проводить исследования, как эта компания из Церкви Матери-Земли.",
    ["她是第一个叫我名字的人，不嫌弃我是赠品的人。"] = "Она первая, кто назвал мое имя, та, кто не возражал против того, чтобы я был бесплатным подарком.",
    ["她最近总抱怨夜班和皮肤差，该找个能和她轮班的同事。"] = "В последнее время она жаловалась на ночные смены и плохую кожу; ей следует найти коллегу, который сможет работать с ней посменно.",
    ["她没说茶会的地点，只留下了这枚胸针。"] = "Она не сказала, где было чаепитие, оставила только эту брошь.",
    ["她的眼神没有杀意。尖叫太刻意，像是故意制造恐慌。"] = "В ее глазах нет намерения убить. Крик был слишком преднамеренным, как будто она намеренно создавала панику.",
    ["她的记忆和情绪破碎了，散落在那些碎片里。"] = "Ее воспоминания и эмоции разбиты, разбросаны среди этих фрагментов.",
    ["她笑着在公园的各个角落里，准确找到了躲藏的孩子们。阳光所到之处，到处洋溢着纯真的欢笑。"] = "Смеясь, она безошибочно находила прячущихся ребятишек в каждом уголке парка. И всюду, куда проникали солнечные лучи, звенел чистый, искренний смех.",
    ["她给一个卖鱼的说他妻子会好起来——牌面明明是逆位星币五，贫困和疾病。她偏说什么“两个人依偎着就能等到春天”。这不是骗人是什么？"] = "Она сказала торговцу рыбой, что его жене станет лучше — карта явно была перевернутой Пятеркой Пентаклей, бедностью и болезнью. Она настаивала на том, что «два человека, опирающиеся друг на друга, могут дождаться весны». Если это не мошенничество, то что?",
    ["她给了我一个能做实验的地方，让我可以继续做研究。"] = "Она дала мне место для экспериментов, позволив мне продолжить исследования.",
    ["她衣服上总沾着皮屑，恐怕只有成年男子有那样大块的皮屑！多脏的人啊！"] = "Ее одежда всегда покрыта чешуйками кожи; Боюсь, такие крупные хлопья будут только у взрослого мужчины! Какой грязный человек!",
    ["她说——你看这两个人，穿得破，但靠在一起。"] = "Она сказала: посмотрите на этих двух людей, они одеты в лохмотья, но опираются друг на друга.",
    ["她说——剑已经全部落下了，不会再多了。"] = "Она сказала: все мечи уже пали, больше их не будет.",
    ["她需要一个不被注意的观察者，我能在这里找到自己的位置；我也能看见她的疲惫，提醒她停下来注意休息。我们总是在互相帮助。"] = "Ей нужен незаметный наблюдатель, и я смогу найти здесь свое место; Я также вижу ее утомление и напоминаю ей остановиться и отдохнуть. Мы всегда помогаем друг другу.",
    ["好,我去试试"] = "Хорошо, я попробую",
    ["好。"] = "Хорошо.",
    ["好。能见到你，就说明当年那张高塔，已经被你打成了逆位高塔。我不会再担心了。"] = "Хороший. Увидеть вас означает, что карта Башни того времени уже была разыграна вами как перевернутая Башня. Я больше не буду волноваться.",
    ["好主意，带我一个。"] = "Хорошая идея, примите меня в расчет.",
    ["好了，弗莱，不论是相亲还是婚姻，都和调查非凡案件完全不同呀。"] = "Хорошо, Фрай, будь то свидание вслепую или свадьба, это полностью отличается от расследования дел Потустороннего.",
    ["好像也没什么变化，树还是这棵树，土地还是这片地。"] = "Не похоже, что что-то изменилось. Дерево всё то же дерево, земля всё та же земля.",
    ["好像叫海莉。就在铁十字街拐角，一棵梧桐树下面。"] = "Я думаю, ее зовут Хали. Прямо на углу Айрон-Кросс-стрит, под платаном.",
    ["好像可以从这边的洞口进去……"] = "Кажется, я могу пройти через отверстие здесь...",
    ["好像是做不到，连我的爷爷和父亲也不行。"] = "Кажется, это невозможно. Ни мой дед, ни отец не смогли.",
    ["好像是这么回事。"] = "Кажется, это так.",
    ["好冰，得快点把它带走收容……"] = "Как холодно, надо скорее забрать это и поместить на хранение...",
    ["好吃的——"] = "Вкусный-",
    ["好吧。明天一定会来，他说过的。"] = "Отлично. Он обязательно придет завтра, пообещал он.",
    ["好吧，我承认我培育的一些品种……确实有那么一点点副作用。"] = "Ладно, признаю: некоторые выведенные мной сорта... и правда имеют крошечные побочные эффекты.",
    ["好吧，死后也有阶层差距。"] = "Что ж, похоже, классовое разделение существует даже после смерти.",
    ["好啊，看来真是马丁在闹鬼，我跟你没完！"] = "Ладно, похоже, Мартин действительно бродит по этому месту. Я еще не закончил с тобой!",
    ["好啦，其实看着你们乱放的扑克、墙上泛黄的合照和这一杯杯咖啡，我早就不生气了。"] = "Ладно вам... На самом деле, глядя на разбросанные карты, пожелтевшую совместную фотографию на стене и эти чашки кофе, я уже давно перестала сердиться.",
    ["好多人……那边的侍者好像在介绍茶会的规矩？也许有线索，去听听看吧。"] = "Столько народа... Официант вон, кажется, объясняет правила чаепития? Может быть, есть подсказка, пойдем послушаем.",
    ["好好挥霍你的天赋吧。"] = "Распорядитесь своим талантом правильно.",
    ["好心人，我还有最后一个问题。我们最后胜利了吗？"] = "Добрый человек, у меня остался последний вопрос. Мы ведь... победили в конце концов?",
    ["好心人，请帮忙找找我的同伴，或许他们中还有人……能实现我们愚蠢的梦想。"] = "Добрый человек, помогите найти моих товарищей. Быть может, кто-то из них... сумеет осуществить нашу глупую мечту.",
    ["好新鲜的水刃草，谢谢你送我生日礼物！"] = "Такая свежая Водяная Трава-Блинка, спасибо за подарок на день рождения!",
    ["好痛喵，吃坏肚子了喵。"] = "Больно, мяу, у меня болит живот, мяу.",
    ["好痛，头好痛……呃，我到底是谁……我是……"] = "Больно, голова так болит... эх, кто я... я...",
    ["好的。"] = "Хорошо.",
    ["好的，我考虑一下，谢谢你。"] = "Хорошо, я подумаю, спасибо.",
    ["好贵！"] = "Так дорого!",
    ["好重的雾气……这里不会真有亡灵吧？"] = "Такой густой туман... неужели здесь не было бы духов, не так ли?",
    ["好齐全！水刃草、夜香草、蜂后草、《高级药剂大全》……"] = "Как полно! Водяная трава, Ночная ароматная трава, Пчелиная трава, «Продвинутый сборник зелий»…",
    ["好，我记住了，我一定平安带回“2-327”。"] = "Хорошо, я запомнил. Я обязательно доставлю «2-327» в целости и сохранности.",
    ["好，祝你顺利。"] = "Отлично, желаю успехов.",
    ["好，那可以来调配魔药了。放轻松，我相信这次晋升你也一定可以。"] = "Хорошо, тогда мы сможем приготовить зелье. Расслабьтесь, я верю, что вы тоже обязательно преуспеете в этом продвижении.",
    ["好，那我们就开始……"] = "Хорошо, тогда начнем...",
    ["如今生命将尽，我想在死之前，去知识的深处，找到他们，确认……他们也幸福。"] = "Теперь, когда моя жизнь вот-вот закончится, я хочу отправиться в глубины знаний, чтобы найти их, прежде чем умру, и подтвердить, что... они тоже счастливы.",
    ["如今，我真的成为“星星”了，才理解了他这句话的含义。"] = "Теперь, когда я по-настоящему стал «Звездой», я понимаю смысл его слов.",
    ["如何将自己的名字显示在上面？"] = "Как сделать так, чтобы на этом отображалось моё имя?",
    ["如果不找回那些碎片复原记忆，谁都无法从这里离开……"] = "Если мы не найдем эти фрагменты и не восстановим ее воспоминания, никто не сможет покинуть это место...",
    ["如果不是刚好来霍伊大学办事，恐怕都不知道这次又有人要放弃名额了。唉……"] = "Если бы я не приехал в Университет Хой по делам, я, вероятно, не узнал бы, что кто-то снова уступает свое место. Вздох...",
    ["如果产生任何失控的预兆——比如呓语、头痛、灵性动荡——随时来找我。"] = "Если появятся какие-либо признаки потери контроля – например, бред, головные боли или духовная нестабильность – приходите ко мне в любое время.",
    ["如果他被逼无奈呢？"] = "Что, если его заставили?",
    ["如果你也在追寻，像我一样耗尽了生命——"] = "Если ты тоже ищешь, исчерпав, как и я, свою жизнь —",
    ["如果你找到了相关线索，请一定、一定要告诉我。当然，我会支付丰厚的报酬。"] = "Если вы найдете соответствующие подсказки, пожалуйста, обязательно скажите мне. Конечно, я тебе хорошо заплачу.",
    ["如果你有机会……首先，你会游泳吗？"] = "Если выпадет такой шанс... Для начала скажи: ты плавать умеешь?",
    ["如果像男爵夫人所说，仆人胆小且诚实，那回应他的人到底是谁？"] = "Если, как говорит баронесса, слуга робок и честен, то кто ему откликается?",
    ["如果出行的距离不远，你也可以多走走，不坐公共马车。虽然每天只能省下一两个便士，但加在一起是很大一笔钱。"] = "Если расстояние небольшое, вы можете больше ходить пешком, а не ездить в общественном транспорте. Хотя вы можете сэкономить только одну или две копейки в день, в целом это составит большую сумму денег.",
    ["如果去学习的钱攒不够，那就再等等。或者先去小一点的工厂做学徒，边做边学。我觉得，只要努力，一定可以过上比现在更美好一点的生活的。"] = "Если вы не накопили достаточно денег на школу, подождите еще немного. Или пойдите на фабрику поменьше, станьте учеником и учитесь, пока работаете. Я думаю, если ты будешь усердно работать, ты определенно сможешь жить немного лучше, чем сейчас.",
    ["如果因为害怕失控就不去研究，那饥饿、贫穷、疾病这些问题就永远解决不了。"] = "Если бы я не проводил исследования, потому что боялся потерять контроль, тогда такие проблемы, как голод, бедность и болезни, никогда бы не были решены.",
    ["如果它是逆位——逆位塔的含义是“在毁灭后重建”。"] = "Если оно перевернуто, то значение перевернутой Башни — «восстановление после разрушения».",
    ["如果您见到他，告诉他我们在等他。"] = "Если вы его увидите, скажите, что мы его ждем.",
    ["如果我出了什么事，希望大家能帮忙照顾我的女儿，守护她的幸福。"] = "Если со мной что-нибудь случится, я надеюсь, что вы поможете позаботиться о моей дочери и сохранить ее счастье.",
    ["如果我没有看见你放下包裹，我一定会相信的。"] = "Если бы я не увидел, как ты положил пакет, я бы точно поверил.",
    ["如果没有弟弟妹妹，我会失去很多生活和工作的动力……<P_Heart>（停顿）</>算了，不说这些了。"] = "Если бы не мои младшие брат и сестра, я бы потерял большую мотивацию к жизни и работе... <P_Heart>(Пауза)</> Забудьте об этом, давайте не будем об этом.",
    ["如果等到他的话！"] = "Если мы его дождёмся!",
    ["如果能和其他东西结合起来的话，事情应该就明朗了……\n<P_Yellow>（获得了线索并放入背包：神奇物品订购信）</>"] = "Если бы это можно было объединить с другими вещами, все должно стать ясно...\n<P_Yellow>(Получена подсказка и добавлена ​​в инвентарь: Письмо о заказе магического предмета)</>",
    ["如果能活着，也许现在也能是个圣者了。"] = "Останься я в живых, сейчас, быть может, уже стал бы Святым.",
    ["如果需要的话，可以再找“正义”女士做一次心理治疗。"] = "При необходимости вы можете вновь обратиться к мисс Справедливость за сеансом психотерапии.",
    ["妈妈没有骗过我。礼物是真的，女神也是真的。"] = "Мама никогда мне не лгала. Подарки настоящие, и Богиня тоже настоящая.",
    ["妈妈！你不要阻挡我的幸福！"] = "Мать! Не стой на пути моего счастья!",
    ["妈妈？！"] = "Мама?!",
    ["威士忌？"] = "Виски?",
    ["威廉·黑伍德，这场舞会的主人，却不像一个真正的主人。三十出头的面容本该英气逼人，眉宇间却笼着一层淡淡的疲惫。 "] = "Уильям Хейвуд, ведущий этого бала, не похож на настоящего хозяина. Его лицо, которому чуть больше тридцати, должно было бы быть впечатляющим, однако между бровями висит легкий слой усталости.",
    ["威廉的反应"] = "Реакция Уильяма",
    ["威廉，受死吧！"] = "Уильям, умри!",
    ["威廉，听从我！听从我！"] = "Уильям, подчиняйся мне! Повинуйся мне!",
    ["婚礼乐师成了分手大师。"] = "Свадебный музыкант превратился в мастера расставаний.",
    ["孤儿院院长爷爷对大家很好，值夜者叔叔阿姨也时常来看望我们，陪大家玩“成为最厉害的值夜者”的过家家游戏。"] = "Директор приюта Дедушка очень добр ко всем, а дяди и тети-Ночные Ястребы часто приходят к нам в гости и играют со всеми в домашнюю игру «Стать самым сильным Ночным Ястребом».",
    ["孤独吗……"] = "Одиночество, говоришь...",
    ["学习建筑是我的梦想，遗憾的是我没有通过绘画考试。"] = "Изучать архитектуру – моя мечта, но, к сожалению, я не сдала экзамен по рисованию.",
    ["孩子们，让爸爸一个人呆会儿吧。"] = "Дети, позвольте папе немного побыть одному.",
    ["孩子走的时候，我还有布丁。"] = "Когда ребенок ушел, у меня еще оставался Пудинг.",
    ["它……"] = "Это...",
    ["它、它回来了？！"] = "Оно, оно вернулось?!",
    ["它一直让您放弃回去？"] = "Оно всё время заставляет вас отказываться от возвращения?",
    ["它一走，早上醒来，床边毯子空空的……"] = "Когда оно исчезало, я просыпался утром, а одеяло у кровати было пустым...",
    ["它后面还出过什么事吗？"] = "А что-нибудь ещё с ним случалось потом?",
    ["它回来了！"] = "Оно вернулось!",
    ["它在找，它一直在找。"] = "Он ищет, он продолжает искать.",
    ["它始终指向使用者锚定的位置，能让人找到返回的方向。"] = "Он всегда указывает на место, закреплённое пользователем, и помогает найти путь назад.",
    ["它并不直接预示死亡。"] = "Оно не предсказывает смерть напрямую.",
    ["它意味着：我会用我的方式，做我能做的事。"] = "Это значит: я сделаю то, что смогу, по-своему.",
    ["它是我们家族仅剩的东西了，承载的记忆比任何东西都宝贵。"] = "Это единственное, что осталось от нашей семьи; воспоминания, которые он несет, дороже всего остального.",
    ["它曾帮我对抗过高序列的恶灵。但是，它必须守护我，无法全力对敌。"] = "Однажды это помогло мне бороться со злыми духами высокой последовательности. Однако он должен охранять меня и не может сражаться в полную силу.",
    ["它曾经是守知派的圣物。起初只帮人整理记忆、归纳学过的知识。但它会和人交流，交流得越多，它给出得越深。从总结，变成推导，变成揭示。"] = "Когда-то это была священная реликвия фракции Хранителей Знания. Поначалу она лишь помогала упорядочивать воспоминания и обобщать полученные знания. Но она способна общаться с людьми, и чем больше с ней говоришь, тем более глубокие вещи она открывает. От простых выводов — к умозаключениям, а затем и к откровениям.",
    ["它没有眉毛没有眼睛没有鼻子，只有一张嘴，舌头鲜红长满尖牙，顶端还长着五根手指……"] = "У него нет ни бровей, ни глаз, ни носа, только рот, ярко-красный язык, покрытый клыками, и пять пальцев, растущих на кончике...",
    ["它的负面效果是让这范围内的液体逐渐冰冻且不会融化，你刚好可以利用这个效果制造不会融化的冰块。"] = "Его негативный эффект: жидкость в этой области постепенно замерзает и не тает. Этим вы можете воспользоваться, чтобы делать нетающие кубики льда.",
    ["它被切割磨制，嵌进了眼镜框里。"] = "Его вырезали, отполировали и вставили в оправу очков.",
    ["它让你觉得自己可以超越一切，然后你就真的会去尝试超越一切——包括死亡。我见过太多人了，都是这么走进去的。"] = "Это заставляет вас чувствовать, что вы можете превзойти все, и тогда вы действительно попытаетесь превзойти все, включая смерть. Я видел слишком много людей, которые приходили просто так.",
    ["守知派最后一点东西。窥秘人的冥想方法，灵性感知的进阶技巧，还有一些关于隐匿贤者的研究。我用不上了。"] = "Последний кусочек Школы поиска знаний. Методы медитации для Тайных Жрецов, продвинутые техники духовного восприятия и некоторые исследования Скрытого Мудреца. Мне они больше не нужны.",
    ["安保？"] = "Безопасность?",
    ["安多只是我朋友的弟弟，想在廷根找一份文员的工作！"] = "Андо — всего лишь младший брат моего друга, который хочет найти конторскую работу в Тингене!",
    ["安多！快跑，我们得赶紧从入口出去！"] = "Андор! Бегите, нам надо немедленно выйти из подъезда!",
    ["安慰他们"] = "Утешайте их",
    ["安抚亡灵"] = "Умиротворить мертвых",
    ["安洁莉卡把俱乐部打理得很温暖，运气好的话你还能在这里遇见些神奇的人。"] = "Анжелика очень тепло управляет Клубом; Если вам повезет, вы даже сможете встретить здесь удивительных людей.",
    ["安迪女士，你是在找笔记本？"] = "Мисс Энди, вы ищете блокнот?",
    ["完美的色泽，完美的香气。这酒，会成为商路上数一数二的名酒！"] = "Идеальный цвет, идеальный аромат. Это вино станет одним из самых знаменитых вин на торговом пути!",
    ["宝剑侍从望向天空，是在寻找风的方向。"] = "Паж Мечей смотрит в небо, выискивая направление ветра.",
    ["实际上……"] = "В реальности...",
    ["实际上，只有真神才能使用三段式尊名。我和塔罗会其他同伴的尊名，是借助了“愚者”先生的真神位格。"] = "Фактически, только Истинный Бог может использовать почетное имя, состоящее из трех частей. Мои почетные имена и имена других членов Клуба Таро зависят от статуса Истинного Бога Мистераа.",
    ["实际上，那是诅咒。那串手链属于亚伯拉罕家族，而我……因为使用了它，继承了那个家族的血脉诅咒。"] = "На самом деле это было проклятие. Этот браслет принадлежал семье Авраама, и я... поскольку я использовал его, унаследовал проклятие родословной этой семьи.",
    ["客人以为我的肉不新鲜，要我赔钱！"] = "Покупатель подумал, что мое мясо несвежее, и потребовал, чтобы я заплатил за него!",
    ["宣布结果"] = "Объявить результат",
    ["害怕？为什么要害怕？失控只是过程的一部分。就像孩子学走路会摔倒一样，研究者也会犯错。"] = "Страх? Чего бояться? Потеря контроля – это лишь часть процесса. Точно так же, как ребенок, который учится ходить, падает, исследователи тоже совершают ошибки.",
    ["家人的信？你可真幸福！"] = "Письмо из дома? Тебе так повезло!",
    ["富人区"] = "Богатый район",
    ["对。你没有急于下结论。"] = "Да. Вы не поспешили с выводами.",
    ["对。很对。她们的命运确实和我看到的一样。"] = "Да. Это верно. Их судьба действительно была такой же, как и то, что я видел.",
    ["对。那种痛苦……诵念所有正神都没有回应，只有他听到了。"] = "Да. Такая боль... пение всех Истинных Богов не получило ответа, только он услышал это.",
    ["对不起……我不该说的。"] = "Мне очень жаль... Я не должен был этого говорить.",
    ["对不起。"] = "Мне жаль.",
    ["对不起，我不该瞒着你……你生气了吗？"] = "Прости, мне не следовало скрывать это от тебя... ты злишься?",
    ["对了！您侄女靠您留的钱读了好学校，现在挣大钱呢，她带你父母搬到其他区了，他们、他们也很想念你。"] = "Oh right! Your niece used the money you left behind to attend a good school and is making a lot of money now. She moved your parents to another district; they, they miss you very much too.",
    ["对了，他说没有人理会他？说起来，那位猎人似乎也没和他搭话……"] = "Кстати, он сказал, что никто не обращал на него внимания? Если подумать, тот Охотник тоже вроде бы с ним не заговорил...",
    ["对了，你和我们一样，从同一个地方来的。"] = "Кстати, вы, как и мы, родом из того же места.",
    ["对了，她身边总是围着猫。老鼠也是。有回一只老鼠从下水道钻出来，爬到她桌上，像在听她说话。"] = "Кстати, ее всегда окружают кошки. И крысы тоже. Однажды крыса вылезла из канализации и залезла к ней на стол, как будто слушая ее речь.",
    ["对于像我们这样的普通家庭来说，稳定的收入很重要。"] = "Для такой простой семьи, как наша, стабильный доход — это самое главное.",
    ["对于普通人来说，确实是。那您为什么还要教授我们这些传统骑士技艺？"] = "Для обычных людей это действительно так. Тогда почему вы до сих пор учите нас этому традиционному рыцарскому искусству?",
    ["对抗末日，我……"] = "Сопротивляясь апокалипсису, я...",
    ["对血族或他们雇来的赏金猎人来说，我就像是一片空气，完全隐形。"] = "Для вампиров или нанятых ими охотников за головами я словно кусочек воздуха, совершенно невидимый.",
    ["对！吃了之后会看到很多有趣的东西，然后就忘记自己睡不着这件事了。很合理吧？"] = "Да! Съев его, видишь много интересного, а потом забываешь, что не можешь спать. Очень разумно, правда?",
    ["对！我夸大自己的美丽，谎称手握着丈夫的大量资产，就为了诱惑他、引他来——"] = "Да! Я преувеличивала свою красоту и солгала о том, что владею большим количеством активов моего мужа, просто чтобы заманить его и привлечь сюда…",
    ["对！我需要给战友们更大的墓地！"] = "Да! Мне нужно кладбище побольше для моих товарищей!",
    ["对！海上的新鲜蔬菜很难保存嘛，我就想，如果蔬菜能像鱼一样适应海洋环境，那不就能在海面上种菜了吗？"] = "Да! Свежие овощи трудно сохранить в море, поэтому я подумал: если овощи смогут адаптироваться к морской среде, как рыба, разве мы не сможем выращивать их на поверхности моря?",
    ["对，但你知道弗洛这三年什么样吗？"] = "Да, но ты знаешь, какой была Фло последние три года?",
    ["对，它们很有趣吧？"] = "Правда ведь занятно?",
    ["对，我也想看看你和海莉夫人谁算得准。"] = "Да, я тоже хочу посмотреть, кто точнее: вы или мадам Хейли.",
    ["封印物“霜之匣”，危险等级2，打开匣盖后会让周围十米范围内的敌人冰冻，并逐渐臣服于它的主人。"] = "Sealed Artifact \"Casket of Frost\", Danger Level 2. Opening the lid freezes enemies within a ten-meter radius, gradually forcing them to submit to its master.",
    ["尊贵的骑士？或许以前是吧，现在只不过是一群被时代淘汰的老古董罢了。"] = "Достопочтенный рыцарь? Возможно, так было и раньше, но сейчас это всего лишь группа старых антиквариатов, уничтоженных временем.",
    ["小丑的考验在前面等着你们，愿女神庇佑。"] = "Впереди вас ждет испытание Клоуна, да хранит вас Богиня.",
    ["小丑胜！"] = "Клоун победил!",
    ["小伙子，你这琴声不仅能驱鸟，还能帮人恋爱啊！"] = "Молодой человек, ваша игра на скрипке может не только пугать птиц, но и помогать людям влюбляться!",
    ["小伙子，这是你干的？"] = "Парень, это твоих рук дело?",
    ["小心观众……"] = "Берегитесь зрителей...",
    ["小时候，别的孩子喜欢玩布娃娃，她却在拆房间里的座钟。"] = "Когда она была ребенком, другие дети любили играть в куклы, а она была занята разборкой напольных часов в комнате.",
    ["小狒狒，你这是怎么啦？"] = "Маленький бабуин, что с тобой не так?",
    ["小瓦莱莉一直坚信金秋湖里住着一位女神。只要虔诚地许愿，愿望就会被实现。"] = "Маленькая Валери всегда верила, что в озере Цзиньцю живет богиня. Если вы загадаете желание искренне, ваше желание сбудется.",
    ["小艾琳，才是我占卜路上的老师。"] = "Маленькая Эйлин — мой настоящий учитель на пути гадания.",
    ["少女被拯救的时间是？"] = "Когда девочка спасена?",
    ["少女走入转角。迎面而来的不是死路，而是持枪警戒的警察。"] = "Девушка зашла в угол. Перед ней оказался не тупик, а полицейские с оружием на страже.",
    ["少废话！拿来！"] = "Без лишних слов! Гони сюда!",
    ["少来烦我。"] = "Отвяжись от меня.",
    ["少爷……"] = "Мастер...",
    ["少爷……你没事吧？"] = "Молодой господин... с вами все в порядке?",
    ["少爷……你没事就好……没事就好……"] = "Молодой господин... пока с вами все в порядке... пока с вами все в порядке...",
    ["少爷……我想起来了。"] = "Молодой господин... Теперь я вспомнил.",
    ["少爷……那块地……不要赠给我。"] = "Молодой господин... тот участок земли... не нужно дарить его мне.",
    ["少爷，原来你一直知道。少爷……对不起。"] = "Молодой Мастер, так что вы все это знали. Молодой господин... Мне очень жаль.",
    ["尤其是在起风的时候？该死的，我还以为是我的耳朵出现了问题！"] = "Особенно когда поднимается ветер? Проклятье, я уж думал, у меня что-то со слухом!",
    ["尤其是她的爱好——她经常沉迷于齿轮、轴承和其他机械设备。"] = "Особенно ее увлечение — она часто с головой уходит в шестеренки, подшипники и прочие механические устройства.",
    ["就像{{PlayerName}}说的，即使今天是相亲，你们也不应该安排这么多离谱的考验。"] = "Как и сказал {{PlayerName}}, даже если бы сегодня было свидание вслепую, вам не следовало бы устраивать так много абсурдных тестов.",
    ["就像……我明明想回家，却因为它，不断放弃，变得胆怯。"] = "It's just like... I clearly want to go home, but because of it, I keep giving up and becoming filled with Timidity.",
    ["就像二十多年前，我们阿霍瓦骑士团不惧一切，冲向因蒂斯共和国那群侵略者。"] = "Как и более двадцати лет назад, наши рыцари Ахоу ничего не боялись и атаковали захватчиков из Республики Интис.",
    ["就到这里吧"] = "На этом и закончим",
    ["就当我是今天的特别摄影师。听说前面十三天都是别人给你拍照，最后一天，换个角度？"] = "Просто считайте меня сегодняшним специальным фотографом. Я слышал, что первые тринадцать дней тебя фотографировали другие; в последний день, как насчет другой точки зрения?",
    ["就当是这枚指南针，给你上的一课。"] = "Consider this a lesson taught to you by this compass.",
    ["就想象一下？"] = "Представьте себе это?",
    ["就是他提醒我中了诅咒，谢谢。请问，我真可以走了吗？"] = "Это он напомнил мне, что я проклят, спасибо. Могу я спросить, могу ли я действительно уйти сейчас?",
    ["就是偶尔太严肃了，得有人帮他松松弦。"] = "Просто иногда он бывает слишком серьезен; кто-то должен помочь ему расслабиться.",
    ["就是啊！您、您过得还好吗？您去哪里了呀？"] = "Exactly! Are, are you doing well? Where did you go?",
    ["就是这里了！"] = "Вот оно!",
    ["就是那场发生于二十年战争后，背誓之战前的战争。它让鲁恩击败因蒂斯，重新变得强势！"] = "Это была война, которая случилась после Двадцатилетней войны и до Войны клятвопреступников. Это позволило Лоэну победить Интиса и снова стать сильным!",
    ["就是那次，我的那些小家伙们开始繁殖之后，它们钻进了甲板里，然后“未来号”就开始产奶了！"] = "Это было время, когда мои маленькие ребята начали размножаться, они зарылись в палубу, и тогда «Будущее» начало производить молоко!",
    ["就算有新种又怎样？你记录了三千七百种植物，谁在乎再多一种？"] = "Ну и что с того, что это новый вид? Ты описал три тысячи семьсот видов растений, кому есть дело еще до одного?",
    ["就这样吧"] = "Вот и все на данный момент",
    ["就这样吧。能说的，也就是这些了。"] = "Давайте оставим это как есть. Это все, что можно сказать.",
    ["尼克，不准哭！奶奶说了，她最不想别人的眼泪落在她的碑前，她要我们高高兴兴的！"] = "Ник, не плачь! Бабушка сказала, что больше всего ненавидит, когда чужие слезы падают перед ее надгробием. Она хочет, чтобы мы были счастливы!",
    ["尼尔先生，“窥秘人”有什么特别的能力吗？"] = "Мистер Нил, есть ли у «Таинственного Прайера» какие-то особые способности?",
    ["尼尔先生，听说您会弹钢琴？"] = "Мистер Нил, я слышал, вы умеете играть на пианино?",
    ["尼尔先生，您了解代罚者吗？"] = "Мистер Нил, вы знаете об Уполномоченных Карателях?",
    ["尼尔先生，您在黑夜教会工作多久了？"] = "Мистер Нил, как долго вы работаете в Церкви Ночи?",
    ["尼尔先生，您觉得邓恩队长是个什么样的人？"] = "Мистер Нил, как вы думаете, что за человек капитан Данн?",
    ["尽管我们只能发出微小的光芒，但只要数量足够多，总能照亮黑夜的一角。"] = "Хотя мы можем излучать лишь крошечный свет, пока нас достаточно, мы всегда можем осветить уголок темной ночи.",
    ["屋里只有我一个人，所以发出声音的只能是……不干净的东西！"] = "Я один в доме, так что звук, должно быть,... какой-то нечистый!",
    ["屏障碎片是塔罗学派的象征和力量源泉，也是正式加入学派的非凡者与塔罗学派签订契约的见证。"] = "Фрагмент Барьера является символом и источником силы Клуба Таро, а также свидетелем того, как Потусторонние официально присоединяются к клубу для подписания контракта с Клубом Таро.",
    ["巨大的聚光灯骤然亮起，将警局外的黑夜照耀得宛如白昼。"] = "Внезапно включился огромный прожектор, освещая ночь возле полицейского участка, как будто это был дневной свет.",
    ["差点死了！唉！看来我还是不能给自己瞎解读。"] = "Чуть не умер! Вздох! Кажется, я до сих пор не могу интерпретировать для себя вслепую.",
    ["已经分不清是不是指南针的负面效果，阻止我面对那扇门了。"] = "I can no longer tell if it's the negative effect of the compass preventing me from facing that Door.",
    ["已经很厉害了，你在这里蹲了多久？"] = "Это уже очень впечатляет. Как долго ты здесь сидишь на корточках?",
    ["市场的波动就是这样迷人，您已经完全掌握了。"] = "Колебания рынка столь пленительны, и вы уже всецело постигли их суть.",
    ["布丁"] = "Пудинг",
    ["布丁尾巴上也有一撮白毛……可它脸是尖的，布丁的脸是圆的。像布丁，又不是。但它找上我了。"] = "У Пурин также был пучок белых волос на хвосте... но лицо у него заостренное, а лицо Пурин было круглым. Похоже на Пудинг, но это не так. Но это пришло ко мне.",
