    ["心情问价范例选项1"] = "Пример запроса цен по настроению, вариант 1",
    ["忘了自我介绍，我叫艾伯特，梦想成为一名婚礼乐师！"] = "Забыл представиться, меня зовут Альберт, и я мечтаю стать свадебным музыкантом!",
    ["快走！离开这！"] = "Бегать! Покиньте это место!",
    ["快！我们走！顺着日记向上！"] = "Быстрый! Пойдем! Вверх по дневнику!",
    ["怎么不早告诉我，你养了一只鹦鹉？我还以为你……我担心死了！"] = "Почему ты не сказал мне раньше, что держишь попугая? Я думал, ты... Я волновался до смерти!",
    ["怎么不能自己出发？"] = "Почему нельзя отправиться в путь самостоятельно?",
    ["怎么了罗珊女士——"] = "Что случилось, мисс Розанна?",
    ["怎么了，先生？"] = "Что случилось, сэр?",
    ["怎么了？"] = "В чем дело?",
    ["怎么回事？他没完成任务，诅咒却消失了？"] = "Что происходит? Он не выполнил квест, а проклятие исчезло?",
    ["怎么感觉有些头晕？"] = "Почему у меня немного кружится голова?",
    ["怎么样！有兴趣来我这当驱鸟师吗？"] = "Как насчет этого! Хотите поработать здесь отпугивателем птиц?",
    ["怎么样，她是不是满口胡言？"] = "Как это было? Она несёт чушь?",
    ["怎么样？她有多爱我？"] = "Как это? Насколько она меня любит?",
    ["怎么突然问这个？调查我吗？"] = "Почему ты вдруг спросил об этом? Расследуете меня?",
    ["怎么，不像通灵者吗？"] = "Что, разве это не похоже на духовную среду?",
    ["怎么，你想去找她？劝你别去。她那套胡说八道，真正的占卜师学不来。"] = "Почему ты хочешь пойти и найти ее? Я советую вам не делать этого. Настоящая прорицательница не сможет выучить свою чушь.",
    ["怎么，想拉我去见警察？"] = "Что, хочешь оттащить меня в полицию?",
    ["怕什么？我又不会做什么恶作剧，至少现在不会。"] = "Чего ты боишься? Я не буду шалить, по крайней мере, не сейчас.",
    ["急什么，钱在箱子里，又不会逃跑。今晚可要喝酒，哈哈！"] = "Какая спешка, деньги в шкатулке, никуда не убегут. Мы сегодня пьем, хаха!",
    ["怪不得。“愚者”先生还真是重视你啊，居然赐予你这样贵重的东西……那么接下来你要做的就是准备仪式材料了。"] = "Неудивительно. Мистер действительно ценит вас, раз уж подарил вам такую ​​драгоценную вещь... Затем вам нужно подготовить ритуальные материалы.",
    ["总之！你以后如果缺钱了，可以来找我。"] = "В общем! Если тебе в будущем понадобятся деньги, приходи ко мне.",
    ["总之，省钱的核心就是——能不花的钱坚决不花。"] = "Короче говоря, суть экономии денег заключается в следующем: если вам не нужно их тратить, ни в коем случае не тратьте их.",
    ["总是装备装备，知识也很重要啊！"] = "Вечно только снаряжение да снаряжение! Знания ведь тоже важны!",
    ["总觉得哪里不对……"] = "Я чувствую, что что-то не так...",
    ["恋人牌。天使的祝福，完美的结合。"] = "Карта Влюбленных. Благословение ангела, идеальный союз.",
    ["恋爱结果不算——我知道这是大家最关心的问题，但我连自己的问题都没解决，更不要提给别人占卜啦。"] = "Результаты любви не в счет — я знаю, что это всех волнует больше всего, но я не решил даже своих собственных проблем, не говоря уже о том, чтобы гадать за других.",
    ["恶龙酒吧老板，退休的代罚者队长。那老家伙天天喝得烂醉，但遇到正事比谁都靠谱。"] = "Владелец бара ««Злой Дракон»», отставной капитан, благословленный Ветром. Этот старик каждый день напивается до смерти, но когда дело касается серьезных дел, он надежнее всех.",
    ["悄悄告诉你，其实我还知道湖里没有心愿女神，那是妈妈编的。"] = "Открою вам секрет: я действительно знаю, что в озере нет Богини Желаний; это мама придумала.",
    ["您……不是喜欢……呃。"] = "Тебе... не понравилось... эээ.",
    ["您……什么意思？"] = "Что ты имеешь в виду?",
    ["您……真的很爱黑荆棘。"] = "Ты... действительно любишь Чёрный Чертополох.",
    ["您一定很想念他们。"] = "Вы, должно быть, очень скучаете по ним.",
    ["您一定很珍视那段时光……"] = "Вы, наверное, очень дорожили тем временем...",
    ["您不害怕吗？"] = "Ты не боишься?",
    ["您不打算搬到市区吗？那里离警察局近些，办事也方便。"] = "Вы не планируете переехать в город? Это было бы ближе к полицейскому участку и удобнее для решения вопросов.",
    ["您也是一位“学徒”？"] = "Are you also an Apprentice?",
    ["您也负责处理这类非凡事件吗？"] = "Вы также отвечаете за организацию подобных мероприятий в Mystic World?",
    ["您刚提到“金秋湖的神秘预言”是什么？"] = "Что такое «Таинственное пророчество об озере Золотой Осени», о котором вы только что упомянули?",
    ["您可以看一下旁边的图册，上面有愿意帮忙占卜的会员的信息和价格。"] = "Вы можете взглянуть на брошюру рядом с вами; он содержит информацию и цены для участников, которые готовы помочь с гаданиями.",
    ["您后悔过吗？用这种方式获取力量？"] = "Вы когда-нибудь сожалели об этом? Получение власти таким способом?",
    ["您后悔过没有晋升吗？"] = "Вы когда-нибудь жалели, что не продвинулись?",
    ["您和他现在还有联系吗？"] = "Вы сейчас с ним общаетесь?",
    ["您喜欢这种风格吗？"] = "Вам нравится этот стиль?",
    ["您因此决定招募他？"] = "Вы решили завербовать его из-за этого?",
    ["您在狩猎乌鸦吗？这还真是少见。"] = "Вы охотитесь на ворон? Это действительно редкость.",
    ["您在现在的年纪依然拥有强健的体魄，真是令人赞叹。"] = "Это поистине замечательно, что в твоем возрасте ты все еще обладаешь таким крепким телосложением.",
    ["您好{{先生|女士}}，您是想占卜，还是想加入我们俱乐部？"] = "Здравствуйте, {{мистер|мисс}}, вы ищете гадание или хотите вступить в наш клуб?",
    ["您好，先生，请问您有没有——或者这附近哪里有食物和保暖物品？"] = "Здравствуйте, сэр, есть ли у вас — или есть ли поблизости где-нибудь еда и теплые вещи?",
    ["您好，夫人。您知道孩子们在争论什么吗？"] = "Здравствуйте, мадам. Знаете, о чем спорят дети?",
    ["您好，我只是路过这里，听到你们的争论，感觉很有意思。"] = "Привет. Я просто проходил мимо и слышал ваши дебаты; это звучало очень интересно.",
    ["您当船长这么多年，最难忘的一次航行是哪次？"] = "Вы были капитаном столько лет, какое путешествие у вас было самым незабываемым?",
    ["您很看好他？"] = "Вы высокого мнения о нем?",
    ["您怎么知道？"] = "Как вы узнали?",
    ["您想……跟在她后面看一看吗？"] = "Хотите... проследить за ней и посмотреть?",
    ["您想去班西港调查吗？"] = "Хотите поехать в Банси-Харбор и провести расследование?",
    ["您想起来了吗？我七岁的时候，您也是这样挡在我面前。"] = "Ты помнишь? Когда мне было семь, ты вот так блокировался передо мной.",
    ["您接下来打算怎么办？"] = "Что вы планируете делать дальше?",
    ["您是一位真正的骑士。"] = "Вы настоящий рыцарь.",
    ["您是不是早就知道玛丽奶奶的事？"] = "Did you know about Grandma Mary's situation all along?",
    ["您是我最喜欢的格尔曼扮演者！能请您帮我在海报上签名吗？"] = "Ты мой любимый актер, сыгравший Германа! Не могли бы вы подписать мне плакат?",
    ["您是执掌好运的黄黑之王。"] = "Вы – король желтого и черного, приносящий удачу.",
    ["您是灰雾之上的神秘主宰……"] = "Ты таинственный правитель над серым туманом...",
    ["您是看着他成长的？"] = "Вы видели, как он рос?",
    ["您是说……"] = "Вы хотите сказать...",
    ["您更喜欢阳光吗？"] = "Вы предпочитаете солнечный свет?",
    ["您最得意的研究成果是什么？"] = "Каким научным достижением вы гордитесь больше всего?",
    ["您有办法找到她？你瞧，她连学校的作业都没写完……"] = "У тебя есть способ найти ее? Смотри, она даже не сделала домашнее задание...",
    ["您有如此威能，也许能立刻将城堡建成！"] = "С вашей силой, возможно, вы сможете немедленно построить замок!",
    ["您有没有考虑过，她盯着你，可能只是在看，什么时候轮到她问诊？"] = "А вы не думали, что она смотрит на вас просто потому, что ждет своей очереди на прием?",
    ["您现在还会打牌吗？"] = "Ты до сих пор играешь в карты?",
    ["您用它战斗过很多次？"] = "Сколько раз вы с этим боролись?",
    ["您的发明，大大增加了社会的文明和便利度。"] = "Ваши изобретения значительно повысили цивилизованность и удобство общества.",
    ["您的善良令我钦佩。不过，我还是想说——这里发生什么都不奇怪，务必要小心。"] = "Я восхищаюсь вашей добротой. Однако должен сказать — здесь нет ничего странного, так что надо быть осторожным.",
    ["您的家人也在廷根吗?"] = "Ваша семья тоже в Тингене?",
    ["您的画像？那就是您么，拉姆德男爵？"] = "Твой портрет? Это вы, барон Ламуд?",
    ["您的研究有没有失控过？"] = "Ваши исследования когда-нибудь выходили из-под контроля?",
    ["您的调查告一段落了吗？"] = "Ваше расследование подошло к концу?",
    ["您看了半天，总不能就这么走了吧？"] = "Вы так долго разглядывали товар, неужели просто так уйдете?",
    ["您真是一位温柔的人，克莱恩先生。守护就是当初您想要变强的理由吗？"] = "Вы действительно очень добрый человек, мистер Клейн. Желание защищать — именно поэтому вы изначально стремились стать сильнее?",
    ["您真是个有智慧的好人，让少女看到真实的血，比报纸上的凶杀报道更有用。"] = "Вы действительно мудрый и добрый человек. Позволить молодой девушке увидеть настоящую кровь более эффективно, чем газетные сообщения об убийствах.",
    ["您真是把省钱研究透了啊……这些都是非常有用的建议！我感觉自己又能多撑一段时间了。"] = "Вы действительно досконально изучили экономию денег... Это все очень полезные советы! Я чувствую, что смогу продержаться еще какое-то время.",
    ["您知道班西港是个什么样的地方吗？"] = "Знаешь, что это за место Банси-Харбор?",
    ["您知道，鲁恩的大学有毕业生不直接留校的传统，因此每年都有学生得到导师的推荐去其他大学面试讲师职位。"] = "Знаете, в университетах Лоена есть традиция, когда выпускники не остаются непосредственно в школе, поэтому каждый год студенты получают рекомендации от своих наставников пройти собеседование на должности преподавателей в других университетах.",
    ["您竟然是脚踏车公司的股东！"] = "На самом деле вы являетесь акционером велосипедной компании!",
    ["您等等！我带您逛了半天，总也有个辛苦费吧？"] = "Ждать! Я вам давно показывал, наверняка услуга платная?",
    ["您经常向阿兹克先生请教问题吗？"] = "Вы часто спрашиваете совета у господина Азика?",
    ["您给我家送过面包！我哥亨利的学费，还是您补上的！"] = "You delivered Bread to my house! You even paid the tuition for my brother, Henry!",
    ["您要不先看看报纸吧。"] = "Возможно, вам стоит сначала прочитать газету.",
    ["您认识我？"] = "Ты меня знаешь?",
    ["您让我去找她，是为了帮她解开心结？"] = "Did you ask me to find her to help her resolve her inner conflict?",
    ["您走得太突然了，孩子们一直希望来廷根和您一起过暑假。"] = "Ты ушел так внезапно; дети всегда надеялись приехать в Тинген, чтобы провести с тобой летние каникулы.",
    ["您还好吗？刚才那是——"] = "Ты в порядке? Это только что было…",
    ["您还真是个作家，连这种事都觉得是素材？"] = "Вы действительно писатель, хотя бы думаете о таких вещах как о материале?",
    ["您这就要走了么，戈多先生？"] = "Вы уходите, господин Годо?",
    ["情报贩子"] = "Информационный брокер",
    ["想出门，撞上桌角！买苹果，切开居然有虫洞！"] = "Хотел выйти — ударился об угол стола! Купил яблоко — разрезал, а внутри червоточина!",
    ["想想怎么带他们去圣赛琳娜教堂广场，接受剩下的考验吧。"] = "Подумайте, как отвести их на площадь собора Святой Селены, чтобы пройти оставшиеся испытания.",
    ["想我了吗？嗯？"] = "Вы пропустили меня? Хм?",
    ["想晋升“旅行家”，要去灵界深处四个完全不同，相隔很远的地方，设立四个特殊坐标。"] = "To achieve advancement to 'Traveler', you must go to four completely different and distant locations deep within the Spirit World to establish four special coordinates.",
    ["想，当然想。可她不只是我的妈妈，有些事情比见面更重要。"] = "Да, конечно, да. Но она не просто моя мать; некоторые вещи важнее встречи.",
    ["意外地不错。他说自己已经偷吃了几口——“作为厨师的特权”——但我知道那是谎话，他肯定没怎么吃。"] = "На удивление хорошо. Он сказал, что уже украл несколько кусочков — «привилегия шеф-повара», — но я знаю, что это ложь; он определенно не ел много.",
    ["愚者先生？有道理，我来试试看！"] = "Mr. The Fool? That makes sense, I'll give it a try!",
    ["感受它们之间的联系，寻找那个起点与终点能完美衔接，且能遍历所有节点的路径。灵性会给你提示，但逻辑与专注同样重要。准备好了就开始吧。"] = "Почувствуйте связь между ними и найдите путь, в котором начало и конец идеально сходятся, проходя через все узлы. Духовность даст подсказку, но логика и сосредоточенность не менее важны. Начинайте, как только будете готовы.",
    ["感谢你的喜欢。"] = "Спасибо за ваши лайки.",
    ["感谢奥黛丽女士的馈赠！"] = "Спасибо за подарок, мисс Одри!",
    ["感谢您！我要怎么进入灵界深处？"] = "Thank you! How do I enter the depths of the Spirit World?",
    ["感谢您，是个好主意。"] = "Спасибо, это хорошая идея.",
    ["愿他安息……"] = "Пусть он упокоится с миром...",
    ["愿您的战友们能够安息……"] = "Пусть ваши товарищи упокоятся с миром...",
    ["慢慢地，我感觉身周温暖了起来。"] = "Понемногу я почувствовал, как вокруг разливается тепло.",
    ["慢走！您在镇上遇到什么问题，报我马修的名字就行！"] = "Заботиться! Если у вас возникнут какие-либо проблемы в городе, просто назовите имя Мэтью!",
    ["戈多……谁？"] = "Годо... кто?",
    ["戈多今天可能不来了。"] = "Годо, возможно, сегодня не придет.",
    ["我——一位伟大的艺术家，坐在墙头，是为了感受艺术的微风，迎接浪漫的雨露。"] = "Я — великий художник, сижу на этой стене, чтобы почувствовать ветерок искусства и поприветствовать романтическую росу.",
    ["我……"] = "Я...",
    ["我……不知道这些。"] = "Я... не знал этого.",
    ["我……我也来！"] = "Я... я тоже иду!",
    ["我……我应该开心吗？我是不是离当婚礼乐师越来越远了……"] = "Я... должен ли я быть счастлив? Я все дальше и дальше отхожу от роли свадебного музыканта...",
    ["我……我梦游？我白天骂它是废品，晚上把它捡回来？！"] = "Я... я хожу во сне? Днем я это называю хламом, а ночью извлекаю?!",
    ["我……我欣赏我的表，可它不被认可……"] = "Я... я восхищаюсь своими часами, но никто этого не признаёт...",
    ["我……谢谢你，守了这么久。"] = "Я... спасибо, что ты так долго его охранял.",
    ["我一直在等你开口。但你太固执了。你说，一个仆人没资格提要求。"] = "Я всё ждал, когда ты заговоришь. Но ты слишком упрям. Ты сказал, что слуга не вправе выдвигать требования.",
    ["我一直想——我选了生命，是不是让老师失望了？我不是合格的求知者，不是合格的窥秘人。我害怕失去，害怕未知，害怕翻过这一页。"] = "Я все время думаю... неужели я разочаровал учителя тем, что выбрал жизнь? Из меня не вышло настоящего искателя знаний, не вышло истинного Тайноведца. Я боюсь потерь, боюсь неизвестности, боюсь перевернуть эту страницу.",
    ["我一直无法对抗那恐怖的呓语，但你！你能隔绝那声音，也许你能带我进去。"] = "Я никогда не мог устоять перед этим ужасающим шепотом, но ты! Ты сможешь изолировать этот голос, возможно, ты сможешь принять меня.",
    ["我不会检举你"] = "Я не буду жаловаться на тебя",
    ["我不做因蒂斯皇帝，在海岛上待了这么久后，还要问我这种引战的问题吗？"] = "Я не Император Интиса. После столь долгого пребывания на острове тебе все еще приходится задавать мне такие провокационные вопросы?",
    ["我不再感到迷茫和缺失，这比灵魂的完整更加充实。"] = "Я больше не чувствую растерянности и пустоты... Это наполняет куда сильнее, чем целостность души.",
    ["我不得不举办舞会，引出幕后的凶手。"] = "У меня не было другого выбора, кроме как устроить бал, чтобы выманить его вдохновителя.",
    ["我不愿意回到那个状态。所以，我选择了现在这样，即使还要重复死而复生和失忆，但至少我保有过去和人性。"] = "I don't want to return to that state. So, I chose this current path; even if it means repeating Resurrection and memory loss, at least I retain my past and my humanity.",
    ["我不敢离开这里，在这里我是安全的，但只要跨出这个圈一步，那些怪物会活吞了我……"] = "I don't dare to leave this place. I am safe here, but as soon as I step one foot outside this circle, those monsters will swallow me alive...",
    ["我不是小孩子了，关于婚姻我也想过很多，你们可以多问问我的想法呀，我很愿意和大家聊天。"] = "Я уже не ребенок и о браке тоже немало думала. Вы могли бы чаще спрашивать мое мнение — я с радостью поговорю со всеми.",
    ["我不知道……我昨天收摊很早……"] = "Я не знаю... Вчера я закрыл лавку очень рано...",
    ["我不知道，但你的确很特别。在某种程度上，你更接近一个灵……"] = "Я не знаю, но ты действительно особенный. В каком-то смысле вы ближе к духу...",
    ["我不租了"] = "Я больше не снимаю аренду",
    ["我不能每次都直接赠予你一笔钱，但我可以告诉你如何投资。罗塞尔大帝说过，送给人一条鱼，不如送他钓鱼的本领！"] = "Я не могу каждый раз давать вам определенную сумму денег, но я могу сказать вам, как инвестировать. Император Розель однажды сказал: дать человеку рыбу не так хорошо, как научить его ловить рыбу!",
    ["我不要走，也不能走。"] = "Я не уйду и не могу уйти.",
    ["我不需要变成人来证明自己的价值，也不需要假装自己只是一条普通的狗来逃避责任。"] = "Мне не нужно становиться человеком, чтобы доказать свою ценность, и мне не нужно притворяться обычной собакой, чтобы уклониться от ответственности.",
    ["我主不会强迫人们改信，也不介意信仰是否纯粹，简单来说，他不介意人们在信仰其他神灵的时候信仰他。"] = "Мой Господь не принуждает никого обращаться в Свою веру и не требует абсолютной чистоты помыслов. Проще говоря, Он не против, если люди веруют в Него, одновременно почитая других богов.",
    ["我主居于现实和灵界之上，仁慈洒满了天国和大地，他的座旁共有六位天使侍立……"] = "Мой Господь обитает над реальностью и Миром Духов, милость наполняет небеса и землю, и шесть ангелов стоят рядом с Ним...",
    ["我主拯救了被众神遗弃的失落城邦，带领那片大陆的幸存者走出“神弃之地”，在海岛上重建了家园……"] = "Мой Господь спас затерянный город-государство, покинутый богами, вывел выживших с этого континента из «Заброшенной Земли Богов» и восстановил их дом на острове...",
    ["我主自称“愚者”，在过去，在现在，也在未来，他是支配灵界的伟大主宰，也是执掌好运的黄黑之王，更是每个生灵追求永恒的道标。"] = "Милорд называет себя «Шутом». В прошлом, настоящем и будущем он — великий правитель, господствующий в мире духов, Король Желтого и Черного, несущий удачу, и маяк для каждого живого существа, стремящегося к вечности.",
    ["我也一样。我的身后，是那些需要被守护的人。"] = "Я такой же. За моей спиной те, кого нужно охранять.",
    ["我也不会再去骗人了，不然良心会遭受谴责……"] = "Я тоже больше не буду лгать людям, а то моя совесть будет осуждена...",
    ["我也不知道，我一直在盯着烤炉里的面包胚……"] = "Я тоже не знаю, я просто смотрела на тесто в духовке...",
    ["我也刚知道布置的“鬼屋”旁有非凡事件，把大家都叫来了。"] = "Я только что узнал, что возле комплекса «Дом с привидениями» произошел инцидент с Потусторонним, поэтому я позвал всех.",
    ["我也很抱歉，罗珊，即便你是来相亲的，我们也不应该过多干涉，更别说只是误会……"] = "Мне тоже очень жаль, Розанна. Даже если бы ты был на свидании вслепую, нам не следовало бы так сильно вмешиваться, не говоря уже о том, что это было всего лишь недоразумение...",
    ["我也懂一点占卜，如果您不介意，我可以帮您看看，完全免费。"] = "Я также немного знаю о гадании. Если вы не против, я могу помочь вам посмотреть, совершенно бесплатно.",
    ["我也是占卜师，我可以看看您抽到的牌吗？"] = "Я еще и прорицатель. Могу я взглянуть на карту, которую вы нарисовали?",
    ["我也是外乡人"] = "я тоже аутсайдер",
    ["我也没想那么多，看到有人被欺负，就冲上去了。"] = "Я тоже особо не думал. Когда я увидел, что над кем-то издеваются, я просто бросился вперед.",
    ["我也知道，他向其他神明祈祷。"] = "Я также знаю, что он молится другим богам.",
    ["我也许能帮上忙，不如让我试试？"] = "Возможно, я смогу помочь. Почему бы тебе не дать мне попробовать?",
    ["我从小就在大地母神的信仰中长大。仁慈的母亲教导我们：万物共生，生命循环。我只是一直在思考——怎样才能更好地实践她的意志？"] = "Я вырос в вере Матери-Земли. Милосердная Мать учила нас: все вещи сосуществуют, жизненные циклы. Я только что подумал: как мне лучше практиковать ее волю?",
    ["我从没停止学习，试图理解这个非凡世界的规则……尽管这是相当危险的。但很有趣，不是吗？"] = "Я никогда не переставал учиться, пытаясь понять правила этого Необыкновенного мира... хотя это довольно опасно. Но это интересно, не так ли?",
    ["我以为你讨厌——等等，那撞桌角和苹果有虫呢？"] = "Я думал, ты ненавидишь… подожди, а что насчет того, чтобы наткнуться на угол стола и червяка в яблоке?",
    ["我以为是你不好意思，所以用“朋友找我”这种借口来掩盖……"] = "Я думал, ты просто застенчив, поэтому ты использовал фразу «друг ищет меня» как предлог, чтобы скрыть это...",
    ["我们不能。"] = "Мы не можем.",
    ["我们从贝克兰德出发，特意选了内陆路线。但对方对我们的路线和人员配置非常清楚，在途中设下了埋伏。"] = "Мы отправились из Баклунда и специально выбрали внутренний маршрут. Но противнику было очень ясно известно о нашем маршруте и составе личного состава, и они устроили засаду по пути.",
    ["我们会的！"] = "Мы обязательно!",
    ["我们伟大的拉斯廷伯爵牺牲在了这场战争里，他的名字就是哈罗德。"] = "Наш великий граф Ластинг отдал свою жизнь в этой войне, и звали его Гарольд.",
    ["我们先点菜吧？我姐姐说这家餐厅的柠檬布丁很不错，你有什么忌口吗？"] = "Может, сначала сделаем заказ? Сестра говорила, что в этом ресторане отличный лимонный пудинг. У вас есть какие-нибудь предпочтения или ограничения в еде?",
    ["我们刚租他房子的时候，他只想签三个月，说怕我们交不起租金。我费了好大劲，才争取到一年租期。"] = "Когда мы только снимали у него жилье, он соглашался лишь на три месяца — боялся, что мы не потянем аренду. Мне стоило немалых трудов выбить контракт на год.",
    ["我们十分心动，答应了一同旅行。"] = "Мы очень соблазнились и согласились поехать вместе.",
    ["我们去找弗兰奇先生的时候，他坐在沙发上，很有气势地宣称“你们应该知道我的原则，绝对不允许拖欠租金！”"] = "Когда мы пришли к мистеру Фрэнку, он сидел на диване и с важным видом заявил: «Вы должны знать мои правила — никакой задержки арендной платы!»",
    ["我们只是几个愚蠢的小伙儿，在这里根本不可能活下去。"] = "We are just a few foolish lads; it's impossible for us to survive here.",
    ["我们就要等待戈多。"] = "Мы должны дождаться Годо.",
    ["我们快转换意识！"] = "Давайте быстро переключим сознание!",
    ["我们想结婚，但不知道未来会怎样。"] = "Мы хотим пожениться, но не знаем, что нас ждет в будущем.",
    ["我们成功了！我可以回到她的身边了！"] = "Мы сделали это! Я могу вернуться к ней!",
    ["我们打算在圣赛琳娜教堂广场，给她的相亲对象一点考验。"] = "Мы планируем устроить ей испытание на свидании вслепую на площади собора Святой Селены.",
    ["我们找不到母亲的墓碑了！"] = "Мы не можем найти надгробие мамы!",
    ["我们是会员年费制度，第一年是100苏勒，之后每年20苏勒。"] = "У нас действует система ежегодных членских взносов: 100 суле за первый год и 20 суле за каждый последующий год.",
    ["我们是安保公司，不是冒险者公会。"] = "Мы охранная компания, а не гильдия искателей приключений.",
    ["我们本来就有矛盾，又被这些乌鸦骚扰得越来越烦躁，看什么都不顺眼。"] = "Мы уже были в ссоре, и, постоянно раздражаясь этими воронами, нам все казалось неприятным.",
    ["我们每个月都会请一些有名的占卜者来讲课，帮助大家更好地学习占卜。"] = "Каждый месяц мы приглашаем известных прорицателей читать лекции, чтобы помочь каждому лучше научиться гаданию.",
    ["我们现在能跳得更高了！"] = "Теперь мы можем прыгать выше!",
    ["我们的会员可以免费使用俱乐部内的工具为人占卜。"] = "Члены нашего клуба могут бесплатно использовать клубный инвентарь для гадания другим.",
    ["我们的途径不同，应该不能这么比。"] = "У нас разные Пути, так что их вряд ли стоит сравнивать.",
    ["我们相信的是生命的无限，泥土知道答案。"] = "Мы верим в бесконечность жизни; земля знает ответ.",
    ["我们要去哪里"] = "Куда мы идем?",
    ["我们走吧。"] = "Пойдем.",
    ["我们通过占卜窥见了未来命运的碎片，却被碎片恐吓，失去了完整命运的可能性。"] = "Мы через гадание мельком увидели фрагменты будущей судьбы, но запугались осколками, потеряв возможность полной судьбы.",
    ["我们都心疼她，但又能说什么呢？她高兴就好。"] = "Нам всем ее безумно жаль, но что тут скажешь? Лишь бы она была счастлива.",
    ["我们都明白！大家生怕您被抓，还撕走了好多通缉令呢！"] = "We all understand! Everyone was so afraid you'd be caught that they even tore down many of the wanted posters!",
    ["我们都没搬走，大家都记得您，您这次回来，还会离开吗？"] = "None of us have moved away, and everyone remembers you. Now that you're back, will you be leaving again?",
    ["我会。封印物需要回收。这是一场对失窃封印物的合法回收行动。幕后黑手已被击毙。"] = "Я буду. Запечатанный артефакт необходимо вернуть. Это законная операция по восстановлению украденного запечатанного артефакта. Организатор ликвидирован.",
    ["我会掉毛，会追尾巴，会趴着晒太阳，会在听到“出门”两个字的时候兴奋地转圈。"] = "Я сбрасываю шерсть, гоняюсь за хвостом, ложусь на солнце и взволнованно кружусь, когда слышу слово «выйти».",
    ["我会注意的。有了“霜之匣”，晋升仪式所需的材料就都准备好了。谢谢伦纳德先生！"] = "I'll keep that in mind. With the 'Casket of Frost,' all the materials needed for the advancement ritual are ready. Thank you, Mr. Leonard!",
    ["我会记住的。"] = "Я запомню это.",
    ["我会试着找找他们，“四个愚蠢的亡灵”……呵，至少不会太孤单。"] = "I'll try to find them, the 'four foolish undead'... Heh, at least they won't be too lonely.",
    ["我住了四十年，这镇上没什么我不知道的。我就是看不惯这些骗子坑人。什么破东西能要40镑！"] = "Я живу здесь сорок лет, в этом городе нет ничего, чего бы я не знал. Терпеть не могу этих мошенников, которые грабят людей. Что за барахло стоит 40 фунтов!",
    ["我先去和她聊聊看。"] = "Сначала я пойду поговорю с ней.",
    ["我其实对富人区比较感兴趣！"] = "На самом деле меня очень интересует богатый район!",
    ["我准备好了！"] = "Я готов!",
    ["我出生在廷根，成长在廷根，我想守护这里。"] = "Я родился в Тингене, вырос в Тингене и хочу охранять это место.",
    ["我到了！"] = "Я на месте!",
    ["我加入好几年了，现在只是偶尔会来坐坐。"] = "Я вступил уже несколько лет назад, а сейчас лишь изредка захожу посидеть.",
    ["我占卜出你有危险！"] = "Я догадался, что ты в опасности!",
    ["我去和弗里尔聊聊，请先随便看看吧。"] = "Я собираюсь поговорить с Фриром; пожалуйста, не стесняйтесь осмотреться.",
    ["我又清醒了，我感觉自己变得很轻！于是我跑了起来……我一直跑啊跑啊，直到感觉不到时间的流逝，直到听不见炮声，直到我看到有人出没。"] = "Я снова проснулся, и мне так легко! Итак, я бежал... Я бежал и бежал, пока не перестал чувствовать течение времени, пока не перестал слышать звук пушек, пока не увидел, как кто-то приходит и уходит.",
    ["我又看到了那个“我”……"] = "Я снова увидел это «я»…",
    ["我发现它消失的时候，吓了一跳。"] = "I was startled when I discovered it had Disappear-ed.",
    ["我只会用那些不着边际的话去逗他，说他没胆量，说他古板……好像这样，就能把自己心里的那点念想藏好一些。"] = "Я бы использовал эти бессмысленные слова только для того, чтобы подразнить его, назвав его бездушным, назвав его старомодным... как будто таким образом я мог бы лучше скрывать свои маленькие мысли в своем сердце.",
    ["我只是……忽然有些不明白……"] = "Я просто... вдруг не понимаю...",
    ["我只是一条狗——这句话是真相，不是借口。"] = "Я всего лишь собака — это предложение — правда, а не оправдание.",
    ["我只是一条狗，为什么要和人切磋？"] = "Я всего лишь собака, зачем мне спарринговаться с человеком?",
    ["我只是想帮您……"] = "I was only trying to help you...",
    ["我只是想让他好好看看现实，而不是整天盯着星星。"] = "Я просто хочу, чтобы он правильно смотрел на реальность, а не целыми днями смотрел на звезды.",
    ["我只是愚蠢地想要证明一次。"] = "Я просто по глупости хотел однажды это доказать.",
    ["我只是有点想妈妈。"] = "Я просто немного скучаю по маме.",
    ["我只是路过看到一阵白光闪过，因为好奇过来看看！"] = "Я просто проходил мимо и увидел вспышку белого света, поэтому подошел из любопытства!",
    ["我只知道家族遭到过一次沉重的打击，死了不少人。"] = "Знаю только, что однажды семье был нанесен тяжелый удар, погибло много людей.",
    ["我叫丹尼斯。我很急！快帮我算算！<P_Heart>（把猫举高）</>我和玛丽安能不能结婚？"] = "Меня зовут Денис. Я спешу! Быстрее, помогите мне посчитать! <P_Heart> (Держит кошку высоко) </> Можем ли мы с Мэри Энн пожениться?",
    ["我叫亚伦，从普利兹港来拜访泰利·里斯本的遗孀奥莉薇，告知她丈夫的死讯。"] = "Меня зовут Аарон, я приехал из Притц-Харбора, чтобы навестить вдову Терри Лиссабона, Оливию, чтобы сообщить ей о смерти ее мужа.",
    ["我叫安娜，在富人家做女仆。他是彼得，在印刷厂做工。"] = "Меня зовут Анна, и я работаю горничной в богатой семье. Его зовут Питер, и он работает на полиграфической фабрике.",
    ["我可不想输了这场赌局，所以我稍稍改了一下时间……"] = "Я не хочу проиграть эту ставку, поэтому немного изменил время...",
    ["我可以向你展示世界的真相……不需要任何代价。"] = "Я могу показать тебе правду о мире... без каких-либо затрат.",
    ["我可以帮助你。"] = "Я могу помочь вам.",
    ["我可以看看吗？"] = "Могу я взглянуть?",
    ["我可怜的欧洛斯，她去午夜茶会后，就再没回过家了。"] = "Моя бедная Орос, она так и не вернулась домой после полуночного чаепития.",
    ["我可是聪明的瓦莱莉。"] = "В конце концов, я умная Валери.",
    ["我吗……咳，我不太会写。"] = "Я?.. Кхм, я не очень-то умею писать.",
    ["我听巡逻的士兵说，那片遗迹可能要彻底封锁。"] = "I heard from the patrolling soldiers that those ruins might be completely sealed off.",
    ["我听有些人说，两个国家最终协议休战，回到了以前的相处状态。"] = "Я слышал, как некоторые говорили, что две страны наконец согласились на перемирие и вернулись к прежнему состоянию отношений.",
    ["我听见他们说的是鲁恩语！我拼命地招手！我以为能救下大家，一起回家……"] = "Я слышал, как они говорили лоен! Я отчаянно замахал руками! Я думал, что смогу спасти всех и пойти домой вместе...",
    ["我听说您和休·迪尔查小姐是很好的朋友？"] = "Я слышал, вы близко дружите с мисс Сио Деречей?",
    ["我听说，梅丽莎是个很特别的妹妹？"] = "Я слышал, что Мелисса особенная сестра?",
    ["我听闻霍华德伯爵，豢养了一只非凡的宠物。看来就是你了，序列8，欺诈师？"] = "Я слышал, что у Эрла Ховарда есть питомец-Потусторонний. Кажется, это ты, из восьмой серии, Трикстер?",
    ["我和贝尔纳黛女士有过几面之缘，她确实给我留下了很深的印象。您的日记里也记载了您和孩子们的事……"] = "Я встречался с Бернадетт несколько раз, и она действительно произвела на меня глубокое впечатление. В твоем дневнике также записано что-то о тебе и твоих детях...",
    ["我回想起的记忆，或许能对历史系的研究起到一些帮助。"] = "The memories I've recalled might be of some help to the research in the History Department.",
    ["我在乎。"] = "Мне не все равно.",
    ["我在海上执行任务时，偶然间遇到一些奇怪的现象……然后就被拉入了那片灰雾之上。"] = "Выполняя задание в море, я случайно столкнулся с некоторыми странными явлениями... и тогда меня вытащило из этого серого тумана.",
    ["我在贝克兰德长大。那场袭击中，我失去了所有的家人。小队是我的第二个家，现在他们也离去了……"] = "Я выросла в Бэкланде. В том нападении я потеряла всю семью. Отряд стал моим вторым домом, а теперь и они погибли...",
    ["我在这里长大，从没见过这种事，也不相信。"] = "Я здесь вырос, такого никогда не видел и не верю.",
    ["我在那里上大学，在那里成为值夜者，在那里……经历了很多。"] = "Я там поступил в университет, стал там Ночным Ястребом, а там... я многое испытал.",
    ["我多希望能亲眼见证她获得幸福，遇见一个陪伴她的人，一个值得共度一生的伴侣，最重要的是，和他在一起，能让罗珊期待新一天的到来。"] = "Я очень надеюсь, что своими глазами стану свидетелем того, как она обретает счастье, встретит кого-то, кто ее сопровождает, партнера, с которым стоит провести всю жизнь, и, самое главное, пребывание с ним может заставить Розанну с нетерпением ждать наступления нового дня.",
    ["我好像……忘了很多事。我记得要一块地……给战友们……但我忘了他们的名字……"] = "Кажется, я... забыл многое. Помню, я хотел кусок земли... для своих товарищей... но забыл их имена...",
    ["我好像迷路了……这里的积雪比我来时要厚得多，干净得多。"] = "Кажется, я заблудился... Снег здесь намного толще и чище, чем когда я впервые приехал.",
    ["我宣布——将黑伍德庄园东侧土地，无偿赠予我的管家阿尔伯特先生。"] = "Настоящим я объявляю: земля на восточной стороне поместья Хейвуд будет безоговорочно подарена моему дворецкому, мистеру Альберту.",
    ["我家三代人都是宫廷乐师，爷爷是首席，父亲给皇后演出过，到了我这代……"] = "Три поколения моей семьи были придворными музыкантами; мой дедушка был концертмейстером, а отец выступал перед королевой. Мое поколение...",
    ["我家世代都是钟表匠，镇上谁的钟表坏了都找我。"] = "В моей семье все были часовщиками из поколения в поколение. Если в городке у кого сломаются часы — все идут ко мне.",
    ["我家的瓜与别家不同。它能让你心想事成、所梦成真——你买了就知道了。"] = "Мои тыквы отличаются от других. Они могут воплотить ваши желания в реальность и мечты в реальность — вы узнаете, как только купите их.",
    ["我对心理学确实有些了解……"] = "Я немного знаю психологию...",
    ["我对这件事很感兴趣，你可以收集情报和我交换！"] = "Я очень заинтересован в этом вопросе; Вы можете собирать информацию и торговать ею со мной!",
    ["我将会很期待你的到来，{{PlayerName}}。"] = "Я буду с нетерпением ждать твоего приезда, {{PlayerName}}.",
    ["我就是你的未婚妻！"] = "Я твоя невеста!",
    ["我就知道。尼克老头，你有纽扣吗？"] = "Я знал это. Старый Ник, у тебя есть какие-нибудь пуговицы?",
    ["我就知道你会理解我的！要不要去看看我最新培育的蘑菇？它能模仿人的声音说话！虽然目前只会说“救命”……"] = "Я знал, что ты меня поймешь! Хочешь увидеть гриб, который я только что вырастил? Он может имитировать человеческие голоса! Хотя пока он может сказать только «помогите»…",
    ["我已经不知道自己的苟活，究竟是一种幸运，还是一种耻辱。"] = "Я больше не знаю, является ли мое выживание удачей или позором.",
    ["我已经告诉你们，朋友有事找我，需要请一天假，还给弗莱写了假条呢！"] = "Я уже говорил тебе, другу есть для чего меня найти, мне нужно отпроситься, и я даже написала Фраю отпуск!",
    ["我已经死去了……"] = "Я уже умер...",
    ["我希望你们获得不仅是骑士的技艺，更能继承骑士的精神，成为混乱时代中的一盏明灯，用你们的力量照亮身边的人。"] = "Я надеюсь, что вы обретете не только рыцарские навыки, но и унаследуете рыцарский дух, став ярким маяком в эту эпоху хаоса и освещая путь окружающим своей силой.",
    ["我帮你们问问吧。"] = "Позвольте мне спросить за вас.",
    ["我帮你看看"] = "Позвольте мне взглянуть на вас",
    ["我干嘛要去杀人呢？虽然我很想离开，但也不能杀人啊。"] = "Зачем мне хотеть кого-то убить? Хоть я и очень хочу уйти, я не могу просто убивать людей.",
    ["我并不是真正的玩偶露米，而是她想要逃离的痛苦现实。"] = "Я не настоящая кукла Люми, а болезненная реальность, от которой она хочет сбежать.",
    ["我当年是怕连累你们才……"] = "Back then, I was only trying to avoid implicating you all when I...",
    ["我当时骂了自己很久，怎么就选了这么个弱鸡途径。不过，发展科技树确实离不开它。"] = "Тогда я долго проклинал себя, задаваясь вопросом, почему я выбрал такой слабый путь. Однако при разработке дерева технологий без этого действительно не обошлось.",
    ["我当然得陪着她。虽然我只是个“纤细敏感”的作家，但让她一个人去送死？"] = "Конечно, мне пришлось ее сопровождать. Хоть я и всего лишь «нежный и чувствительный» писатель, но позволить ей идти на смерть одну?",
    ["我当然收了，但{{他|她}}把烛台放回来了！"] = "I certainly accepted it, but {{he|she}} put the candlestick back!",
    ["我很好……哈哈，我想起了一些重要的事，先走了。"] = "Я в порядке... Хаха, я только что вспомнил кое-что важное. Я пойду сейчас.",
    ["我很遗憾……他一定是位细心而温柔的人。"] = "Мне очень жаль... Должно быть, он был осторожным и нежным человеком.",
    ["我得到了这个。你知道这是什么吗？"] = "Мне досталось вот это. Знаешь, что это такое?",
    ["我得回家看看，我父母和妹妹不知道过得怎么样，但这都是我需要独自面对的事情了。"] = "I need to go home and see how my parents and sister are doing, but these are things I must face on my own now.",
    ["我得留下，守着家里，保护夫人和少爷，等他回来。"] = "Я должен остаться, охранять дом, защищать хозяйку и молодого господина и ждать его возвращения.",
    ["我必须确认他的力量是真实的，确认他对我们没有恶意，确认这一切不是某种陷阱。"] = "Я должен был подтвердить, что его сила реальна, подтвердить, что у него нет злобы по отношению к нам, и подтвердить, что все это не было какой-то ловушкой.",
    ["我必须让他知道我的厉害！"] = "Я должен дать ему понять, насколько я крут!",
    ["我忘了你的生日……忘了你小时候怕黑，每晚都要我点着蜡烛陪你……"] = "Я забыл твой день рождения... забыл, что ты боялся темноты, когда был маленьким, и каждую ночь тебе нужно было, чтобы я зажигал свечу, чтобы сопровождать тебя...",
    ["我怎么会知道！我以为这东西缠上我了！我以为它阴魂不散！"] = "Откуда мне было знать?! Я думал, эта штука преследует меня! Думал, злой дух не отстанет!",
    ["我怎么可能会杀了他呢？我最疼爱的主人，我怎么会……不、不对……"] = "How could I possibly have killed him? My most beloved master, how could I... No, that's not right...",
    ["我怎么隐约觉得……埃姆林先生他今晚恐怕要熬夜了。"] = "Почему у меня смутное ощущение... что мистер Эмлин, вероятно, сегодня не будет спать всю ночь.",
    ["我怕你不要它……也怕你骂我……"] = "Я боялась, что ты не позволишь мне оставить его себе... и боялась, что ты меня отругаешь...",
    ["我情愿我的孩子有更多的人性，而非虔诚的信徒。"] = "Я бы предпочел, чтобы мои дети были более человечными, чем религиозными.",
    ["我想先了解一下。"] = "Сначала я хотел бы узнать больше.",
    ["我想占卜。"] = "Я хочу погадать.",
    ["我想和人分享这个发现很久了！你知道蔷薇战争吗？"] = "Давно хотела с кем-нибудь поделиться этим открытием! Знаете ли вы о Войне роз?",
    ["我想回到真正的故乡。那里没有非凡，没有魔药，没有会让人失控疯狂的知识。"] = "Я хочу вернуться в свой настоящий дом. Там нет Необыкновенного, нет зелий и нет знаний, которые заставляют потерять контроль и сойти с ума.",
    ["我想找您占卜。"] = "Я хочу попросить вас о гадании.",
    ["我想是的，而且你……"] = "Я так думаю, а ты...",
    ["我想看看能不能找到舍伍德的坟墓。"] = "Я хочу посмотреть, смогу ли я найти могилу Шервуда.",
    ["我想着，不能让你一个人上去，我也要做点什么。"] = "Я подумал, что не могу отпустить тебя наверх одного. Я тоже должен хоть что-то сделать.",
    ["我想获得一双翅膀。"] = "Я хотел получить пару крыльев.",
    ["我想让她知道，我正在努力成为和她一样厉害的人。"] = "Я хочу, чтобы она знала, что я усердно работаю, чтобы стать таким же замечательным человеком, как она.",
    ["我想请教您关于如何正确地执行它们，并确保其有效性和……安全性？"] = "Я хотел бы спросить вас о том, как их правильно выполнять и обеспечить их эффективность и... безопасность?",
    ["我想这一定也是解开这座屋子谜团的关键……"] = "Я думаю, что это также должно быть ключом к разгадке тайны этого дома...",
    ["我想除了用于铁路贸易，把这些美酒销售到更近的地方或许也是不错的选择！"] = "Я думаю, что помимо использования его для железнодорожной торговли, хорошим выбором может быть и продажа этих прекрасных вин в более близкие места!",
    ["我想，不要小看神灵的祝福，他会选择你，一定是有他的原因。"] = "I think you should not underestimate the blessing of a God; He must have had His reasons for choosing you.",
    ["我想，我应该有点清楚这间屋子的谜团了……"] = "Кажется, я немного понимаю тайну этой комнаты...",
    ["我感受到了蓬勃的灵性，你很厉害，这么快就晋升了！"] = "I can feel your surging spirituality. You are impressive; you have achieved advancement so quickly!",
    ["我感觉自己像只……<P_Heart>（停顿）</>在书籍面前的卷毛狒狒。"] = "Рядом с этими книгами я чувствую себя... <P_Heart>(пауза)</> кудрявым павианом.",
    ["我感觉自己的力量在消散……也许我很快要消失了。"] = "Я чувствую, как мои силы тают... возможно, я скоро исчезну.",
    ["我愿意将我毕生所知的神秘学知识，都教给你。"] = "Я готов научить вас всем оккультным знаниям, которые я узнал в своей жизни.",
    ["我愿意赞同温暖带来的好处，但我并不喜欢所谓的日光浴，你看我的肤色，很容易就被晒黑。"] = "Я готов признать пользу, которую приносит тепло, но мне не нравятся так называемые солнечные ванны. Посмотрите на мой тон кожи; он очень легко загорает.",
    ["我懂一点占星知识，能帮你看看。"] = "Я немного знаю астрологию; Я могу тебя поискать.",
    ["我成为值夜者的时候，邓恩还是个孩子！"] = "Когда я стал Ночным Ястребом, Данн был еще ребенком!",
    ["我成功了！罗珊女士！我成功了！"] = "У меня получилось! Мисс Розанна! У меня получилось!",
    ["我才不会被这张牌吓到。"] = "Эта карта меня не испугает.",
    ["我找到了让他不得不同意的理由，最后只赔偿了3苏勒押金，就顺利退租了。"] = "Я нашел довод, с которым он не мог не согласиться, и в итоге заплатил всего 3 соли из залога, чтобы расторгнуть договор аренды.",
    ["我承认……是我动的手，谋害了老爷。"] = "Признаюсь... это сделал я, убивший мастера.",
    ["我把愿望写下来，就像在跟她说话一样。"] = "Я записываю свои желания и как будто разговариваю с ней.",
    ["我把表扔进垃圾桶，第二天它回到桌上。我把它埋土里，扔树上，带到隔壁镇子，它都回来了！"] = "Я выбросил часы в мусорное ведро, а на следующий день они снова оказались на столе. Я закопал его в землю, бросил на дерево, отвез в следующий город, и он всегда возвращался!",
    ["我把这种冲动判断成爱好和职业兴趣，最终走上了这条道路。"] = "Я расценил этот порыв как хобби и профессиональный интерес и в конце концов встал на этот путь.",
    ["我指着桌面上的划痕和污渍，跟老板磨了二十分钟，最后砍到原价的三成。"] = "Я указал на царапины и пятна на столешнице и двадцать минут торговался с боссом, в конце концов снизив цену до 30% от первоначальной цены.",
    ["我无法回答这个问题，我只能告诉你不变的真理。"] = "Я не могу ответить на этот вопрос, я могу лишь сказать вам неизменную правду.",
    ["我早就习惯了死亡，可是从今以后，我真的一无所有了。"] = "Я давно привык к смерти, но отныне у меня действительно ничего не осталось.",
    ["我早已分不清疯狂和清醒的边界。但我知道，只要我还活着，就不会让白银城陷入黑暗。"] = "Я уже давно не могу провести границу между безумием и трезвостью. Но я знаю, что пока я жив, я не позволю Серебряному Городу погрузиться во тьму.",
    ["我早该知道是这样。可还是想亲自看看……"] = "Я должен был знать, что это так. Но мне все равно хотелось увидеть самому...",
    ["我明白了。"] = "Я понимаю.",
    ["我明白了。这就是我今晚在这里的意义——见证这一切。"] = "Я понимаю. В этом смысл моего присутствия здесь сегодня вечером – чтобы стать свидетелем всего этого.",
    ["我明白了，是那个非凡的八音盒，将她的记忆和执念化作了城堡。"] = "Я понимаю, именно эта необычная музыкальная шкатулка превратила ее воспоминания и навязчивые идеи в замок.",
    ["我明白了，谢谢您的提醒。"] = "Я понял, благодарю за напоминание.",
    ["我昨晚远远看见，附近有个黑影活动，鬼鬼祟祟的……"] = "Вчера вечером я издалека увидел, что рядом движется темная тень, очень коварная...",
    ["我是一朵蘑菇。"] = "Я гриб.",
    ["我是不是太贪心了？以为它会变成点什么。"] = "Я слишком жадный? Думал, это во что-то превратится.",
    ["我是个占星术爱好者，大家叫我观星的弗洛，你也许听说过我？"] = "Я энтузиаст астрологии. Все зовут меня Фло, смотрящей на звезды. Возможно, вы слышали обо мне?",
    ["我是亚伦，来告知奥莉薇女士她丈夫泰利的死讯。请问你是？"] = "Я Аарон, я здесь, чтобы сообщить мисс Оливии о смерти ее мужа Терри. Могу я спросить, кто вы?",
    ["我是你妈妈，妈妈总会站在你这边。"] = "Я твоя мать, и мать всегда будет на твоей стороне.",
    ["我是佩妮啊！"] = "I am Penny!",
    ["我是来报丧的，你知道住在这里的奥莉薇女士去哪里了吗？"] = "Я здесь, чтобы сообщить о смерти. Вы знаете, куда пропала мисс Оливия, которая живет здесь?",
    ["我是生气，气你瞒着我。"] = "Я злюсь, злюсь, что ты скрыл это от меня.",
    ["我是第十二个，只有找个替死鬼，才能摆脱诅咒。"] = "Я двенадцатый; только найдя козла отпущения, я смогу избавиться от проклятия.",
    ["我是说……理论上，您比他强？"] = "Я имею в виду... теоретически ты сильнее его?",
    ["我是负责廷根大学招聘事务的教员。"] = "Я являюсь преподавателем, ответственным за набор персонала в Университете Тинген.",
    ["我是鲁恩的士兵，我所在的小队和大部队走散了……"] = "Я солдат Лоэна, и отряд, в котором я находился, отделился от основных сил...",
    ["我曾在噩梦中掌控过一把绯红色的武器，它让我短暂拥有了不灭之力。"] = "I once controlled a crimson weapon in a Nightmare, and it granted me Undying Power for a brief moment.",
    ["我曾把十几个人带到悬崖边，可我良心难安，不忍心害人。"] = "Я привел на край обрыва более дюжины человек, но моя совесть не позволяет; Я не могу причинить кому-либо вред.",
    ["我曾经去过贝克兰德的繁星教堂和圣赛缪尔教堂，确实是这样。"] = "Я был в Звездной церкви и церкви Св. Самуила в Баклунде, и это действительно так.",
    ["我最后再问一句——你这瓜，保真吗？"] = "Я спрошу в последний раз — эта твоя тыква настоящая?",
    ["我有一件非凡物品，能将我的存在从那些不怀好意的人脑中抹去 。"] = "У меня есть предмет Потусторонний, который может стереть мое существование из памяти тех, у кого злые намерения.",
    ["我有五位叫赛琳娜的同学，她们家都是女神的信徒！"] = "У меня пять одноклассниц по имени Селена, и все их семьи истово веруют в Богиню!",
    ["我有关于我女儿的急事需要占卜——"] = "У меня срочное дело относительно моей дочери, требующее гадания…",
    ["我有十年向导经验，知道条小路，半小时下山。"] = "У меня десять лет опыта проводника, я знаю тропинку — спустимся с горы за полчаса.",
    ["我有警察厅的薪水，这里还有我过去买下的土地，所以现在也有固定地租收入，这种消费对我来说还好。至少，这些开销是值得的。"] = "Я получаю жалованье в полицейском управлении, к тому же у меня есть земля, купленная в прошлом, так что я имею постоянный доход от аренды. Подобные траты мне вполне по карману. По крайней мере, они того стоят.",
    ["我服侍了一位神明的眷者？！领主大人，您放心我绝对守口如瓶！请您允许我，一辈子都侍奉您！"] = "Я служил Благословенному богу?! Милорд, пожалуйста, будьте уверены, я обязательно буду держать язык за зубами! Пожалуйста, позвольте мне служить Вам до конца моей жизни!",
    ["我未婚夫让出版社的审核文员加上的。"] = "Мой жених попросил рецензента издательства добавить их.",
    ["我来——嘿嘿，下雪了！"] = "Я сама... Хе-хе, снег пошел!",
    ["我来带路！"] = "Я проведу путь!",
    ["我来帮你……咦，你要去哪？"] = "Я помогу тебе... подожди, куда ты идешь?",
    ["我来的第一天他们这么说，第二天第三天第四天……"] = "Они сказали это и в первый день моего приезда, и на второй, третий, четвёртый день...",
    ["我来的第一天他们这么说，第二天第三天第四天……还是这么说。"] = "Они сказали это в первый день моего приезда, и на второй, третий, четвёртый день... они до сих пор говорят то же самое.",
    ["我查阅过教会的内部报告，那里的情况比表面复杂得多。"] = "Я проверил внутренние отчеты Церкви; ситуация там гораздо сложнее, чем кажется на первый взгляд.",
    ["我根据你描绘的星图判断，你最近和家人的关系不太好。"] = "На основании описанной вами звездной карты я сужу, что ваши отношения с семьей в последнее время не очень хорошие.",
    ["我梦到你死了，你的菜摊我买下来改成了肉摊。"] = "Мне приснилось, что ты умер, и я купил твой овощной ларек и превратил его в мясной.",
    ["我正在研究把柠檬也加进去！这样它自己就是一道菜了，不需要额外调味！"] = "В настоящее время я изучаю возможность добавления в него лимонов! Таким образом, это будет самостоятельное блюдо, без каких-либо дополнительных приправ!",
    ["我死了。准确地说，我被第十一个被诅咒害死的人害死了！"] = "Я мертв. Если быть точным, меня убил человек, которого убило проклятие после десятой жертвы!",
    ["我永远不完成任务，就不会再有人受到伤害了。"] = "Если я никогда не выполню этот квест, больше никто больше не пострадает.",
    ["我熟悉这片空间，还能听见那些碎片、和它们共鸣。"] = "Мне знакомо это пространство, и я до сих пор слышу эти фрагменты и резонирую с ними.",
    ["我爱你！"] = "Я тебя люблю!",
    ["我父亲以前也是这家公司的，听说是他认为这么做能增进大家的感情。"] = "Мой отец тоже работал в этой компании. Я слышал, он думал, что это может улучшить отношения между всеми.",
    ["我猜到了。其实我猜到了。进来的人，没有一个回来过。"] = "Я догадался. Собственно, я догадался. Никто из тех, кто вошел, не вернулся.",
    ["我现在只会修修怀表，做做小玩具。但以后……我想设计大型的蒸汽机，用在工厂里，或者火车上，或者更厉害的地方。"] = "Сейчас я могу только чинить карманные часы и делать маленькие игрушки. Но позже... Я хочу сконструировать большие паровые машины, которые можно будет использовать на фабриках, в поездах или в еще более удивительных местах.",
    ["我疯了吗？！"] = "Я что, с ума сошёл?!",
    ["我的名字是乔琳，我女儿佐伊不太对劲！"] = "Меня зовут Джолин, с моей дочерью Зои творится что-то неладное!",
    ["我的女儿，她有最正直，善良的品格。这让她很难接受我后期做出的那些事。当然，这也怪“原始月亮”——你明白被污染的感觉吧？"] = "Моя дочь, у нее самый прямой и добрый характер. Из-за этого ей было трудно принять то, что я делал в последние годы своей жизни. Конечно, в этом виновата и «Первородная Луна» — вы ведь понимаете чувство развращения, верно?",
    ["我的妻子曾说，钢琴是带来美好的乐器。"] = "Моя жена однажды сказала, что фортепиано — это инструмент, приносящий красоту.",
    ["我的尊名是——洞察一切的圣灵，黄黑之王的眷者，梦境与心灵的旅者。"] = "Моё почетное имя — Святой Дух, который видит всё, Благословенный Короля Желтого и Чёрного, Путешественник Снов и Разумов.",
    ["我的小狗，它整整陪了我十五年。"] = "Моя маленькая собачка. Оно оставалось со мной пятнадцать лет.",
    ["我的心愿女神有名字，她的名字是赛拉。"] = "У моей богини желаний есть имя, и ее имя — Сара.",
    ["我的战友们……是为了黑伍德家族，为了鲁恩。"] = "Мои товарищи... они сделали это ради семьи Хейвуд, ради Лоэн.",
    ["我的战友们被困在山里，没有食物和衣服，快要不行了。求您帮帮忙，救救我的战友们，我实在不知道该怎么办了……"] = "Мои товарищи оказались в ловушке в горах, без еды и одежды, и они вот-вот умрут. Пожалуйста, помогите мне, спасите моих товарищей, я правда не знаю, что делать...",
    ["我的故事说完了。<P_Heart>（眨眼）</>你呢？有没有什么更离奇的故事？"] = "Моя история закончена. <P_Heart> (Подмигивает) </> А ты? Есть ли у вас еще странные истории?",
    ["我的朋友科恩，是一个怜惜才华，专注学术的人，我们的观点常常冲突，从而导致无数场小型辩论。"] = "Мой друг Коэн был человеком, который ценил талант и был сосредоточен на учебе. Наши точки зрения часто сталкивались, что приводило к бесчисленным мелким дебатам.",
    ["我的潜意识在告诉我，依次触碰它们，也许有助于我完成接下来的晋升。"] = "My subconscious is telling me that touching them in sequence might help me complete my next advancement.",
    ["我的火腿呢？培根呢？秘制烤香肠呢？"] = "Где моя ветчина? Мой бекон? Мои секретные жареные колбаски?",
    ["我的爱，我来了！"] = "Моя любовь, я иду!",
    ["我的经历让我没有祖国的归属感，但这不算遗憾，毕竟，比起一个概念，我的人生里有着更多更具体的人。"] = "Мой жизненный путь лишил меня чувства принадлежности к какой-либо родине, но я об этом не жалею: в конце концов, в моей жизни было куда больше конкретных живых людей, чем абстрактных понятий.",
    ["我的考验很简单，吟诵后续的诗句，并选择对应的花束，由向导交给我。"] = "Мой тест прост: прочтите последующие строки стихотворения и выберите соответствующий букет, а затем попросите гида передать его мне.",
    ["我的长子也遗传了这一点。在其他很多事情上，他也与我相似。有些是遗传，有些是对父亲的崇拜。"] = "Мой старший сын тоже унаследовал это. Во многом другом он тоже был похож на меня. Некоторые достались по наследству, а некоторые возникли из-за восхищения отцом.",
    ["我相信你。"] = "Я верю в тебя.",
    ["我看到，我看到了大家的尸体……为什么……"] = "Я видел это, я видел тела каждого... почему...",
    ["我看着他从普通队员，一步步成长起来。"] = "Я наблюдал, как он шаг за шагом вырастал из обычного члена.",
    ["我看见你了，出来吧。"] = "I see you. Come out.",
    ["我真是个笨蛋！居然相信这和餐厅毫无关系的活动能免单！"] = "Я такой идиот! Я действительно верил, что мероприятие, не связанное с рестораном, может предлагать бесплатную еду!",
    ["我真的……舍不得她。"] = "Я правда... не могу ее отпустить.",
    ["我真的可以做到吗……"] = "Могу ли я действительно это сделать...",
    ["我真笨！竟然连路都不认识了！"] = "Я такой глупый! Я даже не могу узнать дорогу!",
    ["我真能听懂猫说话了？是那杯茶的效果？"] = "Могу ли я действительно понять, что говорят кошки? Это эффект от чая?",
    ["我知道。所以我说你不是一个好的占卜师。"] = "Я знаю. Вот почему я сказал, что ты плохой предсказатель.",
    ["我知道了"] = "Я понимаю",
    ["我知道你们关心我，可生活有时并不需要“团队合作”，你们不能替我做决定呀。"] = "Я знаю, что ты заботишься обо мне, но жизнь иногда не требует «командной работы»; ты не можешь принимать решения за меня.",
    ["我知道你会想到什么——蒸汽与机械之神，是吧？"] = "Я знаю, о чем ты подумал: о Боге Пара и Машин, верно?",
    ["我知道您一直愧疚。您觉得是您的占卜，害死了我母亲。"] = "Я знаю, ты всегда чувствовал себя виноватым. Ты думаешь, что это твое предсказание убило мою мать.",
    ["我知道我的研究看起来很疯狂。但在这个世界上，最伟大的发明在最开始的时候，看起来都是疯狂的。不是吗？"] = "Я знаю, что мои исследования выглядят сумасшедшими. Но в этом мире величайшие изобретения поначалу кажутся безумием. Не так ли?",
    ["我知道瓜里的东西会吞噬买家。每一个来买瓜的，都死了。"] = "Я знаю, что вещь внутри тыквы пожирает покупателя. Все, кто пришёл купить тыкву, умерли.",
    ["我研究星相三年了，但这几天，它们的位置全乱了！我也开始倒霉！"] = "Я изучаю астрологию три года, но за последние несколько дней положение звезд пошло наперекосяк! И мне тоже начало не везти!",
    ["我祈求您的眷顾，祈求您净化此处的污染！"] = "Я молюсь о вашей благосклонности, я молюсь о том, чтобы вы очистили эту порчу!",
    ["我祈求您的眷顾，祈求您让此地的物品解开封印！"] = "Я молюсь о вашей милости, я молюсь, чтобы вы распечатали эти предметы здесь!",
    ["我第一次经历的时候，以为自己要死了。"] = "Когда я впервые испытал это, я думал, что умру.",
    ["我第一次见他说那么多话……后来，他被炮弹炸毁了右手，再也没法拿笔了。"] = "Я впервые слышал, чтобы он так много говорил... Позже снарядом ему оторвало правую руку, и он больше никогда не мог держать ручку.",
    ["我第一笔成功投资是脚踏车公司的股票，我当时并没有足够的钱购买股票，但我父亲教了我一种投资技巧。"] = "Моей первой успешной инвестицией были акции велосипедных компаний. В то время у меня не было достаточно денег, чтобы покупать акции, но мой отец научил меня технике инвестирования.",
    ["我答应过教你神秘学知识。"] = "Я обещал научить тебя оккультным знаниям.",
    ["我给他算了一笔账，出了一个赚到更多房租的主意。在更多的租金面前，他爽快地同意了。"] = "Я рассчитал ему счет и придумал, как заработать больше на аренде. Учитывая увеличение арендной платы, он с готовностью согласился.",
    ["我花了很长时间观察、试探，才逐渐理解……那位存在的伟大。"] = "Я провел много времени, наблюдая и проверяя, прежде чем постепенно понял... величие этого существования.",
    ["我花了整整两年时间研究这个课题。结果呢？教会的人把我送上了审判庭！"] = "Я потратил целых два года на исследование этой темы. И результат? Люди из Церкви отправили меня в инквизицию!",
    ["我藏了十年，你们就一点不生气？"] = "I've been hiding for ten years, and you're not even a little bit angry?",
    ["我被诅咒了！没法从地上起来，只有真爱之吻才能解除！"] = "Я проклят! Нет возможности подняться с земли, только поцелуй настоящей любви сможет поднять ее!",
    ["我要先去找妹妹了，再见！"] = "Сейчас я найду сестру, до свидания!",
    ["我要求不高，能在婚礼上演奏就行。您愿意听我的演奏，然后给点建议吗？"] = "Запросы у меня скромные — лишь бы играть на свадьбах. Не согласитесь послушать мою игру и дать пару советов?",
    ["我记得三年前过来的时候，就在这边！"] = "Помню, когда мы приехали сюда три года назад, оно было прямо здесь!",
    ["我记得刚成为值夜者的样子，记得第一次独立办案子，第一次领薪水，以及第一次打牌输掉半个月的餐费……"] = "Я помню, как это было, когда я впервые стал Ночным Ястребом, мой первый сольный случай, мою первую зарплату и первый раз, когда я проиграл в карты деньги на еду за полмесяца...",
    ["我记得祂曾说过这样一句话。"] = "Я помню, как Он однажды сказал это предложение.",
    ["我试试。"] = "Я постараюсь.",
    ["我说你们和我父亲一样，都是大笨蛋！"] = "Говорю же вам: вы, как и мой отец, круглые дураки!",
    ["我说马丁，你今天可真古怪，怎么一句话也不说？"] = "Я говорю, Мартин, ты сегодня очень странный, почему ты не говоришь ни слова?",
    ["我诵念祂的尊名，但我从未忘记自己是谁。我是白银城的长老，是六人议事团的成员，是……想要在黑暗中为族人找一条出路的人。"] = "Я повторяю Его почетное имя, но я никогда не забывал, кто я. Я старейшина Серебряного города, член Совета Шести и... тот, кто хочет найти выход из темноты для своего народа.",
    ["我请“魔术师”小姐，找到了最初的手稿，上面还残留着凶手的灵性痕迹。 "] = "Я попросил госпожу Волшебницу найти оригинал рукописи, но на ней все еще остались духовные следы убийцы.",
    ["我请求他们跳下去，可没人愿意，他们都跑了。"] = "Я умоляла их спрыгнуть вниз, но никто не хотел, поэтому все убежали.",
    ["我调整了药物的剂量，只要剂量出错，他的心脏随时都会停下。也是我，锁住房门，把卧室布置成反锁的密室。"] = "Я скорректировал дозировку лекарства; если дозировка была неправильной, его сердце могло остановиться в любой момент. Это я также запер дверь спальни и сделал спальню тайной запертой комнаты.",
    ["我赌了一把，向他祈求。他不仅回应了，还帮我清除了那个呓语，就像……拂去灰尘一样简单。"] = "Я рискнул и помолился ему. Он не только ответил, но и помог мне избавиться от этих шепотов, так же просто, как... смахнуть пыль.",
    ["我走错地方了。"] = "Я не в том месте.",
    ["我过世的妻子非常喜欢音乐，弹琴就是她教我的。"] = "Моя покойная жена очень любила музыку, и именно она научила меня играть.",
    ["我还做了好几种新的药剂！你帮我试试效果吧！"] = "Я также приготовил несколько новых зелий! Помогите мне проверить их эффект!",
    ["我还找到了一个日记本。"] = "А еще я нашел дневник.",
    ["我还是愿意呆在这里。乡下安静、简单……最重要的是，我曾经的战友们也在这墓园里。"] = "Я всё же предпочитаю оставаться здесь. В деревне тихо, спокойно... а главное, мои прежние боевые товарищи тоже покоятся на этом кладбище.",
    ["我还有一个重要猜想需要验证。"] = "У меня все еще есть важная гипотеза, которую необходимо проверить.",
    ["我还没问，“魔术师”小姐就知道了？"] = "I hadn't even asked yet, and Miss Magician already knew?",
    ["我还知道一件事！"] = "Я знаю еще одну вещь!",
    ["我还知道你是非凡者，被一个胡说八道的残影蛊惑到了这里。"] = "Я также знаю, что ты Потусторонний, заманенный сюда бессмысленной остаточной тенью.",
    ["我还知道，这里是回忆构成的空间，我们现在都被困在了这里。"] = "Я также знаю, что это пространство состоит из воспоминаний, и мы все сейчас заперты здесь.",
    ["我还要准备炸鸡，就不送你了。"] = "I still have to prepare fried chicken, so I won't see you out.",
    ["我还遇到了一件更可怕的事。我、我最近总听到，湖上传来叹息的声音！"] = "Я также столкнулся с чем-то еще более ужасающим. Я, я недавно слышал вздохи, доносящиеся с озера!",
    ["我远远见过一次。她脚边趴着好几只野猫，桌上还蹲着老鼠。那些畜生在她面前乖得像宠物。"] = "Я видел ее однажды издалека. У ее ног лежало несколько бездомных кошек, а на столе сидела крыса. Перед ней эти звери были послушны, как домашние животные.",
    ["我都收拾好了，你也快收摊吧。"] = "Я закончил собирать вещи, тебе тоже пора закрыть свой ларек.",
    ["我问他博诺瓦将来会有什么成就，他只是笑了笑，什么也没说！可恶的占卜家！他早就知道了！"] = "Я спросил его, какие достижения будут у Боновы в будущем, а он только улыбнулся и ничего не сказал! Чертов Провидец! Он знал это всегда!",
    ["我随时都准备着倾听。"] = "Я готов выслушать в любое время.",
    ["我雇佣的厨师、杂活女仆，和一个定期过来的浆洗女工可以解放我的时间。"] = "Я нанял повара, горничную и прачку, которые регулярно приходили, чтобы освободить мое время.",
    ["我需要和米拉、埃文追查另一件封印物，必须尽快定位。所以想把带回“2-327”的任务交给你。"] = "Мне нужно вместе с Мирой и Эваном выследить ещё один Запечатанный Артефакт, мы должны обнаружить его как можно скорее. Поэтому я хочу поручить задание по возвращению «2-327» тебе.",
    ["我需要怎么做？"] = "Что мне нужно сделать?",
    ["我骑得很熟练了，都骑到雪山上来了！"] = "Теперь я очень опытен в верховой езде; Я даже доехал до Снежной горы!",
    ["我，我……"] = "Я, я...",
    ["我，我吗？"] = "Я, я?",
    ["我？"] = "Мне?",
    ["我？怎么可能！"] = "Мне? Как это возможно!",
    ["我？我的衣服是用布条拴住的。你自己想办法去。"] = "Мне? Моя одежда связана полосками ткани. Найдите путь сами.",
    ["戒指有机关……是暗器？她在找机会下手？为什么迟迟不动手？"] = "У кольца есть механизм... это скрытое оружие? Она ищет шанс нанести удар? Почему она еще не действовала?",
    ["或许和皇室有关系，或许是一位拉斯廷伯爵的崇拜者，你觉得呢？"] = "Возможно, это как-то связано с королевской семьей или, возможно, с поклонником графа Ластингса, как вы думаете?",
    ["或许我们确实是时代的弃儿，但是我希望骑士的精神能被继承下去，坚持公平，真诚勇敢，保护弱者，捍卫国家。"] = "Возможно, мы действительно брошенные дети той эпохи, но я надеюсь, что дух рыцаря можно унаследовать — настаивать на справедливости, быть искренним и храбрым, защищать слабых и защищать страну.",
    ["或许我成为“收尸人”，冥冥中也是注定的。"] = "Возможно, мне было суждено стать «Собирателем трупов» во тьме.",
    ["战争可以在几分钟内夺去几百名战友的生命……可更残酷的是，我甚至永远无法替他们报仇，替他们完成心愿。"] = "Война может за несколько минут унести жизни сотен товарищей... но что еще более жестоко, я никогда не смогу даже отомстить за них или исполнить их желания.",
    ["战争已经……结束了？我不明白……可我为什么会在这里？难道我一路走了三年？"] = "Война уже... закончилась? Я не понимаю... Но почему я здесь? Неужели я брёл целых три года?",
    ["战争？"] = "Война?",
    ["战友……墓地……战友……墓地……把土地献给我主……"] = "Товарищи... кладбище... товарищи... кладбище... отдайте землю моему Господу...",
    ["战友……墓地？老鼠在重复这些词，是什么意思？"] = "Товарищи... кладбище? Мышь повторяет эти слова, что это значит?",
    ["战友们的名字——汤姆、老约翰、红头发的小比利……队长叫赫尔曼，总说打完仗要回去开面包店……"] = "Имена моих товарищей — Том, Старый Джон, маленький рыжеволосый Билли… капитана звали Герман, который всегда говорил, что после войны вернется, чтобы открыть пекарню…",
    ["战斗很激烈吗？"] = "Была ли битва напряженной?",
    ["戴娜女士，你知道奥莉薇在哪吗？她十分美丽，在这个村中一定很出名吧？"] = "Мисс Дана, вы знаете, где Оливия? Она очень красивая, должно быть, она знаменита в этой деревне, да?",
    ["戴莉女士，听说您在值夜者里被称为“天才”？"] = "Мадам Дэйли, говорят, среди Ночных Ястребов вас называют «гением»?",
    ["戴莉女士，您为什么总是这样打扮？黑袍、蓝眼影、银链……"] = "Мисс Дейли, почему вы всегда так одеваетесь? Черные одежды, синие тени для век, серебряные цепи...",
    ["戴莉女士，您更喜欢廷根还是贝克兰德？"] = "Госпожа Дэйли, что вам больше по душе — Тинген или Бэкланд?",
    ["戴莉女士，能讲讲您的信使吗？听说长得很特别？"] = "Мисс Дейли, можете ли вы рассказать мне о своем посыльном? Я слышал, это выглядит довольно уникально?",
    ["戴莉女士，能问问您和邓恩队长的事吗？"] = "Леди Дейли, могу я спросить о вас и капитане Данне?",
    ["所以……我也能试试？"] = "Итак... можно мне тоже попробовать?",
    ["所以你决定了？"] = "Итак, вы решили?",
    ["所以你将计就计，回信迷惑他，让你有机会报仇？"] = "Значит, ты подыгрывал, писал в ответ, чтобы сбить его с толку, давая тебе шанс отомстить?",
    ["所以你是要赴约了？"] = "Так ты собираешься прийти на встречу?",
    ["所以您一直没说？"] = "Так ты никогда ничего не говорил?",
    ["所以您学心理学是为了什么？"] = "Так почему же вы изучаете психологию?",
    ["所以您就试图把公牛和小麦杂交？"] = "И поэтому вы попытались скрестить быка с пшеницей?!",
    ["所以您很擅长调查？"] = "Значит, вы очень хороши в расследованиях?",
    ["所以您的第二段尊名是黄黑之王的眷者。"] = "Итак, ваша вторая почетная награда — «Благословение Желтого и Черного Короля».",
    ["所以我也在帮他留意相关的线索。如果能帮阿兹克先生找回记忆，我也会很高兴。"] = "Так что я также слежу за соответствующими подсказками для него. Если я смогу помочь господину Азику восстановить его воспоминания, я тоже буду очень рад.",
    ["所以我会在咖啡厅坐坐。"] = "Вот почему я сижу в кафе.",
    ["所以是我们误会了？还帮你设计了这么多考验……"] = "Значит, мы неправильно поняли? И мы даже разработали для вас столько тестов...",
    ["所以现在看起来，你们对“愚者”先生都很尊敬？"] = "Итак, кажется, вы все теперь очень уважаете господина Шута?",
    ["所以答案是廷根。简单、直接，真是令人怀念。"] = "Итак, ответ — Тинген. Просто, прямо и очень скучно.",
    ["所以罗珊刚才着急出门，是……？"] = "Значит, Розанна сейчас так спешила уйти, не так ли...?",
    ["所以要会挑。捏一捏，太软的不要，有虫眼的不要。回家把磕碰的地方切掉，剩下的能吃三天。"] = "Поэтому надо уметь выбирать. Пощупай: слишком мягкие не бери, с червоточинами тоже. Дома срежешь помятые бока — и остального на три дня хватит.",
    ["所以这一切，都是血族内部的问题？"] = "Значит, все это было лишь внутренней проблемой внутри Сангвиника?",
    ["所以这些天，你衣服上的是……"] = "Итак, все эти дни вещи на твоей одежде были...",
    ["所以，<P_Heart>（严肃）</>在非凡世界一定要——“小心观众”。"] = "Поэтому, <P_Heart>(Серьезный)</> в Необыкновенном мире вы всегда должны — «Остерегайтесь зрителей».",
    ["所以，<P_Heart>（点头）</>值得。"] = "Итак, <P_Heart>(Кивает)</>, оно того стоит.",
    ["所以，你……不讨厌我？"] = "Значит, я... тебе не противен?",
    ["所以，我们后来去了南方，那里的天气很惬意，海边的日晒让我们重新开启了一段美好的时光。"] = "Итак, позже мы поехали на юг, где погода была очень приятной, а солнечный свет у моря позволил нам снова начать чудесное времяпрепровождение.",
    ["所以？"] = "Поэтому?",
    ["所有人都知道。您的名字被刻在新白银城的纪念碑上，和科林首席在一起。"] = "Об этом знают абсолютно все. Ваше имя высечено на монументе Нового Города Серебра, рядом с именем главного старейшины Колина.",
    ["所有的叶子。每一种叶脉走向。每一层细胞结构。从古至今，从现在到未来。所有的叶子。"] = "Все листья. Каждый рисунок вен. Каждая клеточная структура. От древних времен до наших дней, отныне до будущего. Все листья.",
    ["所有的叶子？"] = "Все листья?",
    ["所谓“扮演法”的精髓，就是“做出符合魔药名称的行为，明悟暗藏的规律，并以此严格要求自己”。"] = "Суть так называемого «Метода действия» заключается в «выполнении действий, соответствующих названию зелья, постижении скрытых законов и строгом их соблюдении».",
    ["打仗？"] = "Война?",
    ["打仗？你家祖上，有没有参加过战争的长辈？"] = "Война? Кто-нибудь из ваших предков участвовал в войне?",
    ["打完仗，我准备去贝克兰德当职业画家。要是我出了名，你们来贝克兰德的餐费我全包了，记得来找我啊！"] = "После войны я планирую поехать в Бэкланд, чтобы стать профессиональным художником. Если я стану знаменитым, я покрою все твои расходы на еду в Баклунде; не забудь прийти и найти меня!",
    ["打开信件看看"] = "Вскрыть письмо и взглянуть",
    ["打开另一个包裹"] = "Открыть другой пакет",
    ["打开笔记本看看"] = "Открыть блокнот и взглянуть",
    ["托马斯爱说笑话，埃莉诺就在柜台后面笑，手里的杯子都端不稳……啧啧，那个时候，多好啊。"] = "Томас любил рассказывать анекдоты, Элеонора смеялась за стойкой, не в силах даже твердо держать чашку... Тск-цк, это были хорошие времена.",
    ["扫地啊，我的妻子不愿意让我在家里做家务，我只能出来做义工了。"] = "Подметаем пол. Моя жена не хочет, чтобы я выполнял работу по дому, поэтому я могу выходить только на волонтерскую работу.",
    ["扮成侍者，再化个妆……这样罗珊应该就认不出我了。"] = "Оденусь официантом, наложу немного грима... так Розанна меня точно не узнает.",
    ["扮演·占卜家"] = "Acting: Провидец",
    ["扮演·祈光人"] = "Действующий: Искатель Света",
    ["扮演·观众"] = "Актерское мастерство · Зритель",
    ["找人。一个叫艾琳的姑娘。我听说她在雪山一带活动，但我的占卜天赋没你那么好，只能算个大概方位，不知道她什么时候才会经过这里。"] = "Ищу кого-то. Девушка по имени Эйлин. Я слышал, что она действовала возле Снежной горы, но мой талант прорицателя не так хорош, как твой. Я мог только рассчитать общее направление; Я не знаю, когда она пройдет здесь.",
    ["找借口拒绝"] = "Находите оправдания, чтобы отказаться",
    ["找到了，是这个金属盒子？看起来是个神奇物品，那些奇怪的人影就是被它影响了。"] = "Found it, is it this metal box? It looks like a mystical item; those strange shadows were affected by it.",
    ["找到切入口也非常重要，得用恰当的理由让对方接受你的出价。"] = "Найти верный подход тоже крайне важно: нужно подобрать убедительный довод, чтобы собеседник согласился на вашу цену.",
    ["找海莉夫人？她今天不在。"] = "Ищете мадам Хейли? Ее сегодня здесь нет.",
    ["承蒙众神眷顾、亲见神眷外观之人，深谙为他人安魂之道或醉心春夜中的舞会、将教团修行至炉火纯青之人……"] = "Те, кто пользуется благосклонностью богов, те, кто стал свидетелем явления божественной благодати, те, кто хорошо разбирается в реквиемах по другим, или те, кто увлечен балами весенней ночи, те, кто довел свой порядок до совершенства...",
    ["抱歉……说到了您的伤心事。"] = "Извините… говорю о вашей печали.",
    ["抱歉我不知道……"] = "Простите, я не знаю...",
    ["抱歉罗珊，是我们做得不对，搅乱了你的相亲。"] = "Извини, Розанна, мы были не правы, сорвав твое свидание вслепую.",
    ["抱歉！只是好奇您的看法……"] = "Извини! Просто интересно ваше мнение...",
    ["抱歉，以后我们一定会先询问你的意见。这次可以原谅我们吗？"] = "Извините, в будущем мы обязательно сначала спросим ваше мнение. Сможешь ли ты простить нас на этот раз?",
    ["抱歉，富人区目前暂不对普通人开放，需要你有一定的身份后才会开放。"] = "Извините, богатый район в настоящее время закрыт для обычных людей. Он будет доступен только после достижения определенного статуса.",
    ["抱歉，我不是有意……"] = "Прости, я не нарочно...",
    ["抱歉，罗珊女士，看来我今天的运气不够好。"] = "Извините, мисс Розанна, похоже, мне сегодня не повезло.",
    ["抱歉，能够安静地回忆过去，或许也是一种……奢侈的幸福。"] = "Прости, но возможность тихо вспоминать прошлое, пожалуй, тоже... роскошное счастье.",
    ["抱歉，身为队长，我应该像调查非凡事件那样严谨些，先弄清楚真相。"] = "Прошу прощения. Как капитан, я обязан был подойти к делу со всей строгостью расследования потусторонних происшествий и сначала выяснить правду.",
    ["拆下来的几页看起来很新，是有人伪造后贴上去的？"] = "Оторванные страницы выглядят совершенно новыми. Кто-то их подделал и наклеил?",
    ["拉他去警察局"] = "Тащите его в полицейский участок",
    ["拉姆德小镇最好的纪念品！{{先生|女士}}，这里是给您的家人和朋友挑礼物的不二之选！"] = "Лучшие сувениры в Ламуд Тауне! {{ Mr. | Ms. }}, это лучший выбор для выбора подарков родным и близким!",
    ["拉斐尔墓园隶属于黑夜教会，所以你想要埋在这边先得是女神的信徒，其中的一半费用会捐献给教会。你是要穷人区，富人区，还是普通区。"] = "Кладбище Рафаэля принадлежит Церкви Вечной Ночи, поэтому, если вы хотите быть похороненным здесь, вы должны сначала быть верующим в Богиню. Половина стоимости будет пожертвована церкви. Вам нужен бедный район, богатый район или обычный район?",
    ["拯救少女的角色是？"] = "Кто тот персонаж, который спасает девушку?",
    ["拿走……不是我的，扔了也行，别让我看见。"] = "Уберите это... это не мое. Можешь выбросить, только не показывай мне.",
    ["拿走剧本"] = "Возьмите сценарий",
    ["指南针就在她身后……"] = "The compass is right behind her...",
    ["指南针有怎样的非凡能力？"] = "What kind of Beyonder powers does the compass have?",
    ["指引就到这里了。可是……"] = "На этом руководство заканчивается. Но...",
    ["按你们人类的说法，就是天使级别的力量波动。"] = "Говоря человеческим языком, это колебание силы на уровне Ангела.",
    ["按照侦探与占卜师的对话来看，拯救少女的角色应该是<P_Yellow>侦探的助手</>，在剧本上记录一下吧。"] = "Судя по разговору детектива и провидца, спасителем девушки должен быть <P_Yellow>помощник детектива</>; запишите это в сценарий.",
    ["按照配方的材料和计量，先调配晋升到下一序列的魔药吧。"] = "В соответствии с материалами и измерениями формулы сначала приготовьте зелье для перехода к следующей последовательности.",
    ["捉迷藏中扮演鬼的角色是谁？"] = "Кто играет роль призрака в прятках?",
    ["捐给圣赛琳娜教堂的慈善经费？这太棒了，你有兴趣吗，安多？"] = "Благотворительные средства пожертвованы собору Святой Селены? Это здорово, тебе интересно, Андо?",
    ["据我所知，人造死神派已经遭受了重创，那您的灵魂有找回来吗？"] = "Насколько мне известно, секта Искусственной Смерти уже понесла большие потери. Вы нашли свою душу обратно?",
    ["据说秘密藏在湖对岸的森林，想不想去看看？"] = "Говорят, что тайны спрятаны в лесу на другом берегу озера. Хочешь пойти посмотреть?",
    ["接下来几天慢慢适应，很快就能好了。"] = "Не торопитесь и адаптируйтесь в течение следующих нескольких дней; скоро ты поправишься.",
    ["接下来，把我带到记忆印记旁边，我会唤醒那些沉睡已久的玩具和机关"] = "Далее верните меня в отпечаток памяти, и я разбужу эти давно спящие игрушки и механизмы.",
    ["推开巨殿厚重的大门，时隔千年的阳光再次映入白银城居民的眼中。"] = "Распахнув тяжелые двери большого зала, через тысячу лет солнечный свет вновь отразился в глазах жителей Серебряного Города.",
    ["推断到这里，好像只剩下了一个答案……"] = "Подводя итоги, кажется, что остается только один ответ...",
    ["提出帮助"] = "Предложить помощь",
    ["搅拌完成"] = "Перемешивание завершено",
    ["摩根先生，大家都说这是你的表。"] = "Мистер Морган, все говорят, что это ваши часы.",
    ["摩根先生？！"] = "Мистер Морган?!",
    ["摩根是镇上最好的钟表匠，谁家钟表坏了都找他，他修好的钟，走得比新的还准。"] = "Морган — лучший часовщик в городе. Все идут к нему, когда у них ломаются часы. Часы, которые он чинит, идут точнее новых.",
    ["擦拭镜子"] = "Протереть зеркало",
    ["改成公墓吧。"] = "Превратите его в общественное кладбище.",
    ["放回来？你让{{他|她}}放回来的？！"] = "Put it back? You let {{him|her}} put it back?!",
    ["放心吧罗珊女士，那都是人和装置假扮的。"] = "Не волнуйтесь, мисс Розанна, это все замаскированные люди и реквизит.",
    ["放心，只是拍张照而已。这是我给自己留的一份纪念，也是那只乌鸦想给你的谢礼。"] = "Не волнуйтесь, это просто фотография. Это сувенир, который я храню для себя, а также подарок в знак благодарности, который хотела подарить тебе ворона.",
    ["放心，我带过十几个人，没有出事的。"] = "Не волнуйтесь, я руководил более дюжиной человек, и ничего не пошло не так.",
    ["放心，罗珊是个外向的姑娘，她不会孤单的。"] = "Не переживай, Розанна — общительная девушка, она не останется в одиночестве.",
    ["放着不管"] = "Оставь это в покое",
    ["故事开启了新的篇章。"] = "История открыла новую главу.",
    ["敌人的炮弹偏偏在那时准得惊人，舍伍德再也没能站起来。"] = "Снаряд противника в этот момент оказался на удивление точным. Шервуд больше никогда не вставал.",
    ["救人要紧，尽管拿去吧。"] = "Спасение жизней превыше всего, берите сколько нужно.",
    ["教会带走了博诺瓦，我的小儿子。我们父子的关系或许不算那么亲密，但他终究是我的孩子。"] = "Церковь забрала Бенуа, моего младшего сына. Наши отношения как отца и сына, возможно, не такие уж близкие, но в конце концов он мой ребенок.",
    ["教会的人啊……真没意思，我对禁欲的修士可没兴趣。 "] = "Церковники... какая скука. Монахи-аскеты меня совершенно не интересуют.",
    ["教堂的灯亮着，门也没有关。最冷的冬天，两个人依偎着走，总能找到一个可以进去的门。"] = "В церкви горит свет, а дверь не заперта. В самую холодную зиму два человека, идущие, прижавшись друг к другу, всегда могут найти дверь, в которую можно войти.",
    ["散发着不详气息的宝箱。"] = "Сундук с сокровищами, источающий зловещую ауру.",
    ["整理一下现在得到的信息，有问题的是……"] = "Давайте систематизируем имеющуюся у нас на данный момент информацию. Проблема в том...",
    ["文学素养与感受是沟通的桥梁，继续前进吧。"] = "Литературное развитие и восприятие — это мосты общения; продолжайте идти вперед.",
    ["断断续续的。我还在研究怎么让产量稳定下来。嘉德丽雅船长说，如果我再让她的船“生病”，就把我扔到海里去喂鱼。"] = "Это прерывисто. Я все еще исследую, как стабилизировать урожайность. Капитан Каттлея сказала, что если я снова «заболею» ее корабль, она бросит меня в море, чтобы кормить рыб.",
    ["斯维因是？"] = "Кто такой Суэйн?",
    ["新奇？那你的朋友们呢？"] = "Роман? А как насчет твоих друзей?",
    ["新白银城的居民现在生活得很幸福，他们有了自己的田地、房屋，可以和其他国家的人正常交流、贸易。"] = "Жители Нового Серебряного города теперь живут очень счастливо; у них есть свои поля и дома, и они могут нормально общаться и торговать с людьми из других стран.",
    ["新项目？"] = "Новый проект?",
    ["无人的河边"] = "Пустынный берег реки",
    ["既然他向你开放了历史迷雾，你应该也能看到我们从这里——从霍伊大学历史系开始的过去。"] = "Поскольку он открыл вам туман истории, вы тоже сможете увидеть наше прошлое, начиная отсюда — с исторического факультета Университета Хой.",
    ["既然你看出来了——那就亲自试试，什么叫保真。"] = "Раз уж вы это поняли, попробуйте сами, что значит быть искренним.",
    ["既然她无法主动丢弃指南针，那或许可以被动失去？不如……偷走试试！"] = "Since she cannot actively discard the compass, perhaps she can lose it passively? Why not... try stealing it!",
    ["既然如此就只剩下最后一个问题，能够一直陪伴着奥斯瓦尔德，却没有被我找到的“它”，究竟是……"] = "Поскольку это так, остается только последний вопрос: что именно такое «то», что всегда могло сопровождать Освальда, но не было мной найдено...",
    ["既然是为了罗珊的相亲，有什么我能帮忙的吗？"] = "Поскольку это свидание вслепую с Розанной, могу ли я чем-нибудь помочь?",
    ["日记？为什么会出现在这里，让我感受一下它的意图……"] = "Дневник? Почему оно появилось здесь? Дай мне почувствовать его намерение...",
    ["旧钱夹里不论是零钱还是照片都破旧得有些脆弱，似乎许久没有人碰过；日记也只记录到三年前失去补给的绝境。"] = "В старом портмоне и мелочь, и фотографии обветшали от времени, словно к ним много лет никто не прикасался. Дневник же обрывался три года назад описанием безнадежного положения без припасов.",
    ["早该封锁了！我好几次看到人影，冻得跟僵尸一样，还在那儿说话！"] = "It should have been sealed off long ago! I've seen shadows there several times, frozen stiff like zombies, still talking!",
    ["时任白银城首席的科林·伊利亚特在戴里克·伯格的帮助下举行祈祷仪式，俯视着灰雾俯视着灵界的那古老宫殿内，“愚者”回应了祈求，降下了恩赐。"] = "Тогдашний глава Серебряного города Колин Илиад провел молитвенную церемонию с помощью Деррика Берга. Внутри этого древнего дворца с видом на серый туман и мир духов «Шут» ответил на молитву и даровал благословение.",
    ["时间就是生命，暴风雪不等待任何人！"] = "Время — это жизнь, и метель никого ждать не станет!",
    ["明天就是我的婚礼了，艾米莉亚，我美丽的女巫肯定又要生气——"] = "Завтра день моей свадьбы, Эмилия, моя прекрасная ведьма наверняка снова рассердится…",
    ["明明就差一点，明明只要找到那个“管家”，把遗物交上去就……就差一点……"] = "It was so close, if only I had found that \"Butler\" and handed over the relic... it was just so close...",
    ["明白了，谢谢您，我又学到了一些非凡知识。"] = "Понятно, спасибо, я узнал еще кое-что о Потустороннем.",
    ["星星？这是怎么回事？"] = "Звезды? Что происходит?",
    ["昨天我读完有关她的三部曲，据说秘密都藏在湖对岸的森林，想不想去看看？"] = "Вчера дочитала трилогию о ней. Говорят, что все секреты сокрыты в лесу на другом берегу озера. Хочешь пойти посмотреть?",
    ["昨天？昨天我留在旅馆读书，没有出门呀。"] = "Вчера? Вчера я остался в отеле, читал и никуда не выходил.",
    ["昨晚他搂着南威尔士啤酒喊了十七次“宝贝”，对我就一句“晚安”！"] = "Вчера вечером он обнимал бутылку южноуэльсского пива и семнадцать раз назвал её «деткой», а мне выдавил лишь сухое «спокойной ночи»!",
    ["昨晚，我把它扔在古堡，以为终于摆脱了它……可它……"] = "Вчера вечером я бросил его в старый замок, думая, что наконец-то избавился от него... но оно...",
    ["是“最后一页”，那个封印物又在叫我了。"] = "Это «Последняя страница», которую снова зовёт меня Запечатанный Артефакт.",
    ["是……玛丽奶奶吗？"] = "Is that... Grandma Mary?",
    ["是一名叫阿兹克的教员，我和他关系很好。这么久没联系，不知道那家伙怎么样了。"] = "Это инструктор по имени Азик, у меня с ним хорошие отношения. Мы так давно не общались, что мне интересно, как поживает этот парень.",
    ["是个可靠的人。"] = "Он надежный человек.",
    ["是为了解释“旅行家”的含义。"] = "It is to explain the meaning of \"Traveler\".",
    ["是什么？"] = "Что это такое?",
    ["是你在夜晚梦游，捡回了这只怀表。"] = "Это ты ходил ночью во сне и нашел эти карманные часы.",
    ["是你在这……拉琴？"] = "Это ты... играешь здесь на скрипке?",
    ["是吗……？"] = "Это так...?",
    ["是吗？看来我们没人能做到……"] = "Is that so? It seems none of us can do it...",
    ["是啊……在梦里，我时常回忆起他们。"] = "Да... Во снах я часто вспоминаю о них.",
    ["是啊。这些东西放在黑荆棘的话，会让人感觉那些热闹还在。"] = "Да. Если эти вещи хранятся в Блэкторне, у людей создается впечатление, что оживленность все еще здесь.",
    ["是啊，为什么……为什么我会这么做?"] = "Да, почему... почему я это сделал?",
    ["是啊，佛尔思小姐帮了我很大的忙，我才决定听从她的建议，回到这里。"] = "Yes, Miss Fors helped me a lot, which is why I decided to follow her advice and return here.",
    ["是啊，我逃离贝克兰德时，安慰自己很快就能回去，结果一年、两年……"] = "Yeah, when I fled Backlund, I comforted myself by saying I would be back soon. But then a year passed, then two...",
    ["是啊，有时候我想，干嘛要一个接一个传递诅咒呢？"] = "Да, иногда я думаю, а зачем передавать проклятие по одному?",
    ["是她所有残酷真实的记忆，也就是……我。"] = "Это все ее жестокие, настоящие воспоминания... то есть я.",
    ["是我。那是一段美好的日子……某种程度上说，是我离开拜朗帝国后的新生。"] = "It's me. Those were good days... in a way, it was a new beginning for me after leaving the Balam Empire.",
    ["是我家有几百年历史的宅子，那地方太破了，我打算卖点钱补贴家用。"] = "Это дом моей семьи с сотнями лет истории. Это место слишком ветхое, я планирую продать его за какие-то деньги, чтобы прокормить семью.",
    ["是摩根的怀表！它回来了？"] = "Это карманные часы Моргана! Они вернулись?",
    ["是泥土，还是风，还是黄金树听见了我的话……"] = "Была ли это почва, ветер или Золотое Древо, услышавшее мои слова...",
    ["是海莉夫人那番话让我下决心的。她说得对，只要站起来，剑就留在地上了。"] = "Именно слова мадам Хейли заставили меня принять решение. Она была права: пока ты стоишь, мечи остаются на земле.",
    ["是的。但那不是“不像狗”，那是“狗也可以”。"] = "Да. Но это не «непохоже на собаку», это «собака тоже так умеет».",
    ["是的。奥黛丽说书是好东西，要多读书。"] = "Да. Одри говорит, что книги — хорошая вещь, и нужно больше читать.",
    ["是的。奥黛丽说我进步得很快。"] = "Да. Одри говорит, что я прогрессирую очень быстро.",
    ["是的。我的同门卢卡斯选择了真理，老师带着卢卡斯走向了知识领域的深处，再也没有回来。"] = "Да. Мой соученик Лукас выбрал истину. Учитель увел Лукаса в глубины царства Знаний, и они так и не вернулись.",
    ["是的。阿兹克先生就像我的长辈，虽然他正在寻找自己失去的记忆，但他对我的帮助从未减少。"] = "Да. Господин Азик для меня как старший. Хотя он ищет свои утраченные воспоминания, его помощь мне никогда не уменьшалась.",
    ["是的，一个相对独立于现实、灵性更为活跃的层面。在这里进行仪式魔法的学习和实践，能更清晰地感知能量的流动，也相对……安全一些。"] = "Да, план, относительно независимый от реальности, где духовность более активна. Изучение и практика Ритуальной Магии здесь позволяет яснее воспринимать потоки энергии, а также относительно... безопаснее.",
    ["是的，不需要做什么，只是点一杯费尔默咖啡，听周围人聊天。"] = "Да тут делать нечего, просто закажите чашечку кофе «Фермо» и слушайте болтовню вокруг.",
    ["是的，但这同样需要一些智慧和眼力……我想，是时候在这里成立一片可以自由贸易的市场了！请您跟我来。"] = "Да, но это тоже требует некоторой мудрости и острого глазомера... Думаю, пора основать здесь рынок свободной торговли! Пожалуйста, следуйте за мной.",
    ["是的，你是来找主人的吧？"] = "Да, ты здесь, чтобы найти хозяина, верно?",
    ["是的，原话。"] = "Да, это были точные слова.",
    ["是的，她今天应该也会来，也许你可以和她聊聊？"] = "Да, она должна прийти сегодня, может быть, ты сможешь с ней пообщаться?",
    ["是的，我分离出的那个身份一直留在贝克兰德处理基金会的事情，以及陪伴我的家人。"] = "Да, личность, которую я отделил, осталась в Баклунде, чтобы заниматься делами фонда и сопровождать мою семью.",
    ["是的，我当时犹豫了很久。但她最后说“我们需要愿意守护这座城市的人。”"] = "Да, я долго колебался. Но в конце концов она сказала: «Нам нужны люди, готовые охранять этот город».",
    ["是的，我想一直守在这里，保护这里的一切。"] = "Да, я хочу навсегда остаться здесь и оберегать все вокруг.",
    ["是的，我记得我们的这位老乡后面还说：等我成为高序列强者，看到一个“占卜家”就揍一个！"] = "Да, я помню, как наш соотечественник позже сказал: «Как только я стану могучим человеком Высокой Последовательности, я побью каждого «Провидца», которого увижу!»",
    ["是的，据说他们提供的茶都有神奇的效果，能让你操控梦境、掌心生火，有的甚至能让人看见幽灵。"] = "Да, говорят, что чай, который они дают, обладает магическим действием: позволяет управлять снами, разжигать огонь в ладонях, а некоторые даже заставляют людей видеть призраков.",
    ["是的，没错！这首曲子是《婚礼进行曲》。"] = "Да, это так! Это произведение называется «Свадебный марш».",
    ["是的，老爷要去打仗，他出征时把宅子交给我管理，说我是他最信任的仆人。"] = "Да, Мастеру пришлось пойти на войну. Уезжая в поход, он доверил дом мне, сказав, что я слуга, которому он доверяет больше всего.",
    ["是的，而且要先学会一件事——别把他们当成尸体。"] = "Да, и прежде всего вам следует усвоить одну вещь: не обращайтесь с ними как с трупами.",
    ["是的，街上可租赁的脚踏车，就是我之前提供的想法。"] = "Да, велосипеды, которые можно взять напрокат на улице, — это идея, которую я высказал ранее.",
    ["是的，那是我的家乡。一个宁静的小城市，生活节奏很慢，人们都很友善。"] = "Да, это мой родной город. Тихий маленький город с медленным темпом жизни и очень дружелюбными людьми.",
    ["是的，镇上能看到许多依托旅游发展的产业。有很多喜爱拉姆德的自然风光和古堡历史的游客。"] = "Да, в городе можно увидеть множество предприятий, которые зависят от туризма. Многие туристы любят природные пейзажи Ламуда и историю старого замка.",
    ["是的，黄黑之王指向了“愚者”先生。"] = "Да, Король Желтого и Чёрного указывает на господина Шута.",
    ["是相信了之后，就再也没有往前走。"] = "Дело в том, что после того, как она поверила, она больше никогда не двигалась вперед.",
    ["是真的。“愚者”先生打开了通往外界的通道，白银城的居民已经迁移到了拜朗帝国附近的富饶土地上。"] = "Это правда. Господин Шут открыл проход во внешний мир, и жители Города Серебра переселились на плодородные земли близ империи Балам.",
    ["是稿费。"] = "Это плата за мою работу.",
    ["是稿费，贝克兰德邮报的。我把给你们画的画寄了过去，他们给了我稿费，数额不少——如果不是在山里花不了钱，我一定请你们大吃一顿！"] = "Это гонорары от Backlund Post. Я посылал для тебя написанные мною картины, и мне давали гонорары, а это были довольно большие деньги - если бы я не имел возможности тратить деньги в горах, я бы угостил тебя пиром!",
    ["晨曦之剑，可以净化黑暗。银白细剑，能绕过屏障直接攻击。"] = "Меч Рассвета может очистить тьму. Серебряная рапира может обходить препятствия и атаковать напрямую.",
    ["普通区"] = "Общий район",
    ["普通区300苏勒到1000苏勒不等，看具体位置而定。"] = "Общий район колеблется от 300 до 1000 суле, в зависимости от конкретного местоположения.",
    ["普通区呢？"] = "А как же обычный район?",
    ["暴风雪吗……"] = "Метель...",
    ["更不是我。"] = "Тем более я.",
    ["更何况……如果班西港的邪祭真的蔓延开来，整个苏尼亚海都将不得安宁。"] = "К тому же... если зловещие ритуалы порта Банси действительно расползутся повсюду, всему морю Соня не знать покоя.",
    ["更简单的曲子"] = "Более простая мелодия",
    ["更近的地方？"] = "Где-то поближе?",
    ["更重要的是，身为观众，是旁观者，也是见证者。"] = "Что еще более важно, вы как зритель являетесь сторонним наблюдателем и свидетелем.",
    ["最可气的是她专给穷人占卜。那些小贩、女仆、车夫，懂什么占卜？她说什么他们都信。"] = "Самое бесит то, что она специализируется на гадании для бедных. Эти торговцы, горничные и возницы — что они знают о гадании? Они верят всему, что она говорит.",
    ["最后一份能量？"] = "Последняя частица энергии?",
    ["最后一段记忆就在上面！"] = "Последний фрагмент воспоминаний там!",
    ["最后一页？"] = "Последняя страница?",
    ["最后吗……克莱恩那孩子变成他的样子，陪我跳了最后一支舞。"] = "В конце концов... этот ребенок Клейн превратился в свой облик и станцевал со мной последний танец.",
    ["最后是这个，你的护身符。"] = "Наконец-то вот это, твой амулет.",
    ["最后还是要恭喜你，晋升成功。"] = "Наконец, я должен поздравить вас с успешным продвижением.",
    ["最后，他还夸我是一个有良心，做事诚实的年轻人。"] = "В конце концов он даже похвалил меня как молодого человека с совестью, который поступает честно.",
    ["最后，我们在一处无名小岛附近堵住他们。"] = "Наконец мы заблокировали их возле безымянного острова.",
    ["最后，我只花了积蓄就完成了煤气灯加装，没有借一分钱。"] = "В конце концов, я потратил свои сбережения только на установку газовой лампы, не взяв в долг ни копейки.",
    ["最大的风险？我觉得是，停止尝试。"] = "Самый большой риск? Я думаю, это останавливает попытку.",
    ["最近常买她的炸鸡，久而久之就知道了一些。"] = "I've been buying her fried chicken often lately, and over time, I've learned a few things.",
    ["最近开销不小，不知道有没有什么省钱的办法……"] = "Расходы в последнее время большие, интересно, есть ли способы сэкономить...",
    ["最近警察厅倒是安排了不少新人过来学习格斗。"] = "Недавно полицейское управление отправило немало новичков учиться боевому искусству.",
    ["最重要的是，他有颗善良的心。"] = "Самое главное, у него доброе сердце.",
    ["最重要的是，你说过你们在和弗萨克军队作战？"] = "Самое главное, вы сказали, что сражаетесь с армией Фейсака?",
    ["月见草在夜露滋润下。"] = "Лунные цветы, питаемые ночной росой.",
    ["月见草在夜露滋润下，绽开了优雅纤弱的花。"] = "Питаемый ночной росой, лунный цветок расцветает элегантным и нежным цветком.",
    ["有。但大都市太大，人和人隔得太远，每个人都戴着面具说话。"] = "Есть. Но мегаполис слишком велик, люди слишком далеко друг от друга, и все говорят в масках.",
    ["有一个使命锁住我。"] = "Есть миссия, которая меня связывает.",
    ["有一些观众在无尽的观察中，迷失了自己的席位，遗忘了自我，也失去了见证者的资格。"] = "Некоторые Зрители теряют свое место в бесконечном наблюдении, забываются и теряют свою квалификацию свидетеля.",
    ["有一位玛格丽特小姐，频繁来诊所，每周两三次。"] = "В клинику часто приходит мисс Маргарет, два или три раза в неделю.",
    ["有一天，她们缠着我占卜未来。"] = "Однажды они приставали ко мне, пытаясь предугадать их будущее.",
    ["有一次我培育的藤蔓长得太快了，差点把整艘船都缠住了。还有一次，那些小家伙们开始自己繁殖，在船里到处跑……"] = "Однажды лозы, которые я выращивал, росли слишком быстро и почти опоясали весь корабль. В другой раз эти малыши начали размножаться самостоятельно и бегать по кораблю...",
    ["有一段时间是您一个人养家，很辛苦吧？"] = "Было время, когда вы в одиночку кормили семью — тяжело пришлось, да?",
    ["有不好的预感，还是算了。"] = "У меня плохое предчувствие по этому поводу, лучше не надо.",
    ["有些隐患，必须在酿成大祸之前看清。"] = "Некоторые скрытые опасности необходимо выявить, прежде чем они превратятся в катастрофу.",
    ["有人引发男爵的精神异常，扭曲了医生的意志，让忠诚的管家成为本案的凶手，又利用男爵的声音，伪造死亡时间，让每个人都变得可疑。"] = "Кто-то спровоцировал психическое отклонение Барона, исказил волю доктора, сделал в данном случае убийцей верного дворецкого и использовал голос Барона, чтобы инсценировать время смерти, вызвав у всех подозрения.",
    ["有什么好气的，你什么样我早习惯了。"] = "Чего тут злиться? Я уже давно привык к тому, какой ты.",
    ["有时候你能让亡灵安息，却留不住鲜活的生命。我看着太多死亡，太多灵魂消散……最后连很多曾经的队友也都变成了我需要通灵的对象。"] = "Иногда можно дать духам отдохнуть, но продолжать жить не получится. Я видел слишком много смертей, слишком много рассеивающихся душ... В конце концов, даже многие из моих бывших товарищей по команде стали объектами, над которыми мне нужно было применить Духовный Медиумизм.",
    ["有时候她什么都不说，只是看着我微笑。我就能读懂。"] = "Иногда она ничего не говорит, просто смотрит на меня и улыбается. Я могу понять.",
    ["有时候她会笑一下，摸摸我的头，说“谢谢你，苏茜”。"] = "Иногда она улыбается, гладит меня по голове и говорит: «Спасибо, Сьюзи».",
    ["有时候我会想，如果没有他的指导，我可能早就在某次非凡事件中失控或者死亡了。"] = "Иногда я думаю, что если бы не его руководство, я бы давно потерял контроль или погиб в каком-нибудь Чрезвычайном происшествии.",
    ["有时候我会趴在她脚边，把脑袋搁在她膝盖上，询问她：“奥黛丽，你今天呼吸的节奏不对，你是不是累了？”"] = "Иногда я лежу у ее ног, кладу голову ей на колени и спрашиваю ее: «Одри, у тебя сегодня неправильный ритм дыхания. Ты устала?»",
    ["有时候深夜醒来，我会想起那里的一切：早餐店的豆浆油条，地铁里埋头看手机的人群，加班后深夜回家的路……"] = "Иногда, когда я просыпаюсь поздно ночью, я думаю обо всем: о соевом молоке и жареных палочках из теста в магазине для завтраков, о людях, уткнувшихся в свои телефоны в метро, ​​о дороге домой поздно вечером после сверхурочной работы...",
    ["有时候觉得加入黑荆棘就像是昨天的事，一转眼已经这么多年了……"] = "Порой кажется, будто я только вчера переступил порог «Черного Терновника», а ведь пролетело уже столько лет...",
    ["有时候，我们需要用另一种方式说出我们看到的东西。"] = "Иногда нам нужно выразить то, что мы видим, по-другому.",
    ["有段时间不见了，{{PlayerName}}。"] = "Прошло много времени, {{PlayerName}}.",
    ["有潜力的新人，很关心同伴。"] = "Многообещающий новичок, заботится о товарищах.",
    ["有的能让你变成泡沫，操控自己的梦，有的还可以让花——"] = "Некоторые могут превращать вас в пузыри, управлять вашими мечтами, а другие даже делать цветы…",
    ["有过几次。"] = "Несколько раз.",
    ["有这么严重吗？"] = "Это настолько серьёзно?",
    ["有那么一点，毕竟年轻的时候，大家都认为自己是特殊的。"] = "Немного. Ведь когда мы молоды, каждый думает, что он особенный.",
    ["朋友？那姑娘简直是上天派来折磨我的。"] = "Друг? Эту девушку послали небеса, чтобы мучить меня.",
    ["服食魔药后，你会开始灵界遨游，乃至迷失方向。如果没有坐标，你将被困在灵界深处，失去理智。"] = "After consuming a potion, you will begin to roam the Spirit World, and may even become Lost. Without coordinates, you will be trapped in the depths of the Spirit World and lose your sanity.",
    ["本应该是我把你推下去，但我不想害人……麻烦了。"] = "Это я должен был тебя толкнуть, но я не хочу никому причинять вред... это хлопотно.",
    ["本想故作低调，呵——算了，这是穿越者都想做的事吧？再说这里的基础设施真的很落后。"] = "Я хотел вести себя сдержанно, хех – забудь об этом, ведь этого хочет каждый переселенец, верно? К тому же инфраструктура здесь действительно отсталая.",
    ["本案目前有三点矛盾无法解释。"] = "В этом деле на данный момент имеются три необъяснимых противоречия.",
    ["来，牵着我的手，我带你去我的城堡。"] = "Давай, возьми меня за руку, и я отведу тебя в свой замок.",
    ["来，这样，我来教你怎样战斗吧！"] = "Давай вот так, позволь мне научить тебя драться!",
    ["果然……是不能说的词……"] = "Как и ожидалось... это слово, которое невозможно произнести...",
    ["枝叶排成柔软台阶，让我走向水底长眠……"] = "Ветви и листья образуют мягкие шаги, позволяя мне идти навстречу долгому сну под водой...",
    ["柠檬布丁来了，先吃点甜食换换脑子吧？"] = "Лимонный пудинг уже готов, почему бы сначала не съесть немного сладостей, чтобы прочистить голову?",
    ["查拉图这个混蛋，博诺瓦刚出生的时候，他来庆贺，说博诺瓦是“可爱的天使”。"] = "Этот ублюдок Заратул, когда Бонова только родилась, он пришел поздравить и сказал, что Бонова «милый ангел».",
    ["查看剧本"] = "Осмотреть сценарий",
    ["根据剧本的提示，扮演鬼的角色应该是<P_Yellow>穿长裙的少女</>，在剧本上记录一下吧。"] = "По подсказкам в сценарии, роль призрака должна сыграть <P_Yellow> — девушка в длинном платье </>; запишите это в сценарий.",
    ["根据历史记载来看，确实……一言难尽。"] = "Согласно историческим данным, действительно... это было невыразимо.",
    ["根本赶不上——旧的物种在消失，新的物种在进化。我的笔记，永远追不上生命本身的速度。"] = "Никак не поспеть... Старые виды исчезают, новые виды эволюционируют. Мои записи никогда не угонятся за скоростью самой жизни.",
    ["格尔曼·斯帕罗曾经听我唱过一次，他当时的表情……<P_Heart>（摇头）</>我至今难忘。"] = "Герман Спэрроу однажды слышал, как я пою, и выражение его лица... <P_Heart>(качает головой)</> я до сих пор не могу забыть.",
    ["格尔曼小猫，达尼兹小狗，正是本人的杰作。啊毛绒！优雅的毛绒！毛绒即为艺术！"] = "Котенок Герман и щенок Даниц — это мои личные шедевры. О, плюш! Благородный плюш! Плюш — это истинное искусство!",
    ["案发现场与证词的矛盾该如何解释？"] = "Как объяснить противоречие между местом преступления и показаниями?",
    ["档案里说“看见我”是一块透明水晶。但现在，它——不是水晶形状了！"] = "В файлах написано, что \"See Me\" - это кусок прозрачного кристалла. Но теперь оно… оно больше не имеет формы кристалла!",
    ["梅丽莎为了自己的爱好，投入很多时间和精力，将来一定能成为机械师或者工程师……"] = "Мелисса отдает своему увлечению столько сил и времени... Она непременно станет механиком или инженером в будущем...",
    ["梅丽莎总是摆弄她的齿轮和发条，那些零件散落得到处都是，我走路时经常踩到。"] = "Мелисса постоянно возилась со своими шестернями и пружинами; эти части были разбросаны повсюду, и я часто наступал на них, идя.",
    ["梅丽莎，能说说你哥哥班森吗？"] = "Мелисса, можешь рассказать мне о своем брате Бенсоне?",
    ["梦境与现实交织太深，有时候会有些混乱。"] = "Сон и явь переплелись слишком тесно, порой в них не мудрено запутаться.",
    ["梦里？"] = "Во сне?",
    ["植物世界的最后一页。"] = "Последняя страница растительного мира.",
    ["模仿拙劣到令人作呕。根本不是血族会做的事。 "] = "Имитация отвратительно неуклюжа. Сангвиник вообще не стал бы этого делать.",
    ["模仿？"] = "Имитация?",
    ["模拟扮演·占卜家"] = "Имитация актерского мастерства · Провидец",
    ["模拟扮演·祈光人"] = "Имитация актерского мастерства: Люмиан",
    ["模拟扮演·观众"] = "Имитация отыгрыша: Зритель",
    ["欢迎光临黑伍德庄园，{{PlayerName}}{{先生|女士}}。请进，舞会即将开始。"] = "Добро пожаловать в поместье Хейвуд, {{PlayerName}}{{Mr.|Ms.}}. Пожалуйста, входите, бал вот-вот начнется.",
    ["欢迎来到午夜茶会，这次似乎有一些新面孔。"] = "Добро пожаловать на Полуночное чаепитие. Кажется, на этот раз среди нас появились новые лица.",
    ["欢迎来到神许诺的光明世界！"] = "Добро пожаловать в мир света, обещанный Богом!",
    ["欧洛斯，你捉迷藏的本领和小时候一样出色。"] = "Орос, твои навыки игры в прятки так же превосходны, как и в детстве.",
    ["欧洛斯，这是她的胸针。"] = "Орос, это ее брошь.",
    ["欸？"] = "Э?",
    ["欸？那是怎么消化的魔药……"] = "Э? Как зелье таким образом переваривается...",
    ["正位宝剑十。一个人俯卧在地，十把剑钉在背上。"] = "Десятка Мечей в вертикальном положении. Человек, лежащий лицом вниз на земле с десятью мечами, воткнутыми в спину.",
    ["正午的阳光洒满宁静的公园，驱散了所有的阴霾。"] = "Полуденное солнце светит над тихим парком, разгоняя всю унылость.",
    ["此外……也许您还能在这里遇见一些朋友。"] = "Кроме того... возможно, ты даже встретишь здесь друзей.",
    ["死寂的主干道（占位）"] = "Мёртвая главная улица (плейсхолдер)",
    ["死灵导师的工作，就是和亡者沟通。不仅是招魂问卜，还要聆听他们在灵界的回响，送他们彻底安息。"] = "Работа наставника некромантии — общаться с мертвыми. Речь идет не только о вызове душ и гадании, но и о прослушивании их отголосков в Мире Духов и отправке их на полный покой.",
    ["死神陨落后，各地的反抗浪潮接连而起，帝国就此瓦解。 如今的东西拜朗，并不能算是我的祖国。"] = "После падения Смерти повсюду поднялись волны сопротивления, и империя рухнула. Сегодняшние Восточный и Западный Балам нельзя назвать моей родиной.",
    ["残余的强者汇聚在一起，依靠团结起来的力量和两件神奇的物品，抵御住了怪物们的进攻，建立起庇佑着人类文明最后火光的城邦——白银城。"] = "Уцелевшие силачи собрались вместе и, объединив усилия и силу двух магических предметов, отразили натиск монстров и возвели полис, защищающий последнюю искру человеческой цивилизации — Город Серебра.",
    ["残忍的开膛手"] = "Жестокий Потрошитель",
    ["母亲，我们在迪西过的很好，孩子们很听话，您不用挂念。希望您在女神的怀抱里得到安宁。"] = "Мама, у нас в Дичи все очень хорошо, и дети очень послушные; вам не нужно беспокоиться. Надеюсь, ты обретешь покой в ​​объятиях Богини.",
    ["母亲，我带着珊迪和孩子们来看您了。"] = "Мама, я привел Сэнди и детей повидаться с тобой.",
    ["每一次出海，都可能遇到意想不到的事情。风暴、海盗、怪物……甚至是更古老的存在。"] = "Каждый раз, отправляясь в море, вы можете столкнуться с неожиданными вещами. Штормы, пираты, монстры... или даже более древние существа.",
    ["每一行的数据都已经划去，多半早已钱货两清了。\n<P_Yellow>（获得了线索并放入背包：陈旧的销售记录）</>"] = "Каждая строка данных была перечеркнута; кажется, оплата и товары были оплачены давно.\n<P_Yellow>(Подсказка получена и добавлена ​​в рюкзак: Старая запись о продажах)</>",
    ["每个人都有自己的秘密，但在这个聚会上，我们可以交换情报、交易材料，甚至得到他的指点。"] = "У каждого есть свои секреты, но на этом собрании мы можем обмениваться разведданными, обмениваться материалами и даже получать его советы.",
    ["每天从早到晚，店里挤满了人，笑声能从这头传到那头。 "] = "Каждый день с утра до вечера магазин был полон людей, и смех был слышен от одного конца до другого.",
    ["每天早上，你会看到市民排队买面包，小孩在街上跑，商人在讨价还价，情侣在河边散步……"] = "Каждое утро вы видите граждан, стоящих в очереди за хлебом, бегущих по улице детей, торговающихся торговцев, прогуливающихся у реки парочек...",
    ["每年都要举行仪式，用活人献祭，分享他的血液和肉块……"] = "Каждый год они проводили ритуал, принося в жертву живых людей и делясь их кровью и плотью...",
    ["每当太阳在西方下沉，露珠……"] = "Когда солнце садится на западе, роса...",
    ["每当遇到不懂的非凡知识，或者危险的情况，我都会写信向他请教或是求助。"] = "Всякий раз, когда я сталкиваюсь с непонятными мне знаниями Потусторонний или опасными ситуациями, я пишу ему за советом или помощью.",
    ["每次看到像您这样的人出现，我都觉得……嗯，这里还没那么糟。我也想成为这样的人。"] = "Каждый раз, когда я вижу таких людей, как вы, мне кажется... ну, что здесь еще не все потеряно. Я тоже хочу стать таким человеком.",
    ["每逢满月，我会听到呓语。不是幻听，是直接在我脑子里响起的声音，说着听不懂的语言……伴随着疯狂和失控的边缘。"] = "Каждое полнолуние я слышу шепот. Не слуховые галлюцинации, а голоса, звучащие прямо в моем мозгу, говорящие на языке, которого я не понимаю... сопровождаемые грани безумия и потери контроля.",
    ["比你挖空脑袋想不出一句新诗好多了！我在说正经的！"] = "Это гораздо лучше, чем ломать голову и не придумать нового стихотворения! Я говорю серьёзно!",
    ["比如……深夜会自己转动的雕像？或者继承了远方的神秘遗产？我新书正好缺个灵感。"] = "Например... статуи, которые двигаются сами по себе в полночь? Или унаследовать таинственное наследие издалека? Моей новой книге просто не хватает вдохновения.",
    ["比如他突然半夜出去跑步锻炼，比如他放弃了准备很久的廷根大学讲师面试，找了份收入不错的工作……他应该是想让我们过得更好些吧。"] = "Например, он вдруг посреди ночи выходил на пробежку или отказывался от долго готовившегося собеседования с лектором Тингенского университета, чтобы найти хорошо оплачиваемую работу... Должно быть, он хотел, чтобы мы жили лучше.",
    ["比如安装煤气灯那次……我先说服房东出钱改造管道，说这样能提高房屋档次，提高租金。"] = "Например, когда устанавливали газовые фонари... Сначала я убедил домовладельца оплатить замену труб, сказав, что это повысит класс жилья и позволит поднять аренду.",
    ["比如海纳斯·凡森特先生，当年找他占卜的人得从廷根排到贝克兰德！"] = "Например, г-н Хейнс Винсент; тогда люди, выстроившиеся в очередь, чтобы попросить его о гадании, могли простираться от Тингена до Баклунда!",
    ["比如说，解读出命运的轨迹，一字不漏地告诉来占卜的客人？可我感觉占卜命运这种事情，本就玄之又玄。"] = "For example, interpreting the trajectory of fate and telling the client who came for divination every single word? But I feel that things like divining fate are inherently mysterious and profound.",
    ["比如这个。"] = "Как этот.",
    ["比如这样，“窗外盛开的紫藤，像一串串风干的葡萄，半夜值班想起时，总觉得很饿。”"] = "Например, так: «Глициния цветет за окном, как гроздья засохшего винограда; когда я думаю об этом, находясь на дежурстве в полночь, я всегда чувствую себя очень голодным».",
    ["比如那种会让接触者产生幻觉的蘑菇，我只是想用它来治疗失眠！"] = "Например, тот гриб, который вызывает галлюцинации у тех, кто к нему прикасается, — мне как раз хотелось им лечить бессонницу!",
    ["比如那种能让伤口快速愈合的蘑菇，还有能净化水源的海藻——这些都是有用的东西！"] = "Например, тот гриб, который быстро заживляет раны, и морская капуста, способная очищать воду – это все полезные вещи!",
    ["比如陪在奥黛丽身边，比如守护她珍视的一切，比如在这个世界里，保持一颗简单的心。"] = "Например, оставаться рядом с Одри, охранять все, что ей дорого, и сохранять простое сердце в этом мире.",
    ["比如，你现在看不到苏茜，但她确实趴在你的脚边享受午睡时光。"] = "К примеру, прямо сейчас ты не видишь Сьюзи, но она и впрямь лежит у твоих ног, сладко задремав.",
    ["比如，将人强行拉入梦境，看透对方的内心。"] = "Например, насильно затягивать людей во сне и видеть сквозь их внутренние сердца.",
    ["比打打杀杀适合我。"] = "Это меня устраивает больше, чем драться и убивать.",
    ["比清醒状态下更容易发现线索而已。这能力……有利有弊。"] = "Просто найти подсказки легче, чем в бодрствующем состоянии. Эта способность... имеет свои плюсы и минусы.",
    ["比起满足要求，她更需要能理解她的人陪在身边。"] = "Вместо того, чтобы соответствовать требованиям, ей нужен кто-то, кто ее понимает, чтобы быть рядом с ней.",
    ["毕业后你想做什么？"] = "Чем ты хочешь заниматься после окончания учебы?",
    ["毕竟一条金毛犬对你摇尾巴的时候，谁能真的生气呢？"] = "В конце концов, когда золотистый ретривер виляет вам хвостом, кто действительно может злиться?",
    ["毕竟已经冷透了，不是么？"] = "Ведь им уже холодно, не так ли?",
    ["毕竟晋升不是小事，非凡道路上总是与疯狂相伴，我担心你一个人会应付不来。"] = "В конце концов, продвижение – это немаловажное дело; Путь Потустороннего всегда сопровождается безумием, и я боюсь, что ты не сможешь справиться с этим в одиночку.",
    ["毕竟，失控的仪式在现实中可能造成难以预料的后果。"] = "Ведь ритуал, приводящий к потере контроля, в реальности может иметь непредсказуемые последствия.",
    ["毕竟，对历史系来说，亲身经历者的访谈并不多见……呵呵，一个玩笑。"] = "Ведь на истфаке нередки интервью с человеком, который испытал это на собственном опыте... Хаха, шутка.",
    ["毕竟，我只是一条狗。而这，恰恰是我最擅长的事。"] = "В конце концов, я всего лишь собака. И это именно то, в чем я умею лучше всего.",
    ["气什么？见到您健康地活着，比什么都好啊！"] = "Why would I be angry? Seeing you alive and healthy is better than anything else!",
