    ["然后啊……就看着它们，看阳光照在羊毛上，变成金色的。"] = "А потом... просто наблюдайте за ними, наблюдайте, как солнечный свет сияет на шерсти, превращая ее в золотистую.",
    ["然后我利用在进出口公司的关系，以成本价拿到了灯具。"] = "Затем я воспользовался своими связями в импортно-экспортной компании, чтобы получить лампы по себестоимости.",
    ["然后我发现，只要我握住那串手链，就能穿墙而过，能打开锁住的门……我以为是好运，是命运的馈赠。"] = "Потом я обнаружил, что пока я держу этот браслет, я могу проходить сквозь стены и открывать запертые двери... Я подумал, что это удача, подарок судьбы.",
    ["然后我就明白了。我走出去，趴在门口，竖起耳朵。"] = "И тогда я все понял. Я вышел, припал к двери и навострил уши.",
    ["然后等他走过去了，我再悄悄溜走。"] = "А потом, после того как он проходил мимо, я тихонько ускользала.",
    ["然而突然现身的开膛手却打破了这美好的一刻……"] = "Однако внезапное появление Потрошителя прервало этот прекрасный момент...",
    ["然而见证之环的展示容量有限，每周符合标准的名字将在此交替显现。"] = "Однако возможности отображения Кольца Свидетелей ограничены, и имена, соответствующие критериям, каждую неделю будут появляться здесь поочередно.",
    ["熟悉的俱乐部"] = "Знакомый клуб",
    ["父亲……他是一名底层军官，为了追逐权势和财富前往了东拜朗，并且组建了新的家庭。"] = "Отец... он был офицером низшего звена, который отправился в Восточный Балам в поисках власти и богатства и создал новую семью.",
    ["父母去世后，她一度很沉默。我以为她会哭，会闹，但她只是把自己关在房间里，摆弄那些机械。"] = "После смерти наших родителей она какое-то время молчала. Я думал, она заплачет или устроит истерику, но она просто заперлась в своей комнате и возилась с этими машинами.",
    ["牌是这个意思。但……法律不允许人和猫结婚。"] = "Вот что означает карта. Но... закон не позволяет людям и кошкам вступать в брак.",
    ["牌还是那张牌。但怎么告诉别人——那才是占卜师真正的技艺。"] = "Карта остается все той же картой. Но вот как истолковать ее другим — в этом и кроется истинное мастерство прорицателя.",
    ["物理意义上的无光环境很容易制造，而“纯粹”的黑暗意味着黑暗中不掺杂任何其它力量，这需要通过黑夜途径的权柄实现。"] = "A lightless environment in the physical sense is easy to create, but \"pure\" Darkness means that there are no other powers mixed into the darkness, which requires the authority of the Darkness Pathway to achieve.",
    ["牵手"] = "Держитесь за руки",
    ["特别是当我意识到，有时即使不求回报，他也愿意分享那些珍贵的信息时。"] = "Особенно когда я понял, что иногда, даже не прося ничего взамен, он готов поделиться этой драгоценной информацией.",
    ["特殊的茶……用灵视找找看吧。"] = "Особенный чай... попробуем найти его духовным зрением.",
    ["犯人肖像……尸体报告……罗珊打盹……洛耀打牌……"] = "Портреты преступников... отчеты о вскрытиях... Дремлющая Розанна... Ло Яо играет в карты...",
    ["犯错的人，失控的人，邪教徒……统统一视同仁，用雷霆和闪电解除威胁。"] = "С теми, кто совершает преступления, с теми, кто теряет контроль, сектантами... со всеми обращаются одинаково, используя гром и молнию для устранения угроз.",
    ["犹豫"] = "Сомневаться",
    ["狩猎？不，我只是在驱赶它。乌鸦是群体生活的食腐动物，遇上这种落单的往往不是好兆头。"] = "Охота? Нет, я просто увожу его. Вороны — социальные падальщики; Встреча с таким одиноким обычно не является хорошим знаком.",
    ["猎人的反应"] = "Реакция Хантера",
    ["猩红的月光照耀在血泊上，见证了这场血腥的犯罪。"] = "Багровый лунный свет освещал лужу крови, становясь свидетелем этого кровавого преступления.",
    ["猩红遗物，那些红色的碎片。我杀死那些召唤出来的超凡生物，辛辛苦苦地收集。"] = "Scarlet Relics, those red fragments. I killed those summoned Beyonder creatures and collected them with great difficulty.",
    ["玛、玛格丽特小姐，您今天哪里不舒服？"] = "М-мисс Маргарет, в чём сегодня проблема?",
    ["玛丽奶奶……"] = "Grandma Mary...",
    ["玛丽奶奶其实很想回去看看，却因为指南针的负面效果耽误到现在，我得帮帮她。"] = "Grandma Mary actually really wants to go back and take a look, but she has been delayed until now because of the compass's negative effects. I have to help her.",
    ["玛丽奶奶又能做出好吃的炸鸡了，谢谢你，侠盗！"] = "Grandma Mary can make delicious fried chicken again. Thank you, Bandit!",
    ["玛丽安觉得你对它的爱太奇怪了，它需要的不只是你的爱，还有它自己的空间。"] = "Мэриан считает вашу любовь слишком странной; ему нужна не только ваша любовь, но и собственное пространство.",
    ["玛格丽特小姐，您好像经常来这家诊所，身体还好吗？"] = "Мисс Маргарет, кажется, вы довольно часто посещаете эту клинику. Ваше здоровье в порядке?",
    ["环绕的光辉，像一圈缓慢流转的星河。它会将最耀眼的名字铭刻于上。因此，人们称它为「见证之环」。"] = "Окружающее сияние похоже на медленно текущую галактику. На нем будут выгравированы самые ослепительные имена. Поэтому люди называют его «Кольцо свидетеля».",
    ["现在仪式都结束了，你成功获得了想要之物，我也该离开了。"] = "Теперь, когда ритуал окончен и вы успешно получили то, что хотели, мне тоже пора уйти.",
    ["现在她总说托马斯还在，就在她旁边坐着。有时还给空座位倒酒，说托马斯爱喝这口……"] = "Теперь она всегда говорит, что Томас все еще здесь, сидит рядом с ней. Иногда она даже наливает напиток на пустое место, говоря, что Томас любит эту штуку...",
    ["现在好多了！蒂尔达一定会喜欢的。嘿嘿。"] = "Теперь намного лучше! Тильде точно понравится. Хе-хе.",
    ["现在实验结束，我把这个意识还给他们了。"] = "Теперь, когда эксперимент окончен, я вернул им это сознание.",
    ["现在的学生，真没规矩。"] = "У современных студентов действительно нет манер.",
    ["现在这个世道，穷人都活得不长久。"] = "В наше время бедняки долго не живут.",
    ["现在这样足够了。"] = "Этого пока достаточно.",
    ["现在，你前往仪式台布置一下仪式魔法吧。"] = "Теперь идите к ритуальному алтарю и настройте Ритуальную Магию.",
    ["现在，它是你的了，“愚者”先生亲自为这件服饰赋予了神降的奇迹，好好珍藏它。"] = "Теперь оно ваше. Господин Шут лично даровал этому одеянию чудо божественного происхождения. Берегите это хорошо.",
    ["现在，政客们握手言和，一切恢复如常。可那些为此去世的人呢？"] = "Теперь политики пожали друг другу руки и заключили мир, и все вернулось на круги своя. А как насчет тех, кто погиб за это?",
    ["班森先生，听说您很擅长……砍价？"] = "Мистер Бенсон, я слышал, вы весьма искусны в... торговле?",
    ["班森先生，您好像经常提起弗兰奇先生？"] = "Мистер Бенсон, вы, кажется, часто упоминаете мистера Фрэнка?",
    ["班森先生，莫雷蒂家平时是什么样的？"] = "Мистер Бенсон, а как обычно живут в семье Моретти?",
    ["班森？他以前在一家进出口公司工作，周薪1镑10苏勒。"] = "Бенсон? Раньше он работал в компании по импорту и экспорту с еженедельной зарплатой в 1 фунт и 10 шиллингов.",
    ["班西港位于苏尼亚海深处，名义上属于风暴之主教会的辖区，实际上却藏着很多秘密。"] = "Гавань Банси расположена глубоко в море Сония. Номинально он находится под юрисдикцией Церкви Повелителя Бурь, но на самом деле скрывает множество тайн.",
    ["理查德、路易斯、卡伍德，我抛下了他们，自己逃了回来。"] = "Richard, Louis, and Cawood—I abandoned them and escaped back alone.",
    ["瓦莱莉……"] = "Валери...",
    ["甚至还看见了我。"] = "Ты даже видел меня.",
    ["生命之脉，“月亮”先生从血族内部兑换的魔药培育装置，由一位古代炼金师用生命之石制成。"] = "Пульс Жизни, устройство для выращивания зелий, которое мистер Мун обменял из клана Вампиров, было создано древним алхимиком с использованием Камня Жизни.",
    ["生命在于运动。我把琐事交给了专门的人去做，余下的时间都可以自由进行锻炼。"] = "Жизнь — в движении. Всю рутину я препоручил специально нанятым людям, а все остальное время могу свободно посвящать тренировкам.",
    ["用“神降”仪式向“愚者”祈求好运，然后用灵界生物召唤仪式。主材料是这张神之契约，再加上副材料灵界星尘。"] = "Use a \"divine descent\" ritual to pray to \"The Fool\" for good luck, then perform a Spirit World creature Summon ritual. The main ingredient is this divine contract, plus the secondary ingredient, Spirit World stardust.",
    ["用学校不要的材料和路上捡到的东西拼凑的。齿轮、锈铁、弹簧、发条……"] = "Я собрал его вместе с материалами, которые не нужны школе, и вещами, которые я подобрал в дороге. Шестеренки, ржавое железо, пружины, часовой механизм...",
    ["用心灵引导他自己发现"] = "Использовать Психическое Направление, чтобы он догадался сам",
    ["用我微弱的生命，换取见证真理的机会，实在是一件恩赐。"] = "Использовать свою скудную жизнь в обмен на шанс свидетельствовать правду — это действительно подарок.",
    ["用眼睛看着身边的我，而不是那本书。"] = "Чтобы смотреть на меня рядом с ним своими глазами, а не на эту книгу.",
    ["男爵在看那个角落。那里有什么？"] = "Барон смотрит в тот угол. Что там такое?",
    ["男爵夫人离开后，有一个人进入房间，给男爵续了茶。这个人，恐怕就是制造密室的凶手。"] = "После того, как баронесса ушла, кто-то вошел в комнату и снова налил барону чай. Этот человек, скорее всего, является убийцей, создавшим сценарий с запертой комнатой.",
    ["男爵宣布捐赠土地。宾客们说威廉最近行为异常。"] = "Барон объявил о пожертвовании земли. Гости шепчутся, что Уильям в последнее время вел себя странно.",
    ["男爵的表情太平静了。被刺杀的人，哪怕再有修养也该有惊讶和愤怒。"] = "Выражение лица барона слишком невозмутимо. Жертва покушения, сколь бы благородно она ни была воспитана, должна испытывать хотя бы удивление и гнев.",
    ["男爵的表现有些僵硬……不是紧张，像在“表演”。"] = "Игра Барона немного натянутая... не нервная, как будто он \"играет\".",
    ["男爵阁下，您早就知道我是教会的人？也早知道阿尔伯特带着封印物？"] = "Барон, вы все это время знали, что я из Церкви? И что у Альберта был Запечатанный Артефакт?",
    ["留住这些看起来简单的事，就是意义。"] = "Сохранение этих, казалось бы, простых вещей и есть смысл.",
    ["痛苦吗？绝望吗？"] = "Это больно? Это отчаяние?",
    ["白昼般的夜晚"] = "Ночь, светлая как день",
    ["白昼般的夜晚（占位）"] = "Ночь, подобная дню (заглушка)",
    ["的确。但对我而言，有了他的帮助，我才能发现真相，摆脱失去人性的命运。"] = "Верно. Но что до меня, лишь с его помощью я смог узнать правду и избежать участи потерять человечность.",
    ["的确，抛开研究带来的亲切与满足感，历史系的学生和同事都有一种特有的气质，和他们交谈，是一件令人愉快的事。"] = "Действительно, если оставить в стороне близость и удовлетворение, приносимые исследованиями, все студенты и коллеги исторического факультета обладали уникальным темпераментом. Общение с ними было приятным занятием.",
    ["皎洁的深夜"] = "Яркая поздняя ночь",
    ["直到……"] = "До...",
    ["直到我也成为故事的一部分。"] = "Пока я тоже не стану частью этой истории.",
    ["直到我念出了那个尊名——“愚者”先生的尊名。"] = "Пока я не зачитал это почетное имя – почетное имя господина «Шута».",
    ["直到我被富人的保镖抓住，逃走后，他们发布了通缉令，为了不连累家人，我连夜离开了贝克兰德。"] = "Until I was caught by a rich man's bodyguard. After I escaped, they issued a wanted warrant. To avoid implicating my family, I left Backlund overnight.",
    ["直到有人问出了那个问题：“真理的尽头是什么？”"] = "Пока кто-то не задал тот самый вопрос: «Что лежит на краю истины?»",
    ["直到被卷入一场非凡事件。"] = "Пока я не был втянут в инцидент с Потусторонний.",
    ["直接告诉威廉男爵"] = "Скажите барону Уильяму напрямую",
    ["相亲？等等，我父亲到底留下了什么信！这次必须给我看看！"] = "Свидание вслепую? Подожди, что за письмо оставил после себя мой отец! На этот раз я должен это увидеть!",
    ["相信您的工坊一定能产出更多的优质物产，并在市场上一路畅销。"] = "Я верю, что ваша мастерская обязательно будет производить больше качественной продукции и станет бестселлером на рынке.",
    ["相信接下来就算没有我的提醒，你也一样行呢……祝你好运……"] = "Я верю, что даже без моего напоминания у тебя все получится... Удачи...",
    ["看"] = "Смотреть",
    ["看上去有些年头了。"] = "Выглядит довольно старым.",
    ["看上去有些年头了，写信的人是……阿德莱德？"] = "Кажется, прошло несколько лет. Человек, написавший письмо... Аделаида?",
    ["看不出来啊……"] = "Я не могу сказать...",
    ["看什么看！没礼貌，再看我找猫弄你！"] = "Что ты смотришь! Как грубо, продолжайте искать, и я заставлю кота с вами разобраться!",
    ["看什么？一群书呆子。"] = "На что ты смотришь? Куча книжных червей.",
    ["看啊，朋友！这就是我们的精神面貌。欢迎你持续关注赛艇俱乐部，我们会在今年的比赛中战胜廷根大学的队伍！"] = "Смотри, друг! Это наш дух. Вы можете продолжать следить за гребным клубом; мы победим команду Университета Тинген в соревновании этого года!",
    ["看在你人不错的份上，我带你过去吧！好好跟上我灵巧的身姿。"] = "Раз уж ты неплохой парень, так и быть, проведу тебя! Не отставай от моей грациозной походки.",
    ["看在你敢于挑战的份上，奖励保留，但难度不会降低，怎么样？"] = "Поскольку у вас хватит смелости бросить вызов, награда сохранится, но сложность не понизится. Как насчет этого?",
    ["看来你已经尝到了它的苦头，所以才说它是诅咒。"] = "Кажется, ты уже вкусил ее горечи, поэтому и называешь ее проклятием.",
    ["看来她这次还是回不来。你不想见她吗？"] = "Похоже, она и на этот раз не сможет вернуться. Разве ты не хочешь ее увидеть?",
    ["看来您说的是真的。呵呵，我们雪山的猎人，直觉一向准得可怕。"] = "Кажется, то, что вы сказали, правда. Хе-хе, интуиция нас, охотников на заснеженной горе, всегда была пугающе точной.",
    ["看来这间屋子的前主人有一个重要的执念。“它”……究竟是什么？\n<P_Yellow>（获得了线索：黑板上的字迹）</>"] = "Кажется, у предыдущего владельца этой комнаты была важная навязчивая идея. Что... именно «это»? \n<P_Yellow> (Подсказка: почерк на доске) </>",
    ["看来，小镇留下了我的很多画像……"] = "Кажется, этот маленький город оставил после себя много моих портретов...",
    ["看来，您并不怎么欣赏鲁恩贵族的行事风格？"] = "Кажется, ты не ценишь стиль дворян Лоэна?",
    ["看来，我的推论是正确的……这位“工匠”奥斯瓦尔德，将所有的心血都灌注在这座机械小屋上。为了让它获得生命不惜一切。"] = "Похоже, мой вывод верен... Этот «Ремесленник» Освальд вложил всю душу в эту механическую хижину. Он не пожалел ничего, чтобы вдохнуть в нее жизнь.",
    ["看起来好精致，怎么做的？"] = "Выглядит так изысканно, как ты это сделал?",
    ["看起来我们有了一位挑战者，能辛苦你当裁判吗，向导？"] = "Похоже, у нас есть претендент. Не могли бы вы потрудиться стать судьей, Гид?",
    ["看起来还行，但人总会在相亲时有意无意地伪装自己，得再观察下！"] = "Кажется, с ним все в порядке, но люди всегда намеренно или непреднамеренно маскируются на свиданиях вслепую. Мне нужно больше наблюдать!",
    ["看这个烛台，是从古堡里流传出来的。"] = "Посмотрите на этот подсвечник, его передали из замка.",
    ["看那边。"] = "Посмотри туда.",
    ["看，封印解除了。你做得非常出色，第一次尝试就如此成功，你的灵性感知力和控制力都很优秀。"] = "Смотри, печать сломана. Вы проделали отличную работу. Такой успех с первой попытки показывает, что ваше духовное восприятие и контроль превосходны.",
    ["看，那就是需要共鸣的封印！每一段快乐陪伴，都会留下情绪回响，而我最擅长倾听它们！"] = "Смотри, это печать, требующая резонанса! Каждый момент счастливого общения оставляет после себя эмоциональное эхо, и я лучше всех его слушаю!",
    ["真厉害啊，听上去你对自己的未来很有规划。"] = "Это потрясающе, похоже, у тебя очень хороший план на будущее.",
    ["真是厉害，看来还得善于观察才行。"] = "Действительно удивительно, кажется, надо еще и хорошо наблюдать.",
    ["真是热闹的舞会……先观察，看看有什么异常。"] = "Это действительно оживленная танцевальная вечеринка... Сначала понаблюдайте, нет ли чего-нибудь необычного.",
    ["真是聪明的小灵鼠。可惜主人到底是一回到家就在客厅踩中杀人秘术，还是在起居室被恶灵重伤，逃向厨房时踩中秘术而亡的呢——已经无从知晓了。"] = "Какая умная маленькая мышь-призрак. Жаль, что наступил ли мастер на смертельную мистическую ловушку в тот момент, когда вернулся в гостиную, или был тяжело ранен Злым Духом и умер, наступив на ловушку, убегая на кухню – мы никогда не узнаем.",
    ["真正的守护，就是让光明里的人永远不知道黑暗的存在。"] = "Истинная защита – это позволить людям, находящимся во свете, никогда не узнать о существовании тьмы.",
    ["真爱之吻能让我忘却所有烦恼！"] = "Поцелуй истинной любви заставит меня забыть о любых тревогах!",
    ["真理总在你的生命终点之后。"] = "Истина всегда лежит за пределами вашей жизни.",
    ["真的一点影响都没有吗？"] = "Неужели никакого эффекта вообще нет?",
    ["真的吗？"] = "Правда?",
    ["瞧这货的工艺，真正的复古，真正的贵族审美！"] = "Посмотрите на мастерство этого изделия — настоящее ретро, ​​настоящая аристократическая эстетика!",
    ["知识……是指文献库的那些资料？"] = "Знания... вы имеете в виду материалы в архивах?",
    ["知识是力量"] = "Знание – сила",
    ["知识是力量？你这样想，它就会变成诅咒。"] = "Знание – сила? Если ты так думаешь, это превратится в проклятие.",
    ["知识是诅咒"] = "Знание – это проклятие",
    ["知识，在你的内心，变成了魔鬼吗？"] = "Неужели знание в твоём сердце обратилось дьяволом?",
    ["知道廷根大剧院吗？知道贝肯面包房吗？二者强强联手，推出《大冒险家》系列商品，购买甜点即可收获毛绒赠品！"] = "Вы знаете Большой театр Тинген? Вы знаете пекарню Бэкланд? Они объединили усилия, чтобы запустить серию товаров «Великий авантюрист»; покупайте десерты и получайте плюшевые подарки!",
    ["砍价的核心是信息和谈判，你得大概知道商品的成本价，知道商家的利润空间，知道他的竞争对手是谁，再掌握一些谈判技巧……"] = "Основой переговоров являются информация и переговоры. Надо примерно знать себестоимость товара, знать размер прибыли продавца, знать, кто его конкуренты, а затем владеть некоторыми приемами переговоров...",
    ["研究了一年古弗萨克语的变体，手稿被退回三次。"] = "Я изучал варианты Древнего Фейнапоттера в течение года, и мою рукопись трижды отвергли.",
    ["研究就是我的爱好啊。"] = "Исследования – мое хобби.",
    ["确、确实很不可思议……"] = "Это, действительно, невероятно...",
    ["确定。生命有限，知识无限。用有限换无限，值得。"] = "Точно. Жизнь ограничена, а познание бесконечно. Разменять конечное на бесконечное — благородная сделка.",
    ["确实。"] = "Действительно.",
    ["确实如此。"] = "Это действительно так.",
    ["确实比穷人区好一些。"] = "Это действительно лучше, чем бедный район.",
    ["确实，又垒高了不少，墓碑可能被其他的填土埋掉了。"] = "На самом деле, его накопилось гораздо больше; надгробие могло быть погребено под другим грунтом.",
    ["确认剧本"] = "Подтвердите сценарий",
    ["确认舞台布置"] = "Подтвердить планировку сцены",
    ["祂是主的号角，以救赎为名，为白银城带来了新的食物，带来了外界的消息，带领白银城众人一起走向了迈出“深暗时代”的路。"] = "Он — рог Господа, во имя искупления, приносящий новую пищу в Город Серебра, приносящий новости из внешнего мира и ведущий людей Серебряного Города по пути выхода из «Тёмной Эры».",
    ["祈求？“愚者”先生会帮助我打造它吗？"] = "Помолиться? Поможет ли Господин Шут мне создать его?",
    ["祝你好运，陌生人，祝你猎杀愉快，如果……你还有胆量的话……"] = "Good luck, stranger, and happy hunting, if... you still have the guts...",
    ["祝您好运。"] = "Удачи вам.",
    ["祝您拥有愉快的一天！"] = "Приятного дня!",
    ["神奇的人？"] = "Удивительные люди?",
    ["神灵的伟大远超你我想象。我曾向祂祈求过一件精美的衣饰。然后，祂回应了。那衣饰正如你之前所见。"] = "Величие Божества превосходит любые наши представления. Однажды я взмолился Ему о прекрасном наряде. И Он откликнулся. Этот наряд вы уже видели ранее.",
    ["神秘学是我的兴趣爱好，我可以不收钱。"] = "Оккультизм — мое хобби; Я могу сделать это бесплатно.",
    ["离家很近了，我却依然胆怯，辜负了佛尔思小姐的好意。"] = "I am so close to home, yet I still feel Timidity, failing to live up to Miss Fors's kindness.",
    ["离开"] = "Оставлять",
    ["离开金秋湖"] = "Покинуть озеро Золотой Осени",
    ["离那种地方远点，说不定会发生什么……"] = "Stay away from places like that; who knows what might happen...",
    ["科恩老师在学术上十分严谨，我很乐意拿自己的想法跟老师聊聊。"] = "Профессор Коэн очень строг в учебе, и я рад обсудить с ним свои идеи.",
    ["科林·伊利亚特首席……他战死在巨人王庭了。但白银城的所有人都记得他，也记得您。"] = "Вождь Колин Илиад... он погиб в бою при дворе Короля Гигантов. Но все в Серебряном Городе помнят его, и тебя помнят тоже.",
    ["秘密约会？！"] = "Тайное свидание?!",
    ["穷人区"] = "Бедный район",
    ["穷人区一个人60苏勒，地块随便你自己选，别埋在路边就行。"] = "Бедный район — 60 суле на человека. Участок вы можете выбрать сами, только не закапывайте их на обочине.",
    ["穷人区就那么一点地方，却埋葬着大部分的廷根人，胡乱埋葬自然也就成了常态！"] = "Бедный район имеет такую ​​маленькую площадь, но в нем похоронена большая часть жителей Тингена; закапывать их беспорядочно, естественно, стало нормой!",
    ["穷人区？"] = "Бедный район?",
    ["穿过“鬼屋”是最后的考验，出口就隐藏在雾气里。"] = "Прохождение через «Дом с привидениями» — последнее испытание; выход скрыт в тумане.",
    ["穿长裙的少女"] = "Молодая девушка в длинном платье",
    ["穿长裙的少女惊慌逃窜，残忍的开膛手正如阴影般死死跟踪…… "] = "Девушка в длинном платье в панике убежала, жестокий Потрошитель преследовал ее, как тень...",
    ["窥秘人嘛……"] = "Мистер Прайер, ну...",
    ["第一套"] = "Первый набор",
    ["第一封伪造的信到来时，我就发现了问题——因为那里面写着："] = "Когда пришло первое поддельное письмо, я обнаружил проблему — ведь внутри было написано:",
    ["第一幕以开膛手的完美首秀结束。"] = "Первый акт заканчивается прекрасным дебютом Потрошителя.",
    ["第一次的时候，奥黛丽用一种不太好解释的眼神看了我一眼。可我也从她的眼神里看出了信任。"] = "В первый раз Одри одарила меня взглядом, который трудно истолковать. Но в ее глазах я также прочитал доверие.",
    ["第一点，关于医生的矛盾。"] = "Первый момент — о противоречиях между врачами.",
    ["第一，“看见我”在老管家手里，被他做成眼镜。"] = "Во-первых, «Узри меня» находится у старого дворецкого — он вставил его в очки.",
    ["第一，有人对心理和记忆格外关注。"] = "Во-первых, некоторые люди уделяют особое внимание психологии и памяти.",
    ["第三套"] = "Третий сет",
    ["第三点，关于仆人的矛盾。"] = "Третий пункт, касающийся противоречия слуги.",
    ["第三，男爵行为僵硬，像被操控的木偶。"] = "В-третьих, поведение барона жесткое, как у управляемой марионетки.",
    ["第二套"] = "Второй сет",
    ["第二幕结束。"] = "Второй акт заканчивается.",
    ["第二点，关于管家的矛盾。"] = "Второй момент, касающийся противоречия дворецкого.",
    ["第二，棕发女人，戒指藏针，言谈煽情。刺客？"] = "Вторая, шатенка, кольцо, скрывающее иголку, эмоциональная речь. Убийца?",
    ["第二，艾琳娜的“刺杀”是假的，是男爵安排的表演。"] = "Во-вторых, «убийство» Елены — фейк; это спектакль, устроенный бароном.",
    ["第十二个，你可以走了，而且你没死。"] = "Двенадцатый, ты можешь уйти, и ты не умер.",
    ["第十二个，游戏结束，你可以走了。"] = "Двенадцатый, игра окончена. Вы можете идти сейчас.",
    ["第四纪的相关历史不确定的内容太多，你应该从现有的遗物入手研究，排除不确定因素。"] = "В истории Четвертой Эпохи слишком много неясностей; вам следует начать исследование с существующих реликвий и исключить неопределенные факторы.",
    ["等什么？"] = "Подождать чего?",
    ["等他的技艺足够好，会有人愿意为他的手艺付更多的钱。"] = "Когда его мастерство станет достаточно хорошим, найдутся люди, готовые платить больше за его мастерство.",
    ["等你准备好，随时可以来找我，我带你去灵界设立坐标！"] = "Whenever you are ready, come find me, and I will take you to the Spirit World to set the coordinates!",
    ["等到太阳下山，就把它们一只只赶回家。"] = "Когда солнце зайдет, отвезите их домой одного за другим.",
    ["等我晋升到高序列，是不是就不用再为几镑几苏勒发愁了呢。"] = "Как только я перейду на более высокую последовательность, мне больше не придется беспокоиться о нескольких фунтах или шиллингах?",
    ["等等……艾琳娜怎么不逃跑，还微笑着看这一切？"] = "Погодите... почему Елена не убегает, да еще и с улыбкой смотрит на все это?",
    ["等等、我不是——"] = "Погодите, я вовсе не...",
    ["等等吧，明天又是今天，今天又是昨天。"] = "Подождем, завтра — это сегодня, а сегодня — это вчера.",
    ["等等，什么胸针？"] = "Подожди, что за брошь?",
    ["等等，会长出鱼鳞的蔬菜？"] = "Подождите, овощи, на которых растет рыбья чешуя?",
    ["等等，女士，这里面肯定有误会，我和他聊聊！"] = "Постойте, мисс, тут явно какое-то недоразумение, позвольте мне поговорить с ним!",
    ["等等，布雷登——这里最奇怪的应该是布雷登！"] = "Погодите-ка, Брейден... страннее всего здесь ведет себя именно Брейден!",
    ["等等，我想再挑战一次，不知道可不可以？"] = "Подожди, я хочу попробовать еще раз, это разрешено?",
    ["等等，那“归乡”指南针……"] = "Wait, that \"Homecoming\" compass...",
    ["简单直接？"] = "Просто и прямо?",
    ["算了，看您是个实在人。60镑，您就当可怜可怜我，可怜一个贫穷的老头子……"] = "Забудь об этом, я вижу, ты реальный человек. 60 фунтов, пожалей меня, бедного старика...",
    ["算你走运，居然能把我找出来……"] = "Считайте, что вам повезло, что вы действительно смогли меня найти...",
    ["算是，阿兹克先生是我在霍伊大学历史系的讲师。他是一位非常博学的学者，也是一位强大的非凡者。"] = "В каком-то смысле г-н Азик был моим преподавателем на историческом факультете Хойского университета. Он очень образованный ученый, а также могущественный Потусторонний.",
    ["管不了你了，我先回去烤烤火。"] = "Ну тебя, пойду лучше погреюсь у огня.",
    ["管家、医生、仆人……在那段时间里，每个人都有机会进入卧室，看来得去收集其余三人的证词才能继续推理了。"] = "Экономка, врач, слуга... За это время каждый имел возможность войти в спальню. Похоже, нам нужно было собрать показания остальных троих, прежде чем мы сможем продолжить рассуждения.",
    ["管家前往卧室送药的时间与霍克斯男爵的死亡时间吻合。他有充分的时间杀害霍克斯男爵。"] = "Время, когда дворецкий пошел в спальню, чтобы доставить лекарство, совпадает со временем смерти барона Хоукса. У него было достаточно времени, чтобы убить барона Хоукса.",
    ["箱子里！刚才还在！"] = "В коробке! Это было только здесь!",
    ["类似。我可以在梦里做很多清醒时做不到的事。"] = "Похожий. Во сне я могу делать многое, чего не могу сделать наяву.",
    ["精彩，你真的很努力在推理。"] = "Замечательно, вы действительно очень старались это сделать.",
    ["糟糕，他有些发狂了，要先控制住他！"] = "О нет, он теряет контроль. Сначала я должен его удержать!",
    ["糟糕，我经常和同事来这吃饭，已经习惯性提前点餐了！你呢？有什么不能吃的吗？"] = "О нет, я часто прихожу сюда поесть с коллегами, поэтому привыкла заказывать заранее! А ты? Есть ли что-нибудь, что тебе нельзя есть?",
    ["约定的时刻到了，我的听众，也是这段历史的见证者。"] = "Настал назначенный час, мои слушатели и свидетели этой истории.",
    ["纸条后半部分被烧毁了，文字无法完全辨认。只能看出第一个字是“列”，难道是……"] = "Вторая половина записки сгорела, и текст полностью идентифицировать невозможно. Я вижу только, что первый персонаж — «Ложь», может быть…",
    ["线索指出，营地在几年前遭到了毁灭，可布雷登明明还在求救……"] = "Улики указывают на то, что лагерь был уничтожен несколько лет назад, однако Брейден всё ещё явно зовёт на помощь...",
    ["细心、耐心和恒心缺一不可，那谁要上台呢？"] = "Важны осторожность, терпение и настойчивость. Итак, кто выйдет на сцену?",
    ["终于有人来了吗？我等了很久啦。"] = "Наконец-то хоть кто-то пришёл? Я так долго ждала!",
    ["终结开膛手的地点是？"] = "В какой локации заканчивается Потрошитель?",
    ["终结开膛手的时间是？"] = "Когда закончится Потрошитель?",
    ["终结开膛手的角色是？"] = "Кто тот персонаж, который заканчивает Потрошителя?",
    ["经常有人说！但我觉得这是夸奖，对吧？"] = "Люди часто так говорят! Но я думаю, что это комплимент, да?",
    ["经您治理的因蒂斯，想必是您最满意的作品。"] = "Интис, управляемый вами, должно быть, принесет вам наибольшее удовлетворение.",
    ["结束了。"] = "Все кончено.",
    ["结束指证"] = "Покончить с обвинением",
    ["给、给我……"] = "О-отдай... отдай мне...",
    ["给你提个醒，你才是真正的猎物……"] = "Let me give you a reminder: you are the real prey...",
    ["给您添麻烦了，非常谢谢您！"] = "Я доставил вам неприятности, большое спасибо!",
    ["给罗珊说明一切"] = "Объясни все Розанне.",
    ["继续挣扎吧。等你真正站在我面前的那一天，我会让你知道——谁才是这具身体的主人。"] = "Продолжайте бороться. В тот день, когда ты действительно предстанешь передо мной, я дам тебе знать — кто настоящий хозяин этого тела.",
    ["继续旁听"] = "Продолжить прослушивание",
    ["继续看"] = "Продолжить просмотр",
    ["继续追问"] = "Продолжить допрос",
    ["罗塞尔大帝曾经说过——“如果早上能得知真理，让他晚上面临死亡，也是值得的。”"] = "Император Розель однажды сказал: «Если человек может узнать правду утром, ему стоит встретиться со смертью вечером».",
    ["罗塞尔大帝，您和“愚者”先生，是怎么认识的？"] = "Император Розель, как вы познакомились с господином «Шутом»?",
    ["罗塞尔大帝，您和“神秘女王”贝尔纳黛女士是父女？"] = "Император Розель, вы мать и дочь «Мистической королевы» Бернадетты?",
    ["罗塞尔大帝，您如何看待今日的鲁恩和因蒂斯？"] = "Император Розель, как вы оцениваете нынешние Лоэн и Интис?",
    ["罗塞尔大帝，您对这个世界的发展做出了很多的贡献。"] = "Император Розель, вы внесли большой вклад в развитие этого мира.",
    ["罗塞尔大帝，我了解到，您被称为“蒸汽之子”……"] = "Император Розель, я узнал, что тебя называют «Сыном Пара»…",
    ["罗珊会有个能陪伴她，满足她一切要求的好丈夫，连加了胡椒粉的咖啡都能喝那种！"] = "У Розанны будет заботливый муж, исполняющий любые ее капризы — даже способный выпить кофе с добавлением перца!",
    ["罗珊你在外面走一天累了吧？快坐。"] = "Розанна, ты, должно быть, устала ходить целый день, верно? Садиться.",
    ["罗珊女士，请允许我来挑战这一关。"] = "Г-жа Розанна, пожалуйста, позвольте мне взять на себя эту задачу.",
    ["罗珊最近话又多起来了，她把新来的文员带得很好。"] = "В последнее время Розанна снова стала разговорчивой; она хорошо обучила нового клерка.",
    ["罗珊的心意当然是最重要的，我们也只是考察一些基本条件，确保他没什么坏心。"] = "Желания Розанны, конечно, самые важные, мы просто проверяем некоторые базовые условия, чтобы убедиться, что у него нет плохих намерений.",
    ["罗珊迷上了泡咖啡，说想泡出和老尼尔一样的味道。"] = "Розанна стала одержима приготовлением кофе, заявив, что хочет сварить тот же вкус, что и Старина Нил.",
    ["罗珊，你还在生我们的气吗？"] = "Розанна, ты все еще злишься на нас?",
    ["罗珊？"] = "Розанна?",
    ["美丽的小姐，请说。"] = "Прекрасная барышня, прошу вас, говорите.",
    ["羡慕？我、我只是……觉得它确实不错。比我之前召唤出来的……确实要好上那么一点，嗯，就一点点……"] = "Завидуете? Я, я просто... думаю, это действительно очень хорошо. По сравнению с тем, что я вызывал раньше... это действительно немного лучше, да, совсем чуть-чуть...",
    ["老……什么老爷？女神啊，我要尿裤子了……"] = "Старый... какой старый хозяин? Богиня, я собираюсь обмочить штаны...",
    ["老东西？"] = "Старикашка?",
    ["老尼克……别睡……"] = "Старый Ник... не спи...",
    ["老尼尔会边看书边念叨，邓恩总是把队员护在身后，弗莱板着脸却偷偷请大家喝啤酒。"] = "Старина Нил бубнил себе под нос во время чтения, Дэнн всегда заслонял товарищей спиной, а Фрай с невозмутимым лицом тайком угощал всех пивом.",
    ["老板，跟您打听一下——金秋湖农场最近是不是出了什么事？"] = "Босс, позвольте спросить вас: что-то недавно произошло на ферме «Золотое Осеннее озеро»?",
    ["老毛病，心口很闷，您再帮我看看？"] = "Как обычно, моя грудь очень напряжена, не могли бы вы еще раз взглянуть на меня?",
    ["老爷……让我在这里等……"] = "Мастер... сказал мне подождать здесь...",
    ["老爷让我守着宅子等他回来，我就一直等……"] = "Учитель сказал мне охранять дом и ждать его возвращения, поэтому я ждал...",
    ["老爷，可老爷说要我等的。"] = "Учитель, но Учитель сказал, что мне следует подождать.",
    ["老管家出于本能保护男爵，怎么会用封印物操控他？"] = "Старый дворецкий инстинктивно защищает барона; как он мог использовать Запечатанный Артефакт, чтобы контролировать себя?",
    ["老管家戴着“看见我”……是他用封印物操控了男爵？"] = "Старый дворецкий носит надпись «See Me»… это он использует Запечатанный Артефакт, чтобы управлять Бароном?",
    ["老维尔先生，我是黑荆棘安保公司的{{PlayerName}} ，有些事——"] = "Старый мистер Уилл, я {{PlayerName}} из охранной компании Чёрный Чертополох, есть кое-что…",
    ["考试成绩不算——不论我算得高还是低，对你的心态一定会产生影响。"] = "Результаты экзаменов не включены — независимо от того, прогнозирую ли я высокие или низкие результаты, это обязательно повлияет на ваше мышление.",
    ["而且他们……似乎永远年轻，永远无法离开。"] = "И они... кажутся вечно молодыми, вечно неспособными уйти.",
    ["而且他真的出手相助，用一种很平淡的方式，就像只是顺手拂去灰尘。"] = "И он действительно потянулся за помощью, очень просто, как будто просто смахнул пыль.",
    ["而且你不觉得吗？这是真正的奇遇。像我小说里写的那样，神秘、危险，但充满可能。"] = "И вам не кажется? Это настоящее приключение. Совсем как то, что я пишу в своих романах, загадочное, опасное, но полное возможностей.",
    ["而且即使妈妈不能和我见面，我也知道她爱我。"] = "И даже если мама меня не видит, я знаю, что она меня любит.",
    ["而且奥黛丽说过，观众途径最厉害的不是打架，是让对手根本不想和你打。我觉得这说得很有道理。"] = "Кроме того, Одри сказала, что самое мощное на пути наблюдателя — это не борьба, а заставить противника вообще не хотеть драться с вами. Я думаю, это имеет большой смысл.",
    ["而且很多时候死人比活人好相处，因为从不用担心他们会突然冷场。"] = "Кроме того, с мертвыми людьми зачастую легче ладить, чем с живыми, потому что вам не придется беспокоиться о том, что они внезапно сделают ситуацию неловкой.",
    ["而且说到天才，我觉得你也是一个天才。真正的天才。"] = "Говоря о гениях, я думаю, что вы тоже один из них. Настоящий гений.",
    ["而且那位不是银月公爵，而是大地母神教会的高级执事。"] = "И этот человек — не герцог Серебряной Луны, а высокопоставленный дьякон Церкви Матери-Земли.",
    ["而且那地方特别冷，夏天的山脚下多少会融雪，那里还跟冬天似的。"] = "Besides, that place is exceptionally cold. Even if the snow melts at the foot of the mountain in summer, it's still like winter up there.",
    ["而且，你做得比我想象中更好。黑荆棘的委托，你从没让人失望过。魔药材料都准备好了吗？"] = "Кроме того, вы справились лучше, чем я предполагал. Вы еще никого не разочаровали заказами Блэкторна. Готовы ли материалы для зелья?",
    ["而且，我积攒的功勋也不够换取配方和魔药。"] = "Кроме того, накопленных мной заслуг недостаточно, чтобы обменять их на формулы и зелья.",
    ["而且，这样打扮有个好处——没人敢随便搭讪我。那些自以为是的绅士，看到蓝眼影和黑袍就绕道走，省了我很多麻烦。"] = "Кроме того, в такой одежде есть польза: никто не смеет случайно приставать ко мне. Эти самодовольные джентльмены, увидев синие тени для век и черные мантии, пошли в обход, избавив меня от многих неприятностей.",
    ["而他……他是一个孤独的人。我能感觉得出他从骨子里透出来的孤独。"] = "И он... он одинокий человек. Я чувствую одиночество, которое исходит из его костей.",
    ["而促成这一切的我，高高在上，傲慢，冷漠。有时我会想，帝国时期的我，到底算不算我。"] = "А я, содействовавший всему этому, был высок и могуч, высокомерен и холоден. Иногда я задаюсь вопросом, действительно ли я имперской эпохи был мной?",
    ["而到最后，如果你真的达到那个高度，那么，你能与之并肩战斗的，就会是他。"] = "И, в конце концов, если ты действительно достигнешь этой высоты, то тем, с кем ты сможешь сражаться бок о бок, будет он.",
    ["而吸血鬼，多数是服食了“药师”途径某些特定魔药后发生可悲异变的人类怪物，它们只是渴血的奴隶。"] = "Что касается вампиров, то большинство из них — человеческие монстры, претерпевающие трагические мутации после приема определённых зелий пути «Медицина». Они просто кровожадные рабы.",
    ["而我剩下的这一半灵魂，也在分割时被他用非凡物品结合。我开始死而复生，就像“不死者”一样。"] = "А оставшаяся половина моей души была объединена им во время разделения с Запечатанным Артефактом. Я начал воскрешаться, как «Бессмертный».",
    ["而收尸人的职责，就是护送他们体面地走完最后一程。"] = "А обязанность Сборщика Трупов — с достоинством проводить их в последний путь.",
    ["肯定没见到，要不然就带戈多一起来了。"] = "Точно не видел его, иначе ты бы притащила Годо с собой.",
    ["能不能出门要占一下，今天晚饭吃什么也要占一下！"] = "Смогу ли я выйти куда-нибудь, нужно гадать, и что сегодня съесть на ужин тоже нужно гадать!",
    ["能像您这样真好啊。"] = "Так хорошо быть таким, как ты.",
    ["能具体说说嘛，比如伦纳德先生？"] = "Не расскажете поподробнее? Например, о мистере Леонарде?",
    ["能帮助我解决困境的，也只有我自己。"] = "The only one who can help me resolve this predicament is myself.",
    ["能打跑那些坏蛋，让这里变得安全一点。"] = "Чтобы иметь возможность прогнать этих плохих парней и сделать это место немного безопаснее.",
    ["能拜托你帮我打开另一个包裹吗？"] = "Не могли бы вы помочь мне открыть другой пакет?",
    ["能让名字留在此处的，可以是在联赛的战火中挺身而出之人，也可以是将自身养成修炼到极致之人——当然，条条大路通非凡，方式并非唯一……"] = "Те, кто сможет оставить здесь свои имена, могут быть теми, кто шагнул вперёд в пламени лиги, или теми, кто усовершенствовал себя до крайности — конечно, все пути ведут в Мистический Мир, и методы не уникальны...",
    ["能辨认的就只有这么多了，剩下的只有一些非凡物品制作相关的笔记。"] = "Это все, что можно идентифицировать; остальное — просто заметки, связанные с созданием предметов Потусторонний.",
    ["能，有时候是风，有时候是雨，有时候是阳光晒在背上那一阵温暖。您觉得是它，那就是它。"] = "Да. Иногда это ветер, иногда дождь, иногда тепло солнца на спине. Если ты чувствуешь, что это он, значит, это он.",
    ["脑子里……好像多了一些新知识，还有新能力……"] = "На мой взгляд... кажется, появились какие-то новые знания и новые способности...",
    ["自此，白银城一直由“六人议事团”统治，处于最高位的长老被尊称为“首席”，其余五位则不分高低。"] = "С тех пор Серебряным городом управляет «Совет Шести», причем старший, занимающий высшую должность, почитается как «Вождь», а остальные пятеро имеют равный ранг.",
    ["臭丫头，再啰嗦别怪我不客气！"] = "Дрянная девчонка, если не замолчишь, я за себя не отвечаю!",
    ["臭小子！呜呜……"] = "Ты, паршивец! Соб...",
    ["至于她为什么会说话，这源于……一个小失误，一个所有养狗人都会犯的小错误：忘记自己的狗会开门。"] = "Что же касается того, почему она умеет говорить... все началось с одной маленькой оплошности. Ошибки, которую может совершить любой владелец собаки: забыть, что его питомец умеет открывать двери.",
    ["至少，他绝非现在的您。"] = "По крайней мере, он определенно не тот, кто вы сегодня.",
    ["至少，沉睡时我还会有许多美梦，醒来之后，也能看到寄给我的信件，告诉我发生过什么。"] = "По крайней мере, когда я сплю, мне все еще снится много прекрасных снов, а когда я просыпаюсь, я вижу письма, отправленные мне, в которых рассказывается о том, что произошло.",
    ["至少，没有了嵌在灵魂里的负担，睡去的时候，会更安静一些。"] = "At the very least, without the burden embedded in my soul, falling asleep will be a bit more peaceful.",
    ["舍伍德！！"] = "Шервуд!!",
    ["舍伍德，省省力气吧，你在外面冻着不冷吗？"] = "Шервуд, береги силы. Тебе там не холодно?",
    ["舞会人员复杂，小心观察，不要过早下结论。记住，观众不登台。"] = "На шаре полно сложных людей, поэтому наблюдайте внимательно и не делайте поспешных выводов слишком рано. Помните, Зритель не выходит на сцену.",
    ["舞台传来一阵机械齿轮的吱吱声。"] = "Со сцены послышался скрип механических шестерёнок.",
    ["舞台准备中……"] = "Идет подготовка этапа...",
    ["艾拉女士！那里水太深了，别往前走了！"] = "Мисс Элла! Вода там слишком глубока, не идите вперед!",
    ["艾拉女士，其实……"] = "Мисс Элла, вообще-то...",
    ["艾拉女士，是什么让您放不下？"] = "Мисс Элла, от чего вы не можете отказаться?",
    ["艾拉说的死而复生是什么？"] = "О каком воскрешении упоминает Эйла?",
    ["艾琳娜！"] = "Елена!",
    ["艾琳，你一个小女孩去探险太危险了。高塔是一张预示灾难的牌。"] = "Ирен, такой маленькой девочке, как ты, слишком опасно отправляться на разведку. Башня – карта, предвещающая катастрофу.",
    ["艾米托人带给我一封信。只有一句话——“我每天都在想，如果那天没有让你占卜就好了。”"] = "Эми попросила кого-нибудь принести мне письмо. В нем было всего одно предложение: «Я думаю каждый день, если бы я только не позволил тебе сделать то гадание в тот день».",
    ["艾米抽到逆位圣杯骑士。我告诉她，她的爱情不会有结果。"] = "Эми вытянула Рыцаря Кубков в перевернутом виде. Я сказал ей, что ее любовь не будет иметь результата.",
    ["艾米莉亚女士，亨利好像还在嘟囔什么。"] = "Мисс Амелия, Генри, кажется, все еще что-то бормочет.",
    ["节制。"] = "Умеренность.",
    ["苏茜原本只是一只血统不太纯正的金毛犬，是我父亲购买猎狐犬时获得的赠品。但她现在是我的家人，我的助手。"] = "Сьюзи изначально была всего лишь нечистокровным золотистым ретривером, подарком при покупке отцом фоксхаунда. Но теперь она — член моей семьи и моя помощница.",
    ["苏茜女士，在您眼里，奥黛丽小姐是什么样的人？"] = "Мисс Сьюзи, каким человеком, по вашему мнению, является мисс Одри?",
    ["苏茜女士，您晋升了？"] = "Мисс Сьюзи, вы продвинулись?",
    ["苏茜女士，您经常说“我只是一条狗”，您真的这么认为吗？"] = "Мисс Сьюзи, вы часто повторяете: «Я всего лишь собака». Вы правда так считаете?",
    ["苏茜女士，我听说您在研读心理学？"] = "Мисс Сьюзи, я слышал, вы изучаете психологию?",
    ["苏茜女士，每个周一下午，您都会守在奥黛丽小姐的房间门口？"] = "Мисс Сьюзи, каждый понедельник днем ​​вы охраняете дверь в комнату мисс Одри?",
    ["苏茜的身份，让她避免了很多烦恼。当我们面对问题一筹莫展时，苏茜只要说——“我不知道，毕竟我只是一条狗”。"] = "Личность Сьюзи избавила ее от многих неприятностей. Когда мы не знали, что делать, Сьюзи просто говорила: «Я не знаю, в конце концов, я всего лишь собака».",
    ["茶是非凡药剂"] = "Чай - это зелье Потустороннего.",
    ["莫比乌斯环，又称“无尽的迷途”。 特殊工艺打造的长方形金箔纸，一端扭转180度后，与另一端相接，形成只有一个平面的环形。"] = "Лента Мебиуса, также известная как «Бесконечный потерянный путь». Прямоугольная бумага из золотой фольги, изготовленная с особым мастерством, один конец скручен на 180 градусов, а затем соединен с другим концом, образуя кольцо только с одной плоскостью.",
    ["莫里先生……似乎……"] = "Мистер Мори... кажется...",
    ["莫里先生，您在干什么？"] = "Господин Мори, что вы делаете?",
    ["莫里和马丁是一对邻居，莫里开肉摊，马丁卖蔬菜，他们相看两厌，吵了二十年。"] = "Мори и Мартин были соседями. Мори держал мясной ларек, Мартин торговал овощами. Они терпеть не могли друг друга и ссорились уже двадцать лет.",
    ["菜筐永远乱糟糟，什么时候能学会收拾？！"] = "В корзине для овощей всегда беспорядок, когда же ты научишься наводить порядок?!",
    ["营地物品"] = "Предметы для кемпинга",
    ["营地环境"] = "Окружающая среда кемпинга",
    ["营地看上去像是很久之前就被积雪掩埋，连布雷登也无法辨认周围的环境。"] = "Лагерь выглядит так, будто его давным-давно засыпало снегом; даже Брейден не может распознать окружающую среду.",
    ["蒸汽机轰鸣了这么些年，没有石油，这里的车马永远追不上旧日的速度。"] = "Паровой двигатель ревел уже много лет. Без нефти повозки здесь никогда не догонят скорость Великих Древних.",
    ["蔷薇战争？"] = "Война роз?",
    ["蘑菇也会难过吗？"] = "Могут ли грибы тоже грустить?",
    ["蘑菇什么都不会。"] = "Грибам ничего не нужно.",
    ["蘑菇？"] = "Гриб?",
    ["虽然受限于一些传统观念，她们的工作以文员为主，晋升也有隐形的天花板……"] = "Хотя их работа ограничена некоторыми традиционными концепциями, их работа в основном канцелярская, и для продвижения по службе существует невидимый потолок...",
    ["虽然她已经是神秘世界的大人物了，但我还是放心不下。既然都是老乡，等你成长起来，也要记得照看一下她啊。"] = "Хотя она уже большая шишка в мистическом мире, я все равно не могу не волноваться. Поскольку мы оба из одного родного города, не забудь присматривать за ней, когда вырастешь.",
    ["虽然她有时候看到我的成果会脸色发白，但她从来不阻止我……呃有时候也会阻止一下吧。"] = "Пусть она порой и бледнеет, глядя на мои успехи, но никогда мне не мешает... э-э, ну, разве что самую малость иногда.",
    ["虽然条件简陋一些，但干净安全可以保障。"] = "Хотя условия немного суровые, они чистые и безопасные.",
    ["虽然船长当时很生气，但我看得出来她其实也很惊讶。一艘能自己产奶的船，这在全世界都是独一无二的！"] = "Хотя капитан тогда была очень зла, я мог сказать, что она на самом деле была очень удивлена. Корабль, который сам может добывать молоко — такого нет во всем мире!",
    ["虽然要再挨几天饿，但我还是再去找找工作吧！"] = "Хоть мне и придется поголодать еще несколько дней, но я снова пойду искать работу!",
    ["蜡烛象征灵性之光与引导,祭品的选择需契合仪式的目的和祈求对象可能的喜好或象征意义。对于解除封印，这些基础元素足矣。"] = "Свечи символизируют свет духовности и руководства. Выбор подношений должен соответствовать цели ритуала и потенциальным предпочтениям или символическому значению сущности, к которой обращаются. Для взлома пломбы этих основных элементов достаточно.",
    ["血族是秉承月光而生的古老种族，我们拥有自己的历史、骄傲与生活方式。"] = "Сангвиники — древняя раса, рожденная в лунном свете; у нас есть своя история, гордость и образ жизни.",
    ["行，算你厉害！"] = "Хорошо, ты молодец!",
    ["衣着得体、谈吐温和，能关注到罗珊随口一提的东西，总的来说绅士而体贴。"] = "Одет соответствующим образом, говорит мягко и может заметить то, о чем Розанна упоминает вскользь. В целом он джентльмен и внимателен.",
    ["表示疑惑"] = "Выразить недоумение",
    ["被注视？"] = "Присмотрелся?",
    ["被邀请成为文职人员那天，前任队长卡萝带我去参观值夜者们的武器库，那里存满了平时难得一见的武器。"] = "В тот день, когда меня пригласили стать гражданским сотрудником, бывший капитан Кэрол взяла меня с собой на арсенал «Ночных ястребов», который был заполнен оружием, редко встречающимся в повседневной жизни.",
    ["西迦会用一件封印物来帮大家变装，防止罗珊认出我们。"] = "Сика воспользуется Запечатанным Артефактом, чтобы изменить внешность каждого из нас и не дать Розанне нас узнать.",
    ["西里尔，再给我点时间……好了，不要辜负金秋湖的景色，让我们暂时遗忘贝克兰德的一切。"] = "Кирилл, дай мне еще время... Ладно, не пропадай пейзажи озера Золотой Осени; давайте на время забудем все о Баклунде.",
    ["要不换个地方试试？转换一下心情，或许对演奏有帮助。"] = "Как насчет того, чтобы попробовать другое место? Смена обстановки может помочь в исполнении.",
    ["要不是你当初坚持去剧院，我们还能赶上火车呢。"] = "Если бы ты не настоял на том, чтобы пойти в театр, мы бы успели на поезд.",
    ["要小心，因为这个镇子上的一切都在重复。"] = "Будьте осторожны, ведь в этом городе все повторяется.",
    ["要是还找不到的话，或许可以问问这里的掘墓人。"] = "Если вы все еще не можете его найти, возможно, вы могли бы спросить могильщика здесь.",
    ["要说幸会吗……"] = "Стоит ли сказать «рад знакомству»...",
    ["见到茶会的主人，也许就能直接问出欧洛斯的下落？"] = "Если я встречу хозяина чаепития, возможно, я смогу напрямую спросить о местонахождении Ороса?",
    ["见证之环上镌刻的名字并非恒久不变——每逢周一，历史更替，荣光随新的名字一同浮现。"] = "Имена, выгравированные на Кольце Свидетеля, непостоянны — каждый понедельник история меняется, и вместе с новыми именами появляется слава.",
    ["观众从不登台。一旦登台，就成了戏剧的一部分，再也看不见真相。"] = "Зритель никогда не выходит на сцену. Выйдя на сцену, вы становитесь участником драмы и больше не можете видеть правду.",
    ["观众最重要的就是观察。当你在观看我时，我也在观察你。"] = "Самое главное для Зрителя – наблюдать. Когда ты наблюдал за мной, я тоже наблюдал за тобой.",
    ["观众途径非凡者不仅可以心理治疗，也可以利用精神控制，让非凡者走向崩溃。"] = "Путь зрителя Потусторонние могут не только проводить психотерапию, но и использовать контроль над разумом, чтобы довести Потусторонних до коллапса.",
    ["观众途径，序列5——“梦境行者”。"] = "Путь зрителя, эпизод 5 — «Сноходец».",
    ["观察。虽然这是观众途径的基本功，但对非凡者来说，在陌生环境里模拟一个观众，是安全而明智的选择。"] = "Наблюдать. Хотя это основной навык работы с аудиторией, для выдающихся людей имитация аудитории в незнакомой среде является безопасным и мудрым выбором.",
    ["规则和之前一样，在场的所有茶水中，有一杯特殊的茶。"] = "Правила те же, что и раньше: среди всего подаваемого здесь чая есть одна особенная чашка.",
    ["解读有误？"] = "Ошибка интерпретации?",
    ["警局总部外"] = "Возле штаб-квартиры полиции",
    ["让我们从最基础的开始。"] = "Начнем с основ.",
    ["让我化作能量消失吧，我会补全你缺少的力量……"] = "Позвольте мне превратиться в энергию и исчезнуть; Я восполню ту силу, которой тебе не хватает...",
    ["让我来分析一下……"] = "Позвольте мне проанализировать...",
    ["让我看看，该为您这位贵客挑选哪一出戏呢……"] = "Посмотрим, какой спектакль выбрать для столь высокого гостя...",
    ["记下真相"] = "Записать правду",
    ["记住，占卜家是命运的见证者，不是审判者。"] = "Помните, Провидец — свидетель судьбы, а не судья.",
    ["记住，因为你的物品位格过高，这或许将是一场“神降”仪式。"] = "Помните: поскольку уровень вашего предмета слишком высок, это может быть ритуал «божественного происхождения».",
    ["记得院长爷爷说过，作为黑夜的信徒，我们既是黑暗的守夜人，也是照亮黑暗的星光。"] = "Я помню, как декан сказал, что, верующие в Ночь, мы одновременно являемся ночными стражами тьмы и звездным светом, который ее освещает.",
    ["设计它们的人都很擅长运用光影，将光源集中到圣台的位置，让人发自内心地感到敬畏。"] = "Люди, которые их спроектировали, очень умело используют свет и тень, концентрируя источник света на алтаре, чтобы заставить людей испытывать трепет от всего сердца.",
    ["证词已经全部梳理过了，想想吧，谁具有明显嫌疑？"] = "Все показания были учтены. Think about it, who has the most obvious suspicion?",
    ["诅咒解除了？"] = "Проклятие снято?",
    ["诅咒！是谁对您做了这种事？"] = "Проклятие! Кто сделал это с тобой?",
    ["诅咒？真爱之吻？"] = "Проклятие? Поцелуй настоящей любви?",
    ["试着演奏更简单的曲子？而且你也不一定要把曲子的主题局限在婚礼上。"] = "Попробуйте сыграть более простые песни? И вам не обязательно ограничивать тематику вашей музыки свадьбами.",
    ["诗集新增的标点，如同给维纳斯接上了手臂。见鬼，这到底是谁的主意？"] = "Пунктуация, добавленная в сборник стихов, подобна прикреплению рук к Венере. Черт возьми, чья это была идея?",
    ["询问决定"] = "Спросите о решении",
    ["该死的，我感觉我一直活在罗塞尔大帝的影子里。为什么我的灵感永远会被他早一步想到！"] = "Черт возьми, у меня такое ощущение, будто я живу в тени императора Розеллы. Почему мое вдохновение всегда на шаг отстает от его мыслей!",
    ["该死的，这种闹鬼的祖宅，怎么可能卖得出去？"] = "Черт возьми, как можно было продать такой проклятый родовой дом?",
    ["说定了，我回去准备一下，明天湖边见！"] = "Всё решено, я вернусь и подготовлюсь. Увидимся завтра на озере!",
    ["说实话，我一开始也很喜欢这个名字。它也切实地帮助过我。"] = "Честно говоря, мне сначала тоже понравилось это имя. Это действительно помогло мне.",
    ["说得不错，这就是扮演。收尸人途径需要和死亡、灵界打交道，你穿得像个普通人，亡者不会信任你。"] = "Ну, это актерское мастерство. Путь Собирателя трупов должен иметь дело со смертью и миром духов. Если ты оденешься как обычный человек, мертвые не поверят тебе.",
    ["说起来，乔恩家的红果也已经堆成一座山了……"] = "К слову, у Джона красные ягоды уже горой насыпаны...",
    ["说这个没意义，活人都活不好，哪还有能力管死人！"] = "Нет смысла это говорить. Живые даже жить хорошо не могут, как бы им позаботиться о мертвых!",
    ["说重点。"] = "Перейдем к делу.",
    ["诶？！"] = "Eh?!",
    ["请二位跟我来。"] = "Пожалуйста, следуйте за мной, вы оба.",
    ["请他占卜"] = "Попросите его о гадании",
    ["请暂别此刻的喧嚣，来到我的身边。"] = "Пожалуйста, оставь этот шум и подойди ко мне.",
    ["请问你需要帮助吗？"] = "Вам нужна помощь?",
    ["请问您是安迪小姐吗？"] = "Простите, вы мисс Энди?",
    ["请问是玛丽奶奶吗？"] = "Is that you, Grandma Mary?",
    ["请问，你们说的吸血鬼是谁？"] = "Прошу прощения, а о каком вампире вы говорите?",
    ["请问，刚刚那对母女呢？"] = "Могу я спросить, куда делись мать и дочь?",
    ["谁可能拥有作案动机?"] = "У кого может быть мотив для преступления?",
    ["谁啊！大中午的锯木头……"] = "Кто это! Распиловка дров среди бела дня...",
    ["谁在那儿？"] = "Кто там?",
    ["谁干的！到底是谁干的！"] = "Кто это сделал! Кто это сделал!",
    ["谁给他上一课？"] = "Кто преподаст ему урок?",
    ["谁？我？"] = "ВОЗ? Мне?",
    ["调配魔药那天，苏茜开门进了实验室，舔舐了一份观众魔药。幸好我当时准备了两份材料。"] = "В день приготовления зелья Сьюзи открыла дверь, вошла в лабораторию и слизала порцию зелья Зрителя. К счастью, я тогда заготовила два комплекта ингредиентов.",
    ["谈判顺利吗？"] = "Переговоры прошли успешно?",
    ["谢谢。"] = "Спасибо.",
    ["谢谢你……我不知道为什么在这里，但我记得我叫露米。"] = "Спасибо... Не знаю, как я здесь оказалась, но помню, что меня зовут Луми.",
    ["谢谢你。"] = "Спасибо.",
    ["谢谢你。我见到了老师，见到了卢卡斯。他们确实很幸福。"] = "Спасибо. Я видел учителя, я видел Лукаса. Они действительно очень счастливы.",
    ["谢谢你们。我……我们会记住的。"] = "Спасибо вам обоим. Я... мы запомним это.",
    ["谢谢你们。把阳光和这个小家伙一起送给我。"] = "Спасибо вам обоим. За то, что подарил мне солнечный свет вместе с этим малышом.",
    ["谢谢你帮我们驱走了乌鸦，也驱走了坏心情。"] = "Спасибо, что прогнали ворон и наше плохое настроение.",
    ["谢谢你没有丢下她。"] = "Спасибо, что не бросили ее.",
    ["谢谢你的帮助，陌生人。"] = "_\n\nСпасибо за помощь, незнакомец.",
    ["谢谢你艾琳。"] = "Спасибо, Ирен.",
    ["谢谢你，带我找回了她。"] = "Спасибо, что помогли мне найти ее.",
    ["谢谢你，我想，您可能是天使。"] = "Спасибо, я думаю, ты можешь быть Ангелом.",
    ["谢谢关心，我没事。"] = "Спасибо за беспокойство, я в порядке.",
    ["谢谢您……"] = "Спасибо...",
    ["谢谢您。要不是您在，他可能就……"] = "Спасибо. Если бы не ты, он мог бы...",
    ["谢谢您愿意和我说这些，我会尽快把指南针还回来的！"] = "Thank you for being willing to tell me these things; I will return the compass as soon as possible!",
    ["谢谢您给我勇气，让我知道我其实没那么弱。我也能保护自己的妹妹了，哈哈！"] = "Спасибо, что дали мне смелость узнать, что на самом деле я не такой уж и слабый. Теперь я могу защитить свою сестру, хаха!",
    ["谢谢您，但我对古董不太懂，还是算了。"] = "Спасибо, но я не особо разбираюсь в антиквариате, так что пропущу.",
    ["谢谢您，您要回廷根吗？"] = "Спасибо. Ты возвращаешься в Тинген?",
    ["谢谢，您生活在这里？"] = "Спасибо, вы здесь живете?",
    ["谢谢，我会留意的。我们走吧。"] = "Спасибо, я буду иметь это в виду. Пойдем.",
    ["谷仓那边。别说是我讲的。"] = "Вон там, у амбара. Только не говори, что это я сказал.",
    ["贝克兰德也有好人吧？"] = "В Баклунде тоже есть хорошие люди, верно?",
    ["贝克兰德，鲁恩王国的首都，有着“希望之地”“万都之都”的别称。"] = "Бэкланд, столица Королевства Лоэн, известна как «Земля надежды» и «Город городов».",
    ["负面效果则是，每次使用后，都会让人不断想放弃手头的事，且无法主动丢弃它，必须与它保持在一定距离内。"] = "The negative effect is that after each use, it makes one constantly want to give up on what they are currently doing, and it cannot be actively discarded; one must maintain a certain distance from it.",
    ["货比三家。比如，同样的非凡材料，不同渠道的价格可能差很多。值夜者内部的兑换价格通常比黑市便宜一些。"] = "Присмотритесь к ценам. Например, цены на один и тот же материал Потусторонний могут сильно различаться в разных каналах. Внутренняя биржевая цена «Ночных ястребов» обычно дешевле, чем на черном рынке.",
    ["购买庄园"] = "Купить поместье",
    ["购买材料制作圣水净化邪教徒留下的污迹，这理由还不够充分？"] = "Покупка материалов для создания святой воды, чтобы очистить осквернение, оставленное сектантами — разве этой причины недостаточно?",
    ["贵客，快打开剧本看看差了哪一位。"] = "Уважаемый гость, быстро откройте скрипт и посмотрите, кого не хватает.",
    ["赛拉在贝克兰德当医生，忙得连信都没时间写，一年到头也回不来几次。"] = "Сара работает врачом в Баклунде и настолько занята, что у нее нет времени даже писать письма, и она редко приходит домой несколько раз в год.",
    ["赞美女神，本店现在有个活动，如果能通过考验，不仅能免去二位本次餐费，我们还会给圣赛琳娜教堂捐一笔钱。"] = "Слава Богине, в нашем магазине теперь мероприятие; Если вы сможете пройти тест, мы не только откажемся от платы за питание для вас двоих, но и пожертвуем определенную сумму денег собору Святой Селены.",
    ["赞美愚者。你说得很对，“愚者”先生有着一颗温柔的心。"] = "Восславим Шута. Вы совершенно правы: у господина Шута доброе сердце.",
    ["赞美愚者！"] = "Слава Шуту!",
    ["走什么，留下来！那些乌鸦每周都来糟蹋我的郁金香，刚才居然全飞了！日薪3苏勒，干不干？"] = "Почему ты уходишь? Оставаться! Эти вороны прилетают каждую неделю, чтобы испортить мои тюльпаны, и только сейчас они все улетели! 8 суле в день, ты здесь?",
    ["走吧，和我一起回去，你拿了我的指南针，就陪我把该做的事做完 。"] = "Let's go, come back with me. Since you've taken my compass, you'll have to accompany me to finish what needs to be done.",
    ["走吧，带上你的“亲爱的”，和这位帮我找到你的{{哥哥|姐姐}}道谢，我们回家。 "] = "Пойдём, бери своего «милого», поблагодари {{этого братика|эту сестричку}}, что помог{{|ла}} мне найти тебя, и пойдём домой.",
    ["走吧，我带你进“知识领域”。"] = "Пошли, я отведу тебя в «Область Знаний».",
    ["赶紧停下！漆黑的深夜就是最完美的<P_Yellow>时间</>，我绝不允许你毁掉这绝佳的氛围！"] = "Немедленно остановитесь! Черная ночь — идеальное время для <P_Yellow>, </>; Я никогда не позволю вам испортить эту прекрасную атмосферу!",
    ["起来，大笨蛋。"] = "Вставай, дурачина.",
    ["趁着夜色的绝对掩护，两名凶徒抽出利刃，准备在前方转角收割猎物。我甚至都已经闻到血腥味了！"] = "Воспользовавшись абсолютным покровом ночи, двое головорезов обнажили клинки, готовясь схватить добычу на углу впереди. Я даже чувствую запах крови!",
    ["超字数厚葬"] = "Превышено ограничение на количество персонажей. Грандиозные похороны.",
    ["跟我藏着掖着？拿来吧！"] = "Скрываете от меня что-то? Сдайте это!",
    ["跟霍普前往诊所"] = "Сходите в клинику с Хоуп.",
    ["身居高位而博爱开明，赞美我主！"] = "Занимая высокое положение, будучи доброжелательным и просвещенным, хвала моему Господу!",
    ["辛苦倒谈不上，就是填写报销单的要求越来越严格……"] = "Тяжело не то слово, просто требования к заполнению форм возмещения ужесточаются...",
    ["过于破旧的钱夹，停止在三年之前的日记，还有这样厚重的积雪……"] = "Потрёпанный кошелек, остановленный три года назад дневник и такой густой снег...",
    ["还只是个小不点的时候，他就会拖着阔剑跑来跑去，勤奋地练习技艺，想要成为骑士。"] = "Когда он был еще совсем маленьким, он таскал с собой палаш, старательно оттачивая свои навыки, желая стать рыцарем.",
    ["还好是梦，你这么气人的家伙怎么会死呢，哈哈哈。"] = "Хорошо, что это был всего лишь сон. Как мог умереть такой беспощадный парень, как ты? Ха-ха-ха.",
    ["还好，先生，只可惜这一切最终没能用上，还给您。"] = "Все в порядке, сэр. Жаль только, что все это в итоге не удалось использовать. Возвращаю его вам.",
    ["还好，还好。学校有教基础理论，我只是……实践了一下。"] = "Все в порядке, все в порядке. В школе учат базовой теории, я просто... применяю ее на практике.",
    ["还好，还好。我们是想来道谢的。"] = "Всё в порядке, в порядке. Мы просто хотели поблагодарить вас.",
    ["还好，这次的感觉没有之前那么糟糕。"] = "К счастью, на этот раз ощущение было не таким плохим, как раньше.",
    ["还是个侠盗啊……"] = "So you're a chivalrous thief, after all...",
    ["还是被你发现了。"] = "Итак, вы все-таки узнали.",
    ["还有一记响亮的耳光！"] = "И громкая пощечина!",
    ["还有什么线索吗？"] = "Есть ли еще какие-нибудь подсказки?",
    ["还有克莱恩！他是真正的占卜家！只看面相就救了我的命！"] = "И Клейн! Он настоящий Провидец! Он спас мне жизнь, просто взглянув на мое лицо!",
    ["还有别的灵魂吗？"] = "Есть ли другие души?",
    ["还有老师骂，说明还有人给你指导方向。也是一种幸福……"] = "Если преподаватель ругает тебя, значит, еще есть кому наставить тебя на верный путь. В этом тоже есть свое счастье...",
    ["还有贝克兰德最近流行的玩偶和水果糖。"] = "А еще куклы и фруктовые конфеты, которые в последнее время популярны в Баклунде.",
    ["还有这种说法？"] = "Есть такое?",
    ["还有这首，“窗外的紫藤，非常漂亮，漂亮得就像那——窗外的紫藤。”"] = "А вот этот: «Глициния за окном, очень красивая, такая же красивая — глициния за окном».",
    ["还有那些洋葱，总害我掉眼泪，二十年了，就不能换个地方挂吗！"] = "А этот лук, он всегда заставляет меня плакать. Прошло двадцать лет, ты не можешь повесить их где-нибудь еще!",
    ["还有那次买二手书桌……"] = "И в тот раз я купил подержанный письменный стол...",
    ["还有，买面包不要买刚出炉的。放了一晚的便宜四分之一，切片烤一烤，味道一样。"] = "Также не покупайте хлеб, только что вынутый из духовки. Хлеб, простоявший ночь, стоит на четверть дешевле; нарежьте его и поджарьте, вкус тот же.",
    ["还有，能以物换物就尽量不用现金。用不需要的非凡材料去换需要的，这样能省下中间的差价。"] = "Кроме того, по возможности старайтесь торговать вместо наличных денег. Используйте материалы Потусторонний, которые вам не нужно обменивать на те, которые вам нужны; это экономит наценку посредника.",
    ["还有，赚的钱要分配好，一部分用于日常开销，一部分存起来购买非凡材料。"] = "Также заработанные деньги необходимо правильно распределять: часть на ежедневные расходы, а часть откладывать на покупку материалов Потусторонний.",
    ["还能有谁！菜上的青虫都跑到我的香肠上了！"] = "Кто еще! Гусеницы с овощей все заползли на мои сосиски!",
    ["还这么说？"] = "И они до сих пор так говорят?",
    ["还需要最后一份能量。"] = "Нужен последний кусочек энергии.",
    ["这……"] = "Этот...",
    ["这……还能做二十年邻居？"] = "Это... можем ли мы оставаться соседями еще двадцать лет?",
    ["这……这是什么力量？一瞬间就……"] = "Это... Что это за сила? Всего за мгновение...",
    ["这……需要不少钱吧？"] = "Это... требует много денег, верно?",
    ["这一切成功让这个蠢货认为：泰利有一个名叫奥莉薇的美丽妻子。"] = "Все это успешно заставило этого дурака поверить: у Терри была красивая жена по имени Оливия.",
    ["这一场不行，死法太普通了。我们换一个更能凸显您“英雄救美”英姿的惨剧。"] = "Этот не подойдет, способ смерти слишком обычный. Давайте перейдем к трагедии, которая лучше подчеркнет ваше героическое спасение «девицы, попавшей в беду».",
    ["这一幕的角色是……<P_Yellow>穿长裙的少女</>。您选她就没错了。"] = "Персонаж этой сцены... <P_Yellow>Девушка в длинном платье</>. Вы не ошибетесь, выбрав ее.",
    ["这一束是深眠花和月见草做的，这边的是深眠花和夜香草，都是女神喜爱的品种。"] = "Этот букет составлен из цветов сна и примулы вечерней, а этот — из цветов сна и травы, пахнущей ночью, — оба сорта нравятся Богине.",
    ["这一片，全是同一种。每年都有人来采。每年都有人死。"] = "В этом районе все одинаково. Люди приезжают собирать его каждый год. Люди умирают каждый год.",
    ["这三周来我们一直在追踪封印物的下落，较为危险的那件，灵性波动隐秘，只能确定在廷根。"] = "Последние три недели мы отслеживали местонахождение Запечатанных Артефактов. Более опасный из них скрывает духовные колебания, и мы можем только подтвердить, что он находится в Тингене.",
    ["这不是传统意义上的隐身，而是“心理学隐身”——当认知被暗示引导时，真实也会从视野中滑落。"] = "Это не невидимость в традиционном понимании, а «психологическая невидимость» — когда познание направляется внушением, реальность также ускользает из поля зрения.",
    ["这两位是恩马特港的值夜者同事，米拉和埃文。三周前，他们负责运送的两件封印物在途中失窃了。"] = "Эти двое — наши коллеги-Ночные Ястребы из порта Энмат, Мира и Эван. Три недели назад перевозимые ими два Запечатанных Артефакта были похищены в пути.",
    ["这两半灵魂，一半和“死神”途径的唯一性融合在一起，有了活化的趋势，被人造死神派所利用。"] = "Эти две половины души, одна половина слилась с Уникальностью пути «Смерти» и имела тенденцию становиться активной, что и использовала секта Искусственной Смерти.",
    ["这个嘛……“归乡”的意义，是时刻提醒你归乡并不容易。 身为“旅行家”，要心怀起点，才不会被远方吞没。"] = "Well... the meaning of \"Returning Home\" is to constantly remind you that returning home is not easy. As a \"Traveler,\" you must keep your starting point in mind so you won't be swallowed by the distance.",
    ["这个嘛……她只喜欢乖小孩，比如会好好吃掉胡萝卜的那种！"] = "Ну... ей нравятся только хорошие дети, такие, которые правильно едят морковку!",
    ["这个嘛……首先，住宿方面——如果不是长期居住，旅馆选择那种2苏勒一晚的普通房间就足够了。"] = "Ну... во-первых, что касается проживания — если вы не останавливаетесь на длительный срок, вполне достаточно обычного номера в отеле за 2 суле в сутки.",
    ["这个嘛，我们的渊源可以说到几千年前。说起来，那时候你和我们也是室友。"] = "Что ж, наше происхождение можно проследить на тысячи лет. Если подумать, ты тогда тоже был нашим соседом по комнате.",
    ["这个我还真没想过。从黑夜教会孤儿院出来后，加入教会似乎是理所应当的选择。"] = "Я никогда об этом не думал. После ухода из приюта Церкви Вечной Ночи вступление в Церковь казалось естественным выбором.",
    ["这个时代在变——蒸汽机、印刷机、新的机器每天都在出现。能学会新东西的人，不会被时代抛下。"] = "Эта эпоха меняется: каждый день появляются паровые машины, печатные станки, новые машины. Тех, кто умеет узнавать новое, эпоха не оставит позади.",
    ["这个活动的鬼屋做得真好，我第一次见到这么逼真的亡灵，感觉背上凉飕飕的。"] = "Дом с привидениями в этом случае был действительно хорошо сделан. Я впервые увидел такую ​​реалистичную нежить и почувствовал холодок по спине.",
    ["这个蔬菜摊我盘下来了！改成肉摊了！为什么每天还会变回原样！"] = "Я захватил этот овощной ларек! Поменял его на мясной ларек! Почему он каждый день возвращается в исходное состояние!",
    ["这个说起来挺简单的。我从教会离开之后，在海上漂了一段时间，后来遇到了嘉德丽雅船长。"] = "Это довольно просто сказать. После того, как я покинул Церковь, я некоторое время дрейфовал по морю, а позже встретил капитана Каттлею.",
    ["这个，给你。"] = "Это для тебя.",
    ["这么久的时间，您一定和“愚者”先生经历过许多不同寻常的事。"] = "За такое долгое время вы, должно быть, пережили много необычных вещей с Мистеромом.",
    ["这么久？都吵什么？"] = "Так долго? О чем они спорили?",
    ["这么多年……会觉得工作辛苦吗？"] = "Столько лет... тебе тяжело работать?",
    ["这么大的变化要多长时间？况且，这里也看不出弗萨克军队出没的痕迹……"] = "Сколько времени потребуется для таких больших изменений? Кроме того, здесь нет никаких следов армии Фейсака...",
    ["这么干脆？不怕我拍出什么不该拍的东西吗？"] = "Так прямолинейно? Не боишься, что я сниму то, чего не следует делать?",
    ["这么说，你是非凡者？太棒了！"] = "Итак, ты Потусторонний? Это потрясающе!",
    ["这么重的血腥味，你这南瓜里面到底装的什么，你心里清楚。"] = "Учитывая такой тяжелый запах крови, ты прекрасно знаешь, что находится внутри этих тыкв.",
    ["这么隆重吗？"] = "Это так грандиозно?",
    ["这么麻烦？听说它能帮人找到回去的路？"] = "Is it that troublesome? I heard it can help people find their way back?",
    ["这些东西都有什么故事吗？"] = "Есть ли у этих вещей какая-нибудь история?",
    ["这些事，就算是到了高序列也不容易改变。"] = "Такое нелегко изменить, даже достигнув высоких Последовательностей.",
    ["这些人……已经去世很久了。"] = "Эти люди... давно мертвы.",
    ["这些人看起来已经冻僵多时，应该是残留的魔女力量吸引他们游荡到这里。"] = "These people look like they have been frozen for a long time; it must be the residual power of the Witch that attracted them to wander here.",
    ["这些区域，代表着仪式能量的节点与通路。仪式的成功，依赖于引导者用自身的灵性，不重复地激活每一个区域，完成整个能量回路的构建。"] = "Эти области представляют собой узлы и пути энергии ритуала. Успех ритуала зависит от того, использует ли гид свою собственную духовность для активации каждой области без повторений, завершая построение всей энергетической цепи.",
    ["这些可恨的家伙，用爱情小说蛊惑少女们来赴死。"] = "Эти мерзавцы заманивают юных девушек на смерть с помощью любовных романов.",
    ["这些宝物现在是你的了。它们不仅是物质上的奖励，更是你成功掌握第一个仪式魔法的见证。知识固然无价，但适当的激励也是必要的，不是吗？"] = "Эти сокровища теперь ваши. Это не просто материальное вознаграждение, но и свидетельство вашего успешного владения первой Ритуальной Магией. Знания бесценны, но и соответствующее поощрение тоже необходимо, не так ли?",
    ["这些散落的日记里，还藏着记忆的力量！"] = "В этих разбросанных дневниковых страницах по-прежнему скрыта сила памяти!",
    ["这些材料或许能用来布置净化仪式。"] = "Эти материалы можно использовать для проведения ритуала очищения.",
    ["这些菜也是，不新鲜了就赶紧换，不然卖相不好。"] = "Эти овощи тоже, если они не свежие, поменяйте их побыстрее, иначе они будут выглядеть некрасиво.",
    ["这些蠢猪难道不知道不能埋别人的墓碑吗？"] = "Разве эти идиоты не знают, что нельзя хоронить над чужими надгробиями?",
    ["这些话讲给外人听，多半会觉得十分荒唐。可那里之于这里，确实更像是一场美梦。"] = "Рассказывая об этом посторонним, большинство сочло бы это абсурдным. Но по сравнению с этим местом это больше похоже на прекрасный сон.",
    ["这些贩子专门坑过路的。{{先生|女士}}，您别理他。"] = "Эти торговцы специализируются на обмане прохожих. {{Mr.| Ms.}}, не обращай на него внимания.",
    ["这位{{先生|女士}}，请问您认识戈多吗？"] = "Это {{ Mr. | Ms. }}, могу ли я спросить, знаешь ли ты Годо?",
    ["这位“工匠”显然有一件重要的执念……从这些就能看出来。"] = "У этого «Ремесленника» явно была важная навязчивая идея... это видно по этим вещам.",
    ["这位可怜的猎物走入了<P_Yellow>哪儿</>？故事在<P_Yellow>何时</>走向终局？又会有<P_Yellow>谁</>来见证她的死亡？"] = "Куда забрела эта несчастная жертва — <P_Yellow>куда именно</>? В какой момент история придет к развязке — <P_Yellow>когда</>? И кто станет свидетелем ее гибели — <P_Yellow>кто</>?",
    ["这位圣徒被记载于各种圣典中，如果您读过《夜之启示录》，对这个名字一定不会陌生。"] = "Этот святой упоминается в различных писаниях. Если вы читали «Ночные откровения», вам наверняка знакомо это имя.",
    ["这位士兵的战友们被困在了山上，我想先送去些食物和御寒的衣服。"] = "Товарищи этого солдата оказались в ловушке на горе, и я хочу сначала послать им немного еды и теплую одежду.",
    ["这位是？"] = "Кто это?",
    ["这倒不难办，我可以帮你。"] = "That's not hard to handle; I can help you.",
    ["这其实是相处久了之后，自然而然的事情。"] = "На самом деле это то, что происходит естественным образом после долгого времени вместе.",
    ["这则预言是什么意思？"] = "Что означает это пророчество?",
    ["这十四天里，你一直在帮一只乌鸦收集记忆碎片。所以，严格来说，我应该替乌鸦向你当面道个谢。"] = "Все эти четырнадцать дней вы помогали вороне собирать фрагменты воспоминаний. Так что, строго говоря, я должен поблагодарить вас от имени вороны лично.",
    ["这原本是老尼克的东西。"] = "Первоначально это принадлежало Старому Нику.",
    ["这句话，我一直记到现在。"] = "Я запомнил эту фразу до сих пор.",
    ["这只怀表，每个齿轮都是我亲手打磨。三年前，我带它去贝克兰德参赛，评委说它款式太旧，没有市场价值。"] = "В этих карманных часах каждая шестеренка отполирована собственными руками. Три года назад я отвез его в Бэкланд на соревнование, и судьи сказали, что этот стиль слишком старый и не имеет рыночной стоимости.",
    ["这可是全廷根最高档的百货商店，关门期间也有不少人盯着它！"] = "Это самый элитный универмаг во всем Тингене, и многие присматриваются к нему, даже когда он закрыт!",
    ["这可笑的杂技居然阻止了跟踪行动，惊魂未定的她终于在这<P_Yellow>黄昏</>的喧嚣中获救。"] = "Этот нелепый трюк фактически остановил слежение, и она, все еще потрясенная, была наконец спасена в суете этого <P_Yellow>twilight</>.",
    ["这听起来很正常。"] = "Звучит вполне правдоподобно.",
    ["这和百货商店的联系是什么？"] = "Какая связь между этим и универмагом?",
    ["这四把剑，或许就是愚者先生和塔罗会在以他们的方式影响这里，协助我领悟力量，对抗母神的污染。"] = "These four swords are perhaps Mr. The Fool and the Tarot Club influencing this place in their own way, assisting me in comprehending power to resist the corruption of the Mother Goddess.",
    ["这场精心策划的尾随猎杀，最终，反倒成了凶手自投罗网的死局。"] = "Эта тщательно спланированная слежка и охота, в конце концов, превратились в ловушку, в которой убийца попал прямо в сети.",
    ["这家店是埃莉诺和托马斯一起开起来的，都几十年了。 "] = "Этот магазин открыли Элеонора и Томас вместе, прошло уже несколько десятилетий.",
    ["这家的煎蛋最好吃……"] = "В этом месте лучшая яичница...",
    ["这对别人来说就是一间破屋子，卖不了几个钱。"] = "Для других это просто ветхий дом; много денег это не принесет.",
    ["这寻人启事上说有人在农场附近失踪——"] = "В объявлении о пропаже человека говорится, что кто-то пропал недалеко от фермы…",
    ["这封信是寄给前屋主的吗？还不太能确定……"] = "Было ли это письмо отправлено предыдущему владельцу? Это еще не совсем определенно...",
    ["这就是……灵性空间？真是……不可思议。"] = "Это... мир духов? Это действительно... невероятно.",
    ["这就是为什么我们叫“值夜者”。我们在黑夜里守护，也在黑暗中前行。"] = "Вот почему нас называют «Ночными ястребами». Мы охраняем в ночи и идем вперед во тьме.",
    ["这就是奥莉薇。"] = "Это Оливия.",
    ["这帮家伙……还没受够教训？"] = "Эти ребята... они еще не усвоили урок?",
    ["这座城市被流向东南入海口的塔索克河斜着分成了两个部分，由贝克兰德桥和渡船连接，拥有超过五百万的人口，是南北大陆最繁华的都市。"] = "Этот город разделен на две части рекой Тассо, впадающей в устье на юго-востоке, соединенной мостом Бэкланд и паромами. Его население составляет более пяти миллионов человек, и это самый процветающий мегаполис на Северном и Южном континентах.",
    ["这座山还有北坡没有普查。北坡的土壤成分和这边不一样，可能会有新种。"] = "Северный склон этой горы еще не обследовали. Состав почвы там отличается от здешней, так что могут встретиться новые виды.",
    ["这座教堂有着浓厚的黑夜女神教会风格，整体呈黑色，高高的钟塔和尖顶窗，巨大的扶壁，都是它的特色。"] = "Этот собор выполнен в ярко выраженном стиле церкви Богини Вечной Ночи; В целом он черный, с высокими колокольнями, остроконечными окнами и огромными контрфорсами — все это его характеристики.",
    ["这座机械小屋，现在或许真的和它的前主人共用着相同的心跳吧。"] = "Эта Механическая Хижина действительно может иметь то же сердцебиение, что и ее бывший хозяин.",
    ["这座机械屋本身"] = "Сам этот механический дом",
    ["这座机械屋本身……"] = "_\n\nСам машинный цех…",
    ["这座机械屋本身？！"] = "Сам этот механический дом?!",
    ["这张牌的意思是……终结，失败，最坏的结局。"] = "Эта карта означает... конец, неудачу, худший возможный исход.",
    ["这张牌的意思是……贫困还会持续，处境艰难，需要很长的时间才能改善。"] = "Значение этой карты таково... бедность будет продолжаться, ситуация сложная, и на ее улучшение уйдет много времени.",
    ["这时候，您还有心情开玩笑……您来雪山，到底是要做什么？"] = "В такую ​​минуту еще хочется пошутить... что именно ты делаешь, приезжая на Снежную гору?",
    ["这是——神明的奇迹。"] = "Это — чудо божье.",
    ["这是“2-327”的资料。"] = "Это информация по «2-327».",
    ["这是……"] = "Это...",
    ["这是……活祭？"] = "Это... человеческое жертвоприношение?",
    ["这是……该死！"] = "Это... Черт возьми!",
    ["这是……辉光之纱？即便是最出名的设计师也没法发挥出它真正的价值，不如向“愚者”先生祈求帮助吧。"] = "Это... Светящийся шелк? Даже самые известные дизайнеры не могут раскрыть его истинную ценность. Лучше было бы помолиться господину Шуту о помощи.",
    ["这是一张写满了姓名、联系方式的清单……等等，这一行是……非凡特性？"] = "Это список, наполненный именами и контактной информацией... Подождите, эта строка... Характерна для Потустороннего?",
    ["这是一张纸片，看起来是日记的一部分。"] = "Это лист бумаги, он похож на часть дневника.",
    ["这是两码事……"] = "Это две разные вещи...",
    ["这是个……人偶？是你自己做的吗？"] = "Это... кукла? Ты сделал это сам?",
    ["这是佩里的日记本，他是我们的小队长。如果顺利回家，他可能已经是个画家了。"] = "Это дневник Перри. Он был командиром нашего отряда. Если бы он благополучно добрался домой, он, возможно, уже стал бы художником.",
    ["这是占卜俱乐部，不是疯人院！"] = "Это Клуб Гадания, а не приют!",
    ["这是我在湖边发现的。"] = "Вот что мне удалось найти у озера.",
    ["这是我妹妹的学费！"] = "Это обучение моей сестры!",
    ["这是梅丽莎的学费，这是家里的房租，这是餐桌上的面包和肉……"] = "Это плата за обучение Мелиссы, это арендная плата за семью, это хлеб и мясо на столе...",
    ["这是灵界生物的召唤契约？还是一种很古老的契约，连接着远超你我想象的强大灵界生物。"] = "Это контракт на призыв существа из Духовного мира? И это очень древний контракт, соединяющий могущественное существо Духовного Мира, намного превосходящее то, что вы или я можем себе представить.",
    ["这是被封印物控制的结果吗？观察一下老管家。"] = "Является ли это результатом контроля над Запечатанным Артефактом? Мне следует понаблюдать за старым дворецким.",
    ["这是赛拉寄来的吗？"] = "Это прислала Серра?",
    ["这有什么……"] = "Да что в этом такого...",
    ["这枚指南针，我攥了十年，从没敢跟着它走。今天是我这辈子走得最远的一次，谢谢。"] = "I have held this compass for ten years, never daring to follow where it points. Today is the furthest I have ever traveled in my life. Thank you.",
    ["这样……他们的名字就不会被忘记了。"] = "Таким образом... их имена не будут забыты.",
    ["这样啊……"] = "Это так...",
    ["这样说也没错。只不过后来有更多天才，比如伦纳德，比如克莱恩。但最早，我确实算是最聪明的。扮演法是我自己领悟出来的。"] = "Это тоже не так. Просто позже гениев было больше, как Леонард, как Клейн. Но поначалу меня действительно считали самым умным. Я сам реализовал актерский метод.",
    ["这次我们在广场准备了一场考验，看他有没有给罗珊幸福的能力。"] = "На этот раз мы подготовили испытание на площади, чтобы проверить, способен ли он подарить Розанне счастье.",
    ["这次的任务总让我感到不安，我的小罗珊，我最放心不下的人。"] = "Эта миссия всегда заставляет меня чувствовать себя неловко, моя маленькая Розанна, человек, о котором я беспокоюсь больше всего.",
    ["这没什么。我在文法学校读书时，母亲重病去世了。也就是在那时，我收到了父亲的来信，让我继承了贝克兰德的财产。"] = "Ничего. Когда я учился в гимназии, от тяжелой болезни скончалась моя мама. Именно тогда я получил письмо от отца, в котором он просил меня унаследовать собственность в Баклунде.",
    ["这湖里根本就没有能实现愿望的女神！"] = "В этом озере вообще нет Богини, которая могла бы исполнять желания!",
    ["这真的很神奇。"] = "Это и впрямь удивительно.",
    ["这确实很省……"] = "Это действительно очень экономно...",
    ["这种天气走小路，不会更危险吗？"] = "Идти по тропинке в такую погоду... разве это не опаснее?",
    ["这种时候剩下的不都是烂掉的吗？"] = "Не все ли оставшиеся в то время гнилые?",
    ["这种本能反应装不出来。"] = "Такую инстинктивную реакцию невозможно подделать.",
    ["这种游客最好骗，我说什么都信。什么古堡管理员，哈哈哈哈！"] = "Этих туристов легче всего обмануть, они верят всему, что я говорю. «Администратор замка», хахахаха!",
    ["这种过度的热爱，最终沦为了偏执……他多半已经因为失控而葬身此地。"] = "Эта чрезмерная любовь со временем переросла в паранойю... Скорее всего, он погиб здесь из-за потери контроля.",
    ["这耗尽了她的力量，不得不陷入沉睡，但直到现在，她也在暗处守护着我们。"] = "Это истощило ее силы, заставив ее погрузиться в глубокий сон, но даже сейчас она продолжает охранять нас от теней.",
    ["这都是努力的结果，那现在感觉怎么样呢？"] = "Это все результаты упорного труда, как вы себя чувствуете сейчас?",
    ["这里卖些什么？"] = "Что вы здесь продаете?",
    ["这里就是如此……我们已经习惯了和种种荒诞共存。它们并不都是恶意的，就像雪山上的所有其他事物一样寻常。"] = "Вот так у нас... мы привыкли жить со всякой нелепостью. Они не все злобные, как все в заснеженных горах.",
    ["这里就是我过去的办公室，在书架上，你还能看到我过去的书籍。"] = "Это мой старый офис. На книжной полке до сих пор можно увидеть мои старые книги.",
    ["这里怎么会有隐藏起来的亡灵？"] = "Как мог здесь быть скрытый дух?",
    ["这里所有追寻真理的求知者都是幸福的。"] = "Все искатели знаний здесь, которые ищут истину, счастливы.",
    ["这里是第三小段"] = "Это третий абзац",
    ["这里是第二小段"] = "Это второй абзац",
    ["这里是黑夜女神教会在廷根市的总部，以活跃于古老第三纪的女神信徒，圣者圣赛琳娜命名。"] = "Это штаб-квартира Церкви Богини Вечной Ночи в городе Тинген, названной в честь Святой Селены, верующей в Богиню, действовавшей в древней Третьей Эпохе.",
    ["这里没有更多线索了。先来分析一下，男爵最近遭遇了什么事？"] = "Здесь больше нет зацепок. Давайте сначала проанализируем: что же произошло с бароном в последнее время?",
    ["这里没有网络，没有空调，没有手机和电子游戏，在空调房里打游戏的愿望只能寄希望于古代学者的能力。你懂吗？"] = "Здесь нет ни Интернета, ни кондиционеров, ни мобильных телефонов, ни видеоигр. Желание играть в игры в комнате с кондиционером можно объяснить только способностями древних ученых. Вы понимаете?",
    ["这里的人相信生命不会真的消失，它会以另外的形式陪着您的。"] = "Здешние люди верят, что жизнь не исчезает бесследно: она пребудет рядом с вами в ином обличье.",
    ["这里的土地很神奇，一年四季都有果实。"] = "Земля здесь волшебная; плодоносит круглый год.",
    ["这难道是天使的羽毛？……不，远超天使的气息。"] = "Это перо ангела?...Нет, это аура, превосходящая Ангельскую.",
    ["这，我也没有食物……"] = "Но... у меня тоже нет еды...",
    ["迪兰，给大家看看你的拿手好戏！"] = "Дилан, покажи всем свою особенность!",
    ["送给你了！年轻的学徒，珍惜自己的起点吧。"] = "It's yours! Young Apprentice, cherish your starting point.",
    ["逃跑？会有一大群乌鸦来吃你的肉，太恐怖了！"] = "Убегаешь? Огромная стая ворон прилетит, чтобы съесть твою плоть; это слишком страшно!",
    ["逆位……高塔。"] = "Перевернутая... Башня.",
    ["逆位星币五。两个衣衫褴褛的人在雪夜走过教堂。"] = "Пятерка Пентаклей в перевернутом положении. Два оборванца идут мимо церкви снежной ночью.",
    ["遗憾的是，首席科林·伊利亚特与长老洛薇娅·蒂芙尼倒在了黎明之前。"] = "К сожалению, вождь Колин Илиад и старейшина Ловия Тиффани пали еще до рассвета.",
    ["遭遇了那种事件，且没有第一时间接受我们的保护，却依然活着——这足以证明他的幸运。"] = "Столкнуться с таким инцидентом и не сразу принять нашу защиту, но остаться в живых — этого было достаточно, чтобы доказать свою удачу.",
    ["遵循平等是什么意思？"] = "Что означает соблюдение равенства?",
    ["邓恩没有变成我的通灵对象，呵呵……等我知道的时候，他的灵早就消散了。哪里都找不到。"] = "Данн не стал объектом моего духовного медиумизма, хаха... К тому времени, как я это узнал, его дух уже давно рассеялся. Я не мог найти его нигде.",
    ["邓恩队长……"] = "Капитан Данн...",
    ["邓恩队长喜欢叼着烟斗想事情，老尼尔的报销单多到数不清，大家值夜的时候喜欢凑在一起斗邪恶。"] = "Капитан Данн любил поразмышлять с трубкой в зубах, счетов старика Нила было не счесть, а во время ночных дежурств все любили собираться и играть в «Борьбу со злом».",
    ["邓恩队长，“梦魇”有什么样的能力？"] = "Капитан Данн, какие способности есть у «Кошмара»?",
    ["邓恩队长，值夜者平时要做哪些工作？"] = "Капитан Данн, какую работу обычно выполняют «Ночные ястребы»?",
    ["邓恩队长，您工作之余有什么爱好吗？"] = "Капитан Данн, есть ли у вас хобби помимо работы?",
    ["邓恩队长，您第一次见到克莱恩时，对他有什么印象？"] = "Капитан Данн, какое у вас сложилось впечатление о Клейн, когда вы впервые встретились с ним?",
    ["那“毒素专家”这个称号是怎么来的？"] = "Тогда откуда взялось прозвище «Знаток ядов»?",
    ["那一刻的直觉告诉我，魔药彻底消化了。"] = "В то мгновение интуиция подсказала мне, что зелье полностью усвоено.",
    ["那一定很辛苦……"] = "Наверное, это было очень тяжело...",
    ["那一定很辛苦吧。"] = "Это, должно быть, очень тяжело.",
    ["那不是也挺厉害的？婚礼乐师那么多，会驱鸟的就你一个。"] = "Разве это не удивительно? На свете так много свадебных музыкантов, но ты единственный, кто может пугать птиц.",
    ["那不是你最喜欢的剧目吗？现在倒要怪我？"] = "Разве это не твоя любимая пьеса? Теперь ты винишь меня?",
    ["那不是你的错。是封印物的副作用，是别人的阴谋。"] = "Это была не твоя вина. Это побочный эффект Запечатанного Артефакта, чей-то заговор.",
    ["那个“它”正是……"] = "Это «оно» именно...",
    ["那个发光的地方……会是出口吗？"] = "That glowing spot... could it be the exit?",
    ["那个时候，您不会觉得害怕吗？面对一位可能是神灵的存在？"] = "В тот момент вам не было страшно? Столкнуться с существованием, которое может быть богом?",
    ["那个时候，托马斯酿的麦芽酒香得能把隔壁镇子的酒鬼都勾过来。埃莉诺烤的派也是一绝，皮酥得咬一口能掉渣。 "] = "Тогда эль, сваренный Томасом, пах так хорошо, что мог заманить сюда пьяниц из соседнего города. Пироги Элеоноры тоже были шедевром; корка была настолько шелушащейся, что могла рассыпаться от одного укуса.",
    ["那个灵魂生前是序列3的银骑士，死后……仍有序列4的实力。"] = "Эта душа при жизни была Серебряным Рыцарем Последовательности 3, а после смерти... она все еще обладает силой Последовательности 4.",
    ["那个烛台，我明明看着{{他|她}}拿走的！"] = "That candlestick, I clearly saw {{him|her}} take it!",
    ["那个黑影……真的是马丁的鬼魂吗？女神啊……"] = "Эта черная тень... действительно ли это призрак Мартина? Богиня...",
    ["那为什么会和“毒”扯上关系？"] = "Так почему же это связано с «ядом»?",
    ["那么他看起来一定很严肃？"] = "Значит, он должен выглядеть серьезным?",
    ["那么多人为了国家战斗，可结果呢？大臣们签下了休战协议，哼！一切像个笑话……"] = "Столько людей сражалось за свою страну, и ради чего? Министры подписали перемирие, хм! Всё это похоже на дурную шутку...",
    ["那么，祝大家有个愉快的夜晚。"] = "Что ж, тогда желаю всем приятного вечера.",
    ["那也还是最后一步。"] = "Это все еще последний шаг.",
    ["那些爱情小说都是骗人的，吸血鬼会害人的！ "] = "Все эти любовные романы — ложь; вампиры причинят вред людям!",
    ["那些看到最后一页的人，不是被知识杀死的。他们是看到了真理，然后满意地闭上了眼睛。这是求知者的幸福。"] = "Те, кто дочитал до последней страницы, погибли вовсе не от знаний. Они узрели истину и сомкнули веки в полном упоении. Таково наивысшее счастье всякого искателя познания.",
    ["那件非凡物品吸引来的某种特殊存在，让霍克斯男爵察觉了异常，导致了霍克斯男爵的死亡。"] = "A certain special existence attracted by that Beyonder item made Baron Hawkes notice the anomaly, which led to Baron Hawkes's Dead.",
    ["那你为什么还去湖边许愿？"] = "Тогда почему ты до сих пор ходишь к озеру загадывать желания?",
    ["那你就跟着我。家里的空椅子、空盘子，正好给你用吧。"] = "Тогда ты сможешь следовать за мной. Пустой стул и пустая миска дома идеально подойдут вам.",
    ["那你想好下次和安多约会的地方了吗？餐厅会不会有点老套？"] = "Итак, вы уже придумали место для вашего следующего свидания с Андором? Будет ли ресторан немного банальным?",
    ["那副作用呢？"] = "А как насчет побочных эффектов?",
    ["那副眼镜……我捡到它时，以为是女神给我的恩赐。以为用它就能让你“自然而然”同意捐赠土地。"] = "Эта пара очков... когда я нашла их, я подумала, что это подарок Богини. Я думал, что его использование заставит вас «естественным образом» согласиться пожертвовать землю.",
    ["那副眼镜……镜片是水晶的。不是普通水晶，有灵性波动。"] = "Эта пара очков... линзы хрустальные. Не обычный кристалл; происходит колебание духовности.",
    ["那后来呢？"] = "И что случилось потом?",
    ["那后来您是怎么成为船长的？"] = "Тогда как же ты стал капитаном потом?",
    ["那块地我早就准备好了。不是因为你用封印物影响了我——因为那是你应得的。"] = "Я уже подготовил этот участок земли. Не потому, что ты использовал Запечатанный Артефакт, чтобы повлиять на меня, а потому, что ты этого заслуживаешь.",
    ["那块记忆碎片被锁在围栏里面！"] = "Этот фрагмент воспоминаний заперт внутри забора!",
    ["那天晚上她出现了——站在床边，像生前一样。什么都没说，就那么站着，站到天亮。"] = "Той ночью она появилась — стояла у кровати, как и тогда, когда была жива. Она ничего не сказала, просто стояла до рассвета.",
    ["那如果遇到必须花钱的情况呢？"] = "Что же делать, если вы столкнулись с ситуацией, когда вам необходимо потратить деньги?",
    ["那家伙身上一股酸臭味，猫咪的嗅觉很灵敏的！相比他的痛苦，我只是更担心猫咪的痛苦！"] = "От этого парня пахнет кислым и противным; обоняние кошки очень чувствительное! По сравнению с его болью меня просто больше беспокоит кошачья боль!",
    ["那封信呢？"] = "А что насчет того письма?",
    ["那就好！"] = "That's good!",
    ["那就好，记得收束起逸散的灵性。走吧，外面还有委托在等你。"] = "Вот и славно, не забудь усмирить рассеивающуюся духовность. Пойдём, снаружи тебя ждут новые поручения.",
    ["那就把它留在这儿吧，比起我的破屋子，布丁一定更喜欢这里。"] = "Тогда оставим его здесь: Пудингу тут наверняка понравится куда больше, чем в моей развалюхе.",
    ["那就是拉姆德古堡。游客都是为了这古堡来的。"] = "Это замок Ламуд. Туристы приезжают сюда ради этого старинного замка.",
    ["那就让我看尽一切吧。"] = "Тогда дай мне все увидеть.",
    ["那就试试罗塞尔大帝的《小星星》吧。"] = "Тогда давайте попробуем «Мерцай, мерцай, маленькая звездочка» императора Розеллы.",
    ["那岂不是……比霍尔伯爵家的阿尔弗雷德先生序列还高了？"] = "Разве это не значит... что у вас более высокая Последовательность, чем у мистера Альфреда из семьи Эрл Холл?",
    ["那怎么办？"] = "Тогда что мне делать?",
    ["那您为什么会离开黑荆棘？"] = "Тогда почему ты покинул Чёрный Чертополох?",
    ["那您之前也写过吗？"] = "Тогда ты писал что-нибудь раньше?",
    ["那您会怎么回答？"] = "Тогда как ты ответишь?",
    ["那您呢？"] = "Тогда что насчет тебя?",
    ["那您呢？您选哪个？"] = "А ты? Какой из них вы выберете?",
    ["那您打算怎么解决味道问题？"] = "Тогда как вы планируете решить проблему вкуса?",
    ["那您是怎么……"] = "Тогда как ты...",
    ["那您最常用的占卜方法是什么？"] = "А каким методом гадания вы пользуетесь чаще всего?",
    ["那您觉得最大的风险是什么？"] = "Тогда что, по вашему мнению, является самым большим риском?",
    ["那您面对尸体的时候，不会感到害怕吗？"] = "Тогда, когда вы сталкиваетесь с трупами, разве вы не чувствуете страха?",
    ["那我……还能感觉到布丁吗？"] = "Тогда... могу ли я все еще чувствовать Пурин?",
    ["那我们拉钩。"] = "Затем тянем за крючок.",
    ["那我可能会先趴下，摇摇尾巴，用最无辜的眼神看着他。"] = "Тогда я мог бы лечь, вилять хвостом и смотреть на него самыми невинными глазами.",
    ["那我呢？"] = "А что я?",
    ["那我就狠狠踢你的坟墓！"] = "Тогда я сильно пну твою могилу!",
    ["那我是不是可以晋升下个序列了？"] = "Тогда могу ли я перейти к следующей последовательности?",
    ["那我要怎么样才能见到她呢？她肯定很厉害吧！"] = "Тогда как я могу ее увидеть? Она, должно быть, очень сильна!",
    ["那我试试吧！"] = "Тогда я попробую!",
    ["那我选择……"] = "Тогда я выбираю...",
    ["那我？"] = "А что насчет меня?",
    ["那挺好的。"] = "Это хорошо.",
    ["那时候您不相信“愚者”先生吗？"] = "Вы тогда не верили в господина Шута?",
    ["那时候我刚上船，什么都不懂，只会用拳头说话。"] = "В то время я только сел на корабль и ничего не знал. Я мог говорить только кулаками.",
    ["那时候我就知道，他能给白银城带来不一样的希望。"] = "Тогда я знал, что он может принести в Город Серебра другую надежду.",
    ["那时泰利正处于新手爸爸的幸福期，所有信都是以“给奥莉薇”作为开头。"] = "В то время Терри был на счастливой стадии становления отцом, и все его письма начинались со слов «Оливии».",
    ["那是一次……意外，也是命运的安排。"] = "Это была... случайность, а еще и распорядок судьбы.",
    ["那是传说中的黄金树吗？请你们让我过去……"] = "Это легендарное Золотое Дерево? Пожалуйста, дайте мне пройти...",
    ["那是别人乱喊的。我明明是个杂交学家、农业改良者。"] = "Так меня случайно называют другие. Я явно занимаюсь скрещиванием и улучшением сельского хозяйства.",
    ["那是我最宝贝的东西，在家里保存着呢。"] = "Это мое самое ценное имущество, которое я надежно храню дома.",
    ["那是最温暖最美好的地方，你一定会不想离开……"] = "Это самое теплое и чудесное место; тебе точно не захочется уходить...",
    ["那是要去贝克兰德的大公司？"] = "Это значит пойти в большую компанию в Баклунде?",
    ["那是，我可是血族侯爵。对应序列3的召唤大师，能让灵界深处的强大生物来到现实世界。你可以试试这份召唤契约，它应该还能用。"] = "Of course, I am a Sanguine Marquis. Corresponding to the Sequence 3 Summoner, I can bring powerful creatures from the depths of the Spirit World into the real world. You can try this summoning contract; it should still work.",
    ["那最后……"] = "И в конце концов...",
    ["那本解谜手册，应该是他用来记录机械屋逐步活化的测试。万幸，残余的数据救了我一命。"] = "Это руководство по головоломкам, должно быть, было записью испытаний постепенной активации Механической Хижины. К счастью, оставшиеся данные спасли мне жизнь.",
    ["那枚护身符的微弱灵性也许只够维持你的存在，却不能让没有非凡力量的普通人察觉你。"] = "Слабой духовности этого амулета может быть достаточно только для поддержания вашего существования, но он не может позволить обычным людям без Потусторонних сил воспринимать вас.",
    ["那段时间，我每天的睡眠严重不足，头发掉了一大把。"] = "В течение этого времени я каждый день сильно недосыпал и потерял много волос.",
    ["那现在“未来号”还在产奶吗？"] = "«Будущее» все еще производит молоко?",
    ["那现在……"] = "Тогда сейчас...",
    ["那现在呢，陛下？"] = "И что теперь, Ваше Величество?",
    ["那真是一种奇妙的感觉，突然间就发生了。"] = "Это было действительно странное чувство; это произошло внезапно.",
    ["那种日子……<P_Heart>（摇头）</>我不想再经历了。"] = "Такая жизнь... <P_Heart> (качает головой) </> Я не хочу пережить это снова.",
    ["那第一次见到“愚者”先生时，您是什么感觉？"] = "Когда вы впервые увидели  Шута, что вы почувствовали?",
    ["那给我挑一个。不过，你这瓜保真吗？"] = "Тогда выбери один для меня. Но настоящая ли эта твоя тыква?",
    ["那老师和卢卡斯？"] = "Тогда учитель и Лукас?",
    ["那考试会很难吗？"] = "Экзамен был трудным?",
    ["那艘船属于“红骷髅”，一群残忍狡诈的家伙，专门劫掠商船，杀人灭口。"] = "Этот корабль принадлежал «Красным черепам», группе жестоких и хитрых парней, которые специализировались на грабежах торговых судов и убийстве всех свидетелей.",
    ["那蘑菇需要什么？"] = "Тогда что нужно грибам?",
    ["那诅咒就永远在你身上了，你有尝试过逃跑吗？"] = "Тогда проклятие будет на тебе навсегда. Вы пробовали сбежать?",
    ["那边……我听见了第一段记忆。"] = "Там... Я услышал первый сегмент воспоминаний.",
    ["那边有人，过去问一问吧。"] = "Там кто-то есть, пойдем, спросим его.",
    ["那边的车夫会送你们到目的地，祝你们好运。"] = "Тамошний водитель кареты отвезет вас к месту назначения. Удачи.",
    ["那这个能召唤什么？"] = "Тогда что же это может вызвать?",
    ["那这么多年，我的使命……永远也完不成了吗？"] = "Значит, все эти годы... моя миссия так никогда и не завершится?",
    ["那里有阳光、有绿植、有正常的食物，孩子们不用再吃怪物肉了。"] = "Есть солнечный свет, зеленые растения и нормальная еда; детям больше не придется есть мясо монстров.",
    ["那金秋湖有什么特别的吗？"] = "Есть ли что-нибудь особенное в озере Золотая Осень?",
    ["邪恶的小混混"] = "Злой бандит",
    ["都习惯了。上个月马丁去世，本来以为吵架能结束，谁知道莫里又对着空菜摊吵架。"] = "Привык. Мартин скончался в прошлом месяце, и я думал, что споры прекратятся, но кто знал, что Мори снова начнет спорить с пустым овощным ларьком.",
    ["都准备好了，伦纳德先生。"] = "Все готово, мистер Леонард.",
    ["都准备好后，我将陪同你一起开启仪式，见证奇迹般神降之时。"] = "После того, как все будет готово, я буду сопровождать вас, чтобы начать ритуал и стать свидетелем чудесного момента божественного нисхождения.",
    ["都很好。"] = "Они все очень хороши.",
    ["都怪我，都怪我耽误了太久，我真是没用！"] = "Это я виноват, я виноват, что задержался, я действительно бесполезен!",
    ["都找齐了，（小声）果然感觉序列越高，配方和材料都会越难搜集……"] = "Они все собрались. (Шепотом) Как и ожидалось, чем выше Последовательность, тем сложнее собирать формулы и материалы...",
    ["都是之前的人留下的。"] = "Все они раньше были оставлены людьми.",
    ["都是铁十字街那个女人害的！她把生意全抢走了！"] = "Это все та девка с улицы Железного Креста! Она отбила всех клиентов!",
    ["都能算什么"] = "Что вы можете угадать?",
    ["酒醒了？醒了就快跟我走，看我以后还让不让你喝！"] = "Протрезвел? Если ты проснулся, пойдём со мной сейчас. Посмотрим, позволю ли я тебе когда-нибудь снова пить!",
    ["里奇……怎么会……不，我还是来晚了……不！！"] = "Рич... как мог... нет, я опоздал... нет!!",
    ["里奇这家伙是个讨厌鬼！整天什么都没有，向我们要这要那。"] = "Рич такой зануда! Целый день у него ничего нет, и он постоянно просит нас о том и о сем.",
    ["重复？"] = "Повторяешь?",
    ["重新推理"] = "Переобоснование",
    ["重新梳理。"] = "Реорганизуйте.",
    ["重要的是，每次失控之后，我都知道下次该怎么改进了。"] = "Важно то, что после каждой потери контроля я знаю, как улучшиться в следующий раз.",
    ["金秋湖村庄中还流传过一则神秘预言——“当圣者的叹息声响起时，金色幼苗将在此地苏醒，万物将迎接荒芜。”"] = "Таинственное пророчество также распространилось в деревне Золотое Осеннее озеро: «Когда прозвучит вздох Святого, здесь пробудятся золотые саженцы, и все сущее будет приветствовать запустение».",
    ["钱呢？！"] = "Где деньги?!",
    ["钱要花在有用的地方。这是班森教我的。"] = "Деньги должны быть потрачены в полезных местах. Этому меня научил Бенсон.",
    ["铁十字街尽头有家水果摊，傍晚六点之后去。老板急着收摊，一苏勒能买一大袋。"] = "В конце Айрон-Кросс-стрит есть фруктовый киоск; идти после шести вечера. Владелец торопится закрыться, и за один соль можно купить большую сумку.",
    ["银骑士有什么能力？"] = "Какими способностями обладает Серебряный Рыцарь?",
    ["镇上的人都说，你修好的钟，走得比新的还准。如果觉得这只怀表不够好，就修好它。"] = "Все в городе говорят, что часы, которые вы почините, ходят точнее, чем новые. Если вы чувствуете, что эти карманные часы недостаточно хороши, почините их.",
    ["长官，那片要封锁的遗迹里，到底发生什么了？"] = "Officer, what exactly happened in those ruins that need to be sealed off?",
    ["长远的计划是必要的，这样才不会因为走上错误的道路而懊悔……但是，也要允许生活偶尔走一些弯路。"] = "Долгосрочное планирование необходимо для того, чтобы вы не пожалели о том, что выбрали неправильный путь... но вы также должны позволить жизни время от времени идти в обход.",
    ["问……问诊？"] = "П... приём у врача?",
    ["问问价格"] = "Спросите цену",
    ["问题解决了就好，我先走了，你们俩好好聊聊吧。"] = "Если проблема решена, я пойду. Вы двое хорошо поговорили.",
    ["队长……好饿……好冷……"] = "Капитан... так голоден... так холодно...",
    ["队长，你是怎么加入黑夜教会的？"] = "Капитан, как вы присоединились к Церкви Вечной Ночи?",
    ["队长，有没有纽扣？"] = "Капитан, у вас есть какие-нибудь пуговицы?",
    ["队长，那是什么？一封信？"] = "Капитан, что это? Письмо?",
    ["阳光……我们等了三千年的阳光……"] = "Солнечный свет... свет, которого мы ждали три тысячи лет...",
    ["阻止艾米莉亚"] = "Останови Эмилию",
    ["阿兹克先生……"] = "Господин Азик...",
    ["阿兹克先生在离开廷根之前，把一枚铜哨送给了我。"] = "Прежде чем господин Азик покинул Тинген, он подарил мне медный свисток.",
    ["阿兹克先生的见识非常渊博，他总能给出准确而有用的建议。"] = "Господин Азик очень хорошо осведомлен и всегда может дать точный и полезный совет.",
    ["阿兹克先生！我在古堡看到了一幅画像，与您长相相似，不，简直是一模一样！"] = "Господин Азик! Я видел в старом замке портрет, похожий на тебя, нет, он точно такой же!",
    ["阿兹克先生，您之前是霍伊大学的历史系教师？"] = "Господин Азик, раньше вы работали преподавателем истории в Хойском университете?",
    ["阿兹克先生，您是拜朗人？"] = "Господин Азик, вы Балам?",
    ["阿兹克先生，您的不死能力，是来自序列4“不死者”的非凡能力吗？"] = "Мистер Азик, ваша способность к бессмертию взята из силы Потустороннего «Бессмертный» из 4-й последовательности?",
    ["阿兹克先生，教典上写着，您是愚者座下陪伴最久的天使……"] = "Господин Азик, в писаниях говорится, что вы — Ангел, который сопровождал Шута долгое время…",
    ["阿尔伯特。你从未向我提过任何要求。一次都没有。"] = "Альберт. Ты никогда не обращался ко мне ни с какими просьбами. Ни разу.",
    ["阿尔伯特的反应"] = "_\n\nРеакция Альберта",
    ["阿尔伯特，你还好吗？"] = "Альберт, ты в порядке?",
    ["阿尔伯特：少爷，到我身后！"] = "Альберт: Молодой господин, встаньте позади меня!",
    ["阿尔伯特：点上火就不黑了。"] = "Альберт: Как только огонь зажжется, темноты больше не будет.",
    ["阿尔伯特：请安息……我会找到让你们安息的地方……"] = "Альберт: Пожалуйста, покойся с миром... Я найду для тебя место, где можно отдохнуть...",
    ["阿尔伯特：谢谢……谢谢你们。"] = "Альберт: Спасибо... спасибо вам обоим.",
    ["阿斯顿，我相信你明白，教会是有立场的。要剔除这一点很难……"] = "Астон, я думаю, ты понимаешь, что у Церкви есть своя позиция. Трудно это удалить...",
    ["陌生人，也是来参加这场猎杀的吗？"] = "Stranger, are you also here to join this hunt?",
    ["除了精酿酒舍以外，您还可以尝试建造不同种类的工坊，用以满足不同订单的需求。"] = "Помимо крафтовой пивоварни, вы также можете попробовать построить различные типы мастерских для удовлетворения потребностей различных заказов.",
    ["除了这两页，其他的字迹都不是很清楚了。"] = "За исключением этих двух страниц, остальной почерк не очень четкий.",
    ["除了这些家伙，拉姆德小镇还是很值得一逛的，我带您走走吧。"] = "Помимо этих ребят, еще стоит посетить городок Ламуд. Позвольте мне показать вам окрестности.",
    ["难道……被控制了？"] = "Может быть... его контролируют?",
    ["难道你以为我相亲的时候，会这么直接地问对方薪水嘛！"] = "Неужели вы думали, что я буду спрашивать собеседника об его зарплате прямо на свидании вслепую?",
    ["难道是管家伪造案发现场，陷害仆人？可是，他曾经愿意舍身救主……"] = "Неужели дворецкий сфабриковал место преступления, чтобы подставить слугу? Но ведь когда-то он был готов пожертвовать жизнью ради спасения хозяина...",
    ["难道说传说是真的？"] = "Неужели легенда правдива?",
    ["难道说？！"] = "Может быть?!",
    ["难道预言要成真了？可是为什么呢？"] = "Может ли пророчество сбыться? Но почему?",
    ["集中你的精神，想象你的灵性从脚下涌出，向外扩散，形成一个封闭的区域，将我们、仪式台、祭品以及目标宝箱都囊括其中。"] = "Сосредоточьте свой разум, представьте, как ваша духовность выливается из-под ваших ног, распространяется наружу, образуя замкнутую область, охватывающую нас, ритуальный алтарь, подношения и целевой сундук с сокровищами.",
    ["需要的话，我可以帮你画一张人像速写。"] = "Если вам это нужно, я могу нарисовать для вас эскиз портрета.",
    ["需要重新推理下这些疑点了。"] = "Нужно заново сопоставить все эти подозрительные улики.",
    ["霍伊大学一向重视学生的全面发展……看看我们的队员，一个个健康又精神。想要钻研学术，当然要有强健的体魄在先！"] = "В Университете Хой всегда ценили всестороннее развитие студентов... Посмотрите на членов нашей команды, каждый из них здоров и бодр. Если вы хотите изучать академические науки, конечно, сначала вам нужно иметь сильное телосложение!",
    ["霍克斯男爵与埃文医生的关系有些奇怪，埃文医生可能拥有作案动机。看来有必要和他聊聊。"] = "Отношения между бароном Хоуксом и доктором Эваном немного странные; У доктора Эвана может быть мотив. Кажется, необходимо с ним поговорить.",
    ["霍克斯男爵死前，茶杯里的茶水已经快喝完了，可房间的地面却留下了这么多水渍。"] = "Перед смертью барона Хоукса чай в его чашке почти закончился, но на полу комнаты осталось так много пятен от воды.",
    ["霍克斯男爵的异常始于购买一件古董，那恐怕是件非凡物品，它会是这场凶案的开端吗？"] = "Baron Hawkes's anomaly began with the purchase of an antique. I fear it might be a Beyonder item; could it be the start of this murder case?",
    ["霍纳奇斯……这片土地本就不同寻常，又地处边境，总是很动荡。就像几年前的那场战争……"] = "Хорнацис... эта земля по своей сути необычна, и, находясь на границе, она всегда неспокойна. Как и война несколько лет назад...",
    ["霍纳奇斯雪山。"] = "Снежные горы Хорнацис.",
    ["露珠缀满黄昏的衣襟……或如随伴月亮的星星。"] = "Роса украшает отворот сумерек... или как звезды, сопровождающие луну.",
    ["非凡世界的大门将进一步向你敞开，记得保持谨慎。"] = "Двери в Необыкновенный Мир откроются для вас дальше. Не забывайте сохранять осторожность.",
    ["非常感激。他给了我活下去的机会，还让我认识了其他成员……倒吊人、正义、太阳。"] = "Я бесконечно благодарен. Он дал мне шанс выжить и познакомил с другими членами... Висельником, Справедливостью, Солнцем.",
    ["非常感谢。"] = "Большое спасибо.",
    ["靠得住。"] = "Надежный.",
    ["音乐家水平——你以为我会这么说吗？呵呵，其实啊非常一般，不及我妻子半点。"] = "«Уровень настоящего музыканта» — думали, я так скажу? Ха-ха, на самом деле весьма посредственно, моей жене и в подметки не годится.",
    ["领主大人，感谢您为这片土地带来希望和明天。"] = "Мой Господь, спасибо, что принес на эту землю надежду и будущее.",
    ["领主大人，让我们继续期待，城堡更加美好的明天吧！"] = "Господи, давайте и дальше надеяться на лучшее будущее замка!",
    ["颜色鲜艳的蘑菇，尽量别碰。快走吧。"] = "Старайтесь не трогать ярко окрашенные грибы. Пойдем.",
    ["风、风暴在上，终于有人愿意停下脚步了！"] = "Шторм, Шторм наверху, наконец-то кто-то готов остановиться!",
    ["风是很大，是有暴雪的迹象，得快点离开。"] = "Ветер очень сильный, есть признаки метели, надо быстро уходить.",
    ["风暴不会跟你讲道理，它只会考验你是否足够强大。"] = "Буря не будет с тобой рассуждать; это только проверит, достаточно ли вы сильны.",
    ["风暴之主教会和其他教会有很多不同之处。我们崇尚力量，崇尚直面风暴的勇气。"] = "Церковь Повелителя Бурь имеет множество отличий от других церквей. Мы выступаем за силу и смелость противостоять буре напрямую.",
    ["风暴之主教会的官方非凡者，跟我们各管一部分廷根的事件。"] = "Официальные Потусторонние Церкви Повелителя Штормов, каждый из нас занимается частью инцидентов в Тингене.",
    ["风暴信徒啊……"] = "Верующий в шторм, да...",
    ["风暴在上！不、不对……我不知道……不，泰利从来没有说过这件事！"] = "Буря над нами! Нет, не то... Я не знаю... Нет, Терри никогда об этом не говорил!",
    ["首先，前任屋主的名字和身份，我想从这两件东西，应该说得足够明白了……"] = "Во-первых, имя и личность прежнего владельца дома... Думаю, эти две вещи объясняют все достаточно ясно...",
    ["首先，我们需要建立仪式的基础——仪式台与祭品。"] = "Во-первых, нам нужно заложить основу ритуала — алтарь и подношения.",
    ["马丁是谁？他们的关系很不好吗？"] = "Кто такой Мартин? Они были не в ладах друг с другом?",
    ["马丁，你来得正好！快把你的菜筐搬远点！"] = "Мартин, ты как раз вовремя! Отодвиньте корзину с овощами подальше!",
    ["马修这家伙要去哪？怎么鬼鬼祟祟的。"] = "Куда это направился Мэттью? Что-то он ведёт себя подозрительно.",
    ["马洛呢？"] = "А что насчет Марлоу?",
    ["马洛选了生命。他怕死。"] = "Марлоу выбрал жизнь. Он боится смерти.",
    ["马洛，我想，你的老师是幸福的。"] = "Марлоу, я думаю, твой учитель счастлив.",
    ["骂别人蠢猪有什么用，难道不应该想想为什么没有为母亲挑块中等墓地吗？"] = "Какой смысл называть других идиотами? Не стоит ли задуматься, почему ты не выбрал для мамы участок среднего размера?",
    ["高塔……毁灭与崩塌。"] = "Башня... разрушение и крах.",
    ["鬼、鬼魂？"] = "Призрак?",
    ["魔药已经做好了。喝下它，守住自我。我会在这里直到你醒来。"] = "Зелье готово. Выпей его и сохраняй рассудок. Я буду рядом, пока ты не очнешься.",
    ["鲁恩人比因蒂斯人更保守，更阴沉，我怀疑连绵的雨对鲁恩人的心灵健康有影响。不过，这些玩弄政治的贵族们，或许心都……"] = "Люди Лоена более консервативны и мрачны, чем люди Интиса. Я подозреваю, что непрерывный дождь оказывает влияние на психическое здоровье жителей Лоена. Однако у этих политиков и дворян, возможно, их сердца...",
    ["鲁莽、冲动、永远先用拳头思考……你能想象吗？她竟然想单枪匹马去调查一个海盗将军！"] = "Безрассудная, импульсивная, всегда сначала думает кулаками... представляете? Она действительно хотела в одиночку расследовать дело пиратского генерала!",
    ["麻烦了？什么意思？我为什么要跳崖？"] = "Проблемно? Что ты имеешь в виду? Зачем мне прыгать со скалы?",
    ["麻烦带我们去“鬼屋”。"] = "Пожалуйста, отвезите нас в «Дом с привидениями».",
    ["麻烦带路"] = "Пожалуйста, проложите путь",
    ["黄昏"] = "Сумерки",
    ["黑伍德庄园是什么情况，有资料吗？我该怎么潜入庄园？"] = "Какова ситуация с поместьем Хейвуд и есть ли какая-либо информация? Как мне проникнуть в поместье?",
    ["黑板上的字迹和日记残片，都指向了“它”。这显然是一件神奇物品，而且“不会被卖出”。"] = "Почерк на доске и фрагмент дневника указывают на «это». Это явно мистический предмет, который «не будет продан».",
    ["黑板上的字迹已经模糊不清了，依稀能够辨认出一些。"] = "Почерк на доске уже размыт, но кое-что еще можно смутно различить.",
    ["黑荆棘里似乎散落着很多旧物，比如烟斗……报销单……斗邪恶的纸牌……"] = "В «Черном Терновнике», кажется, разбросано немало памятных вещей: трубки... счета на компенсацию... карты для игры в «Борьбу со злом»...",
    ["（一局斗邪恶教学局对战后），我这……算是赢了吗？手上的牌都出光了。"] = "(После урока «Борьба со злом»), я… выиграл? Я разыграл все карты, которые были у меня на руках.",
    ["（心情低落）吼……"] = "(Чувствуя себя подавленным) Рев...",
    ["（语气古怪）不过，能把这些事推到祂身上，某种程度上我也感谢祂。"] = "(Странным тоном) Впрочем, раз уж все это можно свалить на Него, в какой-то мере я даже благодарен Ему.",
    ["（这里接入sequence：罗珊和安多跑向入口，亡灵叫罗珊，大家出现解围，伦纳德催眠安多）"] = "(Здесь происходит соединение: Розанна и Андо бегут к входу, нежить зовет Розанну, все приходят на помощь, Леонард гипнотизирует Андо)",
